// attn_qkv (glm5/attention.h) for bf16 weights as sglang holds them, row-major: the same roles and
// sync, on the hidden states normed here with gamma, with the products in bf16 (as sglang's tgemm)
// and the RMSNorms as sglang's (aklr/norm.h): blocks 0-163 each compute a 16-row group of qkv_a
// (q_a 0-127, kv 128-159, k_pe 160-163, k_pe to its own tensor) and publish it, keeping the normed
// x in LDS; blocks 128-255 each compute a 16-row group of q_b from all of q_a, normed (left in
// LDS), in sc1 stores, and publish it (Q_B_PACKET).
// Later blocks normalize kv themselves (kv_row_sglang). Its loads and norms serve attn_qkv_fp8 too.
#pragma once

#include "glm5/attention.h"
#include "aklr/norm.h"

namespace infera_flash::glm5 {

struct AttnQkvBf16Params {
    const bfloat16 *x;          // [M, HIDDEN_SIZE] the hidden states
    const bfloat16 *gamma;      // [HIDDEN_SIZE] input_layernorm
    float           epsilon;
    const bfloat16 *qkv_weight; // [QKV_A_ROWS, HIDDEN_SIZE] row-major
    const bfloat16 *q_gamma;    // [Q_LORA_RANK] q_a_layernorm
    const bfloat16 *kv_gamma;   // [KV_LORA_RANK] kv_a_layernorm
    float           latent_epsilon;
    const bfloat16 *q_b_weight; // [Q_B_ROWS, Q_LORA_RANK] row-major
    void           *workspace;  // WORKSPACE_SIZE bytes, zeroed once and kept
    bfloat16       *qkv;        // [M, QKV_A_ROWS] qkv_a's output, k_pe's columns unwritten
    bfloat16       *q;          // [M, Q_B_ROWS]
    bfloat16       *k_pe;       // [M, QK_ROPE_DIM]
};

// in a block's slot: its q_b group is out (packet 0: its qkv_a group)
constexpr int Q_B_PACKET = 1;

// a row of x or q in LDS, padded by 16 B: rows a multiple of 64 banks apart would put the tokens'
// reads of one K in one bank
template <int K> constexpr int LDS_ROW = K + 8;

struct AttnQkvBf16Smem {
    bfloat16                          x[Config::MAX_NUM_TOKENS * LDS_ROW<Config::HIDDEN_SIZE>];
    bfloat16                          q[Config::MAX_NUM_TOKENS * LDS_ROW<Q_LORA>]; // the normed q_a
    GroupSmem<Config::MAX_NUM_TOKENS> group;
    float                             reduce[WAVES * Config::MAX_NUM_TOKENS];
};
static_assert(sizeof(AttnQkvBf16Smem) <= Config::SMEM_SIZE && Config::Q_B_ROWS % 16 == 0);

// The hidden states' M rows and gamma, thread t columns 8 (256 i + t) .. + 7 of each row
// (rms_norm's layout)
template <int NUM_TOKENS>
__device__ __forceinline__ void load_x(const bfloat16 *x, const bfloat16 *gamma_in,
                                       bfloat16 (&rows)[NUM_TOKENS][ROW_LOADS][8],
                                       bfloat16 (&gamma)[ROW_LOADS][8]) {
    const int tid = threadIdx.x;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(x + m * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8,
                                   rows[m][i]);
        }
    }
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(gamma_in + (i * Config::BLOCK_SIZE + tid) * 8, gamma[i]);
    }
}

// kv's RMSNorm as sglang's, token m's values 8 lane .. 8 lane + 7 (a wave takes a token), once kv
// is out
template <int NUM_TOKENS, typename Params>
__device__ __forceinline__ void kv_row_sglang(const Params &p, int m, int lane, bfloat16 (&kv)[8]) {
    const auto     qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
    const uint32x4 val =
        buffer_load_sc1(qkv, (m * QKV_ROWS + Q_LORA + 8 * lane) * sizeof(bfloat16));
    bfloat16 gamma[8];
    __builtin_memcpy(kv, &val, 16);
    load_data<bfloat16, 8>(p.kv_gamma + 8 * lane, gamma);
    floatx2 sum2 = {};
    add_squares(sum2, kv);
    const float factor = rsqrtf(WarpReduce<SumOp>(sum2.x + sum2.y) / KV_LORA + p.latent_epsilon);
#pragma unroll
    for (int e = 0; e < 8; ++e) {
        kv[e] = static_cast<bfloat16>(static_cast<float>(kv[e]) * factor * static_cast<float>(gamma[e]));
    }
}

// Once q_a is out: its M rows, thread t columns 8t .. 8t + 7, RMSNormed as sglang's
template <int NUM_TOKENS, typename Params>
__device__ __forceinline__ void normed_q_a(const Params &p, const bfloat16 (&gamma)[1][8],
                                           const uint32x4 *slots, uint32_t epoch, float *reduce,
                                           bfloat16 (&q)[NUM_TOKENS][1][8]) {
    const int tid = threadIdx.x;
    wait_for(slots, 0, 0, QA_GROUPS, epoch);
    // written by other XCDs: sc1 loads
    const auto qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const uint32x4 val = buffer_load_sc1(qkv, (m * QKV_ROWS + 8 * tid) * sizeof(bfloat16));
        __builtin_memcpy(q[m][0], &val, 16);
    }
    rms_norm_sglang<NUM_TOKENS, 1, true>(q, gamma, p.latent_epsilon, reduce);
}

// a wave's quarter of K of a 16-row group, in 16 B steps of 32 K
template <int K> constexpr int BF16_STEPS = K / WAVES / 32;

// What a wave of group_out_bf16 needs of 16-row group `group` of a row-major bf16 [rows, K] weight:
// lane (g, c) row 16 group + c at K K / 4 wave + 32 i + 8 g .. + 7 for step i (lm_head's layout)
template <int K>
__device__ __forceinline__ void load_group_bf16(const bfloat16 *w, int group,
                                                uint32x4 (&regs)[BF16_STEPS<K>]) {
    const int       lane = threadIdx.x % THREADS_PER_WARP;
    const int       wave = threadIdx.x / THREADS_PER_WARP;
    const bfloat16 *row  = w + static_cast<size_t>(16 * group + lane % 16) * K + K / WAVES * wave +
                          8 * (lane / 16);
#pragma unroll
    for (int i = 0; i < BF16_STEPS<K>; ++i) {
        regs[i] = *reinterpret_cast<const uint32x4 *>(row + 32 * i);
    }
}

// The group's [M][16] outputs (group_store) from x [M][K] bf16 in LDS (rows LDS_ROW<K> apart): each
// wave's partial sum over its quarter of K; columns past M repeat token M - 1 and are dropped
template <int K, int NUM_TOKENS, bool SC1>
__device__ __forceinline__ void group_out_bf16(const uint32x4 (&w)[BF16_STEPS<K>], const bfloat16 *x,
                                               GroupSmem<Config::MAX_NUM_TOKENS> &s, bfloat16 *out,
                                               int stride) {
    const int       lane = threadIdx.x % THREADS_PER_WARP;
    const int       wave = threadIdx.x / THREADS_PER_WARP;
    const bfloat16 *xk =
        x + min(lane % 16, NUM_TOKENS - 1) * LDS_ROW<K> + K / WAVES * wave + 8 * (lane / 16);
    floatx4         acc  = {};
#pragma unroll
    for (int i = 0; i < BF16_STEPS<K>; ++i) {
        const bfloat16x8 b = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b, acc,
                                                      0, 0, 0);
    }
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

// Once q_a is out: q_a's RMSNorm into s.q in bf16
template <int NUM_TOKENS>
__device__ __forceinline__ void q_a_bf16(const AttnQkvBf16Params &p, AttnQkvBf16Smem &s,
                                         const bfloat16 (&gamma)[1][8], const uint32x4 *slots,
                                         uint32_t epoch) {
    const int tid = threadIdx.x;
    bfloat16  q[NUM_TOKENS][1][8];
    normed_q_a<NUM_TOKENS>(p, gamma, slots, epoch, s.reduce, q);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        store_data<bfloat16, 8>(s.q + m * LDS_ROW<Q_LORA> + 8 * tid, q[m][0]);
    }
    block_sync_lds();
}

// attn_qkv_bf16's work on this block; returns this call's epoch
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t attn_qkv_bf16_block(const AttnQkvBf16Params &p, uint8_t *smem) {
    constexpr int K_PE_BLOCK0 = QKV_GROUPS - Config::QK_ROPE_DIM / 16;
    AttnQkvBf16Smem &s       = *reinterpret_cast<AttnQkvBf16Smem *>(smem);
    const int        tid     = threadIdx.x;
    const int        block   = blockIdx.x;
    uint32x4        *slots   = static_cast<uint32x4 *>(p.workspace);
    uint32x4        *my_slot = slots + block * PACKETS_PER_SLOT;
    uint32x4         w_q_b[BF16_STEPS<Q_LORA>];
    bfloat16         q_gamma[1][8];
    uint32_t         epoch;
    if (block < QKV_GROUPS) {
        // every load of x issued ahead of the weights': one round trip for both, and x lands first
        // (loads complete in issue order)
        bfloat16 x[NUM_TOKENS][ROW_LOADS][8];
        bfloat16 gamma[ROW_LOADS][8];
        load_x<NUM_TOKENS>(p.x, p.gamma, x, gamma);
        uint32x4 w[BF16_STEPS<Config::HIDDEN_SIZE>];
        asm volatile("" ::: "memory");
        load_group_bf16<Config::HIDDEN_SIZE>(p.qkv_weight, block, w);
        epoch = next_epoch(my_slot);
        rms_norm_sglang<NUM_TOKENS, ROW_LOADS, true>(x, gamma, p.epsilon, s.reduce);
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                store_data<bfloat16, 8>(
                    s.x + m * LDS_ROW<Config::HIDDEN_SIZE> + (i * Config::BLOCK_SIZE + tid) * 8, x[m][i]);
            }
        }
        block_sync_lds();
        const bool k_pe_group = block >= K_PE_BLOCK0;
        group_out_bf16<Config::HIDDEN_SIZE, NUM_TOKENS, true>(
            w, s.x, s.group, k_pe_group ? p.k_pe + 16 * (block - K_PE_BLOCK0) : p.qkv + 16 * block,
            k_pe_group ? Config::QK_ROPE_DIM : QKV_ROWS);
        publish(my_slot, epoch);
        if (block < Q_B_BLOCK0) {
            return epoch;
        }
        const int b = opaque(block); // its loads once qkv_a's weights are in, not with them
        load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
        load_group_bf16<Q_LORA>(p.q_b_weight, b - Q_B_BLOCK0, w_q_b);
    } else {
        load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
        asm volatile("" ::: "memory");
        load_group_bf16<Q_LORA>(p.q_b_weight, block - Q_B_BLOCK0, w_q_b);
        epoch = next_epoch(my_slot);
        // keeps this block's epoch in step, once every wave has read the slot
        publish(my_slot, epoch);
    }
    q_a_bf16<NUM_TOKENS>(p, s, q_gamma, slots, epoch);
    group_out_bf16<Q_LORA, NUM_TOKENS, true>(w_q_b, s.q, s.group, p.q + 16 * (block - Q_B_BLOCK0),
                                             Config::Q_B_ROWS);
    publish(my_slot + Q_B_PACKET, epoch);
    return epoch;
}

// group_out_bf16 with its LDS reads B_AHEAD steps ahead of the MFMAs (the same products in the same order)
template <int K, int NUM_TOKENS, bool SC1>
__device__ __forceinline__ void group_out_bf16_ahead(const uint32x4 (&w)[BF16_STEPS<K>], const bfloat16 *x,
                                                     GroupSmem<Config::MAX_NUM_TOKENS> &s, bfloat16 *out, int stride) {
    constexpr int   STEPS   = BF16_STEPS<K>;
    constexpr int   B_AHEAD = 4;
    const int       lane    = threadIdx.x % THREADS_PER_WARP;
    const int       wave    = threadIdx.x / THREADS_PER_WARP;
    const bfloat16 *xk =
        x + min(lane % 16, NUM_TOKENS - 1) * LDS_ROW<K> + K / WAVES * wave + 8 * (lane / 16);
    static_assert(STEPS >= B_AHEAD);
    bfloat16x8 b[B_AHEAD];
#pragma unroll
    for (int i = 0; i < B_AHEAD; ++i) {
        b[i] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
    }
    floatx4 acc = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b[i % B_AHEAD], acc, 0,
                                                      0, 0);
        if (i + B_AHEAD < STEPS) {
            b[i % B_AHEAD] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * (i + B_AHEAD));
        }
        __builtin_amdgcn_sched_barrier(0);
    }
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

// qkv_a in 8-row units over every block (attn_qkv_bf16_units), not 16-row groups over blocks 0-163: a CU reads a
// unit's 96 KB of the weight before q_a is out, not a group's 196 KB (qkv_a is bound by what a CU has in flight, not
// by HBM). Unit b is q_a's rows 8b .. 8b + 7 on block b, published as packet 0; kv's and k_pe's KV_UNITS units come
// second on blocks 0 .. KV_UNITS - 1, published as packet 0 again with KV_FLAG (off q's way). Each row's products, waves and sums are
// the group's, bit for bit: the unit takes rows 0-7 of a 16-row MFMA tile, whose rows 8-15 (dropped) hold the next
// step's K, so a 16 B load covers two steps of the 8 rows, whole 128 B lines.
constexpr int UNIT_ROWS = 8;
constexpr int KV_UNITS  = (QKV_ROWS - Q_LORA) / UNIT_ROWS;
// a block's packet 0 again, its first word KV_FLAG, once its kv unit is out (the indexer kernel has packets 2 and 3)
constexpr uint32_t KV_FLAG = 1;
static_assert(Q_LORA / UNIT_ROWS == Config::NUM_BLOCKS && KV_UNITS <= Q_B_BLOCK0 && KV_LORA % UNIT_ROWS == 0 &&
              Config::QK_ROPE_DIM % UNIT_ROWS == 0);
template <int K> constexpr int UNIT_LOADS = BF16_STEPS<K> / 2;

// A wave's loads of the unit from row row0 of a row-major bf16 [rows, K] weight: lane (g, c) row row0 + c % 8, in
// load i step 2i + c / 8's K (K / 4 wave + 64 i + 32 (c / 8) + 8 g .. + 7)
template <int K>
__device__ __forceinline__ const bfloat16 *unit_row_bf16(const bfloat16 *w, int row0) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    const int wave = threadIdx.x / THREADS_PER_WARP;
    return w + static_cast<size_t>(row0 + lane % 8) * K + K / WAVES * wave + 8 * (lane / 16) + 32 * (lane % 16 / 8);
}

template <int K>
__device__ __forceinline__ void load_unit_bf16(const bfloat16 *w, int row0, uint32x4 (&regs)[UNIT_LOADS<K>]) {
    const bfloat16 *row = unit_row_bf16<K>(w, row0);
#pragma unroll
    for (int i = 0; i < UNIT_LOADS<K>; ++i) {
        regs[i] = __builtin_nontemporal_load(reinterpret_cast<const uint32x4 *>(row + 64 * i));
    }
}

// each lane the value of the lane 8 on in its row of 16 (DPP row_ror:8): a unit load's odd step into lanes c < 8
__device__ __forceinline__ uint32x4 rotate8(const uint32x4 &v) {
    uint32x4 out;
#pragma unroll
    for (int k = 0; k < 4; ++k) {
        out[k] = static_cast<uint32_t>(__builtin_amdgcn_mov_dpp(static_cast<int>(v[k]), 0x128, 0xf, 0xf, false));
    }
    return out;
}

// A wave's partial sum of a unit over its quarter of K (rows 0-7 of the tile), x one row of [M][K] bf16 in LDS (this
// lane's token): group_out_bf16's MFMAs in its order
template <int K>
__device__ __forceinline__ floatx4 unit_acc_bf16(const uint32x4 (&w)[UNIT_LOADS<K>], const bfloat16 *x) {
    const int       lane = threadIdx.x % THREADS_PER_WARP;
    const int       wave = threadIdx.x / THREADS_PER_WARP;
    const bfloat16 *xk   = x + K / WAVES * wave + 8 * (lane / 16);
    floatx4         acc  = {};
#pragma unroll
    for (int i = 0; i < UNIT_LOADS<K>; ++i) {
        const bfloat16x8 b0 = *reinterpret_cast<const bfloat16x8 *>(xk + 64 * i);
        const bfloat16x8 b1 = *reinterpret_cast<const bfloat16x8 *>(xk + 64 * i + 32);
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b0, acc, 0, 0, 0);
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, rotate8(w[i])), b1, acc, 0,
                                                      0, 0);
    }
    return acc;
}

// group_store for a unit: its 8 rows of each token, the waves added in wave order, rounded to bf16, 16 B a token at
// out (row stride `stride`); only wave 0 stores
template <int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void unit_store(floatx4 acc, GroupSmem<MAX_TOKENS> &s, bfloat16 *out, int stride) {
    static_assert(NUM_TOKENS <= MAX_TOKENS && NUM_TOKENS <= THREADS_PER_WARP);
    const int tid = threadIdx.x;
    s.tiles[tid]  = acc;
    block_sync_lds();
    // thread (m, r): row r of token m, at lane 16 (r / 4) + m of each wave's tile, element r % 4
    if (tid < UNIT_ROWS * NUM_TOKENS) {
        const int      r    = tid % UNIT_ROWS;
        const floatx4 *tile = s.tiles + 16 * (r / 4) + tid / UNIT_ROWS;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][r % 4];
        }
        s.out[tid] = static_cast<bfloat16>(sum);
    }
    block_sync_lds();
    if (tid < NUM_TOKENS) {
        const uint32x4 val = reinterpret_cast<const uint32x4 *>(s.out)[tid];
        auto          *dst = reinterpret_cast<uint32x4 *>(out + tid * stride);
        if constexpr (SC1) {
            store_sc1(dst, val);
        } else {
            *dst = val;
        }
    }
}

// publish for a unit's packet: wave 0 stored the unit, so only it waits for its stores (the others may have loads
// in flight that the packet need not wait for)
__device__ __forceinline__ void publish_wave0(uint32x4 *packet, uint32_t epoch, uint32_t a = 0u) {
    if (__builtin_amdgcn_readfirstlane(threadIdx.x) < THREADS_PER_WARP) {
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
        if (threadIdx.x == 0) {
            store_sc1(packet, uint32x4{a, 0u, 0u, epoch});
        }
    }
}

// Thread t < KV_UNITS waits until block t's packet 0 shows this call's epoch with its kv unit out (KV_FLAG), then the
// block syncs
__device__ __forceinline__ void wait_kv_units(const uint32x4 *slots, uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < KV_UNITS) {
        uint32x4 vals[1];
        do {
            load_sc1(slots + threadIdx.x * PACKETS_PER_SLOT, vals);
        } while (vals[0][3] != epoch || vals[0][0] != KV_FLAG);
    }
    __syncthreads();
}

// Once every unit is out: q_a's M rows, thread t columns 8t .. 8t + 7 (unit t's), RMSNormed as sglang's into s.q
template <int NUM_TOKENS>
__device__ __forceinline__ void q_a_bf16_units(const AttnQkvBf16Params &p, AttnQkvBf16Smem &s,
                                               const bfloat16 (&gamma)[1][8], const uint32x4 *slots, uint32_t epoch) {
    const int tid = threadIdx.x;
    wait_for(slots, 0, 0, Config::NUM_BLOCKS, epoch);
    // written by other XCDs: sc1 loads
    const auto qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
    bfloat16   q[NUM_TOKENS][1][8];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const uint32x4 val = buffer_load_sc1(qkv, (m * QKV_ROWS + 8 * tid) * sizeof(bfloat16));
        __builtin_memcpy(q[m][0], &val, 16);
    }
    rms_norm_sglang<NUM_TOKENS, 1, true>(q, gamma, p.latent_epsilon, s.reduce);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        store_data<bfloat16, 8>(s.q + m * LDS_ROW<Q_LORA> + 8 * tid, q[m][0]);
    }
    block_sync_lds();
}

// kv's and k_pe's unit b < KV_UNITS on block b, x in LDS at xm (this lane's token's row): out with KV_FLAG in packet 0
template <int NUM_TOKENS, typename Params, typename Smem>
__device__ __forceinline__ void kv_unit_bf16(const Params &p, Smem &s, const bfloat16 *xm, uint32x4 *my_slot,
                                             uint32_t epoch) {
    constexpr int KV_ONLY = KV_LORA / UNIT_ROWS; // kv's units, then k_pe's
    const int     block   = blockIdx.x;
    uint32x4      w[UNIT_LOADS<Config::HIDDEN_SIZE>];
    load_unit_bf16<Config::HIDDEN_SIZE>(p.qkv_weight, Q_LORA + UNIT_ROWS * block, w);
    const bool k_pe = block >= KV_ONLY;
    unit_store<NUM_TOKENS, true>(unit_acc_bf16<Config::HIDDEN_SIZE>(w, xm), s.group,
                                 k_pe ? p.k_pe + UNIT_ROWS * (block - KV_ONLY) : p.qkv + Q_LORA + UNIT_ROWS * block,
                                 k_pe ? Config::QK_ROPE_DIM : QKV_ROWS);
    publish_wave0(my_slot, epoch, KV_FLAG);
}

// attn_qkv_bf16_block's work in units (above) on this block; returns this call's epoch. Its q_b group as there: on
// blocks Q_B_BLOCK0 .., once every unit is out, its weights issued behind the unit's (wave 0's once its packet is out,
// so that its wait for the unit's stores does not wait for them too)
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t attn_qkv_bf16_units(const AttnQkvBf16Params &p, uint8_t *smem) {
    AttnQkvBf16Smem &s       = *reinterpret_cast<AttnQkvBf16Smem *>(smem);
    const int        tid     = threadIdx.x;
    const int        block   = blockIdx.x;
    const int        wave    = __builtin_amdgcn_readfirstlane(tid / THREADS_PER_WARP);
    const bool       q_b     = block >= Q_B_BLOCK0;
    uint32x4        *slots   = static_cast<uint32x4 *>(p.workspace);
    uint32x4        *my_slot = slots + block * PACKETS_PER_SLOT;
    uint32x4         w_q_b[BF16_STEPS<Q_LORA>];
    bfloat16         q_gamma[1][8];
    const auto       load_q_b = [&] {
        asm volatile("" ::: "memory");
        load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
        load_group_bf16<Q_LORA>(p.q_b_weight, block - Q_B_BLOCK0, w_q_b);
    };
    // every load of x issued ahead of the weights': one round trip for both, and x lands first (loads complete in
    // issue order)
    bfloat16 x[NUM_TOKENS][ROW_LOADS][8];
    bfloat16 gamma[ROW_LOADS][8];
    load_x<NUM_TOKENS>(p.x, p.gamma, x, gamma);
    uint32x4 w[UNIT_LOADS<Config::HIDDEN_SIZE>];
    asm volatile("" ::: "memory");
    load_unit_bf16<Config::HIDDEN_SIZE>(p.qkv_weight, UNIT_ROWS * block, w);
    const uint32_t epoch = next_epoch(my_slot);
    rms_norm_sglang<NUM_TOKENS, ROW_LOADS, true>(x, gamma, p.epsilon, s.reduce);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            store_data<bfloat16, 8>(s.x + m * LDS_ROW<Config::HIDDEN_SIZE> + (i * Config::BLOCK_SIZE + tid) * 8,
                                    x[m][i]);
        }
    }
    if (q_b && wave != 0) {
        load_q_b();
    }
    block_sync_lds();
    const bfloat16 *xm = s.x + min(tid % THREADS_PER_WARP % 16, NUM_TOKENS - 1) * LDS_ROW<Config::HIDDEN_SIZE>;
    unit_store<NUM_TOKENS, true>(unit_acc_bf16<Config::HIDDEN_SIZE>(w, xm), s.group, p.qkv + UNIT_ROWS * block,
                                 QKV_ROWS);
    publish_wave0(my_slot, epoch);
    if (block < KV_UNITS) {
        kv_unit_bf16<NUM_TOKENS>(p, s, xm, my_slot, epoch);
    }
    if (!q_b) {
        return epoch;
    }
    if (wave == 0) {
        load_q_b();
    }
    q_a_bf16_units<NUM_TOKENS>(p, s, q_gamma, slots, epoch);
    group_out_bf16_ahead<Q_LORA, NUM_TOKENS, true>(w_q_b, s.q, s.group, p.q + 16 * (block - Q_B_BLOCK0),
                                             Config::Q_B_ROWS);
    publish(my_slot + Q_B_PACKET, epoch);
    return epoch;
}

} // namespace infera_flash::glm5

// What the attention layer kernels share (attn_layer/attention*.hip, attn_ix_layer/kernel*.hip):
// mla_core's work after attn_qkv in the layers attending a carried top-k (mla_after_qkv), and their
// run()s' checks and all-reduce params.
#pragma once

#include <ATen/ATen.h>
#include <c10/hip/HIPException.h>

#include "glm5/mlp.h"
#include "aklr/attention_bf16.h"

namespace infera_flash::glm5 {

constexpr double LOG2E = 1.4426950408889634;

template <typename AttnQkvParams> struct AttentionParams {
    AttnQkvParams   attn;
    MlaCoreParams   mla;
    RowLinearParams o_proj;
};

// a kernel attending a carried top-k: its state's attn_qkv sync slots, then mla_core's, o_proj's
// all-reduce call number per block, then o's packets (MlaCoreParams::out_tagged)
struct AttentionState {
    static constexpr int64_t MLA    = WORKSPACE_SIZE;
    static constexpr int64_t CALLS  = 2 * WORKSPACE_SIZE;
    static constexpr int64_t TAGGED = CALLS + Config::NUM_BLOCKS * sizeof(int);
    static constexpr int64_t BYTES =
        TAGGED + Config::MAX_NUM_TOKENS * Config::O_PROJ_K / 4 * sizeof(uint32x4);
};

// mla_core's work on this block (mla::mla_core_block's roles) after attn_qkv's, at this call's
// epoch (slots: mla_core's): q, kv and k_pe were written earlier in the kernel on other XCDs, so
// the blocks wait for their groups (attn_slots at attn_epoch) and read them with sc1. The attending
// blocks build this call's rows once kv's and k_pe's groups are out, normalizing kv themselves, and
// turn q_pe once q_b's are; the projecting blocks compute q_latent once q_b's are out, then o, also
// as the packets o_proj polls.
// Each block runs on_post() once it posts. W_BF16: W_UK and W_UV bf16, without a scale.
template <int NUM_TOKENS, bool W_BF16, typename Params, typename OnPost>
__device__ __forceinline__ void mla_after_qkv(const Params &p, uint8_t *smem, const uint32x4 *attn_slots,
                                              uint32_t attn_epoch, uint32x4 *slots, uint32_t epoch,
                                              OnPost on_post) {
    const MlaCoreParams &ml      = p.mla;
    mla::MlaCoreSmem    &s       = *reinterpret_cast<mla::MlaCoreSmem *>(smem);
    mla::MlaCoreScratch &x       = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
    const int            tid     = threadIdx.x;
    const int            block   = blockIdx.x;
    uint32x4            *my_slot = slots + block * PACKETS_PER_SLOT;
    // every block stores packets 0 (q_latent out) and 1 (partial sums out) each call
    const auto post = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
            store_sc1(my_slot + mla::PARTIAL_SUMS_PACKET, uint32x4{0u, 0u, 0u, epoch});
        }
        on_post();
    };
    if (block < ATTENDING<NUM_TOKENS>) {
        const int       m = block / mla::ATTN_BLOCKS;
        mla::AttendRows r;
        mla::attend_rows(ml, m, block % mla::ATTN_BLOCKS, r);
        wait_for(attn_slots, 0, QA_GROUPS, QKV_GROUPS - QA_GROUPS, attn_epoch);
        mla::fresh_rows<NUM_TOKENS, true>(ml, s, [&](int t, int lane, bfloat16(&lat)[8]) {
            kv_row_sglang<NUM_TOKENS>(p.attn, t, lane, lat);
        });
        wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
        mla::turn_q_pe<true>(ml, s, m);
        wait_for(slots, 0, mla::AD_FIRST, Config::NUM_BLOCKS - mla::AD_FIRST, epoch); // q_latent
        mla::attend<NUM_TOKENS>(ml, s, x, m, block % mla::ATTN_BLOCKS, r);
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
        post();
        if (block == 0) {
            mla::write_fresh<NUM_TOKENS>(ml, s);
            __syncthreads(); // o_proj's x overwrites s.fresh
        }
        return;
    }
    if (block < mla::AD_FIRST) {
        post(); // idle: keep the slot's calls in step
        return;
    }
    const int j = block - mla::AD_FIRST;
    uint32x4  w_v[mla::Project<NUM_TOKENS>::REGS * (W_BF16 ? 2 : 1)];
    mla::project_wv<NUM_TOKENS, W_BF16>(ml, j, w_v);
    wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
    mla::project_q<NUM_TOKENS, true, W_BF16>(ml, x, j);
    post();
    mla::combine<NUM_TOKENS, true, false, W_BF16>(ml, s, x, j, w_v, slots, epoch,
                                                  mla::PARTIAL_SUMS_PACKET);
}

template <int NUM_TOKENS, bool W_BF16, typename Params, typename OnPost>
__device__ __forceinline__ void mla_after_qkv_units(const Params &p, uint8_t *smem, const uint32x4 *attn_slots,
                                              uint32_t attn_epoch, uint32x4 *slots, uint32_t epoch,
                                              OnPost on_post) {
    const MlaCoreParams &ml      = p.mla;
    mla::MlaCoreSmem    &s       = *reinterpret_cast<mla::MlaCoreSmem *>(smem);
    mla::MlaCoreScratch &x       = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
    const int            tid     = threadIdx.x;
    const int            block   = blockIdx.x;
    uint32x4            *my_slot = slots + block * PACKETS_PER_SLOT;
    // every block stores packets 0 (q_latent out) and 1 (partial sums out) each call
    const auto post = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
            store_sc1(my_slot + mla::PARTIAL_SUMS_PACKET, uint32x4{0u, 0u, 0u, epoch});
        }
        on_post();
    };
    if (block < ATTENDING<NUM_TOKENS>) {
        const int       m = block / mla::ATTN_BLOCKS;
        mla::AttendRows r;
        mla::attend_rows(ml, m, block % mla::ATTN_BLOCKS, r);
        wait_kv_units(attn_slots, attn_epoch); // kv's and k_pe's units
        mla::fresh_rows<NUM_TOKENS, true>(ml, s, [&](int t, int lane, bfloat16(&lat)[8]) {
            kv_row_sglang<NUM_TOKENS>(p.attn, t, lane, lat);
        });
        wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
        mla::turn_q_pe<true>(ml, s, m);
        wait_for(slots, 0, mla::AD_FIRST, Config::NUM_BLOCKS - mla::AD_FIRST, epoch); // q_latent
        mla::attend_c<NUM_TOKENS>(ml, s, x, m, block % mla::ATTN_BLOCKS, r);
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
        post();
        if (block == 0) {
            mla::write_fresh<NUM_TOKENS>(ml, s);
            __syncthreads(); // o_proj's x overwrites s.fresh
        }
        return;
    }
    if (block < mla::AD_FIRST) {
        post(); // idle: keep the slot's calls in step
        return;
    }
    const int j = block - mla::AD_FIRST;
    uint32x4  w_v[mla::Project<NUM_TOKENS>::REGS * (W_BF16 ? 2 : 1)];
    mla::project_wv<NUM_TOKENS, W_BF16>(ml, j, w_v);
    uint32x4 w_k[mla::WK_LOADS<W_BF16>];
    mla::project_q_weights<W_BF16>(ml, j, w_k);
    wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
    mla::project_q_w<NUM_TOKENS, true, W_BF16>(ml, x, j, w_k);
    post();
    mla::combine<NUM_TOKENS, true, false, W_BF16>(ml, s, x, j, w_v, slots, epoch,
                                                  mla::PARTIAL_SUMS_PACKET);
}

// What every attention layer kernel's run() checks: 1 to MAX_NUM_TOKENS tokens; its state (zeroed
// once and kept: each call counts its epochs and call number on from the last one's); every rank's
// peer memory, int64 addresses on the host; and all the CUs of the device, as the blocks wait on
// each other
inline void check_run(const at::Tensor &x, const at::Tensor &state, int64_t state_bytes,
                      const at::Tensor &peers, int64_t rank) {
    TORCH_CHECK(x.size(0) >= 1 && x.size(0) <= Config::MAX_NUM_TOKENS, "1 to ",
                Config::MAX_NUM_TOKENS, " tokens");
    TORCH_CHECK(state.nbytes() >= state_bytes, "state: ", state_bytes, " bytes");
    TORCH_CHECK(peers.device().is_cpu() && peers.scalar_type() == at::kLong && peers.dim() == 1 &&
                    peers.numel() >= 1 && peers.numel() <= Config::MAX_RANKS && rank >= 0 &&
                    rank < peers.numel(),
                "peers: every rank's peer memory, int64 on the host, 1 to ", Config::MAX_RANKS);
    int cus = 0;
    C10_HIP_CHECK(hipDeviceGetAttribute(&cus, hipDeviceAttributeMultiprocessorCount, x.get_device()));
    TORCH_CHECK(cus == Config::NUM_BLOCKS, "needs all ", Config::NUM_BLOCKS,
                " CUs of an MI355X (no partitions)");
}

// o_proj's all-reduce: its sum over the ranks of peers, in rank order, plus the stream prior, into
// output; its call numbers at calls
inline AllReduceParams all_reduce_params(at::Tensor &output, const bfloat16 *prior,
                                         const at::Tensor &peers, int64_t rank, void *calls) {
    AllReduceParams ar{};
    ar.out        = static_cast<bfloat16 *>(output.data_ptr());
    ar.accumulate = true;
    ar.prior      = prior;
    ar.world      = static_cast<int>(peers.numel());
    ar.rank       = static_cast<int>(rank);
    ar.calls      = static_cast<int *>(calls);
    for (int r = 0; r < ar.world; ++r) {
        ar.recv[r] = reinterpret_cast<void *>(peers.data_ptr<int64_t>()[r]);
    }
    return ar;
}

} // namespace infera_flash::glm5

// The DSA indexer up to its scores for bf16 weights as sglang holds them, row-major, in a layer
// kernel after attn_qkv_bf16 (the normed x and q_lora in its LDS), each step rounded to bf16 where
// sglang's kernels round (infera_attn's indexer_qk): q = q_lora wq_b^T and k = LayerNorm(x wk^T),
// RoPE (pairs (x[2i], x[2i + 1])) on the first 64 values of each, the Hadamard transform over 128
// times 128^-0.5, q to fp8 at a power-of-two scale per head, the heads' weights x weights_proj^T *
// 32^-0.5 * that scale * 128^-0.5, and k to fp8 into its token's slot of the index-K cache as
// aiter's indexer_k_quant_and_cache; then the scores on that cache through each row's page table
// (indexer_logits', Infera-Flash's ix::scores). Every block computes a 16-row group of wq_b, blocks
// 0-119 first a unit of wk's and weights_proj's rows split over K; blocks 0-31 then finish head b,
// block 32 k; then every wave of the grid scores a run of tiles.
#pragma once

#include "aklr/attention_bf16.h"

namespace infera_flash::glm5 {

struct IndexerBf16Params {
    const int64_t  *position;     // [M]
    const int64_t  *slot;         // [M] each token's key: page slot / INDEX_PAGE, key slot % INDEX_PAGE
    const bfloat16 *wq_b;         // [INDEX_HEADS * INDEX_DIM, Q_LORA_RANK] row-major
    const bfloat16 *wk;           // [INDEX_DIM, HIDDEN_SIZE]
    const bfloat16 *weights_proj; // [INDEX_HEADS, HIDDEN_SIZE]
    const bfloat16 *k_gamma;      // [INDEX_DIM] k_norm, a LayerNorm with bias
    const bfloat16 *k_beta;
    float           k_epsilon;
    const bfloat16 *cos; // [positions, QK_ROPE_DIM / 2]
    const bfloat16 *sin;
    // this layer's index-K cache: pages of INDEX_PAGE keys, their fp8 in aiter's preshuffled 16 x
    // 16 tiles (16 keys by 16 values), then their fp32 scales
    uint8_t        *ki;
    const int      *lens;       // [M] each row's positions, its token's own included
    const int      *page_table; // [M, table_width] each row's pages in position order
    int             table_width;
    bfloat16       *q;       // [M, INDEX_HEADS * INDEX_DIM] wq_b's output
    float          *partial; // [ix_bf16::UNITS][M][16] wk's and weights_proj's partial sums
    uint8_t        *q_fp8;   // [M, INDEX_HEADS, INDEX_DIM]
    float          *weights; // [M, INDEX_HEADS]
    float          *logits;  // [M, logits_stride] the scores of each row's first lens positions
    int             logits_stride;
};

} // namespace infera_flash::glm5

namespace infera_flash::glm5::ix_bf16 {

using ix::DIM;
using ix::HADAMARD_SCALE;
using ix::HEADS;
using ix::PAGE_BYTES;
using ix::Q_ROWS;
constexpr int PAGE      = Config::INDEX_PAGE;
constexpr int HALF_ROPE = Config::QK_ROPE_DIM / 2;
// wk's rows then weights_proj's, in 16-row groups, each split over K in SPLITS units: unit u on
// block u
constexpr int K_ROWS     = DIM + HEADS;
constexpr int SPLITS     = 12;
constexpr int SPLIT_K    = Config::HIDDEN_SIZE / SPLITS;
constexpr int UNITS      = K_ROWS / 16 * SPLITS;
constexpr int UNIT_STEPS = SPLIT_K / WAVES / 32; // a wave's quarter of a split, in 16 B steps of 32 K
// in attn_qkv_bf16's slots: a block's products out (its wq_b group and unit), its head or k out
constexpr int PRODUCTS_PACKET = 2;
constexpr int POST_PACKET     = 3;
constexpr int KEY_BLOCK       = HEADS; // blocks 0 .. HEADS - 1 finish head b, this one k
constexpr float HEAD_SCALE    = 0.17677669529663687f; // 32^-0.5
constexpr float FP8_MAX       = 448.0f;
constexpr int   TILES         = 8; // the scores' tiles in flight per wave
// the scores on the blocks past KEY_BLOCK: the heads' and k's own stores would hold theirs back
constexpr int   SCORE_BLOCK0  = KEY_BLOCK + 1;
constexpr int   SCORE_WAVES   = (Config::NUM_BLOCKS - SCORE_BLOCK0) * WAVES;
static_assert(Q_ROWS / 16 == Config::NUM_BLOCKS && UNITS <= QKV_GROUPS &&
              SPLIT_K % (32 * WAVES) == 0 && Q_B_PACKET < PRODUCTS_PACKET &&
              POST_PACKET < PACKETS_PER_SLOT && DIM == 2 * THREADS_PER_WARP &&
              WAVES == Config::MAX_NUM_TOKENS);

__device__ inline float bf16_round(float v) { return static_cast<float>(static_cast<bfloat16>(v)); }

// act_quant's ue8m0 scale, bit for bit: 2^ceil(log2(amax * (1 / 448)))
__device__ inline float round_scale(float amax) {
    const uint32_t bits = __float_as_uint(amax * (1.0f / FP8_MAX));
    const int      e    = static_cast<int>((bits >> 23) & 0xff) - 127 + ((bits & 0x7fffff) != 0);
    return __uint_as_float(static_cast<uint32_t>(e + 127) << 23);
}

// Lane l's pair (v0, v1), values 2l and 2l + 1 of a 128-vector at position pos: RoPE on the first
// HALF_ROPE pairs, then the Hadamard transform times 128^-0.5 (Sylvester order), each to bf16
template <typename Params>
__device__ inline void rope_hadamard(const Params &p, int64_t pos, float &v0, float &v1) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    if (lane < HALF_ROPE) {
        const float c = static_cast<float>(p.cos[pos * HALF_ROPE + lane]);
        const float s = static_cast<float>(p.sin[pos * HALF_ROPE + lane]);
        const float a = v0 * c - v1 * s;
        const float b = v1 * c + v0 * s;
        v0            = bf16_round(a);
        v1            = bf16_round(b);
    }
    // stride 1: within the lane; stride 2d: lane ^ d, the upper element taking partner - self
    float a = v0 + v1, b = v0 - v1;
#pragma unroll
    for (int d = 1; d < THREADS_PER_WARP; d <<= 1) {
        const float pa = __shfl_xor(a, d, THREADS_PER_WARP);
        const float pb = __shfl_xor(b, d, THREADS_PER_WARP);
        const bool  hi = lane & d;
        a              = hi ? pa - a : a + pa;
        b              = hi ? pb - b : b + pb;
    }
    v0 = bf16_round(a * HADAMARD_SCALE);
    v1 = bf16_round(b * HADAMARD_SCALE);
}

// A wave's K of unit u (its split u % SPLITS): K SPLIT_K / 4 wave + 8 g + 32 i of the split for
// lane (g, c), step i
__device__ inline int unit_k(int u) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    const int wave = threadIdx.x / THREADS_PER_WARP;
    return SPLIT_K * (u % SPLITS) + SPLIT_K / WAVES * wave + 8 * (lane / 16);
}

// What a wave of unit_out needs of unit u: lane (g, c) row c of 16-row group u / SPLITS of wk's
// rows then weights_proj's, at its unit_k
__device__ __forceinline__ void load_unit(const IndexerBf16Params &p, int u,
                                          uint32x4 (&w)[UNIT_STEPS]) {
    const int       row = 16 * (u / SPLITS) + threadIdx.x % 16;
    const bfloat16 *src = (row < DIM ? p.wk + static_cast<size_t>(row) * Config::HIDDEN_SIZE
                                     : p.weights_proj +
                                           static_cast<size_t>(row - DIM) * Config::HIDDEN_SIZE) +
                          unit_k(u);
#pragma unroll
    for (int i = 0; i < UNIT_STEPS; ++i) {
        w[i] = *reinterpret_cast<const uint32x4 *>(src + 32 * i);
    }
}

// Unit u's [M][16] partial sums from x [M][HIDDEN_SIZE] bf16 in LDS (rows LDS_ROW<HIDDEN_SIZE>
// apart): the waves' tiles added in wave order (group_store's), out in sc1 stores
template <int NUM_TOKENS>
__device__ __forceinline__ void unit_out(const IndexerBf16Params &p, const uint32x4 (&w)[UNIT_STEPS],
                                         const bfloat16 *x, GroupSmem<Config::MAX_NUM_TOKENS> &s,
                                         int u) {
    const int       tid  = threadIdx.x;
    const int       lane = tid % THREADS_PER_WARP;
    const bfloat16 *xk = x + min(lane % 16, NUM_TOKENS - 1) * LDS_ROW<Config::HIDDEN_SIZE> + unit_k(u);
    floatx4         acc = {};
#pragma unroll
    for (int i = 0; i < UNIT_STEPS; ++i) {
        const bfloat16x8 b = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b, acc,
                                                      0, 0, 0);
    }
    s.tiles[tid] = acc;
    block_sync_lds();
    if (tid < 16 * NUM_TOKENS) {
        const floatx4 *tile = s.tiles + 16 * (tid % 16 / 4) + tid / 16;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][tid % 4];
        }
        store_sc1(reinterpret_cast<uint32_t *>(p.partial + u * NUM_TOKENS * 16 + tid),
                  __float_as_uint(sum));
    }
    block_sync_lds();
}

// The products on this block once its attn_qkv_bf16 work is done (x normed in s.x on the blocks
// below QKV_GROUPS, q_lora in s.q on those from Q_B_BLOCK0; the others norm q_a once it is out):
// its unit, then wq_b's group `block` into p.q in sc1 stores; then PRODUCTS_PACKET
template <int NUM_TOKENS>
__device__ __forceinline__ void products(const AttnQkvBf16Params &a, const IndexerBf16Params &p,
                                         uint8_t *smem, uint32_t epoch) {
    AttnQkvBf16Smem &s     = *reinterpret_cast<AttnQkvBf16Smem *>(smem);
    const int        tid   = threadIdx.x;
    const int        block = blockIdx.x;
    uint32x4        *slots = static_cast<uint32x4 *>(a.workspace);
    uint32x4         w_q[BF16_STEPS<Q_LORA>];
    if (block < UNITS) {
        uint32x4 w[UNIT_STEPS];
        load_unit(p, block, w);
        load_group_bf16<Q_LORA>(p.wq_b, block, w_q);
        unit_out<NUM_TOKENS>(p, w, s.x, s.group, block);
    } else {
        load_group_bf16<Q_LORA>(p.wq_b, block, w_q);
    }
    if (block < Q_B_BLOCK0) {
        bfloat16 q_gamma[1][8];
        load_data<bfloat16, 8>(a.q_gamma + 8 * tid, q_gamma[0]);
        q_a_bf16_units<NUM_TOKENS>(a, s, q_gamma, slots, epoch); // every block's unit
    }
    group_out_bf16<Q_LORA, NUM_TOKENS, true>(w_q, s.q, s.group, p.q + 16 * block, Q_ROWS);
    publish(slots + block * PACKETS_PER_SLOT + PRODUCTS_PACKET, epoch);
}

// Head h of token m on its wave: RoPE, the transform, fp8 at act_quant's scale, and its weight
// (weights_proj's output in bf16, the rest in fp32 as the compiled head gate)
template <int NUM_TOKENS>
__device__ __forceinline__ void head_out(const IndexerBf16Params &p, int h, int m) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    // written by other XCDs: sc1 loads. Lane s < SPLITS: weights_proj's row h of split s
    const auto     q       = raw_buffer(p.q, NUM_TOKENS * Q_ROWS * sizeof(bfloat16));
    const auto     partial = raw_buffer(p.partial, UNITS * NUM_TOKENS * 16 * sizeof(float));
    const uint32_t pair =
        buffer_load_sc1<uint32_t>(q, (m * Q_ROWS + h * DIM + 2 * lane) * sizeof(bfloat16));
    const int   row  = DIM + h;
    const float part = lane < SPLITS ? buffer_load_sc1<float>(
                                           partial, (((row / 16 * SPLITS + lane) * NUM_TOKENS + m) *
                                                         16 +
                                                     row % 16) *
                                                        sizeof(float))
                                     : 0.0f;
    bfloat16 v[2];
    __builtin_memcpy(v, &pair, sizeof(pair));
    float v0 = static_cast<float>(v[0]), v1 = static_cast<float>(v[1]);
    rope_hadamard(p, p.position[m], v0, v1);
    const float amax  = fmaxf(WarpReduce<MaxOp>(fmaxf(fabsf(v0), fabsf(v1))), 1e-4f);
    const float scale = round_scale(amax);
    const float a     = fminf(fmaxf(v0 / scale, -FP8_MAX), FP8_MAX);
    const float b     = fminf(fmaxf(v1 / scale, -FP8_MAX), FP8_MAX);
    const auto  fp8   = static_cast<uint16_t>(__builtin_amdgcn_cvt_pk_fp8_f32(a, b, 0, false));
    store_sc1(reinterpret_cast<bfloat16 *>(p.q_fp8 + (m * HEADS + h) * DIM) + lane,
              __builtin_bit_cast(bfloat16, fp8));
    float w = 0.0f;
#pragma unroll
    for (int s = 0; s < SPLITS; ++s) {
        w += readlane(part, s);
    }
    if (lane == 0) {
        store_sc1(reinterpret_cast<uint32_t *>(p.weights + m * HEADS + h),
                  __float_as_uint(bf16_round(w) * HEAD_SCALE * scale * HADAMARD_SCALE));
    }
}

// k of token m on its wave: its splits added in order, to bf16 as sglang's linear leaves it,
// k_norm, RoPE and the transform, then into its slot's page at aiter's scale, the power of two at
// or above amax / 448 (the fp32 quotient)
template <int NUM_TOKENS>
__device__ __forceinline__ void key_out(const IndexerBf16Params &p, int m) {
    const int  lane    = threadIdx.x % THREADS_PER_WARP;
    const auto partial = raw_buffer(p.partial, UNITS * NUM_TOKENS * 16 * sizeof(float));
    // rows 2 lane and 2 lane + 1 of wk: rows 2 (lane % 8) .. of group lane / 8
    uint2 parts[SPLITS];
#pragma unroll
    for (int s = 0; s < SPLITS; ++s) {
        parts[s] = buffer_load_sc1<uint2>(
            partial, (((lane / 8 * SPLITS + s) * NUM_TOKENS + m) * 16 + 2 * (lane % 8)) * sizeof(float));
    }
    float k0 = 0.0f, k1 = 0.0f;
#pragma unroll
    for (int s = 0; s < SPLITS; ++s) {
        k0 += __uint_as_float(parts[s].x);
        k1 += __uint_as_float(parts[s].y);
    }
    k0 = bf16_round(k0);
    k1 = bf16_round(k1);
    // k_norm, a LayerNorm with bias, in fp32
    const float mean = WarpReduce<SumOp>(k0 + k1) * (1.0f / DIM);
    const float d0 = k0 - mean, d1 = k1 - mean;
    const float inv  = rsqrtf(WarpReduce<SumOp>(d0 * d0 + d1 * d1) * (1.0f / DIM) + p.k_epsilon);
    k0 = bf16_round(d0 * inv * static_cast<float>(p.k_gamma[2 * lane]) +
                    static_cast<float>(p.k_beta[2 * lane]));
    k1 = bf16_round(d1 * inv * static_cast<float>(p.k_gamma[2 * lane + 1]) +
                    static_cast<float>(p.k_beta[2 * lane + 1]));
    rope_hadamard(p, p.position[m], k0, k1);
    const float    amax  = WarpReduce<MaxOp>(fmaxf(fabsf(k0), fabsf(k1)));
    const uint32_t r     = __float_as_uint(__fdiv_rn(fmaxf(amax, 1e-4f), FP8_MAX));
    const uint32_t e     = (r >> 23) + ((r & 0x7fffff) != 0);
    const float    inv_s = __uint_as_float((254 - e) << 23);
    const int64_t  slot  = p.slot[m];
    const int      o     = static_cast<int>(slot % PAGE);
    uint8_t       *page  = p.ki + slot / PAGE * PAGE_BYTES;
    const auto     fp8 =
        static_cast<uint16_t>(__builtin_amdgcn_cvt_pk_fp8_f32(k0 * inv_s, k1 * inv_s, 0, false));
    // read back in this kernel by other XCDs: sc1 stores
    store_sc1(reinterpret_cast<bfloat16 *>(page + o / 16 * 16 * DIM + lane / 8 * 256 + o % 16 * 16 +
                                           2 * (lane % 8)),
              __builtin_bit_cast(bfloat16, fp8));
    if (lane == 0) {
        store_sc1(reinterpret_cast<uint32_t *>(page + PAGE * DIM + 4 * o), e << 23);
    }
}

// Blocks 0 .. KEY_BLOCK once every block's products are out: wave m < M token m's head `block`, or
// its key; then POST_PACKET
template <int NUM_TOKENS>
__device__ __forceinline__ void finish_qk(const IndexerBf16Params &p, uint32x4 *slots,
                                          uint32_t epoch) {
    const int block = blockIdx.x;
    const int m     = threadIdx.x / THREADS_PER_WARP;
    wait_for(slots, PRODUCTS_PACKET, 0, Config::NUM_BLOCKS, epoch);
    if (m < NUM_TOKENS) {
        if (block < KEY_BLOCK) {
            head_out<NUM_TOKENS>(p, block, m);
        } else {
            key_out<NUM_TOKENS>(p, m);
        }
    }
    publish(slots + block * PACKETS_PER_SLOT + POST_PACKET, epoch);
}

struct ScoresSmem {
    int32x4 q[Config::MAX_NUM_TOKENS * HEADS * DIM / 16];
    floatx4 w[Config::MAX_NUM_TOKENS * HEADS / 4];
};
// past ScoresSmem: the block's round-0 counts of each row's scores, [row][top 8 bits of its key]
constexpr int R0_AT = sizeof(ScoresSmem);
static_assert(R0_AT + Config::MAX_NUM_TOKENS * 256 * 4 <= Config::SMEM_SIZE);

// the block scoring tile t of `tiles`, 16-key tiles of the longest row in runs over the scoring
// waves
__device__ inline int score_block(int t, int tiles) {
    const int run = (tiles + SCORE_WAVES - 1) / SCORE_WAVES;
    return SCORE_BLOCK0 + t / run / WAVES;
}

// The scores (indexer_logits', from Infera-Flash's ix::scores) once q and the weights are out
// (POST_PACKET of blocks 0 .. KEY_BLOCK - 1), and the keys (KEY_BLOCK's) for a block reading one of
// this call's: logits[m][t] = s(t) sum_h w[m][h] relu(<q[m][h], k(t)>) for t < lens[m], in sc1
// stores. Every scoring wave takes a run of 16-key tiles of the longest row, read once from its
// pages when the rows reaching the run have those pages there (one request's rows), else each such
// row reads its own; a tile holding a key of this call's (written on another XCD) is read with sc1.
// A tile is one MFMA B operand against 16 heads of q (LDS), so lane l holds 4 heads of key l % 16
// and adds them in place; two lane swaps add the 4 rows, leaving row r with token r's sums. Rows of
// at most INDEX_TOPK need none (their top-k is all of them): none at all when no row is longer.
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t scores(const IndexerBf16Params &p, uint8_t *smem,
                                           const uint32x4 *slots, uint32_t epoch) {
    ScoresSmem &s    = *reinterpret_cast<ScoresSmem *>(smem);
    const int   tid  = threadIdx.x;
    const int   lane = tid % THREADS_PER_WARP;
    const int   sb   = static_cast<int>(blockIdx.x) - SCORE_BLOCK0; // among the scoring blocks
    const int   wave = __builtin_amdgcn_readfirstlane(sb * WAVES + tid / THREADS_PER_WARP);
    int len[NUM_TOKENS];
    int fresh[NUM_TOKENS]; // the 16-key tile (slot / 16) of each token's key
    int base = 0;          // the longest row
#pragma unroll
    for (int n = 0; n < NUM_TOKENS; ++n) {
        len[n]   = __builtin_amdgcn_readfirstlane(p.lens[n]);
        fresh[n] = __builtin_amdgcn_readfirstlane(static_cast<int>(p.slot[n] / 16));
        base     = len[n] > len[base] ? n : base;
    }
    if (sb < 0 || len[base] <= Config::INDEX_TOPK) {
        return 0u;
    }
    const int tiles = (len[base] + 15) / 16;
    const int run   = (tiles + SCORE_WAVES - 1) / SCORE_WAVES;
    const int first = wave * run;
    const int last  = min(first + run, tiles);
    // a block whose first wave has no tiles has none
    if (sb * WAVES * run >= tiles) {
        return 0u;
    }
    // the rows past TOPK get the block's round-0 counts (R0_AT), each a key's top 8 bits
    uint32_t r0_rows = 0u;
#pragma unroll
    for (int n = 0; n < NUM_TOKENS; ++n) {
        r0_rows |= len[n] > Config::INDEX_TOPK ? 1u << n : 0u;
    }
    uint32_t *const r0_counts = reinterpret_cast<uint32_t *>(smem + R0_AT);
    for (int i = threadIdx.x; i < NUM_TOKENS * 256; i += Config::BLOCK_SIZE) {
        r0_counts[i] = 0u;
    }
    const auto page = [&](int n, int key) { return p.page_table[n * p.table_width + key / PAGE]; };
    // lane l's B operand of the tile of `key` (a multiple of 16) in page pg: key l % 16, values
    // 16 (l / 16) .. and 64 + 16 (l / 16) ..; and that key's scale
    const auto load_tile = [&](int pg, int key, int32x8 &k, float &sk) {
        const uint8_t *src = p.ki + static_cast<size_t>(pg) * PAGE_BYTES;
        const int      at  = key % PAGE / 16 * 16 * DIM + lane / 16 * 256 + lane % 16 * 16;
        const int      sat = PAGE * DIM + 4 * (key % PAGE + lane % 16);
        bool           own = false;
#pragma unroll
        for (int n = 0; n < NUM_TOKENS; ++n) {
            own |= pg * (PAGE / 16) + key % PAGE / 16 == fresh[n];
        }
        if (own) {
            const auto buf = raw_buffer(src, PAGE_BYTES);
            const auto lo  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at));
            const auto hi  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at + 1024));
            k              = __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
            sk             = buffer_load_sc1<float>(buf, sat);
        } else {
            k  = load_fragment(src + at, src + at + 1024);
            sk = *reinterpret_cast<const float *>(src + sat);
        }
    };
    int32x8    k[TILES];
    float      sk[TILES];
    const auto load_batch = [&](int t) {
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            const int key = 16 * min(t + j, last - 1);
            load_tile(page(base, key), key, k[j], sk[j]);
        }
    };
    // only a block whose keys, in any row, hold one of this call's waits for KEY_BLOCK's k and
    // loads after it (a line read before k is out may be read again stale); the others load their
    // first tiles while the heads are finished. And whether the rows reaching the block's pages
    // have the longest row's there
    const int k0     = 16 * sb * WAVES * run;
    const int k1     = min(k0 + 16 * WAVES * run, 16 * tiles);
    const int span   = (k1 - 1) / PAGE - k0 / PAGE + 1; // its pages in a row
    bool      with_k = false;
    bool      differ = false;
    for (int i = lane; i < NUM_TOKENS * span; i += THREADS_PER_WARP) {
        const int n   = i / span;
        const int key = (k0 / PAGE + i % span) * PAGE;
        if (key < len[n]) {
            const int pg = page(n, key);
            differ |= pg != page(base, key);
#pragma unroll
            for (int t = 0; t < NUM_TOKENS; ++t) {
                const int at = key + static_cast<int>(p.slot[t] % PAGE);
                with_k |= pg == static_cast<int>(p.slot[t] / PAGE) && at >= k0 && at < k1 &&
                          at < len[n];
            }
        }
    }
    with_k           = __ballot(with_k) != 0;
    const bool agree = __ballot(differ) == 0;
    // The rows agreeing: a batch's pages in s_loads (lgkmcnt; the table not written during the call), its tiles in
    // straight-line loads, sc1 ones (right for any tile) or plain ones (in a block holding none of this call's keys)
    const auto table  = (const __attribute__((address_space(4))) int *)p.page_table + base * p.table_width;
    const int  last_e = (last - 1) / 4; // the last tile's page-table entry
    const auto load_as = [&](auto sc1, int pg, int key, int32x8 &kt, float &st) {
        const uint8_t *src = p.ki + static_cast<size_t>(pg) * PAGE_BYTES;
        const int      at  = key % PAGE / 16 * 16 * DIM + lane / 16 * 256 + lane % 16 * 16;
        const int      sat = PAGE * DIM + 4 * (key % PAGE + lane % 16);
        if constexpr (decltype(sc1)::value) {
            const auto buf = raw_buffer(src, PAGE_BYTES);
            const auto lo  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at));
            const auto hi  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at + 1024));
            kt             = __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
            st             = buffer_load_sc1<float>(buf, sat);
        } else {
            kt = load_fragment(src + at, src + at + 1024);
            st = *reinterpret_cast<const float *>(src + sat);
        }
    };
    // the first batch, past the last tile its last again: entries first / 4 .. + 2 (none past the last tile's)
    const auto load_first = [&](auto sc1) {
        const int e0  = first / 4;
        const int np0 = table[e0];
        const int np1 = table[min(e0 + 1, last_e)];
        const int np2 = table[min(e0 + 2, last_e)];
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            const int u = min(first + j, last - 1);
            const int e = u / 4 - e0;
            load_as(sc1, e == 0 ? np0 : e == 1 ? np1 : np2, 16 * u, k[j], sk[j]);
        }
    };
    if (!with_k && first < last) {
        if (agree) {
            load_first(std::false_type{});
        } else {
            load_batch(first);
        }
    }
    // q and the weights into LDS once a block, written by other XCDs: sc1 loads
    wait_for(slots, POST_PACKET, 0, with_k ? KEY_BLOCK + 1 : KEY_BLOCK, epoch);
    {
        constexpr int Q_LOADS = NUM_TOKENS * HEADS * DIM / 16 / Config::BLOCK_SIZE;
        const auto    q_buf   = raw_buffer(p.q_fp8, NUM_TOKENS * HEADS * DIM);
        uint32x4      q_in[Q_LOADS];
#pragma unroll
        for (int i = 0; i < Q_LOADS; ++i) {
            q_in[i] = buffer_load_sc1(q_buf, 16 * (tid + i * Config::BLOCK_SIZE));
        }
        if (tid < NUM_TOKENS * HEADS / 4) {
            const auto w_buf = raw_buffer(p.weights, NUM_TOKENS * HEADS * sizeof(float));
            s.w[tid]         = __builtin_bit_cast(floatx4, buffer_load_sc1(w_buf, 16 * tid));
        }
#pragma unroll
        for (int i = 0; i < Q_LOADS; ++i) {
            s.q[tid + i * Config::BLOCK_SIZE] = __builtin_bit_cast(int32x4, q_in[i]);
        }
    }
    __syncthreads();
    if (first >= last) {
        return r0_rows;
    }
    // A operands: heads 16 g + lane % 16 of token n; the weights of heads 16 g + 4 (lane / 16) + i
    int32x8 q[NUM_TOKENS][2];
    floatx2 w[NUM_TOKENS][2][2];
#pragma unroll
    for (int n = 0; n < NUM_TOKENS; ++n) {
#pragma unroll
        for (int g = 0; g < 2; ++g) {
            const int row = n * HEADS + 16 * g + lane % 16;
            q[n][g]       = __builtin_shufflevector(s.q[row * DIM / 16 + lane / 16],
                                                    s.q[row * DIM / 16 + 4 + lane / 16], 0, 1, 2, 3, 4,
                                                    5, 6, 7);
            const floatx4 wg = s.w[(n * HEADS + 16 * g) / 4 + lane / 16];
            w[n][g][0]       = floatx2{wg[0], wg[1]};
            w[n][g][1]       = floatx2{wg[2], wg[3]};
        }
    }
    // lane l writes token l / 16's score of the tile's key l % 16
    const int m       = lane / 16;
    int       row_len = len[0];
#pragma unroll
    for (int n = 1; n < NUM_TOKENS; ++n) {
        row_len = m == n ? len[n] : row_len;
    }
    const auto relu = [](float x) { return __int_as_float(max(__float_as_int(x), 0)); };
    // the tile of `key` against each token n's own kn[n] (every MFMA out before the first result is
    // used): token n's 8 heads of the lane against key l % 16, weighed, times its scale; then row r
    // of lanes adds up token r's
    const auto finish = [&](int key, const int32x8 (&kn)[NUM_TOKENS],
                            const float (&sn)[NUM_TOKENS]) {
        floatx4 d[NUM_TOKENS][2];
#pragma unroll
        for (int n = 0; n < NUM_TOKENS; ++n) {
#pragma unroll
            for (int g = 0; g < 2; ++g) {
                d[n][g] = mfma_16x16x128_fp8(q[n][g], kn[n]);
            }
        }
        float v[4] = {};
#pragma unroll
        for (int n = 0; n < NUM_TOKENS; ++n) {
            floatx2 acc = {};
#pragma unroll
            for (int g = 0; g < 2; ++g) {
                acc = __builtin_elementwise_fma(w[n][g][0],
                                                floatx2{relu(d[n][g][0]), relu(d[n][g][1])}, acc);
                acc = __builtin_elementwise_fma(w[n][g][1],
                                                floatx2{relu(d[n][g][2]), relu(d[n][g][3])}, acc);
            }
            v[n] = (acc[0] + acc[1]) * sn[n];
        }
        const float total = ix::swap_add16(ix::swap_add32(v[0], v[2]), ix::swap_add32(v[1], v[3]));
        if (m < NUM_TOKENS && key + lane % 16 < row_len) {
            const uint32_t k = ix::score_key(total);
            store_sc1(reinterpret_cast<uint32_t *>(p.logits + m * p.logits_stride + key + lane % 16), k);
            if (row_len > Config::INDEX_TOPK) {
                topk::lds_add(r0_counts + m * 256 + (k >> 24), 1u);
            }
        }
    };
    // The rows agreeing (one request's): rolled. Tile j's registers take the batch after's tile j as soon as tile
    // j's scores are out, so that batch loads during this one's MFMAs, and each tile then waits for its own loads
    // alone (vmcnt counts in order: straight-line loads, their pages s_loads before the pass). A block holding one
    // of this call's keys reads every tile with sc1, the others plain.
    if (agree) {
        const auto tile = [&](int j, int key) {
            int32x8 kn[NUM_TOKENS];
            float   sn[NUM_TOKENS];
#pragma unroll
            for (int n = 0; n < NUM_TOKENS; ++n) {
                kn[n] = k[j];
                sn[n] = sk[j];
            }
            finish(key, kn, sn);
        };
        const auto rolled = [&](auto sc1) {
            if (with_k) {
                load_first(sc1);
            }
            __builtin_amdgcn_s_waitcnt(0x0F70); // vmcnt(0): the first batch in before the first store
            int t = first;
            for (; t + TILES < last; t += TILES) {
                // the batch after's pages: its tiles' entries e0 .. e0 + 2 (none past the last tile's)
                const int e0  = (t + TILES) / 4;
                const int np0 = table[e0];
                const int np1 = table[min(e0 + 1, last_e)];
                const int np2 = table[min(e0 + 2, last_e)];
#pragma unroll
                for (int j = 0; j < TILES; ++j) {
                    tile(j, 16 * (t + j));
                    // past the last tile its last again, not scored
                    const int u = min(t + TILES + j, last - 1);
                    const int e = u / 4 - e0;
                    load_as(sc1, e == 0 ? np0 : e == 1 ? np1 : np2, 16 * u, k[j], sk[j]);
                }
            }
#pragma unroll
            for (int j = 0; j < TILES; ++j) {
                if (t + j >= last) {
                    break;
                }
                tile(j, 16 * (t + j));
            }
        };
        if (with_k) {
            rolled(std::true_type{});
        } else {
            rolled(std::false_type{});
        }
        return r0_rows;
    }
    for (int t = first; t < last; t += TILES) {
        if (t != first || with_k) {
            load_batch(t);
        }
        __builtin_amdgcn_s_waitcnt(0x0F70); // vmcnt(0): every tile in before the first store
        // OWN: the other rows read their own pages, so each tile's MFMAs wait for those loads, and
        // the score stores before them; the rows agreeing, nothing waits
        const auto pass = [&](auto own) {
#pragma unroll
            for (int j = 0; j < TILES; ++j) {
                if (t + j >= last) {
                    break;
                }
                const int key = 16 * (t + j);
                int32x8   kn[NUM_TOKENS];
                float     sn[NUM_TOKENS];
#pragma unroll
                for (int n = 0; n < NUM_TOKENS; ++n) {
                    if (decltype(own)::value && n != base && key < len[n]) {
                        load_tile(page(n, key), key, kn[n], sn[n]);
                    } else {
                        kn[n] = k[j];
                        sn[n] = sk[j];
                    }
                }
                finish(key, kn, sn);
            }
        };
        if (agree) {
            pass(std::false_type{});
        } else {
            pass(std::true_type{});
        }
    }
    return r0_rows;
}

} // namespace infera_flash::glm5::ix_bf16

// What the indexer layers' kernels share (attn_ix_layer/kernel*.hip): their state, index_topk's
// rows in them (topk_block) and mla_core's work after the top-k (mla_after_topk).
#pragma once

#include "aklr/attention_layer.h"
#include "aklr/indexer_bf16.h"

namespace infera_flash::glm5 {

template <typename AttnQkvParams, typename IndexerParams> struct AttentionIndexerParams {
    AttnQkvParams   attn;
    IndexerParams   ix;
    IndexTopkParams topk;
    MlaCoreParams   mla;
    RowLinearParams o_proj;
};

// an indexer layer's kernel: its state's attn_qkv sync slots, then those of the scores and top-k,
// mla_core's, o_proj's all-reduce call number per block, o's packets (MlaCoreParams::out_tagged),
// then index_topk's exchange
struct IndexerState {
    static constexpr int64_t IX     = WORKSPACE_SIZE;
    static constexpr int64_t MLA    = 2 * WORKSPACE_SIZE;
    static constexpr int64_t CALLS  = 3 * WORKSPACE_SIZE;
    static constexpr int64_t TAGGED = CALLS + Config::NUM_BLOCKS * sizeof(int);
    static constexpr int64_t TOPK =
        TAGGED + Config::MAX_NUM_TOKENS * Config::O_PROJ_K / 4 * sizeof(uint32x4);
    static constexpr int64_t BYTES = TOPK + sizeof(topk::IndexTopkState);
};

// in the indexer's slots: a block's scores are out (every block, every call)
constexpr int SCORES_PACKET = 0;

// A scoring block's round-0 counts (ix_bf16::scores's, rows `rows`) added into each row's (IndexTopkState::r0_hist) in
// device-scope atomics, before the scores' packet waits for its stores (and so for these); r0_arrive, past that
// packet, counts the block in for each of those rows
template <int NUM_TOKENS>
__device__ __forceinline__ void r0_flush(const IndexTopkParams &p, const uint8_t *smem, uint32_t rows) {
    if (rows == 0u) {
        return;
    }
    __syncthreads(); // every wave's counts in
    auto           &g      = *static_cast<topk::IndexTopkState *>(p.state);
    const uint32_t *counts = reinterpret_cast<const uint32_t *>(smem + ix_bf16::R0_AT);
    const int       tid    = threadIdx.x;
#pragma unroll
    for (int n = 0; n < NUM_TOKENS; ++n) {
        const uint32_t v = counts[n * topk::BINS + tid];
        if ((rows >> n & 1u) && v) {
            __hip_atomic_fetch_add(&g.r0_hist[n][tid], v, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
        }
    }
}

template <int NUM_TOKENS> __device__ __forceinline__ void r0_arrive(const IndexTopkParams &p, uint32_t rows) {
    auto     &g   = *static_cast<topk::IndexTopkState *>(p.state);
    const int tid = threadIdx.x;
    if (tid < NUM_TOKENS && (rows >> tid & 1u)) {
        __hip_atomic_fetch_add(&g.r0_arrived[tid][0], 1u, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    }
}
// the longest row the top-k takes
constexpr int MAX_LEN = topk::ROW_BLOCKS * Config::BLOCK_SIZE * topk::MAX_KPT;

// The KPT class (keys a thread, 16 << c) that holds a row of len scores: by the row, not the
// scores' width, which sglang sizes for the longest context
__device__ __forceinline__ int kpt_class_of(int len) {
    const int per = (len + topk::ROW_BLOCKS * Config::BLOCK_SIZE - 1) /
                    (topk::ROW_BLOCKS * Config::BLOCK_SIZE);
    int c = 0;
    while (c < topk::KPT_CLASSES - 1 && topk::kpt_of(c) < per) {
        ++c;
    }
    return c;
}

// Block (m, j) = (b % 8, b / 8) of row m < M's top-k in its row's KPT class, once the blocks
// scoring its slice are out (SCORES_PACKET), each pick also out with the epoch
// (IndexTopkState::picks) for the attending blocks
template <int NUM_TOKENS>
__device__ __forceinline__ void topk_block(const IndexTopkParams &p, uint8_t *smem, uint32x4 *slots,
                                           uint32_t epoch) {
    const int len = p.lens[blockIdx.x % topk::XCDS];
    if (len > MAX_LEN) {
        __builtin_trap(); // past every KPT class: the contract's rows are at most 2^20
    }
    const auto wait_scores = [&](int from, int n) {
        int longest = 0;
#pragma unroll
        for (int r = 0; r < NUM_TOKENS; ++r) {
            longest = max(longest, p.lens[r]);
        }
        const int tiles = (longest + 15) / 16;
        const int first = ix_bf16::score_block(from / 16, tiles);
        const int last  = ix_bf16::score_block((from + n - 1) / 16, tiles);
        wait_for(slots, SCORES_PACKET, first, last - first + 1, epoch);
    };
    // the blocks scoring, each adding its round-0 counts (ix_bf16::scores's split of the longest row's tiles)
    int longest = 0;
#pragma unroll
    for (int r = 0; r < NUM_TOKENS; ++r) {
        longest = max(longest, p.lens[r]);
    }
    const int tiles       = (longest + 15) / 16;
    const int run         = (tiles + ix_bf16::SCORE_WAVES - 1) / ix_bf16::SCORE_WAVES;
    const int r0_expected = (tiles + WAVES * run - 1) / (WAVES * run);
    static_assert(topk::KPT_CLASSES == 4, "a case per KPT class");
    switch (kpt_class_of(len)) {
    case 0:
        topk::index_topk_row<NUM_TOKENS, topk::kpt_of(0), true>(p, smem, epoch, r0_expected, wait_scores);
        break;
    case 1:
        topk::index_topk_row<NUM_TOKENS, topk::kpt_of(1), true>(p, smem, epoch, r0_expected, wait_scores);
        break;
    case 2:
        topk::index_topk_row<NUM_TOKENS, topk::kpt_of(2), true>(p, smem, epoch, r0_expected, wait_scores);
        break;
    default:
        topk::index_topk_row<NUM_TOKENS, topk::kpt_of(3), true>(p, smem, epoch, r0_expected, wait_scores);
    }
}

// mla_core's work on this block after the top-k's, at this call's epoch (slots: mla_core's), its
// roles around the top-k on XCDs 0 .. M - 1 (mla::mla_ix_block's): q, kv, k_pe and the top-k were
// written earlier in the kernel on other XCDs, so the blocks wait for them (attn_slots at
// attn_epoch, each entry of the top-k showing ix_epoch) and read them with sc1. XCDs 4-7 (b % 8 >=
// 4) compute q_latent's group pair j = 4 (b / 8) + b % 8 - 4 once q_b's groups are out; then token
// m = b % 8 - 4 < M's chunk b / 8: this call's rows built (normalizing kv themselves) and q staged
// while the top-k runs, each row read as soon as its entry is out. XCDs 0-3, free once their top-k
// is done, run prefetch() and then combine j = 4 (b / 8) + b % 8, o out also as the packets o_proj
// polls. Packet 0 every call (XCDs 4-7: q_latent out), packet 1 only from the attending blocks
// (their partial sums). Returns o_proj's last call number, in an SGPR as layer.hip's: XCDs 0-3 read
// it before combine, as its read would wait for combine's stores. W_BF16: W_UK and W_UV bf16,
// without a scale.
template <int NUM_TOKENS, bool W_BF16, typename Params, typename Prefetch>
__device__ __forceinline__ uint32_t mla_after_topk(const Params &p, uint8_t *smem,
                                                   const uint32x4 *attn_slots, uint32_t attn_epoch,
                                                   uint32_t ix_epoch, uint32x4 *slots, uint32_t epoch,
                                                   Prefetch prefetch) {
    const MlaCoreParams &ml      = p.mla;
    mla::MlaCoreSmem    &s       = *reinterpret_cast<mla::MlaCoreSmem *>(smem);
    mla::MlaCoreScratch &x       = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
    const auto          &g       = *static_cast<const topk::IndexTopkState *>(p.topk.state);
    const int            tid     = threadIdx.x;
    const int            block   = blockIdx.x;
    const int            xcd     = block % mla::XCDS;
    uint32x4            *my_slot = slots + block * PACKETS_PER_SLOT;
    const auto           post    = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
        }
    };
    const auto o_proj_call = [&] { return __builtin_amdgcn_readfirstlane(last_call(p.o_proj.ar)); };
    if (xcd < mla::HALF_XCDS) {
        post();
        const int j = mla::HALF_XCDS * (block / mla::XCDS) + xcd;
        uint32x4  w_v[mla::Project<NUM_TOKENS>::REGS * (W_BF16 ? 2 : 1)];
        mla::project_wv<NUM_TOKENS, W_BF16>(ml, j, w_v);
        prefetch();
        const uint32_t call = o_proj_call();
        asm volatile("" ::"s"(call) : "memory"); // read here: the compiler would sink it past combine
        mla::combine<NUM_TOKENS, true, true, W_BF16>(ml, s, x, j, w_v, slots, epoch,
                                                     mla::PARTIAL_SUMS_PACKET);
        return call;
    }
    const int j = mla::HALF_XCDS * (block / mla::XCDS) + xcd - mla::HALF_XCDS;
    uint32x4 w_k[mla::WK_LOADS<W_BF16>]; // W_UK's loads before the wait
    mla::project_q_weights<W_BF16>(ml, j, w_k);
    wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
    mla::project_q_w<NUM_TOKENS, true, W_BF16>(ml, x, j, w_k);
    post();
    const int m = xcd - mla::HALF_XCDS;
    if (m >= NUM_TOKENS) {
        return o_proj_call();
    }
    wait_kv_units(attn_slots, attn_epoch); // kv's and k_pe's units
    mla::fresh_rows<NUM_TOKENS, true>(ml, s, [&](int t, int lane, bfloat16(&lat)[8]) {
        kv_row_sglang<NUM_TOKENS>(p.attn, t, lane, lat);
    });
    mla::turn_q_pe<true>(ml, s, m);
    wait_for(
        slots, 0, Config::NUM_BLOCKS / 2,
        [](int t) { return mla::XCDS * (t / mla::HALF_XCDS) + mla::HALF_XCDS + t % mla::HALF_XCDS; },
        epoch); // q_latent
    mla::stage_q_latent(s, x, m);
    block_sync_lds(); // the rows and q staged above
    mla::AttendRows r;
    mla::attend_rows(ml, m, block / mla::XCDS, r,
                     [&](int at) { return topk::tagged_pick(g, at, ix_epoch); });
    mla::attend_c<NUM_TOKENS, true>(ml, s, x, m, block / mla::XCDS, r);
    publish(my_slot + mla::PARTIAL_SUMS_PACKET, epoch);
    if (j == 0) {
        mla::write_fresh<NUM_TOKENS>(ml, s);
        __syncthreads(); // o_proj's x overwrites s.fresh
    }
    return o_proj_call();
}

} // namespace infera_flash::glm5

// sglang's RMSNorm (aiter's rmsnorm2d) of M rows, each thread holding LOADS x 8 values of every row
// (rms_norm's layout, common/math.h): x = bf16(x rsqrt(sum(x^2) / N + eps) gamma), rounded once.
#pragma once

#include "common/math.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// LDS_ONLY: BlockReduce's
template <int NUM_TOKENS, int LOADS, bool LDS_ONLY>
__device__ __forceinline__ void rms_norm_sglang(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                                const bfloat16 (&gamma)[LOADS][8], float eps,
                                                float *reduce) {
    constexpr int N = LOADS * 8 * Config::BLOCK_SIZE;
    float         sums[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            add_squares(sum2, x[m][i]);
        }
        sums[m] = sum2.x + sum2.y;
    }
    BlockReduce<SumOp, Config::BLOCK_SIZE, LDS_ONLY>(sums, reduce);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const float factor = rsqrtf(sums[m] / N + eps);
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
#pragma unroll
            for (int j = 0; j < 8; ++j) {
                x[m][i][j] = static_cast<bfloat16>(static_cast<float>(x[m][i][j]) * factor *
                                                   static_cast<float>(gamma[i][j]));
            }
        }
    }
}

} // namespace infera_flash::glm5

// row_linear_ar (glm5/mlp.h) in a layer kernel, for a bf16 weight as sglang holds it, row-major: x
// [M, K] times the weight [HIDDEN_SIZE, K] in bf16 products (as sglang's tgemm), on row_linear_ar's
// row split (block k owns output rows 24k .. 24k + 23, waves 0 and 2 taking the first half of K and
// waves 1 and 3 the second), then its all-reduce (world 1: none) and any residual.
#pragma once

#include "glm5/mlp.h"

namespace infera_flash::glm5 {

// x's rows padded by 16 B: rows a multiple of 64 banks apart would put the tokens' reads of one K
// in one bank
template <int K> struct RowLinearBf16Smem {
    static constexpr int ROW = K + 8;
    bfloat16             x[Config::MAX_NUM_TOKENS * ROW];
    RowsSmem             rows;
};

// a lane's 16 B steps of the weight: a wave takes half of K
template <int K> constexpr int ROW_LINEAR_STEPS = K / 2 / 32;

// This block's weights for row_linear_bf16 (p.weight the bf16 [HIDDEN_SIZE, K]) into w, the loads
// only issued: lane (g, c) its wave's group's row split_row, K k0 + 32 i + 8 g .. + 7 for step i
// (lm_head's layout)
template <int K>
__device__ __forceinline__ void row_linear_bf16_weights(const RowLinearParams &p,
                                                        uint32x4 (&w)[ROW_LINEAR_STEPS<K>]) {
    const int       lane  = threadIdx.x % THREADS_PER_WARP;
    const int       wave  = __builtin_amdgcn_readfirstlane(threadIdx.x / THREADS_PER_WARP);
    const bfloat16 *w_row = reinterpret_cast<const bfloat16 *>(p.weight) +
                            static_cast<size_t>(split_group(wave) * 16 + split_row(wave, lane)) * K +
                            wave % 2 * (K / 2) + 8 * (lane / 16);
#pragma unroll
    for (int i = 0; i < ROW_LINEAR_STEPS<K>; ++i) {
        w[i] = *reinterpret_cast<const uint32x4 *>(w_row + 32 * i);
    }
}

// This block's rows of row_linear_bf16's weight (block k's 24, contiguous), read once and dropped
// by the block while it is idle, so they wait in its XCD's L2
template <int K>
__device__ __forceinline__ void row_linear_bf16_prefetch(const RowLinearParams &p) {
    constexpr int  BYTES = Config::HIDDEN_SIZE / Config::NUM_BLOCKS * K * sizeof(bfloat16);
    const uint8_t *src   = p.weight + static_cast<size_t>(blockIdx.x) * BYTES + 16 * threadIdx.x;
    uint32x4       sink  = {};
#pragma unroll
    for (int i = 0; i < BYTES / (16 * Config::BLOCK_SIZE); ++i) {
        asm volatile("global_load_dwordx4 %0, %1, off"
                     : "+v"(sink)
                     : "v"(src + 16 * Config::BLOCK_SIZE * i)
                     : "memory");
    }
    asm volatile("s_waitcnt vmcnt(0)" ::"v"(sink) : "memory");
}

// row_linear_bf16's work on this block, last_call its all-reduce's last call number: w holds
// row_linear_bf16_weights's, issued earlier, and x comes as packets written earlier in the same
// kernel on other XCDs (p.x_tagged: 4 values and the writers' epoch in 16 B), each loaded until it
// shows x_epoch.
template <int K, int NUM_TOKENS>
__device__ __forceinline__ void row_linear_bf16_rows(const RowLinearParams &p, uint8_t *smem,
                                                     uint32_t last_call,
                                                     uint32x4 (&w)[ROW_LINEAR_STEPS<K>],
                                                     uint32_t x_epoch) {
    constexpr int WAVE_K = K / 2;
    constexpr int STEPS  = ROW_LINEAR_STEPS<K>;
    static_assert(K % 256 == 0 && sizeof(RowLinearBf16Smem<K>) <= Config::SMEM_SIZE);

    RowLinearBf16Smem<K> &s = *reinterpret_cast<RowLinearBf16Smem<K> *>(smem);

    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = __builtin_amdgcn_readfirstlane(tid / THREADS_PER_WARP);
    const int k0   = wave % 2 * WAVE_K;

    const float residual = all_reduce_residual<NUM_TOKENS>(p.ar);
    // thread t: x's 16 B chunks t + 256 i
    constexpr int ROW     = RowLinearBf16Smem<K>::ROW;
    constexpr int X_LOADS = NUM_TOKENS * K / 8 / Config::BLOCK_SIZE;
    static_assert(K / 8 % Config::BLOCK_SIZE == 0);
    uint32x4 x[X_LOADS];
    {
        // chunk c from packets 2c and 2c + 1, the ones not yet out loaded again
        const auto xt = raw_buffer(p.x_tagged, NUM_TOKENS * K / 4 * sizeof(uint32x4));
        uint32x4   a[X_LOADS], b[X_LOADS];
        bool       in[X_LOADS] = {};
        bool       all;
        do {
            asm volatile("" ::: "memory");
#pragma unroll
            for (int i = 0; i < X_LOADS; ++i) {
                if (!in[i]) {
                    const int c = Config::BLOCK_SIZE * i + tid;
                    a[i]        = buffer_load_sc1(xt, 2 * c * sizeof(uint32x4));
                    b[i]        = buffer_load_sc1(xt, (2 * c + 1) * sizeof(uint32x4));
                }
            }
            all = true;
#pragma unroll
            for (int i = 0; i < X_LOADS; ++i) {
                in[i] = a[i][3] == x_epoch && b[i][3] == x_epoch;
                all &= in[i];
            }
        } while (!all);
#pragma unroll
        for (int i = 0; i < X_LOADS; ++i) {
            x[i] = uint32x4{a[i][0], a[i][1], b[i][0], b[i][1]};
        }
    }
    pin(last_call);
    const uint32_t call = last_call + 1u;
#pragma unroll
    for (int i = 0; i < X_LOADS; ++i) {
        const int c = Config::BLOCK_SIZE * i + tid;
        *reinterpret_cast<uint32x4 *>(s.x + c / (K / 8) * ROW + 8 * (c % (K / 8))) = x[i];
    }
    block_sync_lds();

    // B: token c's x at the same K; columns past M repeat token M - 1 and are dropped
    const bfloat16 *xk  = s.x + min(lane % 16, NUM_TOKENS - 1) * ROW + k0 + 8 * (lane / 16);
    floatx4         acc = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        const bfloat16x8 b = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b, acc,
                                                      0, 0, 0);
    }
    all_reduce_rows<NUM_TOKENS>(p.ar, s.rows, acc, call, residual);
}

// row_linear_bf16_rows with its LDS reads ahead of the MFMAs
template <int K, int NUM_TOKENS>
__device__ __forceinline__ void row_linear_bf16_rows_ahead(const RowLinearParams &p, uint8_t *smem,
                                                     uint32_t last_call,
                                                     uint32x4 (&w)[ROW_LINEAR_STEPS<K>],
                                                     uint32_t x_epoch) {
    constexpr int WAVE_K = K / 2;
    constexpr int STEPS  = ROW_LINEAR_STEPS<K>;
    static_assert(K % 256 == 0 && sizeof(RowLinearBf16Smem<K>) <= Config::SMEM_SIZE);

    RowLinearBf16Smem<K> &s = *reinterpret_cast<RowLinearBf16Smem<K> *>(smem);

    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = __builtin_amdgcn_readfirstlane(tid / THREADS_PER_WARP);
    const int k0   = wave % 2 * WAVE_K;

    const float residual = all_reduce_residual<NUM_TOKENS>(p.ar);
    // thread t: x's 16 B chunks t + 256 i
    constexpr int ROW     = RowLinearBf16Smem<K>::ROW;
    constexpr int X_LOADS = NUM_TOKENS * K / 8 / Config::BLOCK_SIZE;
    static_assert(K / 8 % Config::BLOCK_SIZE == 0);
    uint32x4 x[X_LOADS];
    {
        // chunk c from packets 2c and 2c + 1, the ones not yet out loaded again
        const auto xt = raw_buffer(p.x_tagged, NUM_TOKENS * K / 4 * sizeof(uint32x4));
        uint32x4   a[X_LOADS], b[X_LOADS];
        bool       in[X_LOADS] = {};
        bool       all;
        do {
            asm volatile("" ::: "memory");
#pragma unroll
            for (int i = 0; i < X_LOADS; ++i) {
                if (!in[i]) {
                    const int c = Config::BLOCK_SIZE * i + tid;
                    a[i]        = buffer_load_sc1(xt, 2 * c * sizeof(uint32x4));
                    b[i]        = buffer_load_sc1(xt, (2 * c + 1) * sizeof(uint32x4));
                }
            }
            all = true;
#pragma unroll
            for (int i = 0; i < X_LOADS; ++i) {
                in[i] = a[i][3] == x_epoch && b[i][3] == x_epoch;
                all &= in[i];
            }
        } while (!all);
#pragma unroll
        for (int i = 0; i < X_LOADS; ++i) {
            x[i] = uint32x4{a[i][0], a[i][1], b[i][0], b[i][1]};
        }
    }
    pin(last_call);
    const uint32_t call = last_call + 1u;
#pragma unroll
    for (int i = 0; i < X_LOADS; ++i) {
        const int c = Config::BLOCK_SIZE * i + tid;
        *reinterpret_cast<uint32x4 *>(s.x + c / (K / 8) * ROW + 8 * (c % (K / 8))) = x[i];
    }
    block_sync_lds();

    // B: token c's x at the same K; columns past M repeat token M - 1 and are dropped
    // its LDS reads B_AHEAD steps ahead of their MFMAs (left to itself the compiler waited for each pair)
    constexpr int   B_AHEAD = 4;
    const bfloat16 *xk      = s.x + min(lane % 16, NUM_TOKENS - 1) * ROW + k0 + 8 * (lane / 16);
    static_assert(STEPS >= B_AHEAD);
    bfloat16x8 b[B_AHEAD];
#pragma unroll
    for (int i = 0; i < B_AHEAD; ++i) {
        b[i] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
    }
    floatx4 acc = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b[i % B_AHEAD], acc, 0,
                                                      0, 0);
        if (i + B_AHEAD < STEPS) {
            b[i % B_AHEAD] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * (i + B_AHEAD));
        }
        __builtin_amdgcn_sched_barrier(0);
    }
    all_reduce_rows<NUM_TOKENS>(p.ar, s.rows, acc, call, residual);
}

} // namespace infera_flash::glm5

// attn_qkv_bf16 (aklr/attention_bf16.h) for up to 16 tokens a call: the same roles, sync and arithmetic (the
// products in bf16 as sglang's tgemm, the RMSNorms as sglang's, aklr/norm.h), the tokens the columns of each 16-row
// group's MFMA tiles, every weight read once for all of them. qkv_a is aklr's, the normed x's whole rows in LDS and
// the same K split, so each token's qkv_a, q and k_pe are the bits aklr's kernel gives it: past X_ROWS tokens the
// rows do not all fit, and a second pass over the same weights in registers takes the rest. Later blocks normalize
// kv themselves (kv_row_sglang).
#pragma once

#include "glm5_m16/attention.h"
#include "aklr/norm.h"

namespace infera_flash::glm5_m16 {

struct AttnQkvBf16Params {
    const bfloat16 *x;          // [M, HIDDEN_SIZE] the hidden states
    const bfloat16 *gamma;      // [HIDDEN_SIZE] input_layernorm
    float           epsilon;
    const bfloat16 *qkv_weight; // [QKV_A_ROWS, HIDDEN_SIZE] row-major
    const bfloat16 *q_gamma;    // [Q_LORA_RANK] q_a_layernorm
    const bfloat16 *kv_gamma;   // [KV_LORA_RANK] kv_a_layernorm
    float           latent_epsilon;
    const bfloat16 *q_b_weight; // [Q_B_ROWS, Q_LORA_RANK] row-major
    void           *workspace;  // WORKSPACE_SIZE bytes, zeroed once and kept
    bfloat16       *qkv;        // [M, QKV_A_ROWS] qkv_a's output, k_pe's columns unwritten
    bfloat16       *q;          // [M, Q_B_ROWS]
    bfloat16       *k_pe;       // [M, QK_ROPE_DIM]
};

// in a block's slot: its q_b group is out (packet 0: its qkv_a group)
constexpr int Q_B_PACKET = 1;

// a row of x or q in LDS, padded by 16 B: rows a multiple of 64 banks apart would put the tokens' reads of one K in
// one bank
template <int K> constexpr int LDS_ROW = K + 8;

// the normed x's rows in LDS at once: qkv_a's first pass takes up to X_ROWS tokens, a second the rest (rows 0 ..)
constexpr int X_ROWS = 12;
static_assert(Config::HIDDEN_SIZE == ROW_LOADS * Config::BLOCK_SIZE * 8 && Config::MAX_NUM_TOKENS <= 2 * X_ROWS &&
              Config::MAX_NUM_TOKENS <= 16);

struct AttnQkvBf16Smem {
    union {
        bfloat16 x[X_ROWS * LDS_ROW<Config::HIDDEN_SIZE>];   // the normed x
        bfloat16 q[Config::MAX_NUM_TOKENS * LDS_ROW<Q_LORA>]; // the normed q_a, once qkv_a is done
    };
    GroupSmem<Config::MAX_NUM_TOKENS> group;
    float                             reduce[WAVES * Config::MAX_NUM_TOKENS];
};
static_assert(sizeof(AttnQkvBf16Smem) <= Config::SMEM_SIZE && Config::Q_B_ROWS % 16 == 0);

// kv's RMSNorm as sglang's, token m's values 8 lane .. 8 lane + 7 (a wave takes a token), once kv is out
template <int NUM_TOKENS, typename Params>
__device__ __forceinline__ void kv_row_sglang(const Params &p, int m, int lane, bfloat16 (&kv)[8]) {
    const auto     qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
    const uint32x4 val = buffer_load_sc1(qkv, (m * QKV_ROWS + Q_LORA + 8 * lane) * sizeof(bfloat16));
    bfloat16       gamma[8];
    __builtin_memcpy(kv, &val, 16);
    load_data<bfloat16, 8>(p.kv_gamma + 8 * lane, gamma);
    floatx2 sum2 = {};
    add_squares(sum2, kv);
    const float factor = rsqrtf(WarpReduce<SumOp>(sum2.x + sum2.y) / KV_LORA + p.latent_epsilon);
#pragma unroll
    for (int e = 0; e < 8; ++e) {
        kv[e] = static_cast<bfloat16>(static_cast<float>(kv[e]) * factor * static_cast<float>(gamma[e]));
    }
}

// kv_row_sglang in parts, so that a block can issue its loads ahead: the lane's gamma (no block writes it), its 16 B of
// token m's row once kv is out, their RMSNorm
template <typename Params>
__device__ __forceinline__ void kv_gamma_sglang(const Params &p, int lane, bfloat16 (&gamma)[8]) {
    load_data<bfloat16, 8>(p.kv_gamma + 8 * lane, gamma);
}

template <int NUM_TOKENS, typename Params>
__device__ __forceinline__ uint32x4 kv_load_sglang(const Params &p, int m, int lane) {
    const auto qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
    return buffer_load_sc1(qkv, (m * QKV_ROWS + Q_LORA + 8 * lane) * sizeof(bfloat16));
}

template <typename Params>
__device__ __forceinline__ void kv_norm_sglang(const Params &p, const uint32x4 &val, const bfloat16 (&gamma)[8],
                                               bfloat16 (&kv)[8]) {
    __builtin_memcpy(kv, &val, 16);
    floatx2 sum2 = {};
    add_squares(sum2, kv);
    const float factor = rsqrtf(WarpReduce<SumOp>(sum2.x + sum2.y) / KV_LORA + p.latent_epsilon);
#pragma unroll
    for (int e = 0; e < 8; ++e) {
        kv[e] = static_cast<bfloat16>(static_cast<float>(kv[e]) * factor * static_cast<float>(gamma[e]));
    }
}

// Once q_a is out: its M rows, thread t columns 8t .. 8t + 7, RMSNormed as sglang's
template <int NUM_TOKENS, typename Params>
__device__ __forceinline__ void normed_q_a(const Params &p, const bfloat16 (&gamma)[1][8], const uint32x4 *slots,
                                           uint32_t epoch, float *reduce, bfloat16 (&q)[NUM_TOKENS][1][8]) {
    const int tid = threadIdx.x;
    wait_for(slots, 0, 0, QA_GROUPS, epoch);
    // written by other XCDs: sc1 loads
    const auto qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const uint32x4 val = buffer_load_sc1(qkv, (m * QKV_ROWS + 8 * tid) * sizeof(bfloat16));
        __builtin_memcpy(q[m][0], &val, 16);
    }
    glm5::rms_norm_sglang<NUM_TOKENS, 1, true>(q, gamma, p.latent_epsilon, reduce);
}

// a wave's quarter of K of a 16-row group, in 16 B steps of 32 K
template <int K> constexpr int BF16_STEPS = K / WAVES / 32;

// What a wave of group_out_bf16 needs of 16-row group `group` of a row-major bf16 [rows, K] weight: lane (g, c) row
// 16 group + c at K K / 4 wave + 32 i + 8 g .. + 7 for step i (lm_head's layout); this the lane's step 0
template <int K> __device__ __forceinline__ const bfloat16 *group_row_bf16(const bfloat16 *w, int group) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    const int wave = threadIdx.x / THREADS_PER_WARP;
    return w + static_cast<size_t>(16 * group + lane % 16) * K + K / WAVES * wave + 8 * (lane / 16);
}

template <int K>
__device__ __forceinline__ void load_group_bf16(const bfloat16 *w, int group, uint32x4 (&regs)[BF16_STEPS<K>]) {
    const bfloat16 *row = group_row_bf16<K>(w, group);
#pragma unroll
    for (int i = 0; i < BF16_STEPS<K>; ++i) {
        regs[i] = *reinterpret_cast<const uint32x4 *>(row + 32 * i);
    }
}

// LDS reads of B ahead of their MFMAs. Left to itself, the compiler, short of registers, read each step's B into the
// same registers and waited for it before its MFMA: a step took an LDS round trip
constexpr int B_AHEAD = 4;

// A wave's partial sum of a 16-row group over its quarter of K, its weights' steps w times row x (K bf16 in LDS) in
// lane (g, c)'s column
template <int K>
__device__ __forceinline__ floatx4 group_acc_bf16(const uint32x4 (&w)[BF16_STEPS<K>], const bfloat16 *x) {
    constexpr int   STEPS = BF16_STEPS<K>;
    const int       lane  = threadIdx.x % THREADS_PER_WARP;
    const int       wave  = threadIdx.x / THREADS_PER_WARP;
    const bfloat16 *xk    = x + K / WAVES * wave + 8 * (lane / 16);
    static_assert(STEPS >= B_AHEAD);
    bfloat16x8 b[B_AHEAD];
#pragma unroll
    for (int i = 0; i < B_AHEAD; ++i) {
        b[i] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
    }
    floatx4 acc = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b[i % B_AHEAD], acc, 0,
                                                      0, 0);
        if (i + B_AHEAD < STEPS) {
            b[i % B_AHEAD] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * (i + B_AHEAD));
        }
        __builtin_amdgcn_sched_barrier(0);
    }
    return acc;
}

// The group's [M][16] outputs (group_store) from x [M][K] bf16 in LDS (rows LDS_ROW<K> apart): each wave's partial
// sum over its quarter of K; columns past M repeat token M - 1 and are dropped
template <int K, int NUM_TOKENS, bool SC1>
__device__ __forceinline__ void group_out_bf16(const uint32x4 (&w)[BF16_STEPS<K>], const bfloat16 *x,
                                               GroupSmem<Config::MAX_NUM_TOKENS> &s, bfloat16 *out, int stride) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    group_store<NUM_TOKENS, SC1>(group_acc_bf16<K>(w, x + min(lane % 16, NUM_TOKENS - 1) * LDS_ROW<K>), s, out,
                                 stride);
}

// Once q_a is out: q_a's RMSNorm into s.q in bf16
template <int NUM_TOKENS>
__device__ __forceinline__ void q_a_bf16(const AttnQkvBf16Params &p, AttnQkvBf16Smem &s,
                                         const bfloat16 (&gamma)[1][8], const uint32x4 *slots, uint32_t epoch) {
    const int tid = threadIdx.x;
    bfloat16  q[NUM_TOKENS][1][8];
    normed_q_a<NUM_TOKENS>(p, gamma, slots, epoch, s.reduce, q);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        store_data<bfloat16, 8>(s.q + m * LDS_ROW<Q_LORA> + 8 * tid, q[m][0]);
    }
    block_sync_lds();
}

// aklr/norm.h's rms_norm_sglang in two steps, its arithmetic: the rows' factors (one BlockReduce), then a row scaled
template <int NUM_TOKENS, int LOADS, bool LDS_ONLY>
__device__ __forceinline__ void rms_factors_sglang(const bfloat16 (&x)[NUM_TOKENS][LOADS][8], float eps,
                                                   float *reduce, float (&factor)[NUM_TOKENS]) {
    constexpr int N = LOADS * 8 * Config::BLOCK_SIZE;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            add_squares(sum2, x[m][i]);
        }
        factor[m] = sum2.x + sum2.y;
    }
    BlockReduce<SumOp, Config::BLOCK_SIZE, LDS_ONLY>(factor, reduce);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        factor[m] = rsqrtf(factor[m] / N + eps);
    }
}

template <int LOADS>
__device__ __forceinline__ void rms_scale_sglang(bfloat16 (&x)[LOADS][8], const bfloat16 (&gamma)[LOADS][8],
                                                 float factor) {
#pragma unroll
    for (int i = 0; i < LOADS; ++i) {
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            x[i][j] = static_cast<bfloat16>(static_cast<float>(x[i][j]) * factor * static_cast<float>(gamma[i][j]));
        }
    }
}

// qkv_a_rows' weight steps issued ahead of x's norm, the rest a few as each row is scaled. A wave issues in order, so
// with all of them ahead the norm waited for the last to go out (the memory system full) and the memory system then
// idled as x was normed
constexpr int W_EARLY = 16;

// qkv_a_group as aklr's: every row of x normed in registers, then in LDS whole, each wave's quarter of K in one pass.
// Past X_ROWS tokens the rest stay in registers, normed, until that pass is done with rows 0 ..; a second pass over
// the same weights then takes them there, its columns those tokens' (an MFMA's columns are apart: the bits one pass
// gives)
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t qkv_a_rows(const AttnQkvBf16Params &p, AttnQkvBf16Smem &s,
                                               const uint32x4 *my_slot, bfloat16 *out, int stride) {
    constexpr int STEPS  = BF16_STEPS<Config::HIDDEN_SIZE>;
    constexpr int ROW    = LDS_ROW<Config::HIDDEN_SIZE>;
    constexpr int ROWS_A = NUM_TOKENS < X_ROWS ? NUM_TOKENS : X_ROWS; // the first pass's tokens
    constexpr int ROWS_B = NUM_TOKENS - ROWS_A;
    static_assert(ROWS_B <= ROWS_A);
    // the weights' steps issued as each row is scaled, the rest after the last
    constexpr int PER = (STEPS - W_EARLY) / NUM_TOKENS;
    const int     tid = threadIdx.x;
    const int     col = tid % THREADS_PER_WARP % 16; // the lane's MFMA column
    // every load of x issued ahead of the weights': one round trip for both, and x lands first (loads complete in
    // issue order)
    bfloat16 x[NUM_TOKENS][ROW_LOADS][8];
    bfloat16 gamma[ROW_LOADS][8];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(p.x + m * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8, x[m][i]);
        }
    }
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(p.gamma + (i * Config::BLOCK_SIZE + tid) * 8, gamma[i]);
    }
    const bfloat16 *w_row = group_row_bf16<Config::HIDDEN_SIZE>(p.qkv_weight, blockIdx.x);
    uint32x4        w[STEPS];
    const auto      load_w = [&](int i) { w[i] = *reinterpret_cast<const uint32x4 *>(w_row + 32 * i); };
    asm volatile("" ::: "memory");
#pragma unroll
    for (int i = 0; i < W_EARLY; ++i) {
        load_w(i);
    }
    // the norm's math after all of them: at 16 tokens the compiler moved it in among x's loads, each wait there one for
    // every load before (loads complete in issue order)
    __builtin_amdgcn_sched_barrier(0);
    const uint32_t epoch = next_epoch(my_slot);
    float          factor[NUM_TOKENS];
    rms_factors_sglang<NUM_TOKENS, ROW_LOADS, true>(x, p.epsilon, s.reduce, factor);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        asm volatile("" ::: "memory");
#pragma unroll
        for (int i = 0; i < PER; ++i) {
            load_w(W_EARLY + PER * m + i);
        }
        // converted again here: the factors' float copies of every row, kept until now, would not fit
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            pin(*reinterpret_cast<uint32x4 *>(x[m][i]));
        }
        rms_scale_sglang<ROW_LOADS>(x[m], gamma, factor[m]);
        if (m < ROWS_A) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                store_data<bfloat16, 8>(s.x + m * ROW + (i * Config::BLOCK_SIZE + tid) * 8, x[m][i]);
            }
        }
    }
    asm volatile("" ::: "memory");
#pragma unroll
    for (int i = W_EARLY + PER * NUM_TOKENS; i < STEPS; ++i) {
        load_w(i);
    }
    block_sync_lds();
    // columns past the pass's tokens repeat its last and are dropped
    floatx4 acc = group_acc_bf16<Config::HIDDEN_SIZE>(w, s.x + min(col, ROWS_A - 1) * ROW);
    if constexpr (ROWS_B > 0) {
        block_sync_lds(); // every wave done with rows 0 .. ROWS_B - 1
#pragma unroll
        for (int m = ROWS_A; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                store_data<bfloat16, 8>(s.x + (m - ROWS_A) * ROW + (i * Config::BLOCK_SIZE + tid) * 8, x[m][i]);
            }
        }
        block_sync_lds();
        const floatx4 acc_b =
            group_acc_bf16<Config::HIDDEN_SIZE>(w, s.x + min(max(col - ROWS_A, 0), ROWS_B - 1) * ROW);
        if (col >= ROWS_A) {
            acc = acc_b;
        }
    }
    group_store<NUM_TOKENS, true>(acc, s.group, out, stride);
    return epoch;
}

// Block b < QKV_GROUPS: qkv_a's 16-row group b of the hidden states normed with gamma into qkv (k_pe's groups into
// k_pe) with sc1 stores, at the epoch it reads from its slot (returned, nothing published)
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t qkv_a_group(const AttnQkvBf16Params &p, AttnQkvBf16Smem &s,
                                                const uint32x4 *my_slot) {
    constexpr int K_PE_BLOCK0 = QKV_GROUPS - Config::QK_ROPE_DIM / 16;
    const int     block       = blockIdx.x;
    const bool    k_pe_group  = block >= K_PE_BLOCK0;
    bfloat16     *out         = k_pe_group ? p.k_pe + 16 * (block - K_PE_BLOCK0) : p.qkv + 16 * block;
    const int     stride      = k_pe_group ? Config::QK_ROPE_DIM : QKV_ROWS;
    return qkv_a_rows<NUM_TOKENS>(p, s, my_slot, out, stride);
}

// attn_qkv_bf16's work on this block (aklr/attention_bf16.h's roles); returns this call's epoch
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t attn_qkv_bf16_block(const AttnQkvBf16Params &p, uint8_t *smem) {
    AttnQkvBf16Smem &s       = *reinterpret_cast<AttnQkvBf16Smem *>(smem);
    const int        tid     = threadIdx.x;
    const int        block   = blockIdx.x;
    uint32x4        *slots   = static_cast<uint32x4 *>(p.workspace);
    uint32x4        *my_slot = slots + block * PACKETS_PER_SLOT;
    uint32x4         w_q_b[BF16_STEPS<Q_LORA>];
    bfloat16         q_gamma[1][8];
    uint32_t         epoch;
    if (block < QKV_GROUPS) {
        epoch = qkv_a_group<NUM_TOKENS>(p, s, my_slot);
        publish(my_slot, epoch);
        if (block < Q_B_BLOCK0) {
            return epoch;
        }
        const int b = opaque(block); // its loads once qkv_a's weights are in, not with them
        load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
        load_group_bf16<Q_LORA>(p.q_b_weight, b - Q_B_BLOCK0, w_q_b);
    } else {
        load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
        asm volatile("" ::: "memory");
        load_group_bf16<Q_LORA>(p.q_b_weight, block - Q_B_BLOCK0, w_q_b);
        epoch = next_epoch(my_slot);
        // keeps this block's epoch in step, once every wave has read the slot
        publish(my_slot, epoch);
    }
    q_a_bf16<NUM_TOKENS>(p, s, q_gamma, slots, epoch);
    group_out_bf16<Q_LORA, NUM_TOKENS, true>(w_q_b, s.q, s.group, p.q + 16 * (block - Q_B_BLOCK0),
                                             Config::Q_B_ROWS);
    publish(my_slot + Q_B_PACKET, epoch);
    return epoch;
}

// qkv_a in 8-row units over every block (attn_qkv_bf16_units), as aklr/attention_bf16.h's, for the token counts whose
// normed x fits in LDS whole (QA_UNITS): unit b is q_a's rows 8b .. 8b + 7 on block b (packet 0), kv's and k_pe's
// KV_UNITS units second on blocks 0 .. KV_UNITS - 1 (packet 0 again, KV_FLAG). Each row's products, waves and sums are qkv_a_rows'
// group's, bit for bit; the norm and the unit's loads interleaved as there (UNIT_EARLY loads ahead of the norm)
constexpr int UNIT_ROWS  = 8;
constexpr int KV_UNITS   = (QKV_ROWS - Q_LORA) / UNIT_ROWS;
// a block's packet 0 again, its first word KV_FLAG, once its kv unit is out (the indexer kernel has packets 2 and 3)
constexpr uint32_t KV_FLAG = 1;
constexpr int UNIT_EARLY = 8;
static_assert(Q_LORA / UNIT_ROWS == Config::NUM_BLOCKS && KV_UNITS <= Q_B_BLOCK0 && KV_LORA % UNIT_ROWS == 0 &&
              Config::QK_ROPE_DIM % UNIT_ROWS == 0);
template <int K> constexpr int UNIT_LOADS = BF16_STEPS<K> / 2;
// 6 and 8 tokens (12: slower, its attending blocks' KV rows on all 128 blocks wait for the kv units; measured)
template <int NUM_TOKENS> constexpr bool QA_UNITS = NUM_TOKENS <= 8;

// lane (g, c): row row0 + c % 8, in load i step 2i + c / 8's K (K / 4 wave + 64 i + 32 (c / 8) + 8 g .. + 7)
template <int K> __device__ __forceinline__ const bfloat16 *unit_row_bf16(const bfloat16 *w, int row0) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    const int wave = threadIdx.x / THREADS_PER_WARP;
    return w + static_cast<size_t>(row0 + lane % 8) * K + K / WAVES * wave + 8 * (lane / 16) + 32 * (lane % 16 / 8);
}

template <int K>
__device__ __forceinline__ void load_unit_bf16(const bfloat16 *w, int row0, uint32x4 (&regs)[UNIT_LOADS<K>]) {
    const bfloat16 *row = unit_row_bf16<K>(w, row0);
#pragma unroll
    for (int i = 0; i < UNIT_LOADS<K>; ++i) {
        regs[i] = __builtin_nontemporal_load(reinterpret_cast<const uint32x4 *>(row + 64 * i));
    }
}

// each lane the value of the lane 8 on in its row of 16 (DPP row_ror:8): a unit load's odd step into lanes c < 8
__device__ __forceinline__ uint32x4 rotate8(const uint32x4 &v) {
    uint32x4 out;
#pragma unroll
    for (int k = 0; k < 4; ++k) {
        out[k] = static_cast<uint32_t>(__builtin_amdgcn_mov_dpp(static_cast<int>(v[k]), 0x128, 0xf, 0xf, false));
    }
    return out;
}

// A wave's partial sum of a unit over its quarter of K (rows 0-7 of the tile), x one row of bf16 in LDS (this lane's
// token): group_acc_bf16's MFMAs in its order, its B reads B_AHEAD steps ahead
template <int K>
__device__ __forceinline__ floatx4 unit_acc_bf16(const uint32x4 (&w)[UNIT_LOADS<K>], const bfloat16 *x) {
    constexpr int   STEPS = BF16_STEPS<K>;
    const int       lane  = threadIdx.x % THREADS_PER_WARP;
    const int       wave  = threadIdx.x / THREADS_PER_WARP;
    const bfloat16 *xk    = x + K / WAVES * wave + 8 * (lane / 16);
    static_assert(STEPS >= B_AHEAD && STEPS % 2 == 0);
    bfloat16x8 b[B_AHEAD];
#pragma unroll
    for (int i = 0; i < B_AHEAD; ++i) {
        b[i] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
    }
    floatx4 acc = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        const uint32x4 a = i % 2 ? rotate8(w[i / 2]) : w[i / 2];
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, a), b[i % B_AHEAD], acc, 0, 0, 0);
        if (i + B_AHEAD < STEPS) {
            b[i % B_AHEAD] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * (i + B_AHEAD));
        }
        __builtin_amdgcn_sched_barrier(0);
    }
    return acc;
}

// group_store for a unit: its 8 rows of each token, the waves added in wave order, rounded to bf16, 16 B a token at
// out (row stride `stride`); only wave 0 stores
template <int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void unit_store(floatx4 acc, GroupSmem<MAX_TOKENS> &s, bfloat16 *out, int stride) {
    static_assert(NUM_TOKENS <= MAX_TOKENS && NUM_TOKENS <= THREADS_PER_WARP);
    const int tid = threadIdx.x;
    s.tiles[tid]  = acc;
    block_sync_lds();
    // thread (m, r): row r of token m, at lane 16 (r / 4) + m of each wave's tile, element r % 4
    if (tid < UNIT_ROWS * NUM_TOKENS) {
        const int      r    = tid % UNIT_ROWS;
        const floatx4 *tile = s.tiles + 16 * (r / 4) + tid / UNIT_ROWS;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][r % 4];
        }
        s.out[tid] = static_cast<bfloat16>(sum);
    }
    block_sync_lds();
    if (tid < NUM_TOKENS) {
        const uint32x4 val = reinterpret_cast<const uint32x4 *>(s.out)[tid];
        auto          *dst = reinterpret_cast<uint32x4 *>(out + tid * stride);
        if constexpr (SC1) {
            store_sc1(dst, val);
        } else {
            *dst = val;
        }
    }
}

// publish for a unit's packet: wave 0 stored the unit, so only it waits for its stores (the others may have loads
// in flight that the packet need not wait for)
__device__ __forceinline__ void publish_wave0(uint32x4 *packet, uint32_t epoch, uint32_t a = 0u) {
    if (__builtin_amdgcn_readfirstlane(threadIdx.x) < THREADS_PER_WARP) {
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
        if (threadIdx.x == 0) {
            store_sc1(packet, uint32x4{a, 0u, 0u, epoch});
        }
    }
}

// Thread t < KV_UNITS waits until block t's packet 0 shows this call's epoch with its kv unit out (KV_FLAG), then the
// block syncs
__device__ __forceinline__ void wait_kv_units(const uint32x4 *slots, uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < KV_UNITS) {
        uint32x4 vals[1];
        do {
            load_sc1(slots + threadIdx.x * PACKETS_PER_SLOT, vals);
        } while (vals[0][3] != epoch || vals[0][0] != KV_FLAG);
    }
    __syncthreads();
}

// Once every unit is out: q_a's M rows, thread t columns 8t .. 8t + 7 (unit t's), RMSNormed as sglang's into s.q
template <int NUM_TOKENS>
__device__ __forceinline__ void q_a_bf16_units(const AttnQkvBf16Params &p, AttnQkvBf16Smem &s,
                                               const bfloat16 (&gamma)[1][8], const uint32x4 *slots, uint32_t epoch) {
    const int tid = threadIdx.x;
    wait_for(slots, 0, 0, Config::NUM_BLOCKS, epoch);
    // written by other XCDs: sc1 loads
    const auto qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
    bfloat16   q[NUM_TOKENS][1][8];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const uint32x4 val = buffer_load_sc1(qkv, (m * QKV_ROWS + 8 * tid) * sizeof(bfloat16));
        __builtin_memcpy(q[m][0], &val, 16);
    }
    glm5::rms_norm_sglang<NUM_TOKENS, 1, true>(q, gamma, p.latent_epsilon, s.reduce);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        store_data<bfloat16, 8>(s.q + m * LDS_ROW<Q_LORA> + 8 * tid, q[m][0]);
    }
    block_sync_lds();
}

// attn_qkv_bf16_block's work in units on this block (QA_UNITS); returns this call's epoch. Its q_b group as there: on
// blocks Q_B_BLOCK0 .., once every unit is out, its weights issued once x is normed (wave 0's once its unit's packet
// is out, so that its wait for the unit's stores does not wait for them too)
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t attn_qkv_bf16_units(const AttnQkvBf16Params &p, uint8_t *smem) {
    constexpr int    LOADS   = UNIT_LOADS<Config::HIDDEN_SIZE>;
    constexpr int    ROW     = LDS_ROW<Config::HIDDEN_SIZE>;
    constexpr int    PER     = (LOADS - UNIT_EARLY) / NUM_TOKENS;
    constexpr int    KV_ONLY = KV_LORA / UNIT_ROWS; // kv's units, then k_pe's
    static_assert(QA_UNITS<NUM_TOKENS> && LOADS >= UNIT_EARLY);
    AttnQkvBf16Smem &s       = *reinterpret_cast<AttnQkvBf16Smem *>(smem);
    const int        tid     = threadIdx.x;
    const int        block   = blockIdx.x;
    const int        wave    = __builtin_amdgcn_readfirstlane(tid / THREADS_PER_WARP);
    const int        col     = tid % THREADS_PER_WARP % 16; // the lane's MFMA column
    const bool       q_b     = block >= Q_B_BLOCK0;
    uint32x4        *slots   = static_cast<uint32x4 *>(p.workspace);
    uint32x4        *my_slot = slots + block * PACKETS_PER_SLOT;
    uint32x4         w_q_b[BF16_STEPS<Q_LORA>];
    bfloat16         q_gamma[1][8];
    const auto       load_q_b = [&] {
        asm volatile("" ::: "memory");
        load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
        load_group_bf16<Q_LORA>(p.q_b_weight, block - Q_B_BLOCK0, w_q_b);
    };
    // every load of x issued ahead of the weights': x lands first (loads complete in issue order)
    bfloat16 x[NUM_TOKENS][ROW_LOADS][8];
    bfloat16 gamma[ROW_LOADS][8];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(p.x + m * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8, x[m][i]);
        }
    }
#pragma unroll
    for (int i = 0; i < ROW_LOADS; ++i) {
        load_data<bfloat16, 8>(p.gamma + (i * Config::BLOCK_SIZE + tid) * 8, gamma[i]);
    }
    const bfloat16 *w_row  = unit_row_bf16<Config::HIDDEN_SIZE>(p.qkv_weight, UNIT_ROWS * block);
    uint32x4        w[LOADS];
    const auto      load_w = [&](int i) { w[i] = __builtin_nontemporal_load(reinterpret_cast<const uint32x4 *>(w_row + 64 * i)); };
    asm volatile("" ::: "memory");
#pragma unroll
    for (int i = 0; i < UNIT_EARLY; ++i) {
        load_w(i);
    }
    __builtin_amdgcn_sched_barrier(0);
    const uint32_t epoch = next_epoch(my_slot);
    float          factor[NUM_TOKENS];
    rms_factors_sglang<NUM_TOKENS, ROW_LOADS, true>(x, p.epsilon, s.reduce, factor);
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        asm volatile("" ::: "memory");
#pragma unroll
        for (int i = 0; i < PER; ++i) {
            load_w(UNIT_EARLY + PER * m + i);
        }
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            pin(*reinterpret_cast<uint32x4 *>(x[m][i]));
        }
        rms_scale_sglang<ROW_LOADS>(x[m], gamma, factor[m]);
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            store_data<bfloat16, 8>(s.x + m * ROW + (i * Config::BLOCK_SIZE + tid) * 8, x[m][i]);
        }
    }
    asm volatile("" ::: "memory");
#pragma unroll
    for (int i = UNIT_EARLY + PER * NUM_TOKENS; i < LOADS; ++i) {
        load_w(i);
    }
    if (q_b && wave != 0) {
        load_q_b();
    }
    block_sync_lds();
    const bfloat16 *xm = s.x + min(col, NUM_TOKENS - 1) * ROW;
    unit_store<NUM_TOKENS, true>(unit_acc_bf16<Config::HIDDEN_SIZE>(w, xm), s.group, p.qkv + UNIT_ROWS * block,
                                 QKV_ROWS);
    publish_wave0(my_slot, epoch);
    if (block < KV_UNITS) {
        load_unit_bf16<Config::HIDDEN_SIZE>(p.qkv_weight, Q_LORA + UNIT_ROWS * block, w);
        const bool k_pe = block >= KV_ONLY;
        unit_store<NUM_TOKENS, true>(unit_acc_bf16<Config::HIDDEN_SIZE>(w, xm), s.group,
                                     k_pe ? p.k_pe + UNIT_ROWS * (block - KV_ONLY) : p.qkv + Q_LORA + UNIT_ROWS * block,
                                     k_pe ? Config::QK_ROPE_DIM : QKV_ROWS);
        publish_wave0(my_slot, epoch, KV_FLAG);
    }
    if (!q_b) {
        return epoch;
    }
    if (wave == 0) {
        load_q_b();
    }
    q_a_bf16_units<NUM_TOKENS>(p, s, q_gamma, slots, epoch);
    group_out_bf16<Q_LORA, NUM_TOKENS, true>(w_q_b, s.q, s.group, p.q + 16 * (block - Q_B_BLOCK0),
                                             Config::Q_B_ROWS);
    publish(my_slot + Q_B_PACKET, epoch);
    return epoch;
}

// attn_qkv_bf16_units at QA_UNITS, attn_qkv_bf16_block otherwise (the indexer kernel's entry: one call for every M)
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t attn_qkv_bf16_any(const AttnQkvBf16Params &p, uint8_t *smem) {
    if constexpr (QA_UNITS<NUM_TOKENS>) {
        return attn_qkv_bf16_units<NUM_TOKENS>(p, smem);
    } else {
        return attn_qkv_bf16_block<NUM_TOKENS>(p, smem);
    }
}

} // namespace infera_flash::glm5_m16

// What the attention layer kernels for up to 16 tokens a call share (aklr/attention_layer.h's, in glm5_m16): MLA's
// work after attn_qkv in the layers attending a carried top-k (mla_after_qkv, glm5_m16/mla.h's roles), the kernel's
// state, and its run()'s checks and all-reduce params.
#pragma once

#include <ATen/ATen.h>
#include <c10/hip/HIPException.h>

#include "glm5_m16/all_reduce.h"
#include "aklr_m16/attention_bf16.h"
#include "aklr_m16/row_linear_bf16.h"

namespace infera_flash::glm5_m16 {

constexpr double LOG2E = 1.4426950408889634;

template <typename AttnQkvParams> struct AttentionParams {
    AttnQkvParams       attn;
    MlaCoreParams       mla;
    RowLinearBf16Params o_proj;
};

// a kernel attending a carried top-k: its state's attn_qkv sync slots, then mla's, o_proj's all-reduce call number
// per block, then o's packets (MlaCoreParams::out_tagged), then o_latent's (latent_tagged), each for MAX_NUM_TOKENS
struct AttentionState {
    static constexpr int64_t MLA    = WORKSPACE_SIZE;
    static constexpr int64_t CALLS  = 2 * WORKSPACE_SIZE;
    static constexpr int64_t TAGGED = CALLS + Config::NUM_BLOCKS * sizeof(int);
    static constexpr int64_t LATENT_TAGGED =
        TAGGED + Config::MAX_NUM_TOKENS * Config::O_PROJ_K / 4 * sizeof(uint32x4);
    static constexpr int64_t BYTES =
        LATENT_TAGGED + Config::MAX_NUM_TOKENS * Config::MLA_HEADS * Config::KV_LORA_RANK / 4 * sizeof(uint32x4);
};

// mla's work on this block (glm5_m16/mla.h's roles) after attn_qkv's, at this call's epoch (slots: mla's): q, kv and
// k_pe were written earlier in the kernel on other XCDs, so the blocks wait for their groups (attn_slots at
// attn_epoch) and read them with sc1. The attending blocks read their rows first, build this call's rows once kv's
// and k_pe's groups are out, normalizing kv themselves, turn q_pe once q_b's are and attend once q_latent is out;
// the projecting blocks compute q_latent once q_b's are out, then (the first UNITS) combine a token's partial sums
// into o_latent and (all) multiply a head's o_latent by W_UV, o going out as the packets o_proj polls. At 12 tokens
// the attending blocks are all AD_FIRST, LAYER_STEPS steps each over the tokens' rows as one list (mla::SPANS:
// attend_spanned, combine_unit_spanned); they load what no block writes before the gather, wait for kv's, k_pe's and
// q_b's groups at once, then build the rows and q_pe with every load issued together (mla::fresh_build) and merge the
// rows before q_latent's wait, so a straddling block takes s.fresh for its next token's q.
// Each block runs on_post() once it posts. W_BF16: W_UK and W_UV bf16, without a scale.
template <int NUM_TOKENS, bool W_BF16, typename Params, typename OnPost>
__device__ __forceinline__ void mla_after_qkv(const Params &p, uint8_t *smem, const uint32x4 *attn_slots,
                                              uint32_t attn_epoch, uint32x4 *slots, uint32_t epoch, OnPost on_post) {
    constexpr int        S       = mla::ATTN_STEPS<NUM_TOKENS>;
    constexpr int        B       = mla::TOKEN_BLOCKS<NUM_TOKENS>;
    constexpr int        LS      = mla::LAYER_STEPS<NUM_TOKENS>;
    const MlaCoreParams &ml      = p.mla;
    mla::MlaCoreSmem    &s       = *reinterpret_cast<mla::MlaCoreSmem *>(smem);
    mla::MlaCoreScratch &x       = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
    const int            tid     = threadIdx.x;
    const int            block   = blockIdx.x;
    uint32x4            *my_slot = slots + block * PACKETS_PER_SLOT;
    // every block stores packets 0 (q_latent out) and 1 (partial sums out) each call
    const auto post = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
            store_sc1(my_slot + mla::PARTIAL_SUMS_PACKET, uint32x4{0u, 0u, 0u, epoch});
        }
        on_post();
    };
    if constexpr (mla::SPANS<LS>) {
        if (block < mla::LAYER_ATTENDING<NUM_TOKENS>) {
            // chunks LS block .. LS block + LS - 1 of the rows as one list: token m's, from hi_from on token m + 1's
            const int  m       = LS * block / mla::CHUNKS;
            const int  hi_from = min(mla::CHUNKS * (m + 1) - LS * block, LS);
            const int  m1      = hi_from < LS ? m + 1 : m;
            const int  lane    = tid % THREADS_PER_WARP;
            // what no block writes first, so it lands under the gather
            mla::FreshTables<NUM_TOKENS> f;
            mla::fresh_tables<NUM_TOKENS>(ml, m, m1, f);
            bfloat16 gamma[8];
            kv_gamma_sglang(p.attn, lane, gamma);
            mla::AttendRows<LS> r;
            mla::attend_rows<LS>(ml, 0, block, r);
            // kv's and k_pe's groups (wave 0) and q_b's (waves 1 and 2) in one poll
            static_assert(QKV_GROUPS - QA_GROUPS <= THREADS_PER_WARP &&
                          THREADS_PER_WARP + Config::NUM_BLOCKS - Q_B_BLOCK0 <= Config::BLOCK_SIZE);
            if (tid < QKV_GROUPS - QA_GROUPS) {
                wait_packet(attn_slots + (QA_GROUPS + tid) * PACKETS_PER_SLOT, attn_epoch);
            } else if (tid >= THREADS_PER_WARP && tid < THREADS_PER_WARP + Config::NUM_BLOCKS - Q_B_BLOCK0) {
                wait_packet(attn_slots + (Q_B_BLOCK0 + tid - THREADS_PER_WARP) * PACKETS_PER_SLOT + Q_B_PACKET,
                            attn_epoch);
            }
            __syncthreads(); // kv, k_pe and q_b in
            float q1[2];
            mla::fresh_build<NUM_TOKENS>(
                ml, s, m, m1, f, [&](int t, int l) { return kv_load_sglang<NUM_TOKENS>(p.attn, t, l); },
                [&](const uint32x4 &raw, bfloat16 (&lat)[8]) { kv_norm_sglang(p.attn, raw, gamma, lat); }, q1);
            block_sync_lds();
            mla::merge_fresh<NUM_TOKENS, LS>(f, s, r);
            wait_for(slots, 0, mla::AD_FIRST, Config::NUM_BLOCKS - mla::AD_FIRST, epoch); // q_latent
            // the wait's block sync: every wave done with s.fresh, where q_hi goes
            if (m1 != m) {
                mla::store_q_hi_pe(s, q1);
            }
            mla::attend_spanned<NUM_TOKENS, LS>(ml, s, x, m, x.partial[block],
                                                x.partial_hi[min(m + 1, mla::M_MAX - 1)], r, hi_from);
            // the stores above are asm, which the compiler does not count: wait for them explicitly
            asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
            post();
            if (block == 0) {
                mla::write_fresh<NUM_TOKENS>(ml, s);
                __syncthreads(); // o_proj's x overwrites s.fresh
            }
            return;
        }
    } else if (block < ATTENDING<NUM_TOKENS>) {
        const int          m = block / B;
        mla::AttendRows<S> r;
        mla::attend_rows<S>(ml, m, block % B, r);
        wait_for(attn_slots, 0, QA_GROUPS, QKV_GROUPS - QA_GROUPS, attn_epoch);
        mla::fresh_rows<NUM_TOKENS, true>(ml, s, [&](int t, int lane, bfloat16 (&lat)[8]) {
            kv_row_sglang<NUM_TOKENS>(p.attn, t, lane, lat);
        });
        wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
        mla::turn_q_pe<true>(ml, s, m);
        wait_for(slots, 0, mla::AD_FIRST, Config::NUM_BLOCKS - mla::AD_FIRST, epoch); // q_latent
        mla::attend<NUM_TOKENS, S>(ml, s, x, m, x.partial[block], r);
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
        post();
        if (block == 0) {
            mla::write_fresh<NUM_TOKENS>(ml, s);
            __syncthreads(); // o_proj's x overwrites s.fresh
        }
        return;
    }
    if (block < mla::AD_FIRST) {
        post(); // idle: keep the slot's calls in step
        return;
    }
    const int j = block - mla::AD_FIRST;
    uint32x4  w_v[mla::WUV_REGS * (W_BF16 ? 2 : 1)];
    mla::wuv_weights<W_BF16>(ml, j, w_v);
    wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
    mla::project_q<NUM_TOKENS, true, W_BF16>(ml, x, j);
    post();
    if (j < mla::UNITS<NUM_TOKENS>) {
        if constexpr (mla::SPANS<LS>) {
            mla::combine_unit_spanned<NUM_TOKENS, LS>(ml, s, x, j, slots, epoch, mla::PARTIAL_SUMS_PACKET);
        } else {
            mla::combine_unit<NUM_TOKENS>(ml, s, x, j, slots, epoch, mla::PARTIAL_SUMS_PACKET);
        }
        block_sync_lds(); // wuv_unit's o_latent overwrites s.osum
    }
    mla::wuv_unit<NUM_TOKENS, W_BF16>(ml, s, j, w_v, epoch);
    block_sync_lds(); // o_proj's x overwrites s.tiles
}

template <int NUM_TOKENS, bool W_BF16, typename Params, typename OnPost>
__device__ __forceinline__ void mla_after_qkv_units(const Params &p, uint8_t *smem, const uint32x4 *attn_slots,
                                              uint32_t attn_epoch, uint32x4 *slots, uint32_t epoch, OnPost on_post) {
    constexpr int        S       = mla::ATTN_STEPS<NUM_TOKENS>;
    constexpr int        B       = mla::TOKEN_BLOCKS<NUM_TOKENS>;
    constexpr int        LS      = mla::LAYER_STEPS<NUM_TOKENS>;
    const MlaCoreParams &ml      = p.mla;
    mla::MlaCoreSmem    &s       = *reinterpret_cast<mla::MlaCoreSmem *>(smem);
    mla::MlaCoreScratch &x       = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
    const int            tid     = threadIdx.x;
    const int            block   = blockIdx.x;
    uint32x4            *my_slot = slots + block * PACKETS_PER_SLOT;
    // every block stores packets 0 (q_latent out) and 1 (partial sums out) each call
    const auto post = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
            store_sc1(my_slot + mla::PARTIAL_SUMS_PACKET, uint32x4{0u, 0u, 0u, epoch});
        }
        on_post();
    };
    if constexpr (mla::SPANS<LS>) {
        if (block < mla::LAYER_ATTENDING<NUM_TOKENS>) {
            // chunks LS block .. LS block + LS - 1 of the rows as one list: token m's, from hi_from on token m + 1's
            const int  m       = LS * block / mla::CHUNKS;
            const int  hi_from = min(mla::CHUNKS * (m + 1) - LS * block, LS);
            const int  m1      = hi_from < LS ? m + 1 : m;
            const int  lane    = tid % THREADS_PER_WARP;
            // what no block writes first, so it lands under the gather
            mla::FreshTables<NUM_TOKENS> f;
            mla::fresh_tables<NUM_TOKENS>(ml, m, m1, f);
            bfloat16 gamma[8];
            kv_gamma_sglang(p.attn, lane, gamma);
            mla::AttendRows<LS> r;
            mla::attend_rows<LS>(ml, 0, block, r);
            // kv's and k_pe's groups (wave 0) and q_b's (waves 1 and 2) in one poll
            constexpr int QB_FROM = Config::BLOCK_SIZE - (Config::NUM_BLOCKS - Q_B_BLOCK0);
            static_assert(KV_UNITS <= QB_FROM);
            if (tid < KV_UNITS) {
                uint32x4 vals[1];
                do {
                    load_sc1(attn_slots + tid * PACKETS_PER_SLOT, vals);
                } while (vals[0][3] != attn_epoch || vals[0][0] != KV_FLAG);
            } else if (tid >= QB_FROM) {
                wait_packet(attn_slots + (Q_B_BLOCK0 + tid - QB_FROM) * PACKETS_PER_SLOT + Q_B_PACKET, attn_epoch);
            }
            __syncthreads(); // kv, k_pe and q_b in
            float q1[2];
            mla::fresh_build<NUM_TOKENS>(
                ml, s, m, m1, f, [&](int t, int l) { return kv_load_sglang<NUM_TOKENS>(p.attn, t, l); },
                [&](const uint32x4 &raw, bfloat16 (&lat)[8]) { kv_norm_sglang(p.attn, raw, gamma, lat); }, q1);
            block_sync_lds();
            mla::merge_fresh<NUM_TOKENS, LS>(f, s, r);
            wait_for(slots, 0, mla::AD_FIRST, Config::NUM_BLOCKS - mla::AD_FIRST, epoch); // q_latent
            // the wait's block sync: every wave done with s.fresh, where q_hi goes
            if (m1 != m) {
                mla::store_q_hi_pe(s, q1);
            }
            mla::attend_spanned<NUM_TOKENS, LS>(ml, s, x, m, x.partial[block],
                                                x.partial_hi[min(m + 1, mla::M_MAX - 1)], r, hi_from);
            // the stores above are asm, which the compiler does not count: wait for them explicitly
            asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
            post();
            if (block == 0) {
                mla::write_fresh<NUM_TOKENS>(ml, s);
                __syncthreads(); // o_proj's x overwrites s.fresh
            }
            return;
        }
    } else if (block < ATTENDING<NUM_TOKENS>) {
        const int          m = block / B;
        mla::AttendRows<S> r;
        mla::attend_rows<S>(ml, m, block % B, r);
        wait_kv_units(attn_slots, attn_epoch); // kv's and k_pe's units
        mla::fresh_rows<NUM_TOKENS, true>(ml, s, [&](int t, int lane, bfloat16 (&lat)[8]) {
            kv_row_sglang<NUM_TOKENS>(p.attn, t, lane, lat);
        });
        wait_for(
            attn_slots, Q_B_PACKET, mla::HEADS * mla::ROPE / 16,
            [](int t) { return Q_B_BLOCK0 + mla::Q_HEAD / 16 * (t / 4) + mla::NOPE / 16 + t % 4; }, attn_epoch);
        mla::turn_q_pe<true>(ml, s, m);
        wait_for(slots, 0, mla::AD_FIRST, Config::NUM_BLOCKS - mla::AD_FIRST, epoch); // q_latent
        mla::attend_c<NUM_TOKENS, S>(ml, s, x, m, x.partial[block], r);
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
        post();
        if (block == 0) {
            mla::write_fresh<NUM_TOKENS>(ml, s);
            __syncthreads(); // o_proj's x overwrites s.fresh
        }
        return;
    }
    if (block < mla::AD_FIRST) {
        post(); // idle: keep the slot's calls in step
        return;
    }
    const int j = block - mla::AD_FIRST;
    uint32x4 w_k[mla::WK_LOADS<W_BF16>];
    mla::project_q_weights<W_BF16>(ml, j, w_k);
    wait_for(
        attn_slots, Q_B_PACKET, mla::NOPE / 16,
        [&](int t) { return Q_B_BLOCK0 + mla::Q_HEAD / 16 * (j / 16) + t; }, attn_epoch);
    mla::project_q_w<NUM_TOKENS, true, W_BF16>(ml, x, j, w_k);
    post();
    if (j < mla::UNITS<NUM_TOKENS>) {
        // token j / 16's o straight from its partial sums (combine_wuv); W_UV's rows behind o_proj's weights, long
        // before the partial sums
        uint32x4 w_v[mla::WUV8_REGS * (W_BF16 ? 2 : 1)];
        mla::wuv8_weights<W_BF16>(ml, j, w_v);
        mla::combine_wuv<NUM_TOKENS, W_BF16>(ml, s, x, j, w_v, slots, epoch, mla::PARTIAL_SUMS_PACKET);
    }
    block_sync_lds(); // o_proj's x overwrites s
}

// What every glm5_m16 attention layer kernel's run() checks: its state (zeroed once and kept: each call counts its
// epochs and call number on from the last one's), state_bytes from its start; every rank's peer memory, int64
// addresses on the host; and all the CUs of the device, as the blocks wait on each other
inline void check_run(const at::Tensor &x, const at::Tensor &state, int64_t state_bytes, const at::Tensor &peers,
                      int64_t rank) {
    TORCH_CHECK(x.size(0) >= 1 && x.size(0) <= Config::MAX_NUM_TOKENS, "1 to ", Config::MAX_NUM_TOKENS,
                " tokens");
    TORCH_CHECK(state.nbytes() >= state_bytes, "state: ", state_bytes, " bytes");
    TORCH_CHECK(peers.device().is_cpu() && peers.scalar_type() == at::kLong && peers.dim() == 1 &&
                    peers.numel() >= 1 && peers.numel() <= Config::MAX_RANKS && rank >= 0 && rank < peers.numel(),
                "peers: every rank's peer memory, int64 on the host, 1 to ", Config::MAX_RANKS);
    int cus = 0;
    C10_HIP_CHECK(hipDeviceGetAttribute(&cus, hipDeviceAttributeMultiprocessorCount, x.get_device()));
    TORCH_CHECK(cus == Config::NUM_BLOCKS, "needs all ", Config::NUM_BLOCKS, " CUs of an MI355X (no partitions)");
}

// o_proj's all-reduce: its sum over the ranks of peers, in rank order, plus the stream prior, into output; its call
// numbers at calls, its receive buffers peer_offset bytes into each rank's peer memory
inline AllReduceParams all_reduce_params(at::Tensor &output, const bfloat16 *prior, const at::Tensor &peers,
                                         int64_t rank, void *calls, int64_t peer_offset) {
    AllReduceParams ar{};
    ar.out        = static_cast<bfloat16 *>(output.data_ptr());
    ar.accumulate = true;
    ar.prior      = prior;
    ar.world      = static_cast<int>(peers.numel());
    ar.rank       = static_cast<int>(rank);
    ar.calls      = static_cast<int *>(calls);
    for (int r = 0; r < ar.world; ++r) {
        ar.recv[r] = reinterpret_cast<void *>(peers.data_ptr<int64_t>()[r] + peer_offset);
    }
    return ar;
}

} // namespace infera_flash::glm5_m16

// The DSA indexer up to its scores (aklr/indexer_bf16.h) for up to 16 tokens a call, in a layer kernel after
// attn_qkv_bf16 for as many (aklr_m16/attention_bf16.h): the same products, heads and keys, the tokens the columns of
// the same MFMA tiles and every weight read once for all of them, so each token's q, weights and key are the bits the
// M <= 4 kernel gives it. The scores take rows of several requests: the rows come in segments, runs of consecutive
// rows on one first page (a request's tokens at consecutive positions), and every scoring wave takes a run of the
// 16-key tiles of one segment's longest row (each segment whole runs), reading each tile once and scoring it for the
// segment's rows 4 at a time (a quad, one a row of lanes), each row's scores the bits the M <= 4 kernel gives it.
#pragma once

#include "aklr/indexer_bf16.h"
#include "aklr_m16/attention_bf16.h"

namespace infera_flash::glm5_m16 {

using glm5::IndexerBf16Params;

} // namespace infera_flash::glm5_m16

namespace infera_flash::glm5_m16::ix_bf16 {

using glm5::ix::DIM;
using glm5::ix::HADAMARD_SCALE;
using glm5::ix::HEADS;
using glm5::ix::PAGE_BYTES;
using glm5::ix::Q_ROWS;
using glm5::ix_bf16::bf16_round;
using glm5::ix_bf16::FP8_MAX;
using glm5::ix_bf16::HALF_ROPE;
using glm5::ix_bf16::HEAD_SCALE;
using glm5::ix_bf16::KEY_BLOCK;
using glm5::ix_bf16::load_unit;
using glm5::ix_bf16::PAGE;
using glm5::ix_bf16::round_scale;
using glm5::ix_bf16::SPLITS;
using glm5::ix_bf16::POST_PACKET;
using glm5::ix_bf16::PRODUCTS_PACKET;
using glm5::ix_bf16::SCORE_BLOCK0;
using glm5::ix_bf16::SCORE_WAVES;
using glm5::ix_bf16::TILES;
using glm5::ix_bf16::unit_k;
using glm5::ix_bf16::UNIT_STEPS;
using glm5::ix_bf16::UNITS;
constexpr int TOPK = Config::INDEX_TOPK;
// the rows a tile is scored for at once: ix::swap_add32 and swap_add16 add up 4, one a row of lanes
constexpr int QUAD = 4;
// a row of q_fp8 in 16 B chunks, one a thread
constexpr int ROW_CHUNKS = HEADS * DIM / 16;
static_assert(Q_ROWS / 16 == Config::NUM_BLOCKS && UNITS <= QKV_GROUPS && Q_B_PACKET < PRODUCTS_PACKET &&
              POST_PACKET < PACKETS_PER_SLOT && SCORE_BLOCK0 == KEY_BLOCK + 1 && glm5::Config::INDEX_TOPK == TOPK &&
              glm5::Config::NUM_BLOCKS == Config::NUM_BLOCKS && ROW_CHUNKS == Config::BLOCK_SIZE &&
              Config::MAX_NUM_TOKENS % QUAD == 0);

// a[i] of a wave-uniform array, i wave-uniform or the lane's, as selects of its values: the compiler folds selects of
// a local array's loads into one load at a selected address, which puts the array (and its struct) in scratch
template <int N> __device__ __forceinline__ int pick(const int (&a)[N], int i) {
    int v = a[0];
    asm("" : "+s"(v));
#pragma unroll
    for (int k = 1; k < N; ++k) {
        int e = a[k];
        asm("" : "+s"(e));
        v = i == k ? e : v;
    }
    return v;
}

// glm5::ix_bf16::unit_out on this kernel's LDS: unit u's [M][16] partial sums from x [M][HIDDEN_SIZE] bf16 in LDS
// (rows LDS_ROW<HIDDEN_SIZE> apart), the waves' tiles added in wave order, out in sc1 stores
template <int NUM_TOKENS>
__device__ __forceinline__ void unit_out(const IndexerBf16Params &p, const uint32x4 (&w)[UNIT_STEPS],
                                         const bfloat16 *x, GroupSmem<Config::MAX_NUM_TOKENS> &s, int u) {
    const int       tid  = threadIdx.x;
    const int       lane = tid % THREADS_PER_WARP;
    const bfloat16 *xk   = x + min(lane % 16, NUM_TOKENS - 1) * LDS_ROW<Config::HIDDEN_SIZE> + unit_k(u);
    floatx4         acc  = {};
#pragma unroll
    for (int i = 0; i < UNIT_STEPS; ++i) {
        const bfloat16x8 b = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b, acc, 0, 0, 0);
    }
    s.tiles[tid] = acc;
    block_sync_lds();
    if (tid < 16 * NUM_TOKENS) {
        const floatx4 *tile = s.tiles + 16 * (tid % 16 / 4) + tid / 16;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][tid % 4];
        }
        store_sc1(reinterpret_cast<uint32_t *>(p.partial + u * NUM_TOKENS * 16 + tid), __float_as_uint(sum));
    }
    block_sync_lds();
}

// Past X_ROWS tokens qkv_a_rows's second pass leaves x's rows X_ROWS .. in s.x's rows 0 .., over tokens 0 .. LOW - 1
// (LOW = NUM_TOKENS - X_ROWS): unit u's lanes (g, c < LOW) norm token c's values at their K again, as qkv_a_rows did
// (rms_scale_sglang), from x and gamma, with the factor its BlockReduce gives (the waves' sums it left in s.reduce,
// added in its order: blocks below Q_B_BLOCK0 norm nothing else before the products); the other lanes' are unused.
// The loads only issued here, the rest once they are in (low_norm).
template <int NUM_TOKENS>
__device__ __forceinline__ void low_loads(const AttnQkvBf16Params &a, int u, bfloat16 (&x)[UNIT_STEPS][8],
                                          bfloat16 (&gamma)[UNIT_STEPS][8]) {
    constexpr int LOW = NUM_TOKENS - X_ROWS;
    const int     c   = min(static_cast<int>(threadIdx.x % 16), LOW - 1);
#pragma unroll
    for (int i = 0; i < UNIT_STEPS; ++i) {
        load_data<bfloat16, 8>(a.x + c * Config::HIDDEN_SIZE + unit_k(u) + 32 * i, x[i]);
    }
#pragma unroll
    for (int i = 0; i < UNIT_STEPS; ++i) {
        load_data<bfloat16, 8>(a.gamma + unit_k(u) + 32 * i, gamma[i]);
    }
}

template <int NUM_TOKENS>
__device__ __forceinline__ void low_norm(const AttnQkvBf16Smem &s, float eps, bfloat16 (&x)[UNIT_STEPS][8],
                                         const bfloat16 (&gamma)[UNIT_STEPS][8]) {
    constexpr int LOW = NUM_TOKENS - X_ROWS;
    constexpr int N   = ROW_LOADS * 8 * Config::BLOCK_SIZE; // rms_factors_sglang's
    const int     c   = threadIdx.x % 16;
    float         factor = 0.0f;
#pragma unroll
    for (int m = 0; m < LOW; ++m) {
        float sum = s.reduce[m];
#pragma unroll
        for (int w = 1; w < WAVES; ++w) {
            sum = sum + s.reduce[w * NUM_TOKENS + m];
        }
        const float f = rsqrtf(sum / N + eps);
        factor        = c == m ? f : factor;
    }
    rms_scale_sglang<UNIT_STEPS>(x, gamma, factor);
}

// unit_out past X_ROWS tokens: lane (g, c)'s column token c, from low (low_norm's) for c < LOW, else from s.x's row
// holding it
template <int NUM_TOKENS>
__device__ __forceinline__ void unit_out_low(const IndexerBf16Params &p, const uint32x4 (&w)[UNIT_STEPS],
                                             const bfloat16 *x, GroupSmem<Config::MAX_NUM_TOKENS> &s, int u,
                                             const bfloat16 (&low)[UNIT_STEPS][8]) {
    constexpr int   LOW  = NUM_TOKENS - X_ROWS;
    const int       tid  = threadIdx.x;
    const int       lane = tid % THREADS_PER_WARP;
    const int       c    = lane % 16;
    const bfloat16 *xk   = x + (c < X_ROWS ? c : c - X_ROWS) * LDS_ROW<Config::HIDDEN_SIZE> + unit_k(u);
    floatx4         acc  = {};
#pragma unroll
    for (int i = 0; i < UNIT_STEPS; ++i) {
        bfloat16x8 own;
        __builtin_memcpy(&own, low[i], sizeof(own));
        // a value, not a load: a select of two loads is folded into a load at a selected address (low in scratch)
        asm volatile("" : "+v"(own));
        const bfloat16x8 lds = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
        const bfloat16x8 b   = c < LOW ? own : lds;
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b, acc, 0, 0, 0);
    }
    s.tiles[tid] = acc;
    block_sync_lds();
    if (tid < 16 * NUM_TOKENS) {
        const floatx4 *tile = s.tiles + 16 * (tid % 16 / 4) + tid / 16;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][tid % 4];
        }
        store_sc1(reinterpret_cast<uint32_t *>(p.partial + u * NUM_TOKENS * 16 + tid), __float_as_uint(sum));
    }
    block_sync_lds();
}

// wk's units, the first of UNITS (weights_proj's after them)
constexpr int K_UNITS = DIM / 16 * SPLITS;

// The rows' lengths, loaded at the kernel's start (nothing written yet: scalar loads, which a later wait for them
// waits for alone; a vector load's wait would wait for every store issued before it, asm stores the compiler does not
// count). M = 16 holds none: its 16 SGPRs through attn_qkv spill registers
template <int NUM_TOKENS> constexpr bool HOLDS_LENS = NUM_TOKENS < 16;

template <int NUM_TOKENS> struct RowLens {
    int v[NUM_TOKENS];
};

template <int NUM_TOKENS> __device__ __forceinline__ RowLens<NUM_TOKENS> row_lens(const IndexerBf16Params &p) {
    RowLens<NUM_TOKENS> lens = {};
    if constexpr (HOLDS_LENS<NUM_TOKENS>) {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            lens.v[m] = p.lens[m];
        }
    }
    return lens;
}

// Whether a row is longer than TOPK (always, for M = 16). Only then are there scores, and only the scores read q_fp8
// and the weights; else every row's top-k is all its positions, and nothing computes them nor what only they read:
// wq_b's groups (q_a's norm below Q_B_BLOCK0 is for them), weights_proj's units, the heads
template <int NUM_TOKENS> __device__ __forceinline__ bool scored(const RowLens<NUM_TOKENS> &lens) {
    if constexpr (!HOLDS_LENS<NUM_TOKENS>) {
        return true;
    }
    int longest = 0;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        longest = max(longest, __builtin_amdgcn_readfirstlane(lens.v[m]));
    }
    return longest > TOPK;
}

// The products on this block once its attn_qkv_bf16 work is done (x normed in s.x on the blocks below QKV_GROUPS,
// q_lora in s.q on those from Q_B_BLOCK0; the others norm q_a once it is out): its unit, then wq_b's group `block` into
// p.q in sc1 stores; then PRODUCTS_PACKET. s.x and s.q share LDS: the unit is done with x before q_a goes in. Past
// X_ROWS tokens the unit's lanes of tokens 0 .. NUM_TOKENS - X_ROWS - 1 norm them again (low_loads, low_norm). Not
// SCORED: wk's units only.
template <int NUM_TOKENS, bool SCORED>
__device__ __forceinline__ void products_as(const AttnQkvBf16Params &a, const IndexerBf16Params &p, uint8_t *smem,
                                            uint32_t epoch) {
    static_assert(NUM_TOKENS <= X_ROWS || (NUM_TOKENS - X_ROWS <= X_ROWS && UNITS <= Q_B_BLOCK0),
                  "x's rows past X_ROWS over rows 0 .. in s.x, its factors' sums in s.reduce on the unit blocks");
    AttnQkvBf16Smem &s     = *reinterpret_cast<AttnQkvBf16Smem *>(smem);
    const int        tid   = threadIdx.x;
    const int        block = blockIdx.x;
    uint32x4        *slots = static_cast<uint32x4 *>(a.workspace);
    uint32x4         w_q[BF16_STEPS<Q_LORA>];
    if (block < (SCORED ? UNITS : K_UNITS)) {
        if constexpr (NUM_TOKENS > X_ROWS) {
            bfloat16 low[UNIT_STEPS][8], gamma[UNIT_STEPS][8];
            low_loads<NUM_TOKENS>(a, block, low, gamma);
            uint32x4 w[UNIT_STEPS];
            load_unit(p, block, w);
            if constexpr (SCORED) {
                load_group_bf16<Q_LORA>(p.wq_b, block, w_q);
            }
            low_norm<NUM_TOKENS>(s, a.epsilon, low, gamma);
            unit_out_low<NUM_TOKENS>(p, w, s.x, s.group, block, low);
        } else {
            uint32x4 w[UNIT_STEPS];
            load_unit(p, block, w);
            if constexpr (SCORED) {
                load_group_bf16<Q_LORA>(p.wq_b, block, w_q);
            }
            unit_out<NUM_TOKENS>(p, w, s.x, s.group, block);
        }
    } else if constexpr (SCORED) {
        load_group_bf16<Q_LORA>(p.wq_b, block, w_q);
    }
    if constexpr (SCORED) {
        if (block < Q_B_BLOCK0) {
            bfloat16 q_gamma[1][8];
            load_data<bfloat16, 8>(a.q_gamma + 8 * tid, q_gamma[0]);
            if constexpr (glm5_m16::QA_UNITS<NUM_TOKENS>) { // every block's unit
                q_a_bf16_units<NUM_TOKENS>(a, s, q_gamma, slots, epoch);
            } else {
                q_a_bf16<NUM_TOKENS>(a, s, q_gamma, slots, epoch);
            }
        }
        group_out_bf16<Q_LORA, NUM_TOKENS, true>(w_q, s.q, s.group, p.q + 16 * block, Q_ROWS);
    }
    publish(slots + block * PACKETS_PER_SLOT + PRODUCTS_PACKET, epoch);
}

template <int NUM_TOKENS>
__device__ __forceinline__ void products(const AttnQkvBf16Params &a, const IndexerBf16Params &p, uint8_t *smem,
                                         uint32_t epoch, bool scored) {
    if (scored) {
        products_as<NUM_TOKENS, true>(a, p, smem, epoch);
    } else {
        products_as<NUM_TOKENS, false>(a, p, smem, epoch);
    }
}

// finish_qk's tokens a wave: wave, wave + WAVES, .. (past NUM_TOKENS - 1 that token again, finished, not stored)
template <int NUM_TOKENS> constexpr int WAVE_TOKENS = (NUM_TOKENS + WAVES - 1) / WAVES;

// lane l's cos and sin of token m's position (l < HALF_ROPE; the others lane HALF_ROPE - 1's, unused): inputs, loaded
// before the products are waited for
struct TokenRope {
    float c, s;
};

__device__ __forceinline__ TokenRope token_rope(const IndexerBf16Params &p, int m) {
    const int     lane = threadIdx.x % THREADS_PER_WARP;
    const int64_t at   = p.position[m] * HALF_ROPE + min(lane, HALF_ROPE - 1);
    return {static_cast<float>(p.cos[at]), static_cast<float>(p.sin[at])};
}

// glm5::ix_bf16::rope_hadamard on T tokens' pairs at once, each token's steps as there
template <int T>
__device__ __forceinline__ void rope_hadamard(const TokenRope (&r)[T], float (&v0)[T], float (&v1)[T]) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    if (lane < HALF_ROPE) {
#pragma unroll
        for (int k = 0; k < T; ++k) {
            const float a = v0[k] * r[k].c - v1[k] * r[k].s;
            const float b = v1[k] * r[k].c + v0[k] * r[k].s;
            v0[k]         = bf16_round(a);
            v1[k]         = bf16_round(b);
        }
    }
    float a[T], b[T];
#pragma unroll
    for (int k = 0; k < T; ++k) {
        a[k] = v0[k] + v1[k];
        b[k] = v0[k] - v1[k];
    }
#pragma unroll
    for (int d = 1; d < THREADS_PER_WARP; d <<= 1) {
        const bool hi = lane & d;
#pragma unroll
        for (int k = 0; k < T; ++k) {
            const float pa = __shfl_xor(a[k], d, THREADS_PER_WARP);
            const float pb = __shfl_xor(b[k], d, THREADS_PER_WARP);
            a[k]           = hi ? pa - a[k] : a[k] + pa;
            b[k]           = hi ? pb - b[k] : b[k] + pb;
        }
    }
#pragma unroll
    for (int k = 0; k < T; ++k) {
        v0[k] = bf16_round(a[k] * HADAMARD_SCALE);
        v1[k] = bf16_round(b[k] * HADAMARD_SCALE);
    }
}

// glm5::ix_bf16::head_out of head h for a wave's tokens m[k] at once: every load issued, then each token's steps as
// there, then the stores (asm stores: no load moves past them), of tokens wave + WAVES k < NUM_TOKENS only
template <int NUM_TOKENS, int T>
__device__ __forceinline__ void heads_out(const IndexerBf16Params &p, int h, int wave, const int (&m)[T],
                                          const TokenRope (&r)[T]) {
    const int  lane    = threadIdx.x % THREADS_PER_WARP;
    const auto q       = raw_buffer(p.q, NUM_TOKENS * Q_ROWS * sizeof(bfloat16));
    const auto partial = raw_buffer(p.partial, UNITS * NUM_TOKENS * 16 * sizeof(float));
    const int  row     = DIM + h;
    uint32_t   pair[T];
    float      part[T];
#pragma unroll
    for (int k = 0; k < T; ++k) {
        pair[k] = buffer_load_sc1<uint32_t>(q, (m[k] * Q_ROWS + h * DIM + 2 * lane) * sizeof(bfloat16));
        part[k] = 0.0f;
    }
    if (lane < SPLITS) {
#pragma unroll
        for (int k = 0; k < T; ++k) {
            part[k] = buffer_load_sc1<float>(
                partial, (((row / 16 * SPLITS + lane) * NUM_TOKENS + m[k]) * 16 + row % 16) * sizeof(float));
        }
    }
    float v0[T], v1[T];
#pragma unroll
    for (int k = 0; k < T; ++k) {
        bfloat16 v[2];
        __builtin_memcpy(v, &pair[k], sizeof(pair[k]));
        v0[k] = static_cast<float>(v[0]);
        v1[k] = static_cast<float>(v[1]);
    }
    rope_hadamard<T>(r, v0, v1);
    float    scale[T];
    uint16_t fp8[T];
#pragma unroll
    for (int k = 0; k < T; ++k) {
        const float amax = fmaxf(WarpReduce<MaxOp>(fmaxf(fabsf(v0[k]), fabsf(v1[k]))), 1e-4f);
        scale[k]         = round_scale(amax);
        const float a    = fminf(fmaxf(v0[k] / scale[k], -FP8_MAX), FP8_MAX);
        const float b    = fminf(fmaxf(v1[k] / scale[k], -FP8_MAX), FP8_MAX);
        fp8[k]           = static_cast<uint16_t>(__builtin_amdgcn_cvt_pk_fp8_f32(a, b, 0, false));
    }
    float w[T];
#pragma unroll
    for (int k = 0; k < T; ++k) {
        w[k] = 0.0f;
#pragma unroll
        for (int s = 0; s < SPLITS; ++s) {
            w[k] += readlane(part[k], s);
        }
    }
#pragma unroll
    for (int k = 0; k < T; ++k) {
        if (NUM_TOKENS % WAVES == 0 || wave + WAVES * k < NUM_TOKENS) {
            store_sc1(reinterpret_cast<bfloat16 *>(p.q_fp8 + (m[k] * HEADS + h) * DIM) + lane,
                      __builtin_bit_cast(bfloat16, fp8[k]));
            if (lane == 0) {
                store_sc1(reinterpret_cast<uint32_t *>(p.weights + m[k] * HEADS + h),
                          __float_as_uint(bf16_round(w[k]) * HEAD_SCALE * scale[k] * HADAMARD_SCALE));
            }
        }
    }
}

// glm5::ix_bf16::key_out for a wave's tokens m[k] at once, as heads_out; gamma, beta (lane l's values 2 l, 2 l + 1)
// and the tokens' slots loaded before
template <int NUM_TOKENS, int T>
__device__ __forceinline__ void keys_out(const IndexerBf16Params &p, int wave, const int (&m)[T],
                                         const TokenRope (&r)[T], const float (&gamma)[2], const float (&beta)[2],
                                         const int64_t (&slot)[T]) {
    const int  lane    = threadIdx.x % THREADS_PER_WARP;
    const auto partial = raw_buffer(p.partial, UNITS * NUM_TOKENS * 16 * sizeof(float));
    uint2      parts[T][SPLITS];
#pragma unroll
    for (int k = 0; k < T; ++k) {
#pragma unroll
        for (int s = 0; s < SPLITS; ++s) {
            parts[k][s] = buffer_load_sc1<uint2>(
                partial, (((lane / 8 * SPLITS + s) * NUM_TOKENS + m[k]) * 16 + 2 * (lane % 8)) * sizeof(float));
        }
    }
    float k0[T], k1[T];
#pragma unroll
    for (int k = 0; k < T; ++k) {
        k0[k] = 0.0f;
        k1[k] = 0.0f;
#pragma unroll
        for (int s = 0; s < SPLITS; ++s) {
            k0[k] += __uint_as_float(parts[k][s].x);
            k1[k] += __uint_as_float(parts[k][s].y);
        }
        k0[k] = bf16_round(k0[k]);
        k1[k] = bf16_round(k1[k]);
    }
#pragma unroll
    for (int k = 0; k < T; ++k) {
        const float mean = WarpReduce<SumOp>(k0[k] + k1[k]) * (1.0f / DIM);
        const float d0 = k0[k] - mean, d1 = k1[k] - mean;
        const float inv  = rsqrtf(WarpReduce<SumOp>(d0 * d0 + d1 * d1) * (1.0f / DIM) + p.k_epsilon);
        k0[k]            = bf16_round(d0 * inv * gamma[0] + beta[0]);
        k1[k]            = bf16_round(d1 * inv * gamma[1] + beta[1]);
    }
    rope_hadamard<T>(r, k0, k1);
    uint32_t e[T];
    uint16_t fp8[T];
#pragma unroll
    for (int k = 0; k < T; ++k) {
        const float    amax  = WarpReduce<MaxOp>(fmaxf(fabsf(k0[k]), fabsf(k1[k])));
        const uint32_t q     = __float_as_uint(__fdiv_rn(fmaxf(amax, 1e-4f), FP8_MAX));
        e[k]                 = (q >> 23) + ((q & 0x7fffff) != 0);
        const float    inv_s = __uint_as_float((254 - e[k]) << 23);
        fp8[k] = static_cast<uint16_t>(__builtin_amdgcn_cvt_pk_fp8_f32(k0[k] * inv_s, k1[k] * inv_s, 0, false));
    }
#pragma unroll
    for (int k = 0; k < T; ++k) {
        if (NUM_TOKENS % WAVES == 0 || wave + WAVES * k < NUM_TOKENS) {
            const int o    = static_cast<int>(slot[k] % PAGE);
            uint8_t  *page = p.ki + slot[k] / PAGE * PAGE_BYTES;
            // read back in this kernel by other XCDs: sc1 stores
            store_sc1(reinterpret_cast<bfloat16 *>(page + o / 16 * 16 * DIM + lane / 8 * 256 + o % 16 * 16 +
                                                   2 * (lane % 8)),
                      __builtin_bit_cast(bfloat16, fp8[k]));
            if (lane == 0) {
                store_sc1(reinterpret_cast<uint32_t *>(page + PAGE * DIM + 4 * o), e[k] << 23);
            }
        }
    }
}

// Blocks 0 .. KEY_BLOCK once every block's products are out: wave w tokens w, w + 4, ..'s head `block` (when scored),
// or their keys (glm5::ix_bf16's head_out and key_out, a wave's tokens at once: heads_out, keys_out); then POST_PACKET
template <int NUM_TOKENS>
__device__ __forceinline__ void finish_qk(const IndexerBf16Params &p, uint32x4 *slots, uint32_t epoch, bool scored) {
    constexpr int T     = WAVE_TOKENS<NUM_TOKENS>;
    const int     block = blockIdx.x;
    const int     wave  = __builtin_amdgcn_readfirstlane(static_cast<int>(threadIdx.x / THREADS_PER_WARP));
    int           m[T];
    TokenRope     r[T];
    if (block < KEY_BLOCK && !scored) {
        publish(slots + block * PACKETS_PER_SLOT + POST_PACKET, epoch);
        return;
    }
#pragma unroll
    for (int k = 0; k < T; ++k) {
        m[k] = min(wave + WAVES * k, NUM_TOKENS - 1);
        r[k] = token_rope(p, m[k]);
    }
    if (block < KEY_BLOCK) {
        wait_for(slots, PRODUCTS_PACKET, 0, Config::NUM_BLOCKS, epoch);
        heads_out<NUM_TOKENS, T>(p, block, wave, m, r);
    } else {
        const int lane = threadIdx.x % THREADS_PER_WARP;
        float     gamma[2], beta[2];
        int64_t   slot[T];
#pragma unroll
        for (int i = 0; i < 2; ++i) {
            gamma[i] = static_cast<float>(p.k_gamma[2 * lane + i]);
            beta[i]  = static_cast<float>(p.k_beta[2 * lane + i]);
        }
#pragma unroll
        for (int k = 0; k < T; ++k) {
            slot[k] = p.slot[m[k]];
        }
        wait_for(slots, PRODUCTS_PACKET, 0, Config::NUM_BLOCKS, epoch);
        keys_out<NUM_TOKENS, T>(p, wave, m, r, gamma, beta, slot);
    }
    publish(slots + block * PACKETS_PER_SLOT + POST_PACKET, epoch);
}

// The rows' segments: runs of consecutive rows whose page tables start on the same page (a request's tokens), each
// scored on its longest row's pages. Per row: its segment's last row, longest row (the first of them), first tile
// in the scores' list and tiles (its longest row's, none when that row is at most TOPK: then the top-k of each of its
// rows is all of them). The list: every segment's tiles in row order, each segment from the first of a scoring
// wave's run tiles, so no wave's tiles span two segments.
template <int NUM_TOKENS> struct Segments {
    uint32_t lead; // bit m: row m starts a segment
    int      len[NUM_TOKENS];
    int      end[NUM_TOKENS];
    int      base[NUM_TOKENS];
    int      start[NUM_TOKENS];
    int      tiles[NUM_TOKENS];
    int      run;   // a scoring wave's tiles
    int      total; // the list's length, each segment's last run whole
};

// the block scoring entry t of the list, run tiles a wave
__device__ __forceinline__ int scoring_block(int t, int run) {
    return SCORE_BLOCK0 + t / run / WAVES;
}

template <int NUM_TOKENS> __device__ __forceinline__ Segments<NUM_TOKENS> segments(const IndexerBf16Params &p) {
    Segments<NUM_TOKENS> sg;
    int                  first[NUM_TOKENS]; // each row's first page
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        sg.len[m] = __builtin_amdgcn_readfirstlane(p.lens[m]);
        first[m]  = __builtin_amdgcn_readfirstlane(p.page_table[m * p.table_width]);
    }
    sg.lead = 1u;
#pragma unroll
    for (int m = 1; m < NUM_TOKENS; ++m) {
        sg.lead |= static_cast<uint32_t>(first[m] != first[m - 1]) << m;
    }
    // backwards: each row's segment's last row, and the longest of its rows from it on and its length (every index a
    // constant: an array indexed at run time goes to scratch, and the struct with it)
    int end = NUM_TOKENS - 1, best = NUM_TOKENS - 1, best_len = sg.len[NUM_TOKENS - 1];
    int longest[NUM_TOKENS];
#pragma unroll
    for (int m = NUM_TOKENS - 1; m >= 0; --m) {
        if (m < NUM_TOKENS - 1 && (sg.lead >> (m + 1) & 1u)) {
            end      = m;
            best     = m;
            best_len = sg.len[m];
        }
        best       = sg.len[m] >= best_len ? m : best;
        best_len   = max(best_len, sg.len[m]);
        sg.end[m]  = end;
        sg.base[m] = best;
        longest[m] = best_len;
    }
    // the run: each segment takes whole runs, at most one more each than an even split of all the tiles would give
    // it, so SCORE_WAVES runs hold them
    int all = 0, segs = 0;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        if (sg.lead >> m & 1u) {
            const int tiles = longest[m] > TOPK ? (longest[m] + 15) / 16 : 0;
            all += tiles;
            segs += tiles > 0;
        }
    }
    const int run = max((all + SCORE_WAVES - segs - 1) / (SCORE_WAVES - segs), 1);
    // forwards: each segment's longest row (its first row's), tiles and first tile
    int total = 0, base = 0, start = 0, tiles = 0;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        if (sg.lead >> m & 1u) {
            base  = sg.base[m];
            tiles = longest[m] > TOPK ? (longest[m] + 15) / 16 : 0;
            start = total;
            total += (tiles + run - 1) / run * run;
        }
        sg.base[m]  = base;
        sg.start[m] = start;
        sg.tiles[m] = tiles;
    }
    sg.run   = run;
    sg.total = total;
    return sg;
}

struct ScoresSmem {
    int32x4 q[Config::MAX_NUM_TOKENS * HEADS * DIM / 16];
    floatx4 w[Config::MAX_NUM_TOKENS * HEADS / 4];
};
// past ScoresSmem: the block's round-0 counts of each row's scores, [row][top 8 bits of its key]
constexpr int R0_AT = sizeof(ScoresSmem);
static_assert(R0_AT + Config::MAX_NUM_TOKENS * 256 * 4 <= Config::SMEM_SIZE);

// The scores (glm5::ix_bf16::scores for segments) once q and the weights are out (POST_PACKET of blocks 0 ..
// KEY_BLOCK - 1), and the keys (KEY_BLOCK's) for a block reading one of this call's: logits[m][t] = s(t) sum_h
// w[m][h] relu(<q[m][h], k(t)>) for t < lens[m], in sc1 stores. Every scoring wave takes a run of sg's list, tiles
// of one segment, each read once from its longest row's pages when the segment's rows the block reaches have those
// pages there, else each such row reads its own; a tile holding a key of this call's (written on another XCD) is
// read with sc1. A block stages the q and weights of the rows of its segments only. Each tile's scores as
// glm5::ix_bf16's, a quad of the segment's rows at a time: a quad's rows past its last row are not scored (their
// sums 0) when the quad's rows read the same tiles, else they repeat it; either way unstored.
template <int NUM_TOKENS>
__device__ __forceinline__ uint32_t scores(const IndexerBf16Params &p, const Segments<NUM_TOKENS> &sg, uint8_t *smem,
                                           const uint32x4 *slots, uint32_t epoch) {
    constexpr int M     = NUM_TOKENS;
    ScoresSmem   &s     = *reinterpret_cast<ScoresSmem *>(smem);
    const int     tid   = threadIdx.x;
    const int     lane  = tid % THREADS_PER_WARP;
    const int     sb    = static_cast<int>(blockIdx.x) - SCORE_BLOCK0; // among the scoring blocks
    const int     total = sg.total;
    if (sb < 0 || total == 0) {
        return 0u;
    }
    const int run = sg.run;
    const int b0  = sb * WAVES * run; // the block's first tile
    // a block whose first wave has no tiles has none
    if (b0 >= total) {
        return 0u;
    }
    const int b1    = min(b0 + WAVES * run, total);
    const int wave  = __builtin_amdgcn_readfirstlane(sb * WAVES + tid / THREADS_PER_WARP);
    const int first = wave * run;
    int       fresh[M];      // the 16-key tile (slot / 16) of each token's key
    int       fresh_page[M]; // its page, and its key's place in it
    int       fresh_at[M];
#pragma unroll
    for (int n = 0; n < M; ++n) {
        const int slot = __builtin_amdgcn_readfirstlane(static_cast<int>(p.slot[n]));
        fresh[n]       = slot / 16;
        fresh_page[n]  = slot / PAGE;
        fresh_at[n]    = slot % PAGE;
    }
    const auto page = [&](int n, int key) { return p.page_table[n * p.table_width + key / PAGE]; };
    // the first row of the segment holding tile t
    const auto segment_of = [&](int t) {
        int r0 = 0;
#pragma unroll
        for (int m = 1; m < M; ++m) {
            r0 = (sg.lead >> m & 1u) && sg.tiles[m] > 0 && sg.start[m] <= t ? m : r0;
        }
        return r0;
    };
    // lane l's B operand of the tile of `key` (a multiple of 16) in page pg (the wave's): key l % 16, values
    // 16 (l / 16) .. and 64 + 16 (l / 16) ..; and that key's scale
    const auto load_tile = [&](int pg, int key, int32x8 &k, float &sk) {
        pg                 = __builtin_amdgcn_readfirstlane(pg);
        const uint8_t *src = p.ki + static_cast<size_t>(pg) * PAGE_BYTES;
        const int      at  = key % PAGE / 16 * 16 * DIM + lane / 16 * 256 + lane % 16 * 16;
        const int      sat = PAGE * DIM + 4 * (key % PAGE + lane % 16);
        bool           own = false;
#pragma unroll
        for (int n = 0; n < M; ++n) {
            own |= pg * (PAGE / 16) + key % PAGE / 16 == fresh[n];
        }
        if (own) {
            const auto buf = raw_buffer(src, PAGE_BYTES);
            const auto lo  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at));
            const auto hi  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at + 1024));
            k              = __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
            sk             = buffer_load_sc1<float>(buf, sat);
        } else {
            k  = load_fragment(src + at, src + at + 1024);
            sk = *reinterpret_cast<const float *>(src + sat);
        }
    };
    // load_tile without the test, in straight-line code (pg uniform): SC1 its sc1 loads (right for any tile), else
    // its plain ones (for a tile known to hold none of this call's keys)
    const auto load_as = [&](auto sc1, int pg, int key, int32x8 &k, float &sk) {
        const uint8_t *src = p.ki + static_cast<size_t>(pg) * PAGE_BYTES;
        const int      at  = key % PAGE / 16 * 16 * DIM + lane / 16 * 256 + lane % 16 * 16;
        const int      sat = PAGE * DIM + 4 * (key % PAGE + lane % 16);
        if constexpr (decltype(sc1)::value) {
            const auto buf = raw_buffer(src, PAGE_BYTES);
            const auto lo  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at));
            const auto hi  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at + 1024));
            k              = __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
            sk             = buffer_load_sc1<float>(buf, sat);
        } else {
            k  = load_fragment(src + at, src + at + 1024);
            sk = *reinterpret_cast<const float *>(src + sat);
        }
    };
    int32x8    k[TILES];
    float      sk[TILES];
    // tiles t .. t + TILES - 1 of the segment from `start` (of its row `base`), those past `end` its last again; their
    // pages first, all in before the first tile's loads (vmcnt counts in order, and a tile's loads, in branches, count
    // as none: a page waited for after them would wait for them too)
    const auto load_batch = [&](int base, int start, int t, int end) {
        int pg[TILES];
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            pg[j] = page(base, 16 * (min(t + j, end - 1) - start));
        }
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            pg[j] = __builtin_amdgcn_readfirstlane(pg[j]);
        }
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            load_tile(pg[j], 16 * (min(t + j, end - 1) - start), k[j], sk[j]);
        }
    };
    // the wave's tiles: first .. end - 1, all of the segment from row r0 (each segment starts a run), from its entry
    // `start`, read from row `base`'s pages; none past the list. Its first batch goes out now, in plain loads, before
    // the checks below: a block whose keys hold one of this call's loads that batch again after KEY_BLOCK's k (sc1),
    // and reads its every tile with sc1, so what these read of a key not yet written is never used
    const int r0    = first < total ? segment_of(first) : 0;
    const int start = pick(sg.start, r0);
    const int base  = pick(sg.base, r0);
    const int end   = first < total ? min(first + run, start + pick(sg.tiles, r0)) : first;
    if (first < end) {
        int pg[TILES];
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            pg[j] = page(base, 16 * (min(first + j, end - 1) - start));
        }
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            pg[j] = __builtin_amdgcn_readfirstlane(pg[j]);
        }
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            load_as(std::false_type{}, pg[j], 16 * (min(first + j, end - 1) - start), k[j], sk[j]);
        }
    }
    // Per segment the block reaches: whether its rows there have its longest row's pages, and whether its keys, in
    // any of those rows, hold one of this call's. Only a block whose keys hold one waits for KEY_BLOCK's k and loads
    // after it (a line read before k is out may be read again stale). And the rows to stage, those of its segments
    bool     with_k = false;
    uint32_t differ = 0u; // bit r0: the segment from row r0 has a row reading other pages
    int      row_lo = M, row_hi = 0;
    // the rows of the block's segments: those past TOPK get the block's round-0 counts (R0_AT), each a key's top 8 bits
    uint32_t r0_rows = 0u;
    for (int r0 = segment_of(b0); r0 < M && pick(sg.start, r0) < b1; r0 = pick(sg.end, r0) + 1) {
        const int start = pick(sg.start, r0);
        const int tiles = pick(sg.tiles, r0);
        if (tiles == 0) {
            continue;
        }
        const int r1   = pick(sg.end, r0);
        const int base = pick(sg.base, r0);
        row_lo         = min(row_lo, r0);
        row_hi         = max(row_hi, r1 + 1);
        r0_rows |= (2u << r1) - (1u << r0);
        const int k0   = 16 * (max(b0, start) - start);
        const int k1   = 16 * (min(b1, start + tiles) - start);
        const int span = (k1 - 1) / PAGE - k0 / PAGE + 1; // its pages in a row
        bool      d     = false;
        const int items = (r1 - r0 + 1) * span;
        // CHECKS items a lane a round, every read out before the first is compared
        constexpr int CHECKS = 4;
        for (int i0 = 0; i0 < items; i0 += CHECKS * THREADS_PER_WARP) {
            int  pn[CHECKS], pb[CHECKS], kv[CHECKS], lv[CHECKS];
            bool in[CHECKS];
#pragma unroll
            for (int c = 0; c < CHECKS; ++c) {
                const int i = i0 + c * THREADS_PER_WARP + lane;
                const int n = r0 + i / span;
                kv[c]       = (k0 / PAGE + i % span) * PAGE;
                lv[c]       = i < items ? pick(sg.len, n) : 0;
                in[c]       = kv[c] < lv[c];
                pn[c]       = in[c] ? page(n, kv[c]) : 0;
                pb[c]       = in[c] ? page(base, kv[c]) : 0;
            }
#pragma unroll
            for (int c = 0; c < CHECKS; ++c) {
                if (in[c]) {
                    d |= pn[c] != pb[c];
#pragma unroll
                    for (int t = 0; t < M; ++t) {
                        const int at = kv[c] + fresh_at[t];
                        with_k |= pn[c] == fresh_page[t] && at >= k0 && at < k1 && at < lv[c];
                    }
                }
            }
        }
        differ |= __ballot(d) != 0 ? 1u << r0 : 0u;
    }
    with_k = __ballot(with_k) != 0;
#pragma unroll
    for (int n = 0; n < M; ++n) {
        r0_rows &= sg.len[n] > TOPK ? ~0u : ~(1u << n);
    }
    uint32_t *const r0_counts = reinterpret_cast<uint32_t *>(smem + R0_AT);
    for (int i = tid; i < M * 256; i += Config::BLOCK_SIZE) {
        r0_counts[i] = 0u;
    }
    // the rows' q and weights into LDS once a block, written by other XCDs: sc1 loads (rows past row_hi read 0)
    wait_for(slots, POST_PACKET, 0, with_k ? KEY_BLOCK + 1 : KEY_BLOCK, epoch);
    {
        const int  rows  = row_hi - row_lo;
        const auto q_buf = raw_buffer(p.q_fp8 + row_lo * HEADS * DIM, rows * HEADS * DIM);
        uint32x4   q_in[M];
#pragma unroll
        for (int i = 0; i < M; ++i) {
            q_in[i] = buffer_load_sc1(q_buf, 16 * (i * ROW_CHUNKS + tid));
        }
        if (tid < rows * HEADS / 4) {
            const auto w_buf = raw_buffer(p.weights, M * HEADS * sizeof(float));
            s.w[row_lo * HEADS / 4 + tid] =
                __builtin_bit_cast(floatx4, buffer_load_sc1(w_buf, 16 * (row_lo * HEADS / 4 + tid)));
        }
#pragma unroll
        for (int i = 0; i < M; ++i) {
            if (i < rows) {
                s.q[(row_lo + i) * ROW_CHUNKS + tid] = __builtin_bit_cast(int32x4, q_in[i]);
            }
        }
    }
    __syncthreads();
    if (first >= end) {
        return r0_rows;
    }
    const auto relu  = [](float x) { return __int_as_float(max(__float_as_int(x), 0)); };
    const int  r1    = pick(sg.end, r0);
    const bool agree = !(differ >> r0 & 1u);
    // the segment's rows at most a quad, agreeing: one pass a batch, during which the batch after loads, tile j's
    // into k[j] once j's scores are out, in straight-line loads (the compiler then waits for each tile alone, vmcnt
    // counting in order): sc1 ones in a block holding one of this call's keys, else plain; its pages s_loads
    // (lgkmcnt), the table not written during the call
    const bool roll  = agree && r1 - r0 < QUAD;
    const auto table = (const __attribute__((address_space(4))) int *)p.page_table + base * p.table_width;
    int        np[3]; // the batch after's pages: its tiles' entries e0 .. (none past its last tile's)
    int        e0 = 0;
    // quad r's pass over batch u: its tiles for the quad's rows i < ROWS (past r1 r1 again), the others' sums 0.
    // OWN: each of the quad's rows to r1 but `base` reads its own tiles, so each tile's MFMAs wait for those loads,
    // and the score stores before them; the rows agreeing, nothing waits. ROLL 1 and 2: the batch full, the batch
    // after loading during it, in plain and in sc1 loads
    const auto pass = [&](int u, int r, auto own, auto rows, auto roll_next) {
        constexpr int ROWS = decltype(rows)::value;
        constexpr int ROLL = decltype(roll_next)::value;
        // lane l writes row r + l / 16's score of the tile's key l % 16
        const int row     = r + lane / 16;
        const int row_len = row <= r1 ? pick(sg.len, row) : 0;
        // A operands: heads 16 g + lane % 16 of row n; the weights of heads 16 g + 4 (lane / 16) + i
        int32x8 q[ROWS][2];
        floatx2 w[ROWS][2][2];
#pragma unroll
        for (int i = 0; i < ROWS; ++i) {
            const int n = min(r + i, r1);
#pragma unroll
            for (int g = 0; g < 2; ++g) {
                const int head = n * HEADS + 16 * g + lane % 16;
                q[i][g]        = __builtin_shufflevector(s.q[head * DIM / 16 + lane / 16],
                                                         s.q[head * DIM / 16 + 4 + lane / 16], 0, 1, 2, 3, 4, 5, 6, 7);
                const floatx4 wg = s.w[(n * HEADS + 16 * g) / 4 + lane / 16];
                w[i][g][0]       = floatx2{wg[0], wg[1]};
                w[i][g][1]       = floatx2{wg[2], wg[3]};
            }
        }
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            if (ROLL == 0 && u + j >= end) {
                break;
            }
            const int key = 16 * (u + j - start);
            int32x8   kn[ROWS];
            float     sn[ROWS];
#pragma unroll
            for (int i = 0; i < ROWS; ++i) {
                const int n = r + i;
                if (decltype(own)::value && n <= r1 && n != base && key < pick(sg.len, n)) {
                    load_tile(page(n, key), key, kn[i], sn[i]);
                } else {
                    kn[i] = k[j];
                    sn[i] = sk[j];
                }
            }
            // the tile against each row i's own kn[i] (every MFMA out before the first result is used): row i's 8
            // heads of the lane against key l % 16, weighed, times its scale; then row i of lanes adds up quad row i's
            floatx4 d[ROWS][2];
#pragma unroll
            for (int i = 0; i < ROWS; ++i) {
#pragma unroll
                for (int g = 0; g < 2; ++g) {
                    d[i][g] = mfma_16x16x128_fp8(q[i][g], kn[i]);
                }
            }
            float v[QUAD] = {};
#pragma unroll
            for (int i = 0; i < ROWS; ++i) {
                floatx2 acc = {};
#pragma unroll
                for (int g = 0; g < 2; ++g) {
                    acc = __builtin_elementwise_fma(w[i][g][0], floatx2{relu(d[i][g][0]), relu(d[i][g][1])}, acc);
                    acc = __builtin_elementwise_fma(w[i][g][1], floatx2{relu(d[i][g][2]), relu(d[i][g][3])}, acc);
                }
                v[i] = (acc[0] + acc[1]) * sn[i];
            }
            const float sum =
                glm5::ix::swap_add16(glm5::ix::swap_add32(v[0], v[2]), glm5::ix::swap_add32(v[1], v[3]));
            if (key + lane % 16 < row_len) {
                const uint32_t k = glm5::ix::score_key(sum);
                store_sc1(reinterpret_cast<uint32_t *>(p.logits + row * p.logits_stride + key + lane % 16), k);
                if (row_len > TOPK) {
                    glm5::topk::lds_add(r0_counts + row * 256 + (k >> 24), 1u);
                }
            }
            if constexpr (ROLL != 0) {
                // the batch after's tile j, from the segment's start (past end its last again, not scored: no line
                // past the wave's tiles is read)
                const int t = min(u + TILES + j, end - 1) - start;
                const int e = t / 4 - e0;
                load_as(std::bool_constant<ROLL == 2>{}, e == 0 ? np[0] : e == 1 ? np[1] : np[2], 16 * t, k[j], sk[j]);
            }
        }
    };
    static_assert(QUAD == 4, "a case per quad's rows");
    // a rolling segment's batches: the first waited for (a block holding one of this call's keys loading it only now),
    // each next loading during the pass before it, the last scored as it comes in. A loop of its own a case of rows
    // and loads: its loads then write the registers its MFMAs read (a copy would wait for its load)
    const auto rolled = [&](auto rows, auto roll_next) {
        if constexpr (decltype(roll_next)::value == 2) {
            load_batch(base, start, first, end);
        }
        __builtin_amdgcn_s_waitcnt(0x0F70); // vmcnt(0): the first batch in before the first store
        int u = first;
        for (; u + TILES < end; u += TILES) {
            const int last = (end - 1 - start) / 4;
            e0             = (u + TILES - start) / 4;
            np[0]          = table[e0];
            np[1]          = table[min(e0 + 1, last)];
            np[2]          = table[min(e0 + 2, last)];
            pass(u, r0, std::false_type{}, rows, roll_next);
        }
        pass(u, r0, std::false_type{}, rows, std::false_type{});
    };
    const auto rolled_rows = [&](auto roll_next) {
        if (r1 == r0) {
            rolled(std::integral_constant<int, 1>{}, roll_next);
        } else if (r1 == r0 + 1) {
            rolled(std::integral_constant<int, 2>{}, roll_next);
        } else if (r1 == r0 + 2) {
            rolled(std::integral_constant<int, 3>{}, roll_next);
        } else {
            rolled(std::integral_constant<int, QUAD>{}, roll_next);
        }
    };
    if (roll) {
        if (with_k) {
            rolled_rows(std::integral_constant<int, 2>{});
        } else {
            rolled_rows(std::integral_constant<int, 1>{});
        }
        return r0_rows;
    }
    for (int u = first; u < end; u += TILES) {
        if (u != first || with_k) {
            load_batch(base, start, u, end);
        }
        __builtin_amdgcn_s_waitcnt(0x0F70); // vmcnt(0): every tile in before the first store
        for (int r = r0; r <= r1; r += QUAD) {
            if (!agree) {
                pass(u, r, std::true_type{}, std::integral_constant<int, QUAD>{}, std::false_type{});
            } else if (r1 == r) {
                pass(u, r, std::false_type{}, std::integral_constant<int, 1>{}, std::false_type{});
            } else if (r1 == r + 1) {
                pass(u, r, std::false_type{}, std::integral_constant<int, 2>{}, std::false_type{});
            } else if (r1 == r + 2) {
                pass(u, r, std::false_type{}, std::integral_constant<int, 3>{}, std::false_type{});
            } else {
                pass(u, r, std::false_type{}, std::integral_constant<int, QUAD>{}, std::false_type{});
            }
        }
    }
    return r0_rows;
}

} // namespace infera_flash::glm5_m16::ix_bf16

// What an indexer layer's kernel for up to 16 tokens a call needs past attn_qkv_bf16 and the scores
// (aklr_m16/ix_indexer_bf16.h): its state, the top-k's rows in it (topk_rows and topk_rows_high, glm5_m16/ix_topk.h)
// and MLA's work after the top-k (mla_after_topk, glm5_m16/mla.h's steps in aklr/indexer_layer.h's roles).
#pragma once

#include "glm5_m16/ix_topk.h"
#include "aklr_m16/attention_layer.h"
#include "aklr_m16/ix_indexer_bf16.h"

namespace infera_flash::glm5_m16 {

using glm5::IndexTopkParams;

struct AttentionIndexerParams {
    AttnQkvBf16Params   attn;
    IndexerBf16Params   ix;
    IndexTopkParams     topk;
    MlaCoreParams       mla;
    RowLinearBf16Params o_proj;
};

// the kernel's state: attn_qkv's sync slots, then those of the scores and top-k, MLA's, o_proj's all-reduce call
// number per block, o's packets (MlaCoreParams::out_tagged), o_latent's (latent_tagged), each for MAX_NUM_TOKENS,
// then the top-k's exchange
struct IndexerState {
    static constexpr int64_t IX     = WORKSPACE_SIZE;
    static constexpr int64_t MLA    = 2 * WORKSPACE_SIZE;
    static constexpr int64_t CALLS  = 3 * WORKSPACE_SIZE;
    static constexpr int64_t TAGGED = CALLS + Config::NUM_BLOCKS * sizeof(int);
    static constexpr int64_t LATENT_TAGGED =
        TAGGED + Config::MAX_NUM_TOKENS * Config::O_PROJ_K / 4 * sizeof(uint32x4);
    static constexpr int64_t TOPK =
        LATENT_TAGGED + Config::MAX_NUM_TOKENS * Config::MLA_HEADS * Config::KV_LORA_RANK / 4 * sizeof(uint32x4);
    static constexpr int64_t BYTES = TOPK + sizeof(topk::IndexTopkState);
};
static_assert(IndexerState::TOPK % sizeof(uint32x4) == 0);

// in the indexer's slots: a block's scores are out (every block, every call)
constexpr int SCORES_PACKET = 0;
// MLA's roles: the attending XCDs, past the top-k's
constexpr int MLA_XCDS = XCDS - topk::TOPK_XCDS;
static_assert(MLA_XCDS == topk::TOPK_XCDS && mla::PROJECTING == Config::NUM_BLOCKS / 2 &&
              ATTENDING<Config::MAX_NUM_TOKENS> <= Config::NUM_BLOCKS / 2 &&
              mla::UNITS<Config::MAX_NUM_TOKENS> <= Config::NUM_BLOCKS / 2 &&
              mla::HEADS * mla::O_GROUPS == Config::NUM_BLOCKS / 2);

// the top-k's rows on XCDs 0 .. TOPK_XCDS - 1 (topk_rows); past them, on the attending XCDs (topk_rows_high)
constexpr int LOW_ROWS = topk::PASS_ROWS<topk::SHORT_BPR>;

// A scoring block's round-0 counts (ix_bf16::scores's, rows `rows`) added into each row's (IndexTopkState::r0_hist) in
// device-scope atomics, before the scores' packet waits for its stores (and so for these); r0_arrive, past that
// packet, counts the block in for each of those rows
__device__ __forceinline__ void r0_flush(const IndexTopkParams &p, const uint8_t *smem, uint32_t rows) {
    if (rows == 0u) {
        return;
    }
    __syncthreads(); // every wave's counts in
    auto           &g      = *static_cast<topk::IndexTopkState *>(p.state);
    const uint32_t *counts = reinterpret_cast<const uint32_t *>(smem + ix_bf16::R0_AT);
    const int       tid    = threadIdx.x;
    for (uint32_t r = rows; r; r &= r - 1) {
        const int      n = __builtin_ctz(r);
        const uint32_t v = counts[n * topk::BINS + tid];
        if (v) {
            __hip_atomic_fetch_add(&g.r0_hist[n][tid], v, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
        }
    }
}

__device__ __forceinline__ void r0_arrive(const IndexTopkParams &p, uint32_t rows) {
    auto     &g   = *static_cast<topk::IndexTopkState *>(p.state);
    const int tid = threadIdx.x;
    if (tid < Config::MAX_NUM_TOKENS && (rows >> tid & 1u)) {
        __hip_atomic_fetch_add(&g.r0_arrived[tid][0], 1u, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    }
}

// Past LOW_ROWS tokens, while each row is at most SHORT_LEN: the half i / SHORT_BPR of XCD x < TOPK_XCDS that takes
// row LOW_ROWS + x after its own row, the first whose row is at most TOPK (its picks only, no select); -1: none, the
// row then on XCD TOPK_XCDS + x
template <int NUM_TOKENS>
__device__ __forceinline__ int paired_half(const ix_bf16::Segments<NUM_TOKENS> &sg, int x) {
    int longest = 0;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        longest = max(longest, sg.len[m]);
    }
    if (longest > topk::SHORT_LEN) {
        return -1;
    }
    return ix_bf16::pick(sg.len, x) <= topk::TOPK                     ? 0
           : ix_bf16::pick(sg.len, topk::TOPK_XCDS + x) <= topk::TOPK ? 1
                                                                       : -1;
}

// The top-k's rows 0 .. LOW_ROWS - 1 on XCDs 0 .. TOPK_XCDS - 1, in passes: while each of them is at most SHORT_LEN,
// 16 blocks a row, row m of the pass's 8 on XCD m % 4, blocks i = b / 8 from 16 (m / 4), then the paired rows
// (paired_half); past that, 32 blocks a row, 4 rows a pass. Each block waits for the blocks scoring its slice
// (SCORES_PACKET); each pick also goes out with the epoch (IndexTopkState::picks) for the attending blocks.
template <int NUM_TOKENS>
__device__ __forceinline__ void topk_rows(const IndexTopkParams &p, uint8_t *smem,
                                          const ix_bf16::Segments<NUM_TOKENS> &sg, uint32x4 *slots, uint32_t epoch) {
    constexpr int ROWS       = NUM_TOKENS < LOW_ROWS ? NUM_TOKENS : LOW_ROWS;
    constexpr int SHORT_ROWS = topk::PASS_ROWS<topk::SHORT_BPR>;
    constexpr int LONG_ROWS  = topk::PASS_ROWS<topk::MAX_BPR>;
    const int     xcd        = blockIdx.x % XCDS;
    const int     i          = blockIdx.x / XCDS;
    int           longest    = 0;
#pragma unroll
    for (int m = 0; m < ROWS; ++m) {
        longest = max(longest, sg.len[m]);
    }
    if (longest > topk::MAX_LEN) {
        __builtin_trap(); // past every KPT class: the contract's rows are at most 2^20
    }
    // row m's block j in its row's KPT class, scores from slice positions (from, n) of the row's segment's tiles
    const auto row = [&](auto bpr, int m, int j) {
        constexpr int BPR         = decltype(bpr)::value;
        const int     start       = ix_bf16::pick(sg.start, m);
        // the blocks scoring the row's segment, each adding its round-0 counts
        const int r0_expected = ix_bf16::scoring_block(start + ix_bf16::pick(sg.tiles, m) - 1, sg.run) -
                                ix_bf16::scoring_block(start, sg.run) + 1;
        const auto    wait_scores = [&](int from, int n) {
            const int b_first = ix_bf16::scoring_block(start + from / 16, sg.run);
            const int b_last  = ix_bf16::scoring_block(start + (from + n - 1) / 16, sg.run);
            wait_for(slots, SCORES_PACKET, b_first, b_last - b_first + 1, epoch);
        };
        static_assert(topk::KPT_CLASSES == 4, "a case per KPT class");
        switch (topk::kpt_class_of<BPR>(ix_bf16::pick(sg.len, m))) {
        case 0:
            topk::index_topk_row<BPR, topk::kpt_of(0)>(p, smem, epoch, m, j, r0_expected, wait_scores);
            break;
        case 1:
            topk::index_topk_row<BPR, topk::kpt_of(1)>(p, smem, epoch, m, j, r0_expected, wait_scores);
            break;
        case 2:
            topk::index_topk_row<BPR, topk::kpt_of(2)>(p, smem, epoch, m, j, r0_expected, wait_scores);
            break;
        default:
            topk::index_topk_row<BPR, topk::kpt_of(3)>(p, smem, epoch, m, j, r0_expected, wait_scores);
        }
    };
    // the passes not unrolled: one copy of each row's four KPT classes
    if (longest <= topk::SHORT_LEN) {
        constexpr int PASSES = (ROWS + SHORT_ROWS - 1) / SHORT_ROWS + (NUM_TOKENS > LOW_ROWS ? 1 : 0);
        for (int q = 0; q < PASSES; ++q) {
            int m = SHORT_ROWS * q + topk::TOPK_XCDS * (i / topk::SHORT_BPR) + xcd;
            if constexpr (NUM_TOKENS > LOW_ROWS) {
                if (q > 0) {
                    m = paired_half<NUM_TOKENS>(sg, xcd) == i / topk::SHORT_BPR ? LOW_ROWS + xcd : NUM_TOKENS;
                }
            }
            if (q > 0) {
                __syncthreads(); // the last pass's LDS
            }
            if (m < NUM_TOKENS) {
                row(std::integral_constant<int, topk::SHORT_BPR>{}, m, i % topk::SHORT_BPR);
            }
        }
    } else {
        for (int q = 0; q < (ROWS + LONG_ROWS - 1) / LONG_ROWS; ++q) {
            const int m = LONG_ROWS * q + xcd;
            if (q > 0) {
                __syncthreads();
            }
            if (m < ROWS) {
                row(std::integral_constant<int, topk::MAX_BPR>{}, m, i);
            }
        }
    }
}

// topk_rows_high's block j of a row is block i = j - HIGH_SHIFT (mod the row's blocks) of its XCD
template <int NUM_TOKENS>
constexpr int HIGH_SHIFT = topk::XCD_BLOCKS - ATTENDING<NUM_TOKENS> / MLA_XCDS % topk::XCD_BLOCKS;

// The top-k's rows LOW_ROWS .. NUM_TOKENS - 1 on the attending XCDs as topk_rows takes its rows, XCD TOPK_XCDS + x row
// LOW_ROWS + x unless XCD x takes it (paired_half): while each of these rows is at most SHORT_LEN, on blocks i >= 16
// (the attending blocks of tokens LOW_ROWS .. and the blocks past ATTENDING), blocks i < 16 taking row
// LOW_ROWS + 4 + x; past that 32 blocks a row. A row's block 0 (its candidates' rounds once the others are done) is its
// XCD's first block past ATTENDING where there is one, so the attending blocks build their rows meanwhile; where there
// is none (HANDED), blocks i = 0 and 16, which then swap roles with blocks i + 1 of XCD x (hands_off).
template <int NUM_TOKENS>
__device__ __forceinline__ void topk_rows_high(const IndexTopkParams &p, uint8_t *smem,
                                               const ix_bf16::Segments<NUM_TOKENS> &sg, uint32x4 *slots,
                                               uint32_t epoch) {
    constexpr int ROWS      = NUM_TOKENS - LOW_ROWS;
    constexpr int LONG_ROWS = topk::PASS_ROWS<topk::MAX_BPR>;
    constexpr int SHIFT     = HIGH_SHIFT<NUM_TOKENS>;
    static_assert(ROWS > 0 && ROWS <= LOW_ROWS && ATTENDING<NUM_TOKENS> % MLA_XCDS == 0);
    const int xcd     = blockIdx.x % XCDS - topk::TOPK_XCDS;
    const int i       = blockIdx.x / XCDS;
    int       longest = 0;
#pragma unroll
    for (int m = LOW_ROWS; m < NUM_TOKENS; ++m) {
        longest = max(longest, sg.len[m]);
    }
    if (longest > topk::MAX_LEN) {
        __builtin_trap();
    }
    // topk_rows's
    const auto row = [&](auto bpr, int m, int j) {
        constexpr int BPR         = decltype(bpr)::value;
        const int     start       = ix_bf16::pick(sg.start, m);
        // the blocks scoring the row's segment, each adding its round-0 counts
        const int r0_expected = ix_bf16::scoring_block(start + ix_bf16::pick(sg.tiles, m) - 1, sg.run) -
                                ix_bf16::scoring_block(start, sg.run) + 1;
        const auto    wait_scores = [&](int from, int n) {
            const int b_first = ix_bf16::scoring_block(start + from / 16, sg.run);
            const int b_last  = ix_bf16::scoring_block(start + (from + n - 1) / 16, sg.run);
            wait_for(slots, SCORES_PACKET, b_first, b_last - b_first + 1, epoch);
        };
        switch (topk::kpt_class_of<BPR>(ix_bf16::pick(sg.len, m))) {
        case 0:
            topk::index_topk_row<BPR, topk::kpt_of(0)>(p, smem, epoch, m, j, r0_expected, wait_scores);
            break;
        case 1:
            topk::index_topk_row<BPR, topk::kpt_of(1)>(p, smem, epoch, m, j, r0_expected, wait_scores);
            break;
        case 2:
            topk::index_topk_row<BPR, topk::kpt_of(2)>(p, smem, epoch, m, j, r0_expected, wait_scores);
            break;
        default:
            topk::index_topk_row<BPR, topk::kpt_of(3)>(p, smem, epoch, m, j, r0_expected, wait_scores);
        }
    };
    if (longest <= topk::SHORT_LEN) {
        const int m = LOW_ROWS + topk::TOPK_XCDS * (1 - i / topk::SHORT_BPR) + xcd;
        if (m < NUM_TOKENS && (m >= LOW_ROWS + topk::TOPK_XCDS || paired_half<NUM_TOKENS>(sg, xcd) < 0)) {
            row(std::integral_constant<int, topk::SHORT_BPR>{}, m, (i + SHIFT) % topk::SHORT_BPR);
        }
    } else {
        for (int q = 0; q < (ROWS + LONG_ROWS - 1) / LONG_ROWS; ++q) {
            const int m = LOW_ROWS + LONG_ROWS * q + xcd;
            if (q > 0) {
                __syncthreads();
            }
            if (m < NUM_TOKENS) {
                row(std::integral_constant<int, topk::MAX_BPR>{}, m, (i + SHIFT) % topk::MAX_BPR);
            }
        }
    }
}

// With every block of the attending XCDs attending, the blocks i of XCD TOPK_XCDS + x that hold a short high row's
// block 0 (hands_off), the last done with the top-k, swap roles with blocks i + 1 of XCD x (block 1 of their low rows,
// topk_rows), done before them: these attend the former's steps (j = 4 i + x), the former combine the latter's unit
// and multiply its group of W_UV
template <int NUM_TOKENS>
constexpr bool HANDED = NUM_TOKENS > LOW_ROWS && ATTENDING<NUM_TOKENS> == Config::NUM_BLOCKS / 2;

template <int NUM_TOKENS>
__device__ __forceinline__ bool hands_off(int i) {
    return i >= 0 && (i + HIGH_SHIFT<NUM_TOKENS>) % topk::SHORT_BPR == 0;
}

// MLA's work on this block after the top-k's, at this call's epoch (slots: MLA's), aklr/indexer_layer.h's roles with
// glm5_m16/mla.h's steps: q, kv, k_pe and the top-k were written earlier in the kernel on other XCDs, so the blocks
// wait for them (attn_slots at attn_epoch, each entry of the top-k showing ix_epoch) and read them with sc1. Block b
// is j = 4 (b / 8) + b % 4 of its half. XCDs 4-7 compute q_latent's group pair j once q_b's groups are out; then the
// first ATTENDING attend token j / TOKEN_BLOCKS's steps j % TOKEN_BLOCKS: this call's rows built (normalizing kv
// themselves) and q staged while the top-k runs, each step's rows read as soon as its entries are out; their partial
// sums go out as packet 1 of slot j (combine_unit's). XCDs 0-3, free once their top-k is done, combine unit j <
// UNITS and multiply W_UV's group j by o_latent, o out as the packets o_proj polls. Packet 0 every call (XCDs 4-7:
// q_latent out). Past LOW_ROWS tokens XCDs 4-7 take the top-k's rows past LOW_ROWS once q_latent is out
// (topk_rows_high on the segments sg, the scores' packets in ix_slots), their attending blocks then building their
// rows; HANDED, the blocks with a row's block 0 and as many of XCDs 0-3 swap roles (hands_off). Loads this block's
// o_proj weights into w_o (combining blocks before they wait, attending ones after attending) and returns
// o_proj's last call number in an SGPR: combining blocks read it before combine, as its read would wait for combine's
// stores. W_UK and W_UV fp8 with their scale (W_BF16: bf16, without a scale).
template <int NUM_TOKENS, bool W_BF16, typename Params>
__device__ __forceinline__ uint32_t mla_after_topk(const Params &p, uint8_t *smem,
                                                   const ix_bf16::Segments<NUM_TOKENS> &sg,
                                                   const uint32x4 *attn_slots, uint32_t attn_epoch,
                                                   uint32x4 *ix_slots, uint32_t ix_epoch, uint32x4 *slots,
                                                   uint32_t epoch, uint32x4 (&w_o)[ROW_LINEAR_STEPS<Config::O_PROJ_K>]) {
    constexpr int        S       = mla::ATTN_STEPS<NUM_TOKENS>;
    constexpr int        B       = mla::TOKEN_BLOCKS<NUM_TOKENS>;
    const MlaCoreParams &ml      = p.mla;
    mla::MlaCoreSmem    &s       = *reinterpret_cast<mla::MlaCoreSmem *>(smem);
    mla::MlaCoreScratch &x       = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
    const auto          &g       = *static_cast<const topk::IndexTopkState *>(p.topk.state);
    const int            tid     = threadIdx.x;
    const int            block   = blockIdx.x;
    const int            xcd     = block % XCDS;
    const int            j       = MLA_XCDS * (block / XCDS) + xcd % MLA_XCDS;
    uint32x4            *my_slot = slots + block * PACKETS_PER_SLOT;
    const auto           post    = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
        }
    };
    // HANDED: attending block ja's steps, as the attending blocks below take theirs
    const auto attend_steps = [&](int ja) __attribute__((always_inline)) {
        const int m = ja / B;
        if constexpr (QA_UNITS<NUM_TOKENS>) {
            wait_kv_units(attn_slots, attn_epoch); // kv's and k_pe's units
        } else {
            wait_for(attn_slots, 0, QA_GROUPS, QKV_GROUPS - QA_GROUPS, attn_epoch);
        }
        mla::fresh_rows<NUM_TOKENS, true>(ml, s, [&](int t, int lane, bfloat16 (&lat)[8]) {
            kv_row_sglang<NUM_TOKENS>(p.attn, t, lane, lat);
        });
        mla::turn_q_pe<true>(ml, s, m);
        wait_for(
            slots, 0, Config::NUM_BLOCKS / 2,
            [](int t) { return XCDS * (t / MLA_XCDS) + topk::TOPK_XCDS + t % MLA_XCDS; }, epoch); // q_latent
        mla::stage_q_latent(s, x, m);
        block_sync_lds(); // the rows and q staged above
        mla::AttendRows<S> r;
        mla::attend_rows<S>(ml, m, ja % B, r, [&](int at) { return topk::tagged_pick(g, at, ix_epoch); });
        if constexpr (QA_UNITS<NUM_TOKENS>) {
            mla::attend_c<NUM_TOKENS, S, true>(ml, s, x, m, x.partial[ja], r);
        } else {
            mla::attend<NUM_TOKENS, S, true>(ml, s, x, m, x.partial[ja], r);
        }
        publish(slots + ja * PACKETS_PER_SLOT + mla::PARTIAL_SUMS_PACKET, epoch);
        if (ja == 0) {
            mla::write_fresh<NUM_TOKENS>(ml, s);
            __syncthreads(); // o_proj's x overwrites s.fresh
        }
    };
    // one copy of the steps for both XCDs' blocks: past ~300 uses of the kernel's parameters, a second one leaves
    // them in scratch (InstCombine no longer reads them from the kernel arguments)
    if constexpr (HANDED<NUM_TOKENS>) {
        static_assert(mla::UNITS<NUM_TOKENS> == Config::NUM_BLOCKS / 2);
        const int i = block / XCDS;
        if (xcd >= topk::TOPK_XCDS) {
            if constexpr (QA_UNITS<NUM_TOKENS>) { // W_UK's loads before the wait
                uint32x4 w_k[mla::WK_LOADS<W_BF16>];
                mla::project_q_weights<W_BF16>(ml, j, w_k);
                wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
                mla::project_q_w<NUM_TOKENS, true, W_BF16>(ml, x, j, w_k);
            } else {
                wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
                mla::project_q<NUM_TOKENS, true, W_BF16>(ml, x, j);
            }
        }
        post();
        if (xcd >= topk::TOPK_XCDS) {
            topk_rows_high<NUM_TOKENS>(p.topk, smem, sg, ix_slots, ix_epoch);
            __syncthreads(); // the top-k's LDS
        }
        // block i of XCD TOPK_XCDS + x and block i + 1 of XCD x, if swapped, each take the other's role
        const bool swapped = hands_off<NUM_TOKENS>(xcd >= topk::TOPK_XCDS ? i : i - 1);
        if ((xcd >= topk::TOPK_XCDS) == swapped) {
            const int u = swapped ? j + MLA_XCDS : j;
            uint32x4  w_v[mla::WUV_REGS * (W_BF16 ? 2 : 1)];
            mla::wuv_weights<W_BF16>(ml, u, w_v);
            row_linear_bf16_weights<Config::O_PROJ_K>(p.o_proj, w_o);
            const uint32_t call = __builtin_amdgcn_readfirstlane(last_call(p.o_proj.ar));
            asm volatile("" ::"s"(call) : "memory"); // read here: the compiler would sink it past combine
            mla::combine_unit<NUM_TOKENS>(ml, s, x, u, slots, epoch, mla::PARTIAL_SUMS_PACKET);
            block_sync_lds(); // wuv_unit's o_latent overwrites s.osum
            mla::wuv_unit<NUM_TOKENS, W_BF16>(ml, s, u, w_v, epoch);
            block_sync_lds(); // o_proj's x overwrites s.tiles
            return call;
        }
        attend_steps(swapped ? j - MLA_XCDS : j);
        row_linear_bf16_weights<Config::O_PROJ_K>(p.o_proj, w_o);
        return __builtin_amdgcn_readfirstlane(last_call(p.o_proj.ar));
    }
    if (xcd < topk::TOPK_XCDS) {
        post();
        uint32x4 w_v[mla::WUV_REGS * (W_BF16 ? 2 : 1)];
        mla::wuv_weights<W_BF16>(ml, j, w_v);
        row_linear_bf16_weights<Config::O_PROJ_K>(p.o_proj, w_o);
        const uint32_t call = __builtin_amdgcn_readfirstlane(last_call(p.o_proj.ar));
        asm volatile("" ::"s"(call) : "memory"); // read here: the compiler would sink it past combine
        if (j < mla::UNITS<NUM_TOKENS>) {
            mla::combine_unit<NUM_TOKENS>(ml, s, x, j, slots, epoch, mla::PARTIAL_SUMS_PACKET);
            block_sync_lds(); // wuv_unit's o_latent overwrites s.osum
        }
        mla::wuv_unit<NUM_TOKENS, W_BF16>(ml, s, j, w_v, epoch);
        block_sync_lds(); // o_proj's x overwrites s.tiles
        return call;
    }
    if constexpr (QA_UNITS<NUM_TOKENS>) { // W_UK's loads before the wait
        uint32x4 w_k[mla::WK_LOADS<W_BF16>];
        mla::project_q_weights<W_BF16>(ml, j, w_k);
        wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
        mla::project_q_w<NUM_TOKENS, true, W_BF16>(ml, x, j, w_k);
    } else {
        wait_for(attn_slots, Q_B_PACKET, Q_B_BLOCK0, Config::NUM_BLOCKS - Q_B_BLOCK0, attn_epoch);
        mla::project_q<NUM_TOKENS, true, W_BF16>(ml, x, j);
    }
    post();
    if constexpr (NUM_TOKENS > LOW_ROWS) {
        topk_rows_high<NUM_TOKENS>(p.topk, smem, sg, ix_slots, ix_epoch);
        __syncthreads(); // the top-k's LDS
    }
    if (j < ATTENDING<NUM_TOKENS>) {
        const int m = j / B;
        if constexpr (QA_UNITS<NUM_TOKENS>) {
            wait_kv_units(attn_slots, attn_epoch); // kv's and k_pe's units
        } else {
            wait_for(attn_slots, 0, QA_GROUPS, QKV_GROUPS - QA_GROUPS, attn_epoch);
        }
        mla::fresh_rows<NUM_TOKENS, true>(ml, s, [&](int t, int lane, bfloat16 (&lat)[8]) {
            kv_row_sglang<NUM_TOKENS>(p.attn, t, lane, lat);
        });
        mla::turn_q_pe<true>(ml, s, m);
        wait_for(
            slots, 0, Config::NUM_BLOCKS / 2,
            [](int t) { return XCDS * (t / MLA_XCDS) + topk::TOPK_XCDS + t % MLA_XCDS; }, epoch); // q_latent
        mla::stage_q_latent(s, x, m);
        block_sync_lds(); // the rows and q staged above
        mla::AttendRows<S> r;
        mla::attend_rows<S>(ml, m, j % B, r, [&](int at) { return topk::tagged_pick(g, at, ix_epoch); });
        if constexpr (QA_UNITS<NUM_TOKENS>) {
            mla::attend_c<NUM_TOKENS, S, true>(ml, s, x, m, x.partial[j], r);
        } else {
            mla::attend<NUM_TOKENS, S, true>(ml, s, x, m, x.partial[j], r);
        }
        publish(slots + j * PACKETS_PER_SLOT + mla::PARTIAL_SUMS_PACKET, epoch);
        if (j == 0) {
            mla::write_fresh<NUM_TOKENS>(ml, s);
            __syncthreads(); // o_proj's x overwrites s.fresh
        }
    }
    row_linear_bf16_weights<Config::O_PROJ_K>(p.o_proj, w_o);
    return __builtin_amdgcn_readfirstlane(last_call(p.o_proj.ar));
}

} // namespace infera_flash::glm5_m16

// row_linear_bf16 (aklr/row_linear_bf16.h) for up to 16 tokens a call, in a layer kernel: x [M, K], packets written
// earlier in the kernel, times a bf16 weight [HIDDEN_SIZE, K] as sglang holds it (row-major) in bf16 products (as
// sglang's tgemm), the tokens the columns, on the all-reduce's row split (block k owns output rows 24k .. 24k + 23,
// waves 0 and 2 taking the first half of K and waves 1 and 3 the second), then its all-reduce (glm5_m16/
// all_reduce.h; world 1: none) and the residual.
#pragma once

#include "common/device.h"
#include "common/math.h"
#include "glm5_m16/all_reduce.h"

namespace infera_flash::glm5_m16 {

struct RowLinearBf16Params {
    // x [M, K] as 16 B packets, 4 values and the writers' epoch, written earlier in the same kernel on other XCDs
    const uint32x4 *x_tagged;
    const bfloat16 *weight; // [HIDDEN_SIZE, K] row-major
    AllReduceParams ar;
};

// x's rows padded by 16 B: rows a multiple of 64 banks apart would put the tokens' reads of one K in one bank
template <int K> struct RowLinearBf16Smem {
    static constexpr int ROW = K + 8;
    bfloat16             x[Config::MAX_NUM_TOKENS * ROW];
    RowsSmem             rows;
};

// a lane's 16 B steps of the weight: a wave takes half of K
template <int K> constexpr int ROW_LINEAR_STEPS = K / 2 / 32;

// This block's weights for row_linear_bf16_rows into w, the loads only issued: lane (g, c) its wave's group's row
// split_row, K k0 + 32 i + 8 g .. + 7 for step i (lm_head's layout); NT: non-temporal loads
template <int K, bool NT = false>
__device__ __forceinline__ void row_linear_bf16_weights(const RowLinearBf16Params &p,
                                                        uint32x4 (&w)[ROW_LINEAR_STEPS<K>]) {
    const int       lane  = threadIdx.x % THREADS_PER_WARP;
    const int       wave  = __builtin_amdgcn_readfirstlane(threadIdx.x / THREADS_PER_WARP);
    const bfloat16 *w_row = p.weight + static_cast<size_t>(split_group(wave) * 16 + split_row(wave, lane)) * K +
                            wave % 2 * (K / 2) + 8 * (lane / 16);
#pragma unroll
    for (int i = 0; i < ROW_LINEAR_STEPS<K>; ++i) {
        if constexpr (NT) { // read once: streamed past L2 and the last-level cache
            w[i] = __builtin_nontemporal_load(reinterpret_cast<const uint32x4 *>(w_row + 32 * i));
        } else {
            w[i] = *reinterpret_cast<const uint32x4 *>(w_row + 32 * i);
        }
    }
}

// row_linear_bf16's work on this block, last_call its all-reduce's last call number: w holds
// row_linear_bf16_weights's, issued earlier, and x comes as packets (p.x_tagged), each loaded until it shows x_epoch.
template <int K, int NUM_TOKENS>
__device__ __forceinline__ void row_linear_bf16_rows(const RowLinearBf16Params &p, uint8_t *smem, uint32_t last_call,
                                                     uint32x4 (&w)[ROW_LINEAR_STEPS<K>], uint32_t x_epoch) {
    constexpr int WAVE_K = K / 2;
    constexpr int STEPS  = ROW_LINEAR_STEPS<K>;
    static_assert(K % 256 == 0 && sizeof(RowLinearBf16Smem<K>) <= Config::SMEM_SIZE &&
                  NUM_TOKENS <= Config::MAX_NUM_TOKENS);

    RowLinearBf16Smem<K> &s = *reinterpret_cast<RowLinearBf16Smem<K> *>(smem);

    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = __builtin_amdgcn_readfirstlane(tid / THREADS_PER_WARP);
    const int k0   = wave % 2 * WAVE_K;

    float residual[AR_ITEMS<NUM_TOKENS>];
    all_reduce_residual<NUM_TOKENS>(p.ar, residual);
    // thread t: x's 16 B chunks t + 256 i
    constexpr int ROW     = RowLinearBf16Smem<K>::ROW;
    constexpr int X_LOADS = NUM_TOKENS * K / 8 / Config::BLOCK_SIZE;
    static_assert(K / 8 % Config::BLOCK_SIZE == 0);
    uint32x4 x[X_LOADS];
    {
        // chunk c from packets 2c and 2c + 1, the ones not yet out loaded again
        const auto xt = raw_buffer(p.x_tagged, NUM_TOKENS * K / 4 * sizeof(uint32x4));
        uint32x4   a[X_LOADS], b[X_LOADS];
        bool       in[X_LOADS] = {};
        bool       all;
        do {
            asm volatile("" ::: "memory");
#pragma unroll
            for (int i = 0; i < X_LOADS; ++i) {
                if (!in[i]) {
                    const int c = Config::BLOCK_SIZE * i + tid;
                    a[i]        = buffer_load_sc1(xt, 2 * c * sizeof(uint32x4));
                    b[i]        = buffer_load_sc1(xt, (2 * c + 1) * sizeof(uint32x4));
                }
            }
            all = true;
#pragma unroll
            for (int i = 0; i < X_LOADS; ++i) {
                in[i] = a[i][3] == x_epoch && b[i][3] == x_epoch;
                all &= in[i];
            }
        } while (!all);
#pragma unroll
        for (int i = 0; i < X_LOADS; ++i) {
            x[i] = uint32x4{a[i][0], a[i][1], b[i][0], b[i][1]};
        }
    }
    pin(last_call);
    const uint32_t call = last_call + 1u;
#pragma unroll
    for (int i = 0; i < X_LOADS; ++i) {
        const int c = Config::BLOCK_SIZE * i + tid;
        *reinterpret_cast<uint32x4 *>(s.x + c / (K / 8) * ROW + 8 * (c % (K / 8))) = x[i];
    }
    block_sync_lds();

    // B: token c's x at the same K; columns past M repeat token M - 1 and are dropped. Its LDS reads B_AHEAD steps
    // ahead of their MFMAs (left to itself, the compiler waited for each before its MFMA)
    constexpr int   B_AHEAD = 4;
    const bfloat16 *xk      = s.x + min(lane % 16, NUM_TOKENS - 1) * ROW + k0 + 8 * (lane / 16);
    static_assert(STEPS >= B_AHEAD);
    bfloat16x8 b[B_AHEAD];
#pragma unroll
    for (int i = 0; i < B_AHEAD; ++i) {
        b[i] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * i);
    }
    floatx4 acc = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(__builtin_bit_cast(bfloat16x8, w[i]), b[i % B_AHEAD], acc, 0,
                                                      0, 0);
        if (i + B_AHEAD < STEPS) {
            b[i % B_AHEAD] = *reinterpret_cast<const bfloat16x8 *>(xk + 32 * (i + B_AHEAD));
        }
        __builtin_amdgcn_sched_barrier(0);
    }
    all_reduce_rows<NUM_TOKENS>(p.ar, s.rows, acc, call, residual);
}

} // namespace infera_flash::glm5_m16

// Device primitives: vector types, loads and stores with cache-policy bits, fp8 and MXFP4 MFMAs,
// wave and block reductions.
#pragma once

#include <hip/hip_runtime.h>

#include "common/hw.h"

namespace infera_flash {

using bfloat16 = __bf16; // not hip_bfloat16: it rounds in software, with a branch per value

using uint32x4 = uint32_t __attribute__((ext_vector_type(4)));
using int32x4  = int __attribute__((ext_vector_type(4)));
using int32x8  = int __attribute__((ext_vector_type(8)));
using floatx2  = float __attribute__((ext_vector_type(2)));
using floatx4  = float __attribute__((ext_vector_type(4)));

template <typename T, int N> __device__ inline void load_data(const T *src, T *dst) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

template <typename T, int N> __device__ inline void store_data(T *dst, const T *src) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

// sc1 sends a global access through the device-wide coherence point. Without it a store stays in
// this XCD's L2 and a load can keep hitting a stale L1 line, so other XCDs never see the value.
// s_nop 1: a VALU must not overwrite the store's data VGPRs for 2 wait states (ISA 4.5), and the
// compiler does not pad stores inside asm.
__device__ inline void store_sc1(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(uint2 *ptr, uint2 val) {
    asm volatile("global_store_dwordx2 %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(uint32_t *ptr, uint32_t val) {
    asm volatile("global_store_dword %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(bfloat16 *ptr, bfloat16 val) {
    const uint32_t bits = __builtin_bit_cast(uint16_t, val);
    asm volatile("global_store_short %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(bits) : "memory");
}

// 16 B packets between blocks of one XCD: the store reaches their L2, an nt load reads it there
// past the CU cache (CDNA4 ISA, tables 49 and 50). asm store, so it is not merged or moved.
__device__ inline void store_l2(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline uint32x4 buffer_load_l2(__amdgpu_buffer_rsrc_t buffer, int offset) {
    constexpr int NT = 2; // the cache-policy operand's nt bit
    return __builtin_bit_cast(uint32x4,
                              __builtin_amdgcn_raw_buffer_load_b128(buffer, offset, 0, NT));
}

// Packets between GPUs, on uncached memory: system scope (sc0 sc1) and nt keep them out of every
// cache even where a mapping is cached. asm, so a polling loop really reloads.
__device__ inline void store_nt(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc0 sc1 nt\n\ts_nop 1" ::"v"(ptr), "v"(val)
                 : "memory");
}

__device__ inline uint32x4 load_nt(const uint32x4 *ptr) {
    uint32x4 val;
    asm volatile("global_load_dwordx4 %0, %1, off sc0 sc1 nt\n\ts_waitcnt vmcnt(0)"
                 : "=v"(val)
                 : "v"(ptr)
                 : "memory");
    return val;
}

// Code that uses val stays after this point and memory accesses stay on their side of it: placed
// after later loads, it keeps the wait for val's load from holding them back.
template <typename T> __device__ inline void pin(T &val) {
    asm volatile("" : "+v"(val)::"memory");
}

// val as a value the compiler cannot see through, in a scalar register: loads whose address uses it
// go out from here, not hoisted with the loads before
__device__ inline int opaque(int val) {
    asm volatile("" : "+s"(val)::"memory");
    return val;
}

// __syncthreads also waits for every global load in flight; this waits for LDS accesses only.
__device__ inline void block_sync_lds() {
    asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
    __builtin_amdgcn_s_barrier();
}

// A raw buffer resource over bytes [base, base + size), for loads with cache-policy bits.
__device__ inline __amdgpu_buffer_rsrc_t raw_buffer(const void *base, int size) {
    return __builtin_amdgcn_make_buffer_rsrc(const_cast<void *>(base), 0, size, 0x00020000);
}

// An sc1 load of a T (4, 8 or 16 B) at a byte offset, counted by the compiler like any load (an asm
// load is not: the compiler may move its register before the data lands).
template <typename T = uint32x4>
__device__ inline T buffer_load_sc1(__amdgpu_buffer_rsrc_t buffer, int offset) {
    constexpr int SC1 = 16; // the cache-policy operand's sc1 bit
    if constexpr (sizeof(T) == 4) {
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b32(buffer, offset, 0, SC1));
    } else if constexpr (sizeof(T) == 8) {
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b64(buffer, offset, 0, SC1));
    } else {
        static_assert(sizeof(T) == 16);
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b128(buffer, offset, 0, SC1));
    }
}

// Loads N consecutive 16-byte packets with sc1, waiting once for all of them.
template <int N> __device__ inline void load_sc1(const uint32x4 *ptr, uint32x4 (&vals)[N]) {
    static_assert(N == 1 || N == 2);
    if constexpr (N == 1) {
        asm volatile("global_load_dwordx4 %0, %1, off sc1\n\ts_waitcnt vmcnt(0)"
                     : "=v"(vals[0])
                     : "v"(ptr)
                     : "memory");
    } else {
        asm volatile("global_load_dwordx4 %0, %2, off sc1\n\t"
                     "global_load_dwordx4 %1, %2, off offset:16 sc1\n\t"
                     "s_waitcnt vmcnt(0)"
                     : "=&v"(vals[0]), "=&v"(vals[1])
                     : "v"(ptr)
                     : "memory");
    }
}

// One lane's 32 B of an fp8 MFMA 16x16x128 operand: K bytes 16g..16g+15 and 64+16g..64+16g+15 of
// row (A) or column (B) l % 16, for g = l / 16 (ISA layout).
__device__ inline int32x8 load_fragment(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = *reinterpret_cast<const int32x4 *>(first);
    const int32x4 hi = *reinterpret_cast<const int32x4 *>(second);
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// load_fragment with nt, for weights read once a layer: they stream through L2 and the MALL instead
// of pushing out what is read again (data read ahead for the next kernel, the lm_head between steps)
__device__ inline int32x8 load_fragment_nt(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(first));
    const int32x4 hi = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(second));
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// D = A B for 16x16 fp8 e4m3 tiles over K = 128; lane l gets D[4 (l / 16) + i][l % 16] in element
// i. Zero scales make the compiler emit the instruction without block scaling.
__device__ inline floatx4 mfma_16x16x128_fp8(int32x8 a, int32x8 b) {
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a, b, floatx4{}, 0, 0, 0, 0, 0, 0);
}

// C + A B for 16x16 MXFP4 (e2m1) tiles over K = 128, D laid out as fp8's. Lane l holds K
// 32 g..32 g + 31 (g = l / 16) of row (A) or column (B) l % 16, two per byte with the lower K in
// the low nibble, and that block's e8m0 scale in byte SEL of scale_a / scale_b (127 = 1.0). Half
// the cycles of fp8.
template <int SEL_A = 0, int SEL_B = 0>
__device__ inline floatx4 mfma_16x16x128_fp4(int32x4 a, int32x4 b, int scale_a, int scale_b,
                                             floatx4 c = {}) {
    constexpr int E2M1 = 4; // cbsz / blgp: the operand format
    // the builtin takes fp8's 8 VGPRs, fp4 reads the first 4: zero padding, as CK, which the
    // compiler drops
    const int32x8 a8 = {a[0], a[1], a[2], a[3], 0, 0, 0, 0};
    const int32x8 b8 = {b[0], b[1], b[2], b[3], 0, 0, 0, 0};
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a8, b8, c, E2M1, E2M1, SEL_A, scale_a,
                                                            SEL_B, scale_b);
}

template <typename T> struct SumOp {
    __device__ static T op(const T &x, const T &y) { return x + y; }
};

template <typename T> struct MaxOp {
    __device__ static T op(const T &x, const T &y) { return x > y ? x : y; }
};

// Orders like the float, as an unsigned integer.
__device__ __forceinline__ uint32_t ordered_bits(float x) {
    const uint32_t bits = __float_as_uint(x);
    return (bits & 0x80000000u) ? ~bits : bits | 0x80000000u;
}

// Each lane gets the value of the lane that DPP_CTRL picks within its 16-lane row. bound_ctrl lets
// the compiler fold the move into the instruction that uses it.
template <int DPP_CTRL, typename T> __device__ inline T dpp_mov(T val) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(
        T, __builtin_amdgcn_mov_dpp(__builtin_bit_cast(int, val), DPP_CTRL, 0xF, 0xF, true));
}

template <typename T> __device__ inline T readlane(T val, int lane) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(T, __builtin_amdgcn_readlane(__builtin_bit_cast(int, val), lane));
}

// Reduces over each aligned group of WIDTH lanes; every lane gets its group's result. DPP within
// a 16-lane row; across rows, row 3 adds row 2 and then rows 0 + 1, and lane 63 is read out. No
// LDS round trip.
template <template <class> class Func, typename T, int WIDTH = THREADS_PER_WARP>
__device__ inline T WarpReduce(T val) {
    static_assert(WIDTH == 4 || WIDTH == 16 || WIDTH == THREADS_PER_WARP);
    val = Func<T>::op(dpp_mov<0xB1>(val), val); // quad_perm [1,0,3,2]
    val = Func<T>::op(dpp_mov<0x4E>(val), val); // quad_perm [2,3,0,1]
    if constexpr (WIDTH == 4) {
        return val;
    }
    val = Func<T>::op(dpp_mov<0x141>(val), val); // row_half_mirror
    val = Func<T>::op(dpp_mov<0x140>(val), val); // row_mirror
    if constexpr (WIDTH == THREADS_PER_WARP) {
        val = Func<T>::op(val, dpp_mov<0x142>(val)); // row_bcast:15, row r gets row r - 1
        val = Func<T>::op(val, dpp_mov<0x143>(val)); // row_bcast:31, rows 2, 3 get row 1
        val = readlane(val, 63);
    }
    return val;
}

// Every thread gets the result. Warps are combined in a fixed order so all blocks get the same
// bits. smem holds NUM_WARPS * N elements and can be reused as soon as this returns. LDS_ONLY
// syncs on LDS alone, leaving global loads in flight.
template <template <class> class Func, int BLOCK_SIZE, bool LDS_ONLY = false, typename T, int N>
__device__ inline void BlockReduce(T (&vals)[N], T *smem) {
    const auto sync = [] {
        if constexpr (LDS_ONLY) {
            block_sync_lds();
        } else {
            __syncthreads();
        }
    };
    constexpr int NUM_WARPS = BLOCK_SIZE / THREADS_PER_WARP;
    const int     warp_id   = threadIdx.x / THREADS_PER_WARP;
    const int     lane_id   = threadIdx.x % THREADS_PER_WARP;

#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = WarpReduce<Func>(vals[n]);
    }
    // not inside the loop above: a branch there would serialize the N independent reductions
    if (lane_id == 0) {
#pragma unroll
        for (int n = 0; n < N; ++n) {
            smem[warp_id * N + n] = vals[n];
        }
    }
    sync();
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = smem[n];
#pragma unroll
        for (int w = 1; w < NUM_WARPS; ++w) {
            vals[n] = Func<T>::op(vals[n], smem[w * N + n]);
        }
    }
    sync();
}

} // namespace infera_flash

// fp8 or MXFP4 GEMM of up to 4 rows of x by an aiter-preshuffled weight, a 16-row group of the
// weight at a time.
#pragma once

#include <type_traits>

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

// aiter-preshuffled weights come in groups of 16 rows; a group's 128-K block is a contiguous 2 KB
// (MXFP4: 1 KB, lane l of the fp4 MFMA reading its 16 B at 16 l)
constexpr int K_BLOCK_BYTES = 16 * 128;
// by format: that block's bytes, and a lane's share of it for the MFMA
template <bool MXFP4> constexpr int K_BLOCK_BYTES_OF = MXFP4 ? K_BLOCK_BYTES / 2 : K_BLOCK_BYTES;
template <bool MXFP4> using Fragment = std::conditional_t<MXFP4, int32x4, int32x8>;

// The dword of aiter's shuffle_scale layout holding the e8m0 of (row, group) of [rows, GROUPS]
// MXFP4 scales: it packs rows r, r + 16 of groups g, g + 4 (r % 32 < 16, g % 8 < 4), this one at
// byte group / 4 % 2 * 2 + row / 16 % 2. Returns its byte offset.
template <int GROUPS> __device__ inline int e8m0_dword(int row, int group) {
    return row / 32 * 32 * GROUPS + group / 8 * 256 + group % 4 * 64 + row % 16 * 4;
}

// What a wave of group_out needs of 16-row group `group` of a preshuffled [rows, K] fp8 weight: its
// quarter of the K blocks, and in lane j the scale of its K block j. The scales go out first.
template <int K>
__device__ __forceinline__ void load_group(const uint8_t *weight, const float *scale, int group,
                                           int32x8 (&w)[K / 128 / WAVES], float &w_scales) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    const int     kb0    = threadIdx.x / THREADS_PER_WARP * WAVE_K;
    w_scales             = scale[group / 8 * (K / 128) + kb0 + lane % WAVE_K];
    const uint8_t *src = weight + static_cast<size_t>(group) * 16 * K + kb0 * K_BLOCK_BYTES +
                         lane / 16 * 256 + lane % 16 * 16;
#pragma unroll
    for (int j = 0; j < WAVE_K; ++j) {
        w[j] = load_fragment(src + j * K_BLOCK_BYTES, src + j * K_BLOCK_BYTES + 1024);
    }
}

// load_group for an MXFP4 weight (e2m1 pairs) and its e8m0 in aiter shuffle_scale's layout: lane
// l's 16 B of each of its wave's K blocks, and a dword per two blocks holding their scales of its
// row l % 16 and K 32 (l / 16) on (e8m0_dword: bytes 0 and 2 once shifted right by group % 2 * 8).
template <int K>
__device__ __forceinline__ void load_group_mxfp4(const uint8_t *weight, const uint8_t *scale,
                                                 int group, int32x4 (&w)[K / 128 / WAVES],
                                                 int (&w_e8m0)[K / 128 / WAVES / 2]) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    const int     kb0    = threadIdx.x / THREADS_PER_WARP * WAVE_K;
    static_assert(WAVE_K % 2 == 0);
#pragma unroll
    for (int p = 0; p < WAVE_K / 2; ++p) {
        w_e8m0[p] = *reinterpret_cast<const int *>(
            scale + e8m0_dword<K / 32>(group * 16 + lane % 16, 4 * (kb0 + 2 * p) + lane / 16));
    }
    const uint8_t *src = weight + static_cast<size_t>(group) * 8 * K +
                         kb0 * K_BLOCK_BYTES_OF<true> + lane * 16;
#pragma unroll
    for (int j = 0; j < WAVE_K; ++j) {
        w[j] = *reinterpret_cast<const int32x4 *>(src + j * K_BLOCK_BYTES_OF<true>);
    }
}

// LDS of group_store, for up to MAX_TOKENS rows of x
template <int MAX_TOKENS>
struct GroupSmem {
    floatx4  tiles[Hw::BLOCK_SIZE];   // each wave's 16x16 partial sum
    bfloat16 out[MAX_TOKENS * 16]; // the group's outputs, [M][16]
};

// The group's [M][16] outputs from each wave's 16x16 partial sum acc: the 4 added in wave order,
// rounded to bf16 and stored 16 B per half row at out (row stride `stride`), with sc1 when other
// XCDs read them back.
template <int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_store(floatx4 acc, GroupSmem<MAX_TOKENS> &s, bfloat16 *out,
                                            int stride) {
    static_assert(NUM_TOKENS <= MAX_TOKENS);
    const int tid = threadIdx.x;
    s.tiles[tid]  = acc;
    block_sync_lds();
    // thread (m, r): row r of token m, at lane 16 (r / 4) + m of each wave's tile, element r % 4
    if (tid < 16 * NUM_TOKENS) {
        const floatx4 *tile = s.tiles + 16 * (tid % 16 / 4) + tid / 16;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][tid % 4];
        }
        s.out[tid] = static_cast<bfloat16>(sum);
    }
    block_sync_lds();
    if (tid < 2 * NUM_TOKENS) {
        const uint32x4 val = reinterpret_cast<const uint32x4 *>(s.out)[tid];
        auto          *dst = reinterpret_cast<uint32x4 *>(out + tid / 2 * stride + tid % 2 * 8);
        if constexpr (SC1) {
            store_sc1(dst, val);
        } else {
            *dst = val;
        }
    }
}

// A wave's sum over N fp8 K blocks from kb0: w and, in lane j, the scale of block kb0 + j as
// load_group loads them; x [M][K] in LDS with its scales [M][K / 128], this lane's column token.
template <int K, int N>
__device__ __forceinline__ floatx4 fp8_blocks(const int32x8 (&w)[N], float w_scales,
                                              const uint8_t *x, const float *x_scale, int token,
                                              int kb0) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    floatx4   acc  = {};
#pragma unroll
    for (int j = 0; j < N; ++j) {
        const uint8_t *xq = x + token * K + (kb0 + j) * 128 + lane / 16 * 16;
        acc += mfma_16x16x128_fp8(w[j], load_fragment(xq, xq + 64)) *
               (readlane(w_scales, j) * x_scale[token * (K / 128) + kb0 + j]);
    }
    return acc;
}

// The group's [M][16] outputs (group_store) from the fp8 x [M][K] in LDS (scales [M][K / 128]):
// each wave's partial sum over its K blocks.
template <int K, int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_out(const int32x8 (&w)[K / 128 / WAVES], float w_scales,
                                          const uint8_t *x, const float *x_scale,
                                          GroupSmem<MAX_TOKENS> &s, bfloat16 *out, int stride) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    // columns past M repeat token M - 1 and are dropped
    const floatx4 acc = fp8_blocks<K, WAVE_K>(w, w_scales, x, x_scale,
                                              min(lane % 16, NUM_TOKENS - 1),
                                              threadIdx.x / THREADS_PER_WARP * WAVE_K);
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

// A wave's sum over N MXFP4 K blocks from kb0 (even: block pairs share a dword): w and w_e8m0 as
// load_group_mxfp4 loads them (the e8m0 at bytes 0 and 2 once shifted right by `shift`), x
// [M][K / 2] in LDS with its e8m0 [M][K / 32], this lane's column token. The scales go into the
// instruction, which accumulates.
template <int K, int N>
__device__ __forceinline__ floatx4 mxfp4_blocks(const int32x4 (&w)[N], const int (&w_e8m0)[N / 2],
                                                int shift, const uint8_t *x, const uint8_t *x_e8m0,
                                                int token, int kb0) {
    static_assert(N % 2 == 0);
    const int  lane = threadIdx.x % THREADS_PER_WARP;
    const auto x_of = [&](int b) {
        return *reinterpret_cast<const int32x4 *>(x + token * K / 2 + b * 64 + lane / 16 * 16);
    };
    const auto e_of = [&](int b) { return x_e8m0[token * K / 32 + 4 * b + lane / 16]; };
    floatx4    acc  = {};
#pragma unroll
    for (int i = 0; i < N / 2; ++i) {
        const int b       = kb0 + 2 * i;
        const int w_scale = w_e8m0[i] >> shift;
        acc = mfma_16x16x128_fp4<0, 0>(w[2 * i], x_of(b), w_scale, e_of(b), acc);
        acc = mfma_16x16x128_fp4<2, 0>(w[2 * i + 1], x_of(b + 1), w_scale, e_of(b + 1), acc);
    }
    return acc;
}

// group_out for group `group` of an MXFP4 weight (load_group_mxfp4) and x [M][K / 2] in LDS with
// its e8m0 [M][K / 32].
template <int K, int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_out_mxfp4(const int32x4 (&w)[K / 128 / WAVES],
                                                const int (&w_e8m0)[K / 128 / WAVES / 2], int group,
                                                const uint8_t *x, const uint8_t *x_e8m0,
                                                GroupSmem<MAX_TOKENS> &s, bfloat16 *out,
                                                int stride) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    // columns past M repeat token M - 1 and are dropped
    const floatx4 acc = mxfp4_blocks<K, WAVE_K>(w, w_e8m0, group % 2 * 8, x, x_e8m0,
                                                min(lane % 16, NUM_TOKENS - 1),
                                                threadIdx.x / THREADS_PER_WARP * WAVE_K);
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

} // namespace infera_flash

// MI355X as our kernels use it: block b runs on XCD b % NUM_XCDS, and a kernel whose blocks wait on
// each other runs NUM_BLOCKS of them, all resident.
#pragma once

namespace infera_flash {

constexpr int THREADS_PER_WARP = 64;

struct Hw {
    static constexpr int NUM_BLOCKS = 256; // one per CU
    static constexpr int NUM_XCDS   = 8;
    static constexpr int BLOCK_SIZE = 256;
    // all of a CU's LDS, so each CU runs exactly one block
    static constexpr int SMEM_SIZE = 160 * 1024;
};

constexpr int WAVES = Hw::BLOCK_SIZE / THREADS_PER_WARP; // a block's

} // namespace infera_flash

// Math the kernels share, rounded as HF rounds: bf16 pairs, fp8 conversion and quant, MXFP4 quant
// (as Quark), RoPE, the residual add and RMSNorm.
#pragma once

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

using bfloat16x2 = bfloat16 __attribute__((ext_vector_type(2)));

// bf16 pairs to floats (exact) and back (round to nearest even), for packed floatx2 math
__device__ inline floatx2 to_float2(bfloat16x2 v) { return __builtin_convertvector(v, floatx2); }
__device__ inline bfloat16x2 to_bf16x2(floatx2 v) { return __builtin_convertvector(v, bfloat16x2); }

constexpr float FP8_MAX = 448.0f; // largest finite e4m3fn

using bfloat16x8 = bfloat16 __attribute__((ext_vector_type(8)));

// 8 fp8 values as bf16, exactly, 2 per instruction
__device__ inline bfloat16x8 fp8x8_to_bf16(uint32_t lo, uint32_t hi) {
    const bfloat16x2 v0 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(lo, 1.0f, false);
    const bfloat16x2 v1 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(lo, 1.0f, true);
    const bfloat16x2 v2 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(hi, 1.0f, false);
    const bfloat16x2 v3 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(hi, 1.0f, true);
    return __builtin_shufflevector(__builtin_shufflevector(v0, v1, 0, 1, 2, 3),
                                   __builtin_shufflevector(v2, v3, 0, 1, 2, 3), 0, 1, 2, 3, 4, 5, 6,
                                   7);
}

// aiter's MXFP4 quant (MxScaleRoundMode RoundUp, its default) of a 32-value group held by 4
// consecutive lanes, 8 values each: stores this lane's 8 e2m1 codes (4 B, the lower K in the low
// nibble) to q and returns the group's e8m0 scale, 2^(e8m0 - 127), amax / 6 rounded up to a power
// of two; values round to nearest even.
__device__ inline int quant_mxfp4(const bfloat16 (&x)[8], uint8_t *q) {
    float amax = 0.0f;
#pragma unroll
    for (int j = 0; j < 8; ++j) {
        amax = fmaxf(amax, fabsf(static_cast<float>(x[j])));
    }
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 4>(__float_as_uint(amax)));
    const uint32_t ratio = __float_as_uint(amax / 6.0f);
    const int      e8m0  = min(static_cast<int>((ratio >> 23) + ((ratio & 0x7fffffu) != 0u)), 254);
    // the convert divides by scale; its byte index must be a constant, so one call per byte
    const float scale = __uint_as_float(static_cast<uint32_t>(e8m0) << 23);
    const auto  f     = [&](int j) { return static_cast<float>(x[j]); };
    uint32_t    codes = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(0, f(0), f(1), scale, 0);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(2), f(3), scale, 1);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(4), f(5), scale, 2);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(6), f(7), scale, 3);
    *reinterpret_cast<uint32_t *>(q) = codes;
    return e8m0;
}

// HF's interleaved RoPE of the pair (x0, x1) by the position's (c, s), each bf16 op rounded: an
// FMA would skip the products' rounding
__device__ inline void rope_pair(float &x0, float &x1, float c, float s) {
#pragma clang fp contract(off)
    const auto  bf16 = [](float v) { return static_cast<float>(static_cast<bfloat16>(v)); };
    const float y0   = bf16(bf16(x0 * c) - bf16(x1 * s));
    x1               = bf16(bf16(x1 * c) + bf16(x0 * s));
    x0               = y0;
}

// HF finegrained-fp8 quant of a 1x128 group held by 16 consecutive lanes, 8 values each: stores
// this lane's 8 fp8 values to q and returns the group's scale. A multiply and v_rcp where HF
// divides move a few values by one fp8 step.
__device__ inline float quant_fp8(const bfloat16 (&x)[8], uint8_t *q) {
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
    floatx2     v[4];
    float       amax = 0.0f;
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        v[j] = to_float2(x2[j]); // pairs, so a scale_row before stays packed
        amax = fmaxf(amax, fmaxf(fabsf(v[j].x), fabsf(v[j].y)));
    }
    // amax >= 0 orders like its bits: an integer max, whose DPP moves fold into it
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 16>(__float_as_uint(amax)));
    const float scale     = amax * (1.0f / FP8_MAX);
    const float inv_scale = __builtin_amdgcn_rcpf(fmaxf(scale, 1e-12f));
    uint32_t    fp8[2];
#pragma unroll
    for (int j = 0; j < 2; ++j) {
        const floatx2 lo = v[2 * j] * inv_scale; // packed: two values per instruction
        const floatx2 hi = v[2 * j + 1] * inv_scale;
        // the second convert overwrites the half the first keeps: no need to zero it
        const int any    = __builtin_bit_cast(int, lo.x);
        fp8[j]           = __builtin_amdgcn_cvt_pk_fp8_f32(
            hi.x, hi.y, __builtin_amdgcn_cvt_pk_fp8_f32(lo.x, lo.y, any, false), true);
    }
    *reinterpret_cast<uint2 *>(q) = *reinterpret_cast<const uint2 *>(fp8);
    return scale;
}

// x's rows quantized into LDS, each thread holding LOADS x 8 values of every row (as rms_norm's
// x): fp8 as HF, scales [M][COLS / 128], or MXFP4 as aiter, e8m0 [M][COLS / 32]
template <int NUM_TOKENS, int LOADS, bool MXFP4>
__device__ __forceinline__ void quant_rows(const bfloat16 (&x)[NUM_TOKENS][LOADS][8], uint8_t *q,
                                           void *scales) {
    constexpr int COLS   = LOADS * 8 * Hw::BLOCK_SIZE;
    const int     tid    = threadIdx.x;
    const auto    offset = [&](int m, int i) { return m * COLS + (i * Hw::BLOCK_SIZE + tid) * 8; };
    if constexpr (MXFP4) {
        int e8m0[NUM_TOKENS][LOADS];
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < LOADS; ++i) {
                e8m0[m][i] = quant_mxfp4(x[m][i], q + offset(m, i) / 2);
            }
        }
        // not inside the loop above: a branch there would serialize the groups
        if (tid % 4 == 0) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
                for (int i = 0; i < LOADS; ++i) {
                    static_cast<uint8_t *>(scales)[offset(m, i) / 32] = e8m0[m][i];
                }
            }
        }
    } else {
        float s[NUM_TOKENS][LOADS];
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < LOADS; ++i) {
                s[m][i] = quant_fp8(x[m][i], q + offset(m, i));
            }
        }
        if (tid % 16 == 0) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
                for (int i = 0; i < LOADS; ++i) {
                    static_cast<float *>(scales)[offset(m, i) / 128] = s[m][i];
                }
            }
        }
    }
}

// HF's act_fn(gate) * up of the linears' bf16 outputs: silu and the product each round to bf16
__device__ __forceinline__ bfloat16 silu_mul(bfloat16 gate, bfloat16 up) {
    const float g    = gate;
    const float silu = static_cast<bfloat16>(g / (1.0f + expf(-g)));
    return static_cast<bfloat16>(silu * static_cast<float>(up));
}

// x += residual as HF adds them, in bf16; each thread holds LOADS x 8 values of every row.
template <int NUM_TOKENS, int LOADS>
__device__ __forceinline__ void add_rows(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                         const bfloat16 (&residual)[NUM_TOKENS][LOADS][8]) {
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            auto       *x2 = reinterpret_cast<bfloat16x2 *>(x[m][i]);
            const auto *r2 = reinterpret_cast<const bfloat16x2 *>(residual[m][i]);
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                x2[j] = to_bf16x2(to_float2(x2[j]) + to_float2(r2[j]));
            }
        }
    }
}

// sum2 += x^2 over 8 values, two at a time
__device__ __forceinline__ void add_squares(floatx2 &sum2, const bfloat16 (&x)[8]) {
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        const floatx2 v = to_float2(x2[j]);
        sum2 += v * v;
    }
}

// v as computed, in VGPRs: the compiler would split a pair whose halves are used apart into one
// convert and one multiply per value
template <typename T> __device__ __forceinline__ void keep_pair(T &v) {
    asm volatile("" : "+v"(v));
}

// 8 values of a row as HF's RMSNorm leaves them: x = bf16(gamma * bf16(x * factor)), gamma in
// float pairs
__device__ __forceinline__ void scale_row(bfloat16 (&x)[8], const floatx2 (&gamma)[4],
                                          float factor) {
    auto *x2 = reinterpret_cast<bfloat16x2 *>(x);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        const floatx2 normed = to_float2(to_bf16x2(to_float2(x2[j]) * factor));
        x2[j]                = to_bf16x2(gamma[j] * normed);
        keep_pair(x2[j]);
    }
}

__device__ __forceinline__ void scale_row(bfloat16 (&x)[8], const bfloat16 (&gamma)[8],
                                          float factor) {
    const auto *g2 = reinterpret_cast<const bfloat16x2 *>(gamma);
    floatx2     g[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        g[j] = to_float2(g2[j]);
    }
    scale_row(x, g, factor);
}

// HF's RMSNorm of M rows, each thread holding LOADS x 8 values of every row (so rows of LOADS x 8 x
// BLOCK_SIZE). LDS_ONLY as BlockReduce's.
template <int NUM_TOKENS, int LOADS, bool LDS_ONLY>
__device__ __forceinline__ void rms_norm(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                         const bfloat16 (&gamma)[LOADS][8], float eps,
                                         float *reduce) {
    constexpr int COLS = LOADS * 8 * Hw::BLOCK_SIZE;
    float sums[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            add_squares(sum2, x[m][i]);
        }
        sums[m] = sum2.x + sum2.y;
    }
    BlockReduce<SumOp, Hw::BLOCK_SIZE, LDS_ONLY>(sums, reduce);
    floatx2 g[LOADS][4]; // once for all rows
#pragma unroll
    for (int i = 0; i < LOADS; ++i) {
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            g[i][j] = to_float2(reinterpret_cast<const bfloat16x2 *>(gamma[i])[j]);
            keep_pair(g[i][j]);
        }
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        // torch's mean multiplies by 1/N rather than dividing
        const float factor = rsqrtf(sums[m] * (1.0f / COLS) + eps);
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            scale_row(x[m][i], g[i], factor);
        }
    }
}

