// The blocks of one kernel waiting on each other: each block publishes 16 B packets in its slot of
// a sync workspace, tagged with the call's epoch.
#pragma once

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

// bytes: a 64 B slot per block, 4 packets of 16 B that each kernel numbers for itself; zero it once
// at allocation, never between calls
constexpr int WORKSPACE_SIZE = Hw::NUM_BLOCKS * 64;
// a block's slot in a sync workspace, in 16 B packets
constexpr int PACKETS_PER_SLOT = WORKSPACE_SIZE / Hw::NUM_BLOCKS / sizeof(uint32x4);

// One more than the epoch this block published in its slot last call, past 0 when it wraps (slots
// and tagged buffers start zeroed): stream order makes that store visible to this plain load. A
// vector load: a scalar one holds back the scalar loads after it, those of x's address among them.
__device__ __forceinline__ uint32_t next_epoch(const uint32x4 *slot) {
    const uint32_t epoch =
        __builtin_amdgcn_raw_buffer_load_b32(raw_buffer(slot, sizeof(uint32x4)), 12, 0, 0) + 1;
    return epoch ? epoch : 1;
}

// The packet at src once it shows this call's epoch (sc1 loads: other XCDs write it).
__device__ __forceinline__ uint32x4 wait_packet(const uint32x4 *src, uint32_t epoch) {
    uint32x4 vals[1];
    do {
        load_sc1(src, vals);
    } while (vals[0][3] != epoch);
    return vals[0];
}

// Thread t < count waits until packet `packet` of block first + t's slot shows this call's epoch,
// then the block syncs.
__device__ __forceinline__ void wait_for(const uint32x4 *slots, int packet, int first, int count,
                                         uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < count) {
        wait_packet(slots + (first + threadIdx.x) * PACKETS_PER_SLOT + packet, epoch);
    }
    __syncthreads();
}

// The same over blocks block_of(t), t < count.
template <typename BlockOf>
__device__ __forceinline__ void wait_for(const uint32x4 *slots, int packet, int count,
                                         BlockOf block_of, uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < count) {
        wait_packet(slots + block_of(static_cast<int>(threadIdx.x)) * PACKETS_PER_SLOT + packet,
                    epoch);
    }
    __syncthreads();
}

// the stores before are asm, which the compiler does not count: wait for them, then the packet
// (LOCAL: for this XCD's blocks, through its L2), carrying a and b
template <bool LOCAL = false>
__device__ __forceinline__ void publish(uint32x4 *packet, uint32_t epoch, uint32_t a = 0u,
                                        uint32_t b = 0u) {
    asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
    __syncthreads();
    if (threadIdx.x == 0) {
        if constexpr (LOCAL) {
            store_l2(packet, uint32x4{a, b, 0u, epoch});
        } else {
            store_sc1(packet, uint32x4{a, b, 0u, epoch});
        }
    }
}

// thread t < count waits until packet `packet` of block block_of(t), on this XCD, shows this
// call's epoch (nt loads, from the L2), then the block syncs
template <typename BlockOf>
__device__ __forceinline__ void wait_local(const uint32x4 *slots, int packet, int count,
                                           BlockOf block_of, uint32_t epoch) {
    if (static_cast<int>(threadIdx.x) < count) {
        uint32x4 v;
        do {
            asm volatile("global_load_dwordx4 %0, %1, off nt\n\ts_waitcnt vmcnt(0)"
                         : "=v"(v)
                         : "v"(slots + block_of(threadIdx.x) * PACKETS_PER_SLOT + packet)
                         : "memory");
        } while (v[3] != epoch);
    }
    __syncthreads();
}

} // namespace infera_flash

// The all-reduce over the TP ranks that ends moe's down and row_linear_ar, written for GLM-5's 6144
// rows = 256 blocks x 24.
#pragma once

#include "common/device.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// a packet to another rank's receive buffer: system scope like store_nt, but without nt (the peer's last-level cache
// keeps the line for its poll)
__device__ inline void store_peer(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc0 sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}


// Block k of every rank swaps its share of the [M, HIDDEN_SIZE] output with block k of the others.
struct AllReduceParams {
    bfloat16 *out;        // [M, HIDDEN_SIZE]
    bool      accumulate; // out = bf16(bf16(sum) + prior), HF's residual add
    const bfloat16 *prior; // [M, HIDDEN_SIZE] the residual
    // every rank's AR_BUFFER_SIZE receive buffer, IPC-mapped; per-block call counters; one of each
    // per process, shared by every kernel that exchanges across the ranks (lm_head_argmax too).
    // World 1 means no all-reduce.
    void *recv[Config::MAX_RANKS];
    int  *calls;
    int   rank;
    int   world;
};

// This block's last call number, as a vector load (a scalar one holds back the loads after it) that
// reads 0 past the end (world 1).
__device__ inline uint32_t last_call(const AllReduceParams &p) {
    return __builtin_amdgcn_raw_buffer_load_b32(
        raw_buffer(p.calls, p.world > 1 ? Config::NUM_BLOCKS * sizeof(int) : 0),
        blockIdx.x * sizeof(int), 0, 0);
}

// The row split of moe's down and row_linear_ar: block k owns output rows 24k .. 24k + 23. Blocks
// 2j and 2j + 1 share 16-row groups 3j .. 3j + 2, the even one taking group 3j and rows 0-7 of
// 3j + 1, the odd one rows 8-15 of 3j + 1 and group 3j + 2. Waves 0 and 1 take the full group,
// waves 2 and 3 the half group, each pair splitting K; in the half group lanes 8-15 repeat the rows
// of lanes 0-7 and their C rows are dropped.
static_assert(Config::AR_ROWS == 24); // the split: one 16-row group and half of another
__device__ inline int split_group(int block, int wave) {
    return block / 2 * 3 + (wave < 2 ? 2 * (block & 1) : 1);
}
__device__ inline int split_group(int wave) { return split_group(blockIdx.x, wave); }
// the row of its 16-row group this lane loads
__device__ inline int split_row(int wave, int lane) {
    return wave < 2 ? lane % 16 : lane % 8 + 8 * (blockIdx.x & 1);
}

// The residual this thread adds in all_reduce_rows (0 without accumulate). Load it well before the
// exchange: the exchange's poll waits for every load issued before it.
template <int NUM_TOKENS>
__device__ inline float all_reduce_residual(const AllReduceParams &p) {
    const int tid = threadIdx.x;
    if (p.accumulate && tid < Config::AR_ROWS * NUM_TOKENS) {
        return static_cast<float>(p.prior[tid / Config::AR_ROWS * Config::HIDDEN_SIZE +
                                          Config::AR_ROWS * blockIdx.x + tid % Config::AR_ROWS]);
    }
    return 0.0f;
}

// packet i of block `block`'s share from rank src in the receive buffer, for call's parity
__device__ __forceinline__ uint32_t ar_slot(uint32_t call, int src, int block, int i) {
    return ((call % 2 * Config::MAX_RANKS + src) * Config::NUM_BLOCKS + block) *
               Config::AR_PACKETS +
           i;
}

// all_reduce_rows' LDS
struct RowsSmem {
    floatx4  tiles[Config::BLOCK_SIZE]; // each wave's 16x16 result
    // every rank's [M][AR_ROWS] share
    bfloat16 rows[Config::MAX_RANKS][Config::AR_ROWS * Config::MAX_NUM_TOKENS];
};

// The end of down and row_linear_ar: block k's output rows from its 4 waves' 16x16 tiles, split as
// above, summed over the TP ranks, plus prior (all_reduce_residual) when accumulating. SC1: the rows
// go out in sc1 stores, for other XCDs in the same kernel.
template <int NUM_TOKENS, bool SC1 = false>
__device__ __forceinline__ void all_reduce_rows(const AllReduceParams &p, RowsSmem &s, floatx4 acc,
                                                uint32_t call, float prior) {
    constexpr int ROWS  = Config::AR_ROWS;
    const int     tid   = threadIdx.x;
    const int     block = blockIdx.x;
    const int     odd   = block & 1;
    bfloat16     *at    = p.out + tid / ROWS * Config::HIDDEN_SIZE + ROWS * block + tid % ROWS;
    s.tiles[tid]        = acc;
    block_sync_lds(); // loads the block no longer needs may still be in flight
    if (tid < ROWS * NUM_TOKENS) {
        const int m = tid / ROWS;
        const int q = tid % ROWS; // our output row 24k + q
        // even CUs: the full group's 16 rows, then the half group's 8; odd CUs the other way round
        const bool     full = odd ? q >= 8 : q < 16;
        const int      c    = full ? q - 8 * odd : q - 16 + 16 * odd;
        const floatx4 *tile = s.tiles + (full ? 0 : 2) * THREADS_PER_WARP + 16 * (c / 4) + m;
        s.rows[p.rank][tid] =
            static_cast<bfloat16>(tile[0][c % 4] + tile[THREADS_PER_WARP][c % 4]);
    }
    block_sync_lds();

    // all-reduce: block k swaps its rows with block k of every other rank. A packet is 6 outputs and
    // the call number in one 16 B store, which lands whole (none torn in 5.5M across XGMI, measured;
    // 8 B halves each with the number cost a third more bytes, 1.1 us a layer at M = 4), so a packet
    // showing this call is complete. Two buffers by call parity: no rank gets two calls ahead
    if (p.world > 1) {
        constexpr int PACKETS = ROWS * NUM_TOKENS / 6;
        if (tid < (p.world - 1) * PACKETS) {
            const int       other = (p.rank + 1 + tid / PACKETS) % p.world;
            const int       i     = tid % PACKETS;
            const uint32_t *mine  = reinterpret_cast<const uint32_t *>(s.rows[p.rank]) + 3 * i;
            store_peer(static_cast<uint32x4 *>(p.recv[other]) + ar_slot(call, p.rank, block, i),
                     uint32x4{mine[0], mine[1], mine[2], call});
            const uint32x4 *src =
                static_cast<const uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, i);
            uint32x4 packet;
            do {
                packet = load_nt(src);
            } while (packet.w != call);
            uint32_t *rows = reinterpret_cast<uint32_t *>(s.rows[other]) + 3 * i;
            rows[0]        = packet.x;
            rows[1]        = packet.y;
            rows[2]        = packet.z;
        }
        block_sync_lds();
        if (tid == 0) {
            p.calls[block] = call;
        }
    }
    // in rank order, so every rank gets the same bits
    if (tid < ROWS * NUM_TOKENS) {
        float sum = 0.0f;
        for (int r = 0; r < p.world; ++r) {
            sum += static_cast<float>(s.rows[r][tid]);
        }
        const bfloat16 val =
            p.accumulate ? static_cast<bfloat16>(static_cast<float>(static_cast<bfloat16>(sum)) + prior)
                         : static_cast<bfloat16>(sum);
        if constexpr (SC1) {
            store_sc1(at, val);
        } else {
            *at = val;
        }
    }
}

} // namespace infera_flash::glm5

// The start of a decoder layer's attention in one kernel (attention.hip), with variants that go on
// into the indexer's scores or into MLA; its device code, for that kernel and the layer kernel.
#pragma once

#include <type_traits>

#include "common/gemm.h"
#include "common/math.h"
#include "common/sync.h"
#include "glm5/config.h"
#include "glm5/indexer.h"
#include "glm5/mla.h"

namespace infera_flash::glm5 {

// The start of a decoder layer's attention: input RMSNorm, qkv_a (q_a, kv, k_pe), the q_a and kv
// RMSNorms and q_b, as HF computes them.
struct AttnQkvParams {
    const bfloat16 *x;     // [M, HIDDEN_SIZE] the layer's input
    const bfloat16 *gamma; // [HIDDEN_SIZE] input_layernorm
    float           epsilon;
    // [QKV_A_ROWS, HIDDEN_SIZE] fp8, q_a_proj's rows then kv_a_proj_with_mqa's, preshuffled like
    // gate_up's; scales [ceil(QKV_A_ROWS / 128), NUM_GROUPS]
    const uint8_t  *qkv_weight;
    const float    *qkv_scale;
    const bfloat16 *q_gamma;  // [Q_LORA_RANK] q_a_layernorm
    const bfloat16 *kv_gamma; // [KV_LORA_RANK] kv_a_layernorm
    float           latent_epsilon;
    // [Q_B_ROWS, Q_LORA_RANK] fp8, this rank's heads of q_b_proj, preshuffled; scales [16, 16]
    const uint8_t  *q_b_weight;
    const float    *q_b_scale;
    void           *workspace; // WORKSPACE_SIZE bytes, one per process
    bfloat16       *y;         // [M, HIDDEN_SIZE] the normed x
    bfloat16       *qkv;       // [M, QKV_A_ROWS] qkv_a's output; it ends in k_pe
    bfloat16       *q;         // [M, Q_B_ROWS]
    bfloat16       *q_resid;   // [M, Q_LORA_RANK] the normed q_a
    bfloat16       *k_latent;  // [M, KV_LORA_RANK] the normed kv
};


// With indexer (else null), the indexer's work up to the scores too, on attn_qkv's y and q_resid;
// with mla (else null), mla_core's work after it with W_lat for W_UK, so q gets only its q_pe columns (mla->q,
// k_latent, k_pe point at attn_qkv's outputs). Not both.
void attn_qkv_launch(const AttnQkvParams &params, const IndexerQkParams *indexer,
                     const MlaCoreParams *mla, int num_tokens, hipStream_t stream);

// attn_qkv: blocks 0-163 each compute a 16-row group of qkv_a (q_a 0-127, kv 128-159, k_pe
// 160-163) and publish it; blocks 128-255 then each compute a 16-row group of q_b from all of q_a,
// and block 0 normalizes kv. Blocks 164-255 also write y.
// With the indexer, blocks take its work up to the scores where they would wait: every block one
// group of wq_b (after its qkv_a or q_b group), the 8 of head h on
// h's XCD; blocks 0-31 also weights_proj's row b and then q's head b, blocks 32-127 one of wk's 96
// K splits (block 32 then k; block 163 normalizes kv). ix::WK_PACKET says a block's wk split is
// out, HEAD_PACKET a head or k, WQB_PACKET (for its XCD) its wq_b group. Then every block scores,
// block 32 only the tokens' own keys (see ix::scores).
// With MLA (layers attending a carried top-k), mla_core's work follows in the same kernel, W_UK
// folded into q_b's q_nope rows (W_lat): blocks 0 .. 32M - 1 attend, reading their top-k rows and
// building this call's rows (kv normed there) after their qkv_a group; the others compute q from
// q_a, 16-row groups of q_latent (W_lat) and of q_b's q_pe rows (no q_nope), one on a block with a
// qkv_a group and the rest up to 3 each on blocks 164-255 (read once their share of y is out, off
// x's and qkv_a's way). Blocks 128-255 then combine the partial sums through W_UV. Packet 1 says a
// block's q groups are out, 2 its partial sums.
constexpr int Q_LORA     = Config::Q_LORA_RANK;
constexpr int KV_LORA    = Config::KV_LORA_RANK;
constexpr int QKV_ROWS   = Config::QKV_A_ROWS;
constexpr int QKV_GROUPS = QKV_ROWS / 16;
constexpr int QA_GROUPS  = Q_LORA / 16;
constexpr int KV_GROUPS  = KV_LORA / 16;
// q_b group j runs on block Q_B_BLOCK0 + j
constexpr int Q_B_BLOCK0 = Config::NUM_BLOCKS - Config::Q_B_ROWS / 16;
// of a group's K blocks, each wave takes a quarter
constexpr int QKV_WAVE_K = Config::NUM_GROUPS / WAVES;
constexpr int Q_B_WAVE_K = Q_LORA / 128 / WAVES;
// the blocks without a qkv_a group, which write y: chunk c of a row by block
// QKV_GROUPS + c % Y_WRITERS
constexpr int Y_WRITERS    = Config::NUM_BLOCKS - QKV_GROUPS;
// each thread holds one 16 B chunk of a q_a row
static_assert(Q_LORA == Config::BLOCK_SIZE * 8);
// the indexer's wq_b: a group a block, the 8 of head h on h's XCD (h % 8), so head h's block h
// reads them from its L2: group 8 h + i on block h % 8 + 8 (8 (h / 8) + i)
constexpr int XCDS = Config::NUM_XCDS;
static_assert(ix::Q_ROWS / 16 == Config::NUM_BLOCKS && ix::HEADS == 4 * XCDS &&
              ix::DIM / 16 == XCDS);
__device__ __forceinline__ int wqb_block(int h, int i) {
    return h % XCDS + XCDS * (XCDS * (h / XCDS) + i);
}
__device__ __forceinline__ int wqb_group(int b) {
    return XCDS * (b % XCDS + XCDS * (b / (XCDS * XCDS))) + b / XCDS % XCDS;
}
// with MLA: q's groups, q_latent's (W_lat) then q_b's q_pe groups (k: head k / 4)
constexpr int QL_PACKET   = 1;
constexpr int PART_PACKET = 2;
constexpr int LAT_GROUPS  = mla::HEADS * mla::LATENT / 16;
constexpr int QL_GROUPS   = LAT_GROUPS + mla::HEADS * mla::ROPE / 16;
constexpr int Q_ROUNDS    = 3; // a writer block's most
template <int NUM_TOKENS>
constexpr int ATTENDING = NUM_TOKENS * mla::ATTN_BLOCKS;
// q group i's weights, output and its row stride
struct QGroup {
    const uint8_t *w;
    const float   *scale;
    int            group;
    bfloat16      *out;
    int            stride;
};
__device__ __forceinline__ QGroup q_group(const AttnQkvParams &p, const MlaCoreParams &ml, int i) {
    if (i < LAT_GROUPS) {
        auto &mx = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
        return {ml.w_lat, ml.w_lat_scale, i, &mx.q[0][0][0] + 16 * i, mla::HEADS * mla::LATENT};
    }
    const int k = i - LAT_GROUPS;
    const int g = k / 4 * (mla::Q_HEAD / 16) + mla::NOPE / 16 + k % 4;
    return {p.q_b_weight, p.q_b_scale, g, p.q + 16 * g, Config::Q_B_ROWS};
}
// block b's q group of round r (if below QL_GROUPS): blocks with a qkv_a group one, the writers
// the rest
template <int NUM_TOKENS>
__device__ __forceinline__ int q_group_of(int b, int r) {
    constexpr int LIGHT = QKV_GROUPS - ATTENDING<NUM_TOKENS>;
    return b < QKV_GROUPS ? (r == 0 ? b - ATTENDING<NUM_TOKENS> : QL_GROUPS)
                          : LIGHT + b - QKV_GROUPS + Y_WRITERS * r;
}
static_assert(mla::AD_FIRST == Q_B_BLOCK0 && mla::M_MAX * mla::ATTN_BLOCKS <= Q_B_BLOCK0 &&
              mla::ROPE / 16 == 4 &&
              QKV_GROUPS - mla::M_MAX * mla::ATTN_BLOCKS + Q_ROUNDS * Y_WRITERS >= QL_GROUPS);

struct AttnQkvSmem {
    uint8_t   x[Config::MAX_NUM_TOKENS * Config::HIDDEN_SIZE]; // y in fp8, [M][HIDDEN_SIZE]
    float     x_scale[Config::MAX_NUM_TOKENS * Config::NUM_GROUPS];
    uint8_t   q[Config::MAX_NUM_TOKENS * Q_LORA]; // q_resid in fp8
    float     q_scale[Config::MAX_NUM_TOKENS * Q_LORA / 128];
    GroupSmem<Config::MAX_NUM_TOKENS> group;
    float     reduce[WAVES * Config::MAX_NUM_TOKENS];
    ix::IndexerQkSmem ix; // the indexer's: wk's partial sums, then q's heads for the scores
};

// Once q_a is out: q_a's RMSNorm and fp8 quant into s.q, s.q_scale; q_b group `group`'s block
// (if any) also writes 16 columns of q_resid.
template <int NUM_TOKENS>
__device__ __forceinline__ void q_a_fp8(const AttnQkvParams &p, AttnQkvSmem &s,
                                        const bfloat16 (&gamma)[1][8], const uint32x4 *slots,
                                        uint32_t epoch, int group) {
    const int tid = threadIdx.x;
    wait_for(slots, 0, 0, QA_GROUPS, epoch);
    // written by other XCDs: sc1 loads; thread t holds columns 8t .. 8t + 7
    const auto qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
    bfloat16   q[NUM_TOKENS][1][8];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        const uint32x4 val = buffer_load_sc1(qkv, (m * QKV_ROWS + 8 * tid) * sizeof(bfloat16));
        __builtin_memcpy(q[m][0], &val, 16);
    }
    rms_norm<NUM_TOKENS, 1, true>(q, gamma, p.latent_epsilon, s.reduce);
    if (tid / 2 == group) {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
            store_data<bfloat16, 8>(p.q_resid + m * Q_LORA + 8 * tid, q[m][0]);
        }
    }
    quant_rows<NUM_TOKENS, 1, false>(q, s.q, s.q_scale);
    block_sync_lds();
}

// q_b group blockIdx.x - Q_B_BLOCK0, given its weights: q_a_fp8, then the group's outputs (SC1: in
// sc1 stores, for other XCDs in the same kernel)
template <int NUM_TOKENS, bool SC1 = false>
__device__ __forceinline__ void q_b_group(const AttnQkvParams &p, AttnQkvSmem &s,
                                          const int32x8 (&w)[Q_B_WAVE_K], float w_scales,
                                          const bfloat16 (&gamma)[1][8], const uint32x4 *slots,
                                          uint32_t epoch) {
    const int group = blockIdx.x - Q_B_BLOCK0;
    q_a_fp8<NUM_TOKENS>(p, s, gamma, slots, epoch, group);
    group_out<Q_LORA, NUM_TOKENS, SC1>(w, w_scales, s.q, s.q_scale, s.group, p.q + 16 * group,
                                       Q_LORA);
}

// kv's RMSNorm, token m's values 8 lane .. 8 lane + 7 (a wave takes a token), once kv is out
template <int NUM_TOKENS>
__device__ __forceinline__ void kv_row(const AttnQkvParams &p, int m, int lane, bfloat16 (&kv)[8]) {
    const auto     qkv = raw_buffer(p.qkv, NUM_TOKENS * QKV_ROWS * sizeof(bfloat16));
    const uint32x4 val =
        buffer_load_sc1(qkv, (m * QKV_ROWS + Q_LORA + 8 * lane) * sizeof(bfloat16));
    bfloat16 gamma[8];
    __builtin_memcpy(kv, &val, 16);
    load_data<bfloat16, 8>(p.kv_gamma + 8 * lane, gamma);
    floatx2 sum2 = {};
    add_squares(sum2, kv);
    const float sum = WarpReduce<SumOp>(sum2.x + sum2.y);
    scale_row(kv, gamma, rsqrtf(sum * (1.0f / KV_LORA) + p.latent_epsilon));
}

// Block KV_BLOCK: kv's RMSNorm into k_latent, wave m taking token m (SC1: in sc1 stores)
template <int NUM_TOKENS, bool SC1 = false>
__device__ __forceinline__ void kv_norm(const AttnQkvParams &p, const uint32x4 *slots,
                                        uint32_t epoch) {
    wait_for(slots, 0, QA_GROUPS, KV_GROUPS, epoch);
    const int m    = threadIdx.x / THREADS_PER_WARP;
    const int lane = threadIdx.x % THREADS_PER_WARP;
    if (m < NUM_TOKENS) {
        bfloat16 kv[8];
        kv_row<NUM_TOKENS>(p, m, lane, kv);
        bfloat16 *out = p.k_latent + m * KV_LORA + 8 * lane;
        if constexpr (SC1) {
            store_sc1(reinterpret_cast<uint32x4 *>(out), __builtin_bit_cast(uint32x4, kv));
        } else {
            store_data<bfloat16, 8>(out, kv);
        }
    }
}

// The indexer on block b < Q_B_BLOCK0 after its qkv_a group, x normed in registers and in fp8 in
// LDS: its wq_b group (wqb_group(b)) once q_a is out, with weights_proj's row b then q's head b
// (b < HEADS), or with one of wk's K splits (then k on block WK_BLOCK0).
static_assert(ix::WK_BLOCK0 + ix::WK_GROUPS * ix::WK_SPLITS == Q_B_BLOCK0); // a wk split each
template <int NUM_TOKENS>
__device__ __forceinline__ void ix_low(const AttnQkvParams &p, const IndexerQkParams &ix,
                                       AttnQkvSmem                &s,
                                       const bfloat16 (&x)[NUM_TOKENS][ROW_LOADS][8],
                                       uint32x4 *slots, uint32_t epoch) {
    const int tid = threadIdx.x;
    // its loads below would otherwise go out with qkv_a's weights and slow them down
    const int block = opaque(blockIdx.x);
    uint32x4 *my_slot = slots + block * PACKETS_PER_SLOT;
    int32x8   w[Q_B_WAVE_K];
    float     w_scales;
    bfloat16  gamma[1][8];
    load_data<bfloat16, 8>(p.q_gamma + 8 * tid, gamma[0]);
    const int g = wqb_group(block);
    load_group<Q_LORA>(ix.wq_b, ix.wq_b_scale, g, w, w_scales);
    if (block < ix::HEADS) {
        bfloat16 row[ROW_LOADS][8];
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(
                ix.weights_proj + block * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8,
                row[i]);
        }
        bfloat16 rope[8];
        ix::load_rope<NUM_TOKENS>(ix, rope);
        const float weight = ix::row_weight<NUM_TOKENS>(x, row, s.reduce);
        q_a_fp8<NUM_TOKENS>(p, s, gamma, slots, epoch, -1);
        group_out<Q_LORA, NUM_TOKENS, false>(w, w_scales, s.q, s.q_scale, s.group,
                                             ix.q + 16 * g, ix::Q_ROWS);
        publish<true>(my_slot + ix::WQB_PACKET, epoch);
        wait_local(
            slots, ix::WQB_PACKET, ix::DIM / 16, [&](int t) { return wqb_block(block, t); }, epoch);
        ix::head_out<NUM_TOKENS>(ix, weight, rope);
        publish(my_slot + ix::HEAD_PACKET, epoch);
    } else {
        const int      lane  = tid % THREADS_PER_WARP;
        const int      wave  = tid / THREADS_PER_WARP;
        const int      group = (block - ix::WK_BLOCK0) / ix::WK_SPLITS;
        const int      split = (block - ix::WK_BLOCK0) % ix::WK_SPLITS;
        const int      kb    = split * ix::WK_KB + wave; // this wave's K block of wk
        const float    wk_scale = ix.wk_scale[kb];
        const uint8_t *src = ix.wk + group * 16 * Config::HIDDEN_SIZE + kb * K_BLOCK_BYTES +
                             lane / 16 * 256 + lane % 16 * 16;
        const int32x8 wk = load_fragment(src, src + 1024);
        ix::wk_partial<NUM_TOKENS>(wk, wk_scale, s.x + split * ix::WK_K, Config::HIDDEN_SIZE,
                                   s.x_scale + split * ix::WK_KB, Config::NUM_GROUPS, s.ix,
                                   ix.k_partial +
                                       (group * ix::WK_SPLITS + split) * NUM_TOKENS * 16);
        q_a_fp8<NUM_TOKENS>(p, s, gamma, slots, epoch, -1);
        group_out<Q_LORA, NUM_TOKENS, false>(w, w_scales, s.q, s.q_scale, s.group,
                                             ix.q + 16 * g, ix::Q_ROWS);
        // wk's partial sums for block WK_BLOCK0, the wq_b group for this XCD's head
        publish(my_slot + ix::WK_PACKET, epoch);
        if (tid == 0) {
            store_l2(my_slot + ix::WQB_PACKET, uint32x4{0u, 0u, 0u, epoch});
        }
        if (block == ix::WK_BLOCK0) {
            ix::k_out<NUM_TOKENS>(ix, slots, epoch);
            publish(my_slot + ix::HEAD_PACKET, epoch);
        }
    }
}

// With MLA, block b past its qkv_a group or its share of y. Attending blocks: their rows, then
// attend once q is out. The others, their q groups' weights in (w[r] round r's): q from q_a, then
// blocks 128-255 read their rows of W_UV and combine.
template <int NUM_TOKENS, bool IN_LAYER>
__device__ __forceinline__ void mla_rest(const AttnQkvParams &p, const MlaCoreParams &ml,
                                         AttnQkvSmem &s, mla::MlaCoreSmem &sm,
                                         const int32x8 (&w)[Q_ROUNDS][Q_B_WAVE_K],
                                         const float (&w_scales)[Q_ROUNDS],
                                         const bfloat16 (&gamma)[1][8], uint32x4 *slots,
                                         uint32_t epoch) {
    constexpr int ATTN    = ATTENDING<NUM_TOKENS>;
    const int     block   = blockIdx.x;
    uint32x4     *my_slot = slots + block * PACKETS_PER_SLOT;
    auto         &mx      = *static_cast<mla::MlaCoreScratch *>(ml.scratch);
    if (block < ATTN) {
        mla::AttendRows r;
        mla::attend_rows(ml, block / mla::ATTN_BLOCKS, block % mla::ATTN_BLOCKS, r);
        // kv's and k_pe's groups: this call's tokens' rows, kv normed here
        wait_for(slots, 0, QA_GROUPS, QKV_GROUPS - QA_GROUPS, epoch);
        mla::fresh_rows<NUM_TOKENS, true>(ml, sm, [&](int m, int lane, bfloat16(&kv)[8]) {
            kv_row<NUM_TOKENS>(p, m, lane, kv);
            if (block == 0) {
                store_data<bfloat16, 8>(p.k_latent + m * KV_LORA + 8 * lane, kv);
            }
        });
        wait_for(slots, QL_PACKET, ATTN, Config::NUM_BLOCKS - ATTN, epoch);
        mla::turn_q_pe<true>(ml, sm, block / mla::ATTN_BLOCKS);
        mla::attend<NUM_TOKENS>(ml, sm, mx, block / mla::ATTN_BLOCKS, block % mla::ATTN_BLOCKS,
                                r);
        publish(my_slot + PART_PACKET, epoch);
        if (block == 0) {
            mla::write_fresh<NUM_TOKENS>(ml, sm);
        }
        return;
    }
    q_a_fp8<NUM_TOKENS>(p, s, gamma, slots, epoch, block - Q_B_BLOCK0);
#pragma unroll
    for (int r = 0; r < Q_ROUNDS; ++r) {
        const int i = q_group_of<NUM_TOKENS>(block, r);
        if (i < QL_GROUPS) {
            const QGroup g = q_group(p, ml, i);
            group_out<Q_LORA, NUM_TOKENS, true>(w[r], w_scales[r], s.q, s.q_scale, s.group, g.out,
                                                g.stride);
        }
    }
    publish(my_slot + QL_PACKET, epoch);
    if (block >= Q_B_BLOCK0) { // W_UV only now: its loads would be on q's way
        mla::prefetch_o_proj(ml.prefetch, block - Q_B_BLOCK0);
        uint32x4 w_v[mla::Project<NUM_TOKENS>::REGS];
        mla::project_wv<NUM_TOKENS>(ml, block - Q_B_BLOCK0, w_v);
        mla::combine<NUM_TOKENS, IN_LAYER>(ml, sm, mx, block - Q_B_BLOCK0, w_v, slots, epoch,
                                           PART_PACKET);
    }
}

// attn_qkv's work on this block; returns this call's epoch. IN_LAYER, in a layer kernel: with MLA,
// going on into o_proj, o goes out in sc1 stores and again as packets o_proj polls (out_tagged);
// with the indexer, going on into its top-k and MLA, q, k_latent and the scores go out in sc1
// stores.
template <int NUM_TOKENS, bool INDEXER, bool MLA, bool IN_LAYER = false>
__device__ __forceinline__ uint32_t attn_qkv_block(const AttnQkvParams &p,
                                                   const IndexerQkParams &ix,
                                                   const MlaCoreParams &ml, uint8_t *smem) {
    static_assert(!(INDEXER && MLA) && (MLA || INDEXER || !IN_LAYER) &&
                  sizeof(mla::MlaCoreSmem) <= Config::SMEM_SIZE);
    AttnQkvSmem &s = *reinterpret_cast<AttnQkvSmem *>(smem);
    // with MLA, its LDS once a block is past its attn_qkv work
    mla::MlaCoreSmem &sm = *reinterpret_cast<mla::MlaCoreSmem *>(smem);
    // with the indexer kv's norm goes to a q_b block (blocks 0-127 are on the indexer's way); with
    // MLA the attending blocks normalize kv themselves
    constexpr int KV_BLOCK = INDEXER ? QKV_GROUPS - 1 : MLA ? -1 : 0;

    const int tid   = threadIdx.x;
    const int block = blockIdx.x;
    uint32x4 *slots   = static_cast<uint32x4 *>(p.workspace);
    uint32x4 *my_slot = slots + block * PACKETS_PER_SLOT;

    // x and gamma before any weights: loads complete in issue order. Except in the layer kernel at
    // M = 4, where the qkv_a blocks load their weights first: x's 48 KB ahead of them held the
    // weights back more than the early norm gained (measured; at M = 1 x first wins)
    constexpr bool WEIGHTS_FIRST = IN_LAYER && MLA && NUM_TOKENS == 4;
    const auto     offset        = [&](int m, int i) {
        return m * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8;
    };
    bfloat16   x[NUM_TOKENS][ROW_LOADS][8];
    bfloat16   gamma[ROW_LOADS][8];
    const auto load_rows = [&] {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                load_data<bfloat16, 8>(p.x + offset(m, i), x[m][i]);
            }
        }
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(p.gamma + (i * Config::BLOCK_SIZE + tid) * 8, gamma[i]);
        }
    };
    if (!WEIGHTS_FIRST || block >= QKV_GROUPS) {
        load_rows();
    }
    // nothing uses the values above before the weights' loads are out
    const auto pin_rows = [&] {
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
                pin(*reinterpret_cast<uint32x4 *>(x[m][i]));
            }
            pin(*reinterpret_cast<uint32x4 *>(gamma[i]));
        }
    };
    // input RMSNorm as HF; with write, this block's chunks of y go out (stores in qkv_a's blocks
    // would make the compiler wait for them before the MFMAs)
    const auto input_norm = [&](auto write) {
        const auto writer = [&](int i) {
            return (i * Config::BLOCK_SIZE + tid) % Y_WRITERS == block - QKV_GROUPS;
        };
        rms_norm<NUM_TOKENS, ROW_LOADS, true>(x, gamma, p.epsilon, s.reduce);
        if constexpr (write) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                if (writer(i)) {
#pragma unroll
                    for (int m = 0; m < NUM_TOKENS; ++m) {
                        store_data<bfloat16, 8>(p.y + offset(m, i), x[m][i]);
                    }
                }
            }
        }
    };
    int32x8  w_q_b[Q_B_WAVE_K];
    float    w_q_b_scales;
    bfloat16 q_gamma[1][8];
    // with the indexer, the q_b blocks' wq_b group
    int32x8 w_ix[Q_B_WAVE_K];
    float   w_ix_scales;
    // with MLA, the weights of a block's q groups, w_q[r] round r's
    int32x8 w_q[Q_ROUNDS][Q_B_WAVE_K];
    float   w_q_scales[Q_ROUNDS];
    // the epoch read after each role's first loads: computed earlier, at the join of the roles, its
    // wait held those loads back
    uint32_t epoch;
    // each role a straight line of code, so the compiler counts the loads in flight exactly
    if (block < QKV_GROUPS) {
        int32x8 w[QKV_WAVE_K];
        float   w_scales;
        asm volatile("" ::: "memory"); // the weights' loads go out behind x's (WEIGHTS_FIRST: ahead)
        load_group<Config::HIDDEN_SIZE>(p.qkv_weight, p.qkv_scale, block, w, w_scales);
        if constexpr (WEIGHTS_FIRST) {
            load_rows();
        }
        epoch = next_epoch(my_slot);
        pin_rows();
        pin(w_scales);
        input_norm(std::false_type{});
        quant_rows<NUM_TOKENS, ROW_LOADS, false>(x, s.x, s.x_scale);
        block_sync_lds();
        group_out<Config::HIDDEN_SIZE, NUM_TOKENS, true>(w, w_scales, s.x, s.x_scale, s.group,
                                                         p.qkv + 16 * block, QKV_ROWS);
        publish(my_slot, epoch);
        if (block == KV_BLOCK) {
            kv_norm<NUM_TOKENS, IN_LAYER>(p, slots, epoch);
        }
        if constexpr (MLA) {
            if (block >= ATTENDING<NUM_TOKENS>) {
                const int b = opaque(block); // its loads once qkv_a's weights are in, not with them
                load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
                const QGroup g = q_group(p, ml, q_group_of<NUM_TOKENS>(b, 0));
                load_group<Q_LORA>(g.w, g.scale, g.group, w_q[0], w_q_scales[0]);
            }
        } else {
            if (block < Q_B_BLOCK0) {
                if constexpr (INDEXER) {
                    ix_low<NUM_TOKENS>(p, ix, s, x, slots, epoch);
                    ix::scores<NUM_TOKENS, IN_LAYER>(ix, s.ix, slots, epoch);
                }
                return epoch;
            }
            load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
            if constexpr (INDEXER) {
                const int b = opaque(block); // its loads once qkv_a's weights are in, not with them
                load_group<Q_LORA>(p.q_b_weight, p.q_b_scale, b - Q_B_BLOCK0, w_q_b,
                                   w_q_b_scales);
                load_group<Q_LORA>(ix.wq_b, ix.wq_b_scale, wqb_group(b), w_ix, w_ix_scales);
            } else {
                load_group<Q_LORA>(p.q_b_weight, p.q_b_scale, block - Q_B_BLOCK0, w_q_b,
                                   w_q_b_scales);
            }
        }
    } else {
        // q_b only: its weights stream in while this block writes its share of y
        // (MLA: its q groups' weights only after, off x's and qkv_a's way)
        load_data<bfloat16, 8>(p.q_gamma + 8 * tid, q_gamma[0]);
        asm volatile("" ::: "memory");
        if constexpr (!MLA) {
            load_group<Q_LORA>(p.q_b_weight, p.q_b_scale, block - Q_B_BLOCK0, w_q_b,
                               w_q_b_scales);
        }
        epoch = next_epoch(my_slot);
        pin_rows();
        pin(*reinterpret_cast<uint32x4 *>(q_gamma[0]));
        if constexpr (!MLA) {
            pin(w_q_b_scales);
        }
        input_norm(std::true_type{});
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch}); // keeps this block's epoch in step
        }
        if constexpr (MLA) {
            const int b = opaque(block);
#pragma unroll
            for (int r = 0; r < Q_ROUNDS; ++r) {
                const int i = q_group_of<NUM_TOKENS>(b, r);
                if (i < QL_GROUPS) {
                    const QGroup g = q_group(p, ml, i);
                    load_group<Q_LORA>(g.w, g.scale, g.group, w_q[r], w_q_scales[r]);
                }
            }
        }
    }
    if constexpr (MLA) {
        mla_rest<NUM_TOKENS, IN_LAYER>(p, ml, s, sm, w_q, w_q_scales, q_gamma, slots, epoch);
        return epoch;
    }
    q_b_group<NUM_TOKENS, IN_LAYER>(p, s, w_q_b, w_q_b_scales, q_gamma, slots, epoch);
    if constexpr (INDEXER) {
        if (block >= QKV_GROUPS) { // its wq_b group only now: with x's loads it slows qkv_a's
            const int b = opaque(block);
            load_group<Q_LORA>(ix.wq_b, ix.wq_b_scale, wqb_group(b), w_ix, w_ix_scales);
        }
        group_out<Q_LORA, NUM_TOKENS, false>(w_ix, w_ix_scales, s.q, s.q_scale, s.group,
                                             ix.q + 16 * wqb_group(block), ix::Q_ROWS);
        publish<true>(my_slot + ix::WQB_PACKET, epoch);
        ix::scores<NUM_TOKENS, IN_LAYER>(ix, s.ix, slots, epoch);
    }
    return epoch;
}

} // namespace infera_flash::glm5

// GLM-5.3 on 8 GPUs (TP8): the sizes every GLM-5 kernel is written for, per card where noted.
#pragma once

#include "common/hw.h"

namespace infera_flash::glm5 {

struct Config : Hw {
    static constexpr int   HIDDEN_SIZE           = 6144;
    static constexpr int   QUANT_GROUP_SIZE      = 128; // one fp8 scale per 1x128 of activations
    static constexpr int   NUM_GROUPS            = HIDDEN_SIZE / QUANT_GROUP_SIZE;
    static constexpr int   NUM_EXPERTS           = 256;
    static constexpr int   INTERMEDIATE_SIZE     = 256; // per card: 2048 / TP8
    static constexpr int   TOP_K                 = 8;
    static constexpr float ROUTED_SCALING_FACTOR = 2.5f;
    static constexpr int   MAX_NUM_TOKENS        = 4; // rows a decode call takes: MTP k=3 verifies 4
    // attention per card: q_a_proj's rows, kv_a_proj_with_mqa's (the kv latent, then the rope
    // part of k), qkv_a's (both), q_b_proj's; o_proj's K
    static constexpr int   Q_LORA_RANK           = 2048;
    static constexpr int   KV_LORA_RANK          = 512;
    static constexpr int   QK_ROPE_DIM           = 64;
    static constexpr int   QK_NOPE_DIM           = 192;
    static constexpr int   MLA_HEADS             = 8; // per card
    static constexpr int   V_HEAD_DIM            = 256;
    static constexpr int   QKV_A_ROWS            = Q_LORA_RANK + KV_LORA_RANK + QK_ROPE_DIM;
    static constexpr int   Q_B_ROWS              = MLA_HEADS * (QK_NOPE_DIM + QK_ROPE_DIM);
    static constexpr int   O_PROJ_K              = MLA_HEADS * V_HEAD_DIM;
    // the dense layers' MLP per card: gate_proj's rows, up_proj's (12288 / TP8)
    static constexpr int   DENSE_ROWS            = 1536;
    // the MTP layer's eh_proj rows per card (6144 / TP8)
    static constexpr int   MTP_ROWS              = HIDDEN_SIZE / 8;
    // the DSA indexer (replicated): heads, head dim, tokens per ki page
    static constexpr int   INDEX_HEADS           = 32;
    static constexpr int   INDEX_DIM             = 128;
    static constexpr int   INDEX_PAGE            = 64;
    static constexpr int   INDEX_TOPK            = 2048;
    // ExpertTable slots: the shared expert, then the most distinct experts M tokens can pick
    static constexpr int   MAX_SLOTS             = MAX_NUM_TOKENS * TOP_K + 1;
    // the shared expert's id: its weights come after the routed ones
    static constexpr int   SHARED_EXPERT         = NUM_EXPERTS;
    // the all-reduce (AllReduceParams): block k sums output rows AR_ROWS k .., a 16 B packet
    // carrying 6 of its AR_ROWS x M; receive buffer [call parity][source rank][block][packet]
    static constexpr int MAX_RANKS      = 8;
    static constexpr int AR_ROWS        = HIDDEN_SIZE / NUM_BLOCKS;
    static constexpr int AR_PACKETS     = AR_ROWS * MAX_NUM_TOKENS / 6;
    static constexpr int AR_BUFFER_SIZE = 2 * MAX_RANKS * NUM_BLOCKS * AR_PACKETS * 16;
};

// each thread's 16 B chunks of a HIDDEN_SIZE row, a block's threads covering it
constexpr int ROW_LOADS = Config::HIDDEN_SIZE / (Config::BLOCK_SIZE * 8);
static_assert(ROW_LOADS * Config::BLOCK_SIZE * 8 == Config::HIDDEN_SIZE);

} // namespace infera_flash::glm5

// The DSA indexer: its params, its device code up to the scores (run in attn_qkv's kernel), and its
// top-k's (index_topk in indexer.hip, and the indexer layer's kernel).
#pragma once

#include "common/gemm.h"
#include "common/math.h"
#include "common/sync.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// The DSA indexer's q and k up to the scores, as HF computes them: wq_b of q_resid, wk of x and
// k_norm, interleaved RoPE, weights_proj of x; then, as sglang, the Hadamard rotation and the ue8m0
// fp8 quant. k goes into its ki page; q and weights (weights_proj's times q's scales) feed the
// scores.
struct IndexerQkParams {
    const int64_t  *position; // [M]
    // [INDEX_HEADS * INDEX_DIM, Q_LORA_RANK] and [INDEX_DIM, HIDDEN_SIZE] fp8, preshuffled like
    // gate_up's; scales [32, 16] and [1, NUM_GROUPS]
    const uint8_t  *wq_b;
    const float    *wq_b_scale;
    const uint8_t  *wk;
    const float    *wk_scale;
    const bfloat16 *weights_proj; // [INDEX_HEADS, HIDDEN_SIZE]
    const bfloat16 *k_gamma;      // [INDEX_DIM] k_norm, a LayerNorm with bias
    const bfloat16 *k_beta;
    float           k_epsilon;
    const bfloat16 *cos; // [positions, QK_ROPE_DIM / 2]
    const bfloat16 *sin;
    // this layer's pages of INDEX_PAGE keys: their fp8 in aiter's preshuffled 16 x 16 tiles, then
    // their fp32 scales
    uint8_t        *ki;
    float          *k_partial; // M * ix::DIM * ix::WK_SPLITS floats of scratch: wk's partial sums
    bfloat16       *q;         // [M, INDEX_HEADS * INDEX_DIM] wq_b's output
    bfloat16       *k;         // [M, INDEX_DIM] wk's output
    uint8_t        *q_fp8;     // [M, INDEX_HEADS, INDEX_DIM]
    float          *weights;   // [M, INDEX_HEADS]
    // the scores of every past position, as aiter's deepgemm_fp8_paged_mqa_logits:
    // [M, logits_stride], -inf past a row's lens up to the longest row's, untouched past that
    const int      *lens; // [M] each row's positions, its token's own included
    float          *logits;
    int             logits_stride;
};

// The DSA indexer's top-k for M <= 4 rows of scores: per row the INDEX_TOPK highest of its first
// lens[m] scores, in no particular order, -1 where a row has fewer.
struct IndexTopkParams {
    const float *logits; // [M, stride]
    int          stride;
    const int   *lens;      // [M]
    void        *workspace; // WORKSPACE_SIZE bytes, one per process
    void        *state;     // index_topk_state_bytes(), zeroed once, one per process
    int         *out;       // [M, INDEX_TOPK]
    // position t of row m is the slot page_table[m * page_table_stride + t / page_size] * page_size
    // + t % page_size
    const int   *page_table;
    int          page_table_stride;
    int          page_size;
};

size_t index_topk_state_bytes();
int    index_topk_max_len();
void   index_topk_launch(const IndexTopkParams &params, int num_tokens, hipStream_t stream);

} // namespace infera_flash::glm5

namespace infera_flash::glm5::ix {

constexpr int Q_LORA    = Config::Q_LORA_RANK;
constexpr int HEADS     = Config::INDEX_HEADS;
constexpr int DIM       = Config::INDEX_DIM;
constexpr int Q_ROWS    = HEADS * DIM;
constexpr int WK_GROUPS = DIM / 16;
// a wk block takes WK_KB K blocks, one per wave: (group g, split s) on block
// WK_BLOCK0 + WK_SPLITS g + s
constexpr int WK_KB     = WAVES;
constexpr int WK_K      = WK_KB * 128;
constexpr int WK_SPLITS = Config::HIDDEN_SIZE / WK_K;
constexpr int WK_BLOCK0 = HEADS;
// attn_qkv's packets with the indexer: a wk split's partial sums out (k_out waits), a head or k out
// (the scores wait), a wq_b group out for its XCD (plain stores, read through L2)
constexpr int WK_PACKET   = 1;
constexpr int HEAD_PACKET = 2;
constexpr int WQB_PACKET  = 3;
// of the 16 lanes holding a 128-dim row, 8 dims each, the first ROPE_LANES hold RoPE's dims
constexpr int ROPE_LANES = Config::QK_ROPE_DIM / 8;
constexpr int PAGE_BYTES = Config::INDEX_PAGE * (DIM + 4);
constexpr float HADAMARD_SCALE = 0.08838834764831845f; // 128^-0.5
static_assert(Q_ROWS / 16 == Config::NUM_BLOCKS && Q_LORA == Config::BLOCK_SIZE * 8 &&
              WAVES == Config::MAX_NUM_TOKENS);

struct IndexerQkSmem {
    uint8_t   q_fp8[Config::MAX_NUM_TOKENS * HEADS * DIM]; // the finished q, for the scores
    float     weights[Config::MAX_NUM_TOKENS * HEADS];
    GroupSmem<Config::MAX_NUM_TOKENS> group;
    float     partial[Config::MAX_NUM_TOKENS * 16]; // a wk block's sums, [M][16]
};

// A wk block's sum over its K, wave w taking K block w, from x's fp8 in LDS (token m's K at
// x + m x_stride, its scales at x_scale + m scale_stride): the waves' tiles added in wave order,
// out as fp32 [M][16] with sc1.
template <int NUM_TOKENS>
__device__ __forceinline__ void wk_partial(int32x8 w, float w_scale, const uint8_t *x, int x_stride,
                                           const float *x_scale, int scale_stride, IndexerQkSmem &s,
                                           float *out) {
    const int      tid   = threadIdx.x;
    const int      lane  = tid % THREADS_PER_WARP;
    const int      wave  = tid / THREADS_PER_WARP;
    const int      token = min(lane % 16, NUM_TOKENS - 1);
    const uint8_t *xq    = x + token * x_stride + wave * 128 + lane / 16 * 16;
    s.group.tiles[tid]   = mfma_16x16x128_fp8(w, load_fragment(xq, xq + 64)) *
                         (w_scale * x_scale[token * scale_stride + wave]);
    block_sync_lds();
    // as group_out: thread (m, r) adds row r of token m from each wave's tile
    if (tid < 16 * NUM_TOKENS) {
        const floatx4 *tile = s.group.tiles + 16 * (tid % 16 / 4) + tid / 16;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][tid % 4];
        }
        s.partial[tid] = sum;
    }
    block_sync_lds();
    if (tid < 4 * NUM_TOKENS) {
        store_sc1(reinterpret_cast<uint32x4 *>(out) + tid,
                  reinterpret_cast<const uint32x4 *>(s.partial)[tid]);
    }
}

// HF's k_norm, a LayerNorm with bias, of a 128-dim row held by 16 lanes, 8 values each.
__device__ inline void layer_norm(bfloat16 (&x)[8], const bfloat16 (&gamma)[8],
                                  const bfloat16 (&beta)[8], float eps) {
#pragma clang fp contract(off) // each op rounded, as torch's
    float v[8];
    float sum = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        v[i] = static_cast<float>(x[i]);
        sum += v[i];
    }
    const float mean = WarpReduce<SumOp, float, 16>(sum) * (1.0f / DIM);
    float       sum2 = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        v[i] -= mean;
        sum2 += v[i] * v[i];
    }
    const float rstd = rsqrtf(WarpReduce<SumOp, float, 16>(sum2) * (1.0f / DIM) + eps);
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        x[i] = static_cast<bfloat16>(static_cast<float>(gamma[i]) * (rstd * v[i]) +
                                     static_cast<float>(beta[i]));
    }
}

// The end of q's heads and of k, on a 128-dim row held by 16 lanes, 8 dims each: RoPE on the
// first QK_ROPE_DIM dims in interleaved pairs, rounded as HF's bf16 ops; the Hadamard rotation as
// fast_hadamard_transform; the ue8m0 fp8 quant as sglang. rope holds the lane's 4 cos, then 4 sin.
// Stores the lane's 8 fp8 values to out and returns the row's scale.
__device__ inline float rope_rotate_quant(const bfloat16 (&x)[8], const bfloat16 (&rope)[8],
                                          uint8_t *out) {
    const int  j    = threadIdx.x % 16;
    const bool turn = j < ROPE_LANES;
    const auto bf16 = [](float v) { return static_cast<float>(static_cast<bfloat16>(v)); };
    float      v[8];
#pragma unroll
    for (int i = 0; i < 4; ++i) {
        float y0 = x[2 * i], y1 = x[2 * i + 1];
        rope_pair(y0, y1, rope[i], rope[4 + i]);
        v[2 * i]     = turn ? y0 : static_cast<float>(x[2 * i]);
        v[2 * i + 1] = turn ? y1 : static_cast<float>(x[2 * i + 1]);
    }
    // butterflies over index bits 0-2 within the lane, then bits 3-6 across lanes
#pragma unroll
    for (int b = 1; b < 8; b *= 2) {
#pragma unroll
        for (int i = 0; i < 8; ++i) {
            if (!(i & b)) {
                const float lo = v[i], hi = v[i + b];
                v[i]               = lo + hi;
                v[i + b]           = lo - hi;
            }
        }
    }
#pragma unroll
    for (int b = 1; b < 16; b *= 2) {
#pragma unroll
        for (int i = 0; i < 8; ++i) {
            const float other = __shfl_xor(v[i], b, 16);
            v[i]              = j & b ? other - v[i] : v[i] + other;
        }
    }
    float amax = 0.0f;
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        v[i] = bf16(v[i] * HADAMARD_SCALE);
        amax = fmaxf(amax, fabsf(v[i]));
    }
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 16>(__float_as_uint(amax)));
    // the power of two at or above amax / FP8_MAX, so the values need no clamp
    const uint32_t r     = __float_as_uint(__fdiv_rn(fmaxf(amax, 1e-4f), FP8_MAX));
    const uint32_t e     = (r >> 23) + ((r & 0x7fffff) != 0);
    const float    inv   = __uint_as_float((254 - e) << 23);
    uint32_t       fp8[2];
#pragma unroll
    for (int i = 0; i < 2; ++i) {
        fp8[i] = __builtin_amdgcn_cvt_pk_fp8_f32(
            v[4 * i + 2] * inv, v[4 * i + 3] * inv,
            __builtin_amdgcn_cvt_pk_fp8_f32(v[4 * i] * inv, v[4 * i + 1] * inv, 0, false), true);
    }
    store_sc1(reinterpret_cast<uint2 *>(out), uint2{fp8[0], fp8[1]}); // read back in this kernel
    return __uint_as_float(e << 23);
}

// x's rows times a weight row (both HIDDEN_SIZE, thread t holding 16 B chunks i of each at column
// 8 (256 i + t)) in fp32, added up over the block; each thread gets token t / 16's (the last past
// M).
template <int NUM_TOKENS>
__device__ __forceinline__ float row_weight(const bfloat16 (&x)[NUM_TOKENS][ROW_LOADS][8],
                                            const bfloat16 (&row)[ROW_LOADS][8], float *reduce) {
    float sums[NUM_TOKENS];
#pragma unroll
    for (int t = 0; t < NUM_TOKENS; ++t) {
        floatx2 sum = {};
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x[t][i]);
            const auto *w2 = reinterpret_cast<const bfloat16x2 *>(row[i]);
#pragma unroll
            for (int k = 0; k < 4; ++k) {
                sum += to_float2(x2[k]) * to_float2(w2[k]);
            }
        }
        sums[t] = sum.x + sum.y;
    }
    BlockReduce<SumOp, Config::BLOCK_SIZE, true>(sums, reduce);
    const int m      = min(static_cast<int>(threadIdx.x) / 16, NUM_TOKENS - 1);
    float     weight = sums[0];
#pragma unroll
    for (int t = 1; t < NUM_TOKENS; ++t) {
        weight = m == t ? sums[t] : weight;
    }
    return weight;
}

// lane l of wave 0 holds dims 8 (l % 16) .. 8 (l % 16) + 7 of token l / 16 (the last past M); its
// position's 4 cos and 4 sin for rope_rotate_quant
template <int NUM_TOKENS>
__device__ __forceinline__ int64_t load_rope(const IndexerQkParams &p, bfloat16 (&rope)[8]) {
    const int64_t pos    = p.position[min(static_cast<int>(threadIdx.x) / 16, NUM_TOKENS - 1)];
    const int64_t offset = pos * (Config::QK_ROPE_DIM / 2) + 4 * (threadIdx.x % ROPE_LANES);
    *reinterpret_cast<uint2 *>(rope)     = *reinterpret_cast<const uint2 *>(p.cos + offset);
    *reinterpret_cast<uint2 *>(rope + 4) = *reinterpret_cast<const uint2 *>(p.sin + offset);
    return pos;
}

// Block h, once the 8 groups of head h are out (from its XCD's blocks): the head of each token, and
// its weight times its scale.
template <int NUM_TOKENS>
__device__ __forceinline__ void head_out(const IndexerQkParams &p, float weight,
                                         const bfloat16 (&rope)[8]) {
    const int tid = threadIdx.x;
    const int h   = blockIdx.x;
    const int m   = min(tid / 16, NUM_TOKENS - 1);
    const int j   = tid % 16;
    if (tid < 16 * NUM_TOKENS) {
        // written by this XCD's blocks: read from its L2
        const auto     q_buf = raw_buffer(p.q, NUM_TOKENS * Q_ROWS * sizeof(bfloat16));
        const int      at    = (m * Q_ROWS + h * DIM + 8 * j) * sizeof(bfloat16);
        const uint32x4 val   = buffer_load_l2(q_buf, at);
        bfloat16       q[8];
        __builtin_memcpy(q, &val, 16);
        const float scale = rope_rotate_quant(q, rope, p.q_fp8 + (m * HEADS + h) * DIM + 8 * j);
        if (j == 0) {
            const float out = static_cast<float>(static_cast<bfloat16>(weight)) * scale;
            store_sc1(reinterpret_cast<uint32_t *>(p.weights + m * HEADS + h),
                      __float_as_uint(out));
        }
    }
}

// Block WK_BLOCK0, once wk's partial sums are out (WK_PACKET of their blocks): k rounded as
// HF's linear rounds it, k_norm, then the end shared with q's heads, into the token's slot of its
// ki page.
template <int NUM_TOKENS>
__device__ __forceinline__ void k_out(const IndexerQkParams &p, const uint32x4 *slots,
                                      uint32_t epoch) {
    const int tid = threadIdx.x;
    const int m   = min(tid / 16, NUM_TOKENS - 1);
    const int j   = tid % 16;
    bfloat16  rope[8];
    const int64_t pos = load_rope<NUM_TOKENS>(p, rope);
    bfloat16      gamma[8];
    bfloat16      beta[8];
    load_data<bfloat16, 8>(p.k_gamma + 8 * j, gamma);
    load_data<bfloat16, 8>(p.k_beta + 8 * j, beta);
    wait_for(slots, WK_PACKET, WK_BLOCK0, WK_GROUPS * WK_SPLITS, epoch);
    if (tid < 16 * NUM_TOKENS) {
        // dims 8j .. 8j + 7 are rows 8 (j % 2) .. of wk group j / 2: the splits added in order, every
        // load out before the first is used (left to itself the compiler waits for each in turn)
        const auto partials =
            raw_buffer(p.k_partial, NUM_TOKENS * DIM * WK_SPLITS * sizeof(float));
        uint32x4   parts[WK_SPLITS][2];
#pragma unroll
        for (int split = 0; split < WK_SPLITS; ++split) {
            const int offset =
                (((j / 2 * WK_SPLITS + split) * NUM_TOKENS + m) * 16 + j % 2 * 8) * sizeof(float);
#pragma unroll
            for (int half = 0; half < 2; ++half) {
                parts[split][half] = buffer_load_sc1(partials, offset + 16 * half);
            }
        }
        floatx4 sum[2] = {};
#pragma unroll
        for (int split = 0; split < WK_SPLITS; ++split) {
#pragma unroll
            for (int half = 0; half < 2; ++half) {
                pin(parts[split][half]);
                sum[half] += __builtin_bit_cast(floatx4, parts[split][half]);
            }
        }
        bfloat16 k[8];
#pragma unroll
        for (int i = 0; i < 8; ++i) {
            k[i] = static_cast<bfloat16>(sum[i / 4][i % 4]);
        }
        store_data<bfloat16, 8>(p.k + m * DIM + 8 * j, k);
        layer_norm(k, gamma, beta, p.k_epsilon);
        const int o    = pos % Config::INDEX_PAGE;
        uint8_t  *page = p.ki + pos / Config::INDEX_PAGE * PAGE_BYTES;
        // aiter's preshuffled page: 16 x 16 tiles of 16 keys by 16 dims
        const float scale = rope_rotate_quant(
            k, rope, page + o / 16 * 16 * DIM + j / 2 * 256 + o % 16 * 16 + j % 2 * 8);
        if (j == 0) {
            store_sc1(reinterpret_cast<uint32_t *>(page + Config::INDEX_PAGE * DIM + 4 * o),
                      __float_as_uint(scale));
        }
    }
}

// x of rows r and r + 2 added up in rows 0, 1, y's in rows 2, 3 (rows of 16 lanes)
__device__ inline float swap_add32(float x, float y) {
    const auto s =
        __builtin_amdgcn_permlane32_swap(__float_as_uint(x), __float_as_uint(y), false, false);
    return __uint_as_float(s[0]) + __uint_as_float(s[1]);
}

// x of rows r and r + 1 added up in rows 0, 2, y's in rows 1, 3
__device__ inline float swap_add16(float x, float y) {
    const auto s =
        __builtin_amdgcn_permlane16_swap(__float_as_uint(x), __float_as_uint(y), false, false);
    return __uint_as_float(s[0]) + __uint_as_float(s[1]);
}

// The top-k's key of a score: its bits in an order-preserving form (ordered_bits), at least 1 (0 marks an empty slot,
// so a score of all ones, a NaN, takes 1, the least key). A layer kernel's scores go out as these keys.
__device__ __forceinline__ uint32_t score_key(float x) {
    const uint32_t b = __float_as_uint(x);
    return max(b ^ (static_cast<uint32_t>(static_cast<int32_t>(b) >> 31) | 0x80000000u), 1u);
}

// every wave of the grid but k's block's scores a run of 16-key tiles, TILES at a time, but for the
// tokens' own keys: k's block scores those
constexpr int SCORE_WAVES = (Config::NUM_BLOCKS - 1) * WAVES;
constexpr int TILES       = 8;

// the block scoring tile t of `tiles` (but the tokens' own keys), its index skipping WK_BLOCK0
__device__ inline int score_block(int t, int tiles) {
    const int run = (tiles + SCORE_WAVES - 1) / SCORE_WAVES;
    const int b   = t / run / WAVES;
    return b + (b >= WK_BLOCK0);
}

// The indexer's end: the score of each past position t for every token, as aiter's
// deepgemm_fp8_paged_mqa_logits up to rounding, s_k(t) sum_h weights(m, h) relu(<q(m, h), k(t)>).
// A ki page's 16 keys are one MFMA operand (A = 16 heads of q, B = 16 keys), so lane l holds 4
// heads of key l % 16 and adds them in place; two lane swaps add the 4 rows, leaving row r with
// token r's sums. A wave loads its first tiles while q's heads are finished. The tokens' own keys
// are written in this kernel by block WK_BLOCK0 (k's), after everyone's q is out: it then scores
// them alone, wave m the tile holding token m's, read with sc1; the others score the rest and never
// wait for k. SC1: the scores go out in sc1 stores, for other XCDs in the same kernel.
template <int NUM_TOKENS, bool SC1 = false>
__device__ __forceinline__ void scores(const IndexerQkParams &p, IndexerQkSmem &s,
                                       const uint32x4 *slots, uint32_t epoch) {
    const int  block = blockIdx.x;
    const bool own   = block == WK_BLOCK0;
    const int  tid   = threadIdx.x;
    const int  lane  = tid % THREADS_PER_WARP;
    const int  wave  = __builtin_amdgcn_readfirstlane(
        own ? tid / THREADS_PER_WARP
             : (block - (block > WK_BLOCK0)) * WAVES + tid / THREADS_PER_WARP);
    int        lens[NUM_TOKENS];
    int        pos[NUM_TOKENS];
    int        len = 0;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        lens[m] = p.lens[m];
        pos[m]  = static_cast<int>(p.position[m]);
        len     = max(len, lens[m]);
    }
    int own_tile = -1; // own: wave m's, token m's key's tile
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        own_tile = wave == m ? pos[m] / 16 : own_tile;
    }
    const int tiles = (len + 15) / 16;
    const int run   = (tiles + SCORE_WAVES - 1) / SCORE_WAVES;
    const int first = own ? own_tile : wave * run;
    const int last  = own ? own_tile + (own_tile >= 0) : min(first + run, tiles);
    // B operands: tile t + j's 16 keys, column lane % 16, and key lane % 16's scale (a tile past
    // the run loads its last one again); with sc1 on k's block
    int32x8    k[TILES];
    float      sk[TILES];
    const auto load = [&](int t) {
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            const int      t0   = 16 * min(t + j, last - 1);
            const uint8_t *page = p.ki + static_cast<size_t>(t0 / Config::INDEX_PAGE) * PAGE_BYTES;
            const int      at   = t0 % Config::INDEX_PAGE / 16 * 16 * DIM + lane / 16 * 256 +
                           lane % 16 * 16;
            const int sat = Config::INDEX_PAGE * DIM + 4 * (t0 % Config::INDEX_PAGE + lane % 16);
            if (!own) {
                k[j]  = load_fragment(page + at, page + at + 1024);
                sk[j] = *reinterpret_cast<const float *>(page + sat);
            } else if (j == 0) {
                const auto buf = raw_buffer(page, PAGE_BYTES);
                const auto lo  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at));
                const auto hi  = __builtin_bit_cast(int32x4, buffer_load_sc1(buf, at + 1024));
                k[j]           = __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
                sk[j] = buffer_load_sc1<float>(buf, sat);
            }
        }
    };
    if (first < last) {
        load(first);
    }
    // q's heads out (HEAD_PACKET of blocks 0 .. HEADS - 1); q and the weights into LDS, written by
    // other XCDs: sc1 loads
    wait_for(slots, HEAD_PACKET, 0, HEADS, epoch);
    const auto q_buf = raw_buffer(p.q_fp8, NUM_TOKENS * HEADS * DIM);
#pragma unroll
    for (int i = 0; i < NUM_TOKENS * HEADS * DIM / 16 / Config::BLOCK_SIZE; ++i) {
        const int at = (tid + i * Config::BLOCK_SIZE) * 16;
        *reinterpret_cast<uint32x4 *>(s.q_fp8 + at) = buffer_load_sc1(q_buf, at);
    }
    if (tid < NUM_TOKENS * HEADS / 4) {
        const auto w_buf = raw_buffer(p.weights, NUM_TOKENS * HEADS * sizeof(float));
        reinterpret_cast<uint32x4 *>(s.weights)[tid] = buffer_load_sc1(w_buf, 16 * tid);
    }
    block_sync_lds();
    if (first >= last) {
        return;
    }
    // A operands: heads 16g + lane % 16 of token n; the weights of heads 16g + 4 (lane / 16) + i
    int32x8 q[NUM_TOKENS][2];
    floatx2 w[NUM_TOKENS][2][2];
#pragma unroll
    for (int n = 0; n < NUM_TOKENS; ++n) {
#pragma unroll
        for (int g = 0; g < 2; ++g) {
            const uint8_t *src = s.q_fp8 + (n * HEADS + 16 * g + lane % 16) * DIM + lane / 16 * 16;
            q[n][g]            = load_fragment(src, src + 64);
            const floatx4 wg =
                *reinterpret_cast<const floatx4 *>(s.weights + n * HEADS + 16 * g + lane / 16 * 4);
            w[n][g][0] = floatx2{wg[0], wg[1]};
            w[n][g][1] = floatx2{wg[2], wg[3]};
        }
    }
    // lane l writes token l / 16's score of the tile's key l % 16
    const int m       = lane / 16;
    int       row_len = lens[0];
#pragma unroll
    for (int i = 1; i < NUM_TOKENS; ++i) {
        row_len = m == i ? lens[i] : row_len;
    }
    const auto relu = [](float x) { return __int_as_float(max(__float_as_int(x), 0)); };
    for (int t = first; t < last; t += TILES) {
        if (t != first) {
            load(t);
        }
        __builtin_amdgcn_s_waitcnt(0x0F70); // vmcnt(0): every tile in before the first store
#pragma unroll
        for (int j = 0; j < TILES; ++j) {
            if (t + j >= last) {
                break;
            }
            // every MFMA of the tile out before the first result is used: one after another on a
            // single accumulator, each would wait for the last
            floatx4 d[NUM_TOKENS][2];
#pragma unroll
            for (int n = 0; n < NUM_TOKENS; ++n) {
#pragma unroll
                for (int g = 0; g < 2; ++g) {
                    d[n][g] = mfma_16x16x128_fp8(q[n][g], k[j]);
                }
            }
            float v[4] = {};
#pragma unroll
            for (int n = 0; n < NUM_TOKENS; ++n) {
                floatx2 acc = {};
#pragma unroll
                for (int g = 0; g < 2; ++g) {
                    acc = __builtin_elementwise_fma(
                        w[n][g][0], floatx2{relu(d[n][g][0]), relu(d[n][g][1])}, acc);
                    acc = __builtin_elementwise_fma(
                        w[n][g][1], floatx2{relu(d[n][g][2]), relu(d[n][g][3])}, acc);
                }
                v[n] = acc[0] + acc[1];
            }
            // row r: token r's sum over the 4 rows
            const float score =
                swap_add16(swap_add32(v[0], v[2]), swap_add32(v[1], v[3])) * sk[j];
            const int key     = 16 * (t + j) + lane % 16;
            bool      own_key = false;
#pragma unroll
            for (int n = 0; n < NUM_TOKENS; ++n) {
                own_key |= key == pos[n];
            }
            if (m < NUM_TOKENS && key < len && own_key == own) {
                const float val = key < row_len ? score : -__builtin_inff();
                float      *at  = p.logits + m * p.logits_stride + key;
                if constexpr (SC1) {
                    store_sc1(reinterpret_cast<uint32_t *>(at), __float_as_uint(val));
                } else {
                    *at = val;
                }
            }
        }
    }
}

} // namespace infera_flash::glm5::ix

// index_topk's device code, for its kernel (indexer.hip) and the indexer layer's (layer.hip)
namespace infera_flash::glm5::topk {

// index_topk: the DSA indexer's top-k for M <= 4 rows of scores, each row's INDEX_TOPK highest
// among its first lens[m] (in no particular order; -1 where a row has fewer). Keys are the scores'
// bits in an order-preserving form. Row m takes the ROW_BLOCKS blocks b with b % XCDS == m, all on
// XCD m (blocks go round the XCDs), so they trade through its L2; each holds a slice of the row in
// registers, KPT keys a thread. Rounds fix the threshold key 8 bits at a time: every block counts
// its keys still in play per digit and publishes the counts, 6 to a 16 B packet with this call's
// epoch, then reads its row's blocks' packets until all carry the epoch and adds them up. Once at
// most CAP keys share the fixed bits (mostly after two rounds), each block lists its keys equal to
// them (candidates) for the row's block 0, each a packet with the epoch, and publishes how many it
// has above them (winners) and equal; with every block's counts it writes its winners after the
// lower blocks', and block 0 picks the rest from the candidates in LDS, equal keys in (thread,
// entry) order.
constexpr int TOPK        = Config::INDEX_TOPK;
constexpr int M_MAX       = Config::MAX_NUM_TOKENS;
constexpr int XCDS        = Config::NUM_XCDS;
constexpr int ROW_BLOCKS  = Config::NUM_BLOCKS / XCDS; // all of XCD m's blocks take row m
constexpr int BINS        = 256;
constexpr int ROUNDS      = 4;
constexpr int PACKETS     = (BINS + 5) / 6; // a block's counts in a round
constexpr int ROW_PACKETS = ROW_BLOCKS * PACKETS;
constexpr int WAVE_ROWS   = ROW_BLOCKS / WAVES; // the row's blocks a wave adds up
// keys a thread (KPT) by class c: 16 << c; rows up to ROW_BLOCKS * 256 * MAX_KPT
constexpr int KPT_CLASSES = 4;
constexpr int kpt_of(int c) { return 16 << c; }
constexpr int MAX_KPT     = kpt_of(KPT_CLASSES - 1);
constexpr int CAP         = TOPK; // candidates block 0 picks from, and the most a block lists
constexpr int PER_THREAD  = CAP / Config::BLOCK_SIZE; // block 0's share of the lists

struct IndexTopkState {
    uint32x4 packets[ROUNDS][M_MAX * ROW_BLOCKS][PACKETS];
    uint32x4 done[M_MAX * ROW_BLOCKS]; // a block's counts: (winners, candidates, 0, epoch)
    uint32x4 candidates[M_MAX * ROW_BLOCKS][CAP]; // (key, position, 0, epoch)
    uint2    picks[M_MAX * TOPK]; // in a layer kernel, out's entries again: (position, epoch)
    // in a layer kernel: the scores' round-0 counts of each row (its keys by their top 8 bits), added up in
    // device-scope atomics by the scoring blocks, and how many of them have added theirs ([m][0], a line a row); the
    // row's block 0 zeroes both once every block of the row is past round 0
    uint32_t r0_hist[M_MAX][BINS];
    uint32_t r0_arrived[M_MAX][32];
};

static_assert(BINS == 4 * THREADS_PER_WARP && BINS == Config::BLOCK_SIZE && PACKETS <= THREADS_PER_WARP &&
              ROW_BLOCKS <= THREADS_PER_WARP && CAP % Config::BLOCK_SIZE == 0 && TOPK <= CAP);

struct IndexTopkSmem {
    // this block's counts in a round; block 0's over the candidates. Past BINS, a word a lane: count_in's keys out of
    // play (never read)
    uint32_t hist[BINS + THREADS_PER_WARP];
    uint32_t part[WAVES][BINS]; // the row's counts, wave w's of blocks WAVE_ROWS w .. + WAVE_ROWS - 1
    uint32_t scan[WAVES];
    uint32_t digit, beyond, in_bin;
    uint32_t epoch;
    uint32_t off_w[ROW_BLOCKS + 1], off_c[ROW_BLOCKS + 1]; // where each block's lists start
    uint64_t cand[CAP];
};

// index_topk_row's keys sit in LDS, so its loops over them are rolled and skip the groups past the slice: group q of
// a thread's keys (slots 4 q .. 4 q + 3) at keys[q * BLOCK_SIZE + tid], 16 B. Round 0 counts into COPIES histograms,
// lane l into copy l % COPIES, BINS + 1 words apart: the scores' top bits fall in few bins, and one bin of different
// copies is in different banks rather than one word. The copies share cand's bytes, which block 0 fills only after
// round 0.
constexpr int COPIES      = 16;
constexpr int COPY_STRIDE = BINS + 1;
constexpr int COPIES_AT   = __builtin_offsetof(IndexTopkSmem, cand);
constexpr int KEYS_AT     = (COPIES_AT + COPIES * COPY_STRIDE * 4 + 15) / 16 * 16;
constexpr int GROUP_STEP  = 4; // key groups a loop step reads
static_assert(KEYS_AT + MAX_KPT * Config::BLOCK_SIZE * 4 <= Config::SMEM_SIZE && kpt_of(0) % (4 * GROUP_STEP) == 0);
// in a layer kernel, a block's slice's page-table entries in LDS past the keys (a slice: at most MAX_KPT a thread)
constexpr int PT_AT    = KEYS_AT + MAX_KPT * Config::BLOCK_SIZE * 4;
constexpr int PT_LOADS = (MAX_KPT * Config::BLOCK_SIZE / Config::INDEX_PAGE + 2 + Config::BLOCK_SIZE - 1) /
                         Config::BLOCK_SIZE;
static_assert(PT_AT + PT_LOADS * Config::BLOCK_SIZE * 4 <= Config::SMEM_SIZE);

// DPP of v with row and bank masks; lanes left out or reading out of their row get 0
template <int CTRL, int ROW_MASK>
__device__ __forceinline__ uint32_t dpp(uint32_t v) {
    return static_cast<uint32_t>(
        __builtin_amdgcn_update_dpp(0, static_cast<int>(v), CTRL, ROW_MASK, 0xF, false));
}

// inclusive prefix sum over the wave, lower lanes first: within rows of 16, then across rows
__device__ __forceinline__ uint32_t wave_scan(uint32_t v) {
    v += dpp<0x111, 0xF>(v); // row_shr:1
    v += dpp<0x112, 0xF>(v); // row_shr:2
    v += dpp<0x114, 0xF>(v); // row_shr:4
    v += dpp<0x118, 0xF>(v); // row_shr:8
    v += dpp<0x142, 0xA>(v); // row_bcast:15 into rows 1 and 3
    v += dpp<0x143, 0xC>(v); // row_bcast:31 into rows 2 and 3
    return v;
}

// v over the block: this thread's exclusive prefix (lower threads first) and the total
__device__ __forceinline__ uint32_t block_scan(uint32_t v, uint32_t *scan, uint32_t &total) {
    const int      lane = threadIdx.x % THREADS_PER_WARP, wave = threadIdx.x / THREADS_PER_WARP;
    const uint32_t incl = wave_scan(v);
    if (lane == THREADS_PER_WARP - 1) {
        scan[wave] = incl;
    }
    __syncthreads();
    uint32_t before = 0;
    total           = 0;
#pragma unroll
    for (int w = 0; w < WAVES; ++w) {
        before += w < wave ? scan[w] : 0;
        total += scan[w];
    }
    __syncthreads();
    return before + incl - v;
}

// an LDS atomic add whose result nobody waits for
__device__ __forceinline__ void lds_add(uint32_t *at, uint32_t v) {
    __hip_atomic_fetch_add((__attribute__((address_space(3))) uint32_t *)at, v, __ATOMIC_RELAXED,
                           __HIP_MEMORY_SCOPE_WORKGROUP);
}

// adds 1 to hist[bin] for each lane that is on, an LDS atomic each: lanes on one address queue in
// the LDS, still far cheaper than merging them first (a chain of scalar steps)
__device__ __forceinline__ void count(uint32_t *hist, uint32_t bin, bool on) {
    if (on) {
        lds_add(hist + bin, 1u);
    }
}

// count's for a round past the first, the fixed bits so far `prefix` and the digit at `shift`: the key into
// hist[its digit] when its bits above match prefix, else into the lane's word past BINS (out_of_play, BINS + lane), no
// branch: a key out of play costs an add of its own, without count's exec-mask steps (and one shared word would
// queue every lane's add)
__device__ __forceinline__ void count_in(uint32_t *hist, uint32_t key, int shift, uint32_t base, uint32_t out_of_play) {
    lds_add(hist + min((key >> shift) - base, out_of_play), 1u);
}

// The first round's counts of this thread's N keys: their top bits fall in few bins, so the queues
// at those bins are long; the keys in the first one's bin go in as one add, the rest 1 each
template <int N>
__device__ __forceinline__ void count_first(uint32_t *hist, const uint32_t (&key)[N], int shift) {
    uint32_t first = 0;
    bool     found = false;
#pragma unroll
    for (int k = 0; k < N; ++k) {
        first = !found && key[k] ? key[k] >> shift : first;
        found |= key[k] != 0;
    }
    uint32_t same = 0;
#pragma unroll
    for (int k = 0; k < N; ++k) {
        same += key[k] && key[k] >> shift == first;
    }
    if (same) {
        lds_add(hist + first, same);
    }
#pragma unroll
    for (int k = 0; k < N; ++k) {
        if (key[k] && key[k] >> shift != first) {
            lds_add(hist + (key[k] >> shift), 1u);
        }
    }
}

// Wave 0: the bin where the keys counted from the top bin down reach need (lane l adds up bins
// BINS - 1 - 4 l .. - 3), into s with the keys above it and in it.
template <typename Counts>
__device__ __forceinline__ void find_digit(IndexTopkSmem &s, Counts counts, uint32_t need) {
    const int lane = threadIdx.x;
    if (lane < THREADS_PER_WARP) {
        uint32_t c[4], sum = 0;
#pragma unroll
        for (int i = 0; i < 4; ++i) {
            c[i] = counts(BINS - 1 - 4 * lane - i);
            sum += c[i];
        }
        uint32_t run = wave_scan(sum) - sum;
#pragma unroll
        for (int i = 0; i < 4; ++i) {
            if (run < need && run + c[i] >= need) {
                s.digit  = BINS - 1 - 4 * lane - i;
                s.beyond = run;
                s.in_bin = c[i];
            }
            run += c[i];
        }
    }
}

// In a layer kernel, on another XCD: entry `at` of the top-k (m * TOPK + i) once it shows this
// call's epoch, so a reader needs no other signal
__device__ __forceinline__ int tagged_pick(const IndexTopkState &g, int at, uint32_t epoch) {
    const auto    buf = raw_buffer(g.picks, sizeof(g.picks));
    uint2         e;
    do {
        asm volatile("" ::: "memory");
        e = buffer_load_sc1<uint2>(buf, 8 * at);
    } while (e.y != epoch);
    return static_cast<int>(e.x);
}

// the KPT class for rows of up to `stride` scores: the least KPT that holds them
inline int kpt_class(int stride) {
    const int per = (stride + ROW_BLOCKS * Config::BLOCK_SIZE - 1) / (ROW_BLOCKS * Config::BLOCK_SIZE);
    int       c   = 0;
    while (c < KPT_CLASSES - 1 && kpt_of(c) < per) {
        ++c;
    }
    return c;
}

// Block (m, j) = (b % XCDS, b / XCDS) of row m < NUM_TOKENS, at this call's epoch. IN_LAYER, in a
// layer kernel: the scores were written earlier in the same kernel on other XCDs, so they are read
// with sc1 once wait_scores(from, n) returns for its slice, positions from .. from + n - 1, and the
// picks go out in sc1 stores for other XCDs in it.
template <int NUM_TOKENS, int KPT, bool IN_LAYER = false, typename WaitScores = void (*)(int, int)>
__device__ __forceinline__ void index_topk_row(const IndexTopkParams &p, uint8_t *smem,
                                               uint32_t epoch, int r0_expected = 0,
                                               WaitScores wait_scores = [](int, int) {}) {
    IndexTopkSmem  &s     = *reinterpret_cast<IndexTopkSmem *>(smem);
    IndexTopkState &g     = *static_cast<IndexTopkState *>(p.state);
    const int       tid   = threadIdx.x;
    const int       block = blockIdx.x;
    const int       m     = block % XCDS;
    const int       j     = block / XCDS;
    const int       len   = p.lens[m];
    int            *out   = p.out + m * TOPK;
    const auto      put   = [&](int i, int v) {
        const int slot =
            v < 0 ? v
                  : p.page_table[m * p.page_table_stride + v / p.page_size] * p.page_size +
                        v % p.page_size;
        if constexpr (IN_LAYER) {
            store_sc1(reinterpret_cast<uint32_t *>(out + i), static_cast<uint32_t>(slot));
            store_sc1(&g.picks[m * TOPK + i], uint2{static_cast<uint32_t>(slot), epoch});
        } else {
            out[i] = slot;
        }
    };
    // a candidate's entry: in a layer kernel its slot (the list's), else its position
    const auto put_entry = [&](int i, int e) {
        if constexpr (IN_LAYER) {
            store_sc1(reinterpret_cast<uint32_t *>(out + i), static_cast<uint32_t>(e));
            store_sc1(&g.picks[m * TOPK + i], uint2{static_cast<uint32_t>(e), epoch});
        } else {
            put(i, e);
        }
    };
    if (len <= TOPK) {
        if (tid < TOPK / ROW_BLOCKS) {
            const int i = j * (TOPK / ROW_BLOCKS) + tid;
            put(i, i < len ? i : -1);
        }
        return;
    }

    // the slice into registers: key slot k is element 4 (tid + 256 (k / 4)) + k % 4
    const int  per   = ((len + ROW_BLOCKS - 1) / ROW_BLOCKS + 3) & ~3;
    const int  from  = min(j * per, len);
    const int  n     = min(per, len - from);
    // in a layer kernel: the slice's page-table entries (an input) loaded while the scores are waited for, then into
    // LDS: the winners' slots from there, not each a page-table read after the last winner's store
    const int p0 = from / Config::INDEX_PAGE;
    const int np = IN_LAYER && n > 0 ? (from + n - 1) / Config::INDEX_PAGE - p0 + 1 : 0;
    int       pt_v[PT_LOADS];
#pragma unroll
    for (int i = 0; i < PT_LOADS; ++i) {
        const int e = tid + i * Config::BLOCK_SIZE;
        pt_v[i]     = e < np ? p.page_table[m * p.page_table_stride + p0 + e] : 0;
    }
    wait_scores(from, n);
    int *const pages = reinterpret_cast<int *>(smem + PT_AT);
#pragma unroll
    for (int i = 0; i < PT_LOADS; ++i) {
        const int e = tid + i * Config::BLOCK_SIZE;
        if (e < np) {
            pages[e] = pt_v[i];
        }
    }
    const auto slice = raw_buffer(p.logits + static_cast<size_t>(m) * p.stride + from, 4 * n);
    const auto at    = [&](int k) { return 4 * (tid + Config::BLOCK_SIZE * (k / 4)) + k % 4; };
    constexpr int AUX = IN_LAYER ? 16 : 0; // the cache-policy operand's sc1 bit
    uint32x4      raw[KPT / 4];
#pragma unroll
    for (int q = 0; q < KPT / 4; ++q) {
        raw[q] = __builtin_bit_cast(
            uint32x4, __builtin_amdgcn_raw_buffer_load_b128(slice, 4 * at(4 * q), 0, AUX));
    }
    // every load out before the first is used: else the compiler waits for each in turn
#pragma unroll
    for (int q = 0; q < KPT / 4; ++q) {
        pin(raw[q]);
    }
    // the keys into LDS, the groups below `groups` (the slice's, up to a multiple of GROUP_STEP). In a layer kernel
    // the scores are their keys already (ix::score_key), and only the groups past `full` hold slots past the slice
    uint32x4 *const keys   = reinterpret_cast<uint32x4 *>(smem + KEYS_AT);
    const int       groups = ((n + 4 * Config::BLOCK_SIZE - 1) / (4 * Config::BLOCK_SIZE) + GROUP_STEP - 1) &
                       ~(GROUP_STEP - 1);
    const int       full   = n / (4 * Config::BLOCK_SIZE);
#pragma unroll
    for (int q = 0; q < KPT / 4; ++q) {
        if (q < groups) {
            uint32x4 k4;
            if (IN_LAYER && q < full) {
                k4 = raw[q];
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) {
                    // key 0 marks an empty slot: a score of all ones (a NaN) takes 1, the least key
                    k4[e] = at(4 * q + e) >= n ? 0u
                            : IN_LAYER         ? raw[q][e]
                                               : max(ordered_bits(__uint_as_float(raw[q][e])), 1u);
                }
            }
            keys[q * Config::BLOCK_SIZE + tid] = k4;
        }
    }
    // the counts take the empty slots too, in bin 0 while the fixed bits are all 0: taken off again there
    const uint32_t  empty  = static_cast<uint32_t>(4 * Config::BLOCK_SIZE * groups - n);
    uint32_t *const copies = reinterpret_cast<uint32_t *>(smem + COPIES_AT);
    if constexpr (!IN_LAYER) {
        for (int i = tid; i < COPIES * COPY_STRIDE; i += Config::BLOCK_SIZE) {
            copies[i] = 0;
        }
    }
    // fn(key) for every key of the groups below `groups`, in slot order
    const auto each_key = [&](auto fn) {
        for (int q = 0; q < groups; q += GROUP_STEP) {
            uint32x4 k4[GROUP_STEP];
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
                k4[i] = keys[(q + i) * Config::BLOCK_SIZE + tid];
            }
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
#pragma unroll
                for (int e = 0; e < 4; ++e) {
                    fn(k4[i][e]);
                }
            }
        }
    };

    const int row  = m * ROW_BLOCKS; // the row's blocks in the state
    uint32_t  need = TOPK, prefix = 0;
    int       bits = 0;
    for (int r = 0; r < ROUNDS; ++r) {
        const int shift = 24 - 8 * r;
        if (IN_LAYER && r == 0) {
            // round 0 from the scores' counts, once every block scoring the row has added its own
            const auto arrived = raw_buffer(&g.r0_arrived[m][0], sizeof(uint32_t));
            const auto counts  = raw_buffer(&g.r0_hist[m][0], BINS * sizeof(uint32_t));
            uint32_t   in;
            do {
                asm volatile("" ::: "memory");
                in = buffer_load_sc1<uint32_t>(arrived, 0);
            } while (static_cast<int>(in) < r0_expected);
            s.hist[tid] = buffer_load_sc1<uint32_t>(counts, 4 * tid);
            block_sync_lds();
            find_digit(s, [&](int b) { return s.hist[b]; }, need);
            block_sync_lds();
            need -= s.beyond;
            prefix = s.digit;
            bits   = 8;
            if (s.in_bin <= CAP) {
                break;
            }
            continue;
        }
        if (r > 0) {
            s.hist[tid] = 0;
        }
        block_sync_lds();
        if (r == 0) {
            uint32_t *const mine = copies + tid % COPIES * COPY_STRIDE;
            each_key([&](uint32_t key) { lds_add(mine + (key >> 24), 1u); });
        } else {
            const uint32_t base = prefix << 8, out = BINS + threadIdx.x % THREADS_PER_WARP;
            each_key([&](uint32_t key) { count_in(s.hist, key, shift, base, out); });
        }
        block_sync_lds();
        if (r == 0) {
            // bin tid over the copies
            uint32_t c = tid == 0 ? 0u - empty : 0u;
#pragma unroll
            for (int i = 0; i < COPIES; ++i) {
                c += copies[i * COPY_STRIDE + tid];
            }
            s.hist[tid] = c;
            block_sync_lds();
        } else if (prefix == 0 && tid == 0) {
            s.hist[0] -= empty;
        }
        if (tid < PACKETS) {
            uint32x4 pk;
#pragma unroll
            for (int c = 0; c < 3; ++c) {
                const int      b  = 6 * tid + 2 * c;
                const uint32_t lo = b < BINS ? s.hist[b] : 0u;
                const uint32_t hi = b + 1 < BINS ? s.hist[b + 1] : 0u;
                pk[c]             = lo | hi << 16;
            }
            pk[3] = epoch;
            store_l2(&g.packets[r][row + j][tid], pk);
        }
        // the row's blocks' counts, added up: wave w's lane l < PACKETS adds up packet l of blocks
        // WAVE_ROWS w .. + WAVE_ROWS - 1
        const int wave = tid / THREADS_PER_WARP, lane = tid % THREADS_PER_WARP;
        if (lane < PACKETS) {
            const auto buf = raw_buffer(&g.packets[r][row][0], ROW_PACKETS * sizeof(uint32x4));
            uint32x4   v[WAVE_ROWS];
            bool       ready;
            do {
                // reload every time: without it the loads are hoisted and the loop assumed to end
                asm volatile("" ::: "memory");
#pragma unroll
                for (int i = 0; i < WAVE_ROWS; ++i) {
                    v[i] = buffer_load_l2(buf, 16 * ((WAVE_ROWS * wave + i) * PACKETS + lane));
                }
                ready = true;
#pragma unroll
                for (int i = 0; i < WAVE_ROWS; ++i) {
                    ready &= v[i][3] == epoch;
                }
            } while (!ready);
#pragma unroll
            for (int e = 0; e < 6; ++e) {
                uint32_t c = 0;
#pragma unroll
                for (int i = 0; i < WAVE_ROWS; ++i) {
                    c += v[i][e / 2] >> 16 * (e % 2) & 0xffffu;
                }
                if (6 * lane + e < BINS) {
                    s.part[wave][6 * lane + e] = c;
                }
            }
        }
        block_sync_lds();
        find_digit(
            s, [&](int b) { return s.part[0][b] + s.part[1][b] + s.part[2][b] + s.part[3][b]; },
            need);
        block_sync_lds();
        need -= s.beyond;
        prefix = prefix << 8 | s.digit;
        bits   = 8 * (r + 1);
        if (s.in_bin <= CAP) {
            break;
        }
    }

    // this block's winners (fixed bits above prefix) go straight out, its candidates (equal to it)
    // to its list for block 0: at most CAP, enough for block 0 when all bits are fixed. Both as bit
    // masks, so the stores below loop over the few set bits, not over every key
    constexpr int WORDS = (KPT + 31) / 32;
    const int     low   = 32 - bits;
    uint32_t      wm[WORDS] = {}, cm[WORDS] = {}; // bit k % 32 of word k / 32: key k wins / ties
#pragma unroll
    for (int q = 0; q < KPT / 4; q += GROUP_STEP) {
        if (q < groups) {
            uint32x4 k4[GROUP_STEP];
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
                k4[i] = keys[(q + i) * Config::BLOCK_SIZE + tid];
            }
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
#pragma unroll
                for (int e = 0; e < 4; ++e) {
                    const int      k   = 4 * (q + i) + e;
                    const uint32_t key = k4[i][e], top = key >> low;
                    wm[k / 32] |= static_cast<uint32_t>(top > prefix) << k % 32;
                    cm[k / 32] |= static_cast<uint32_t>(key && top == prefix) << k % 32;
                }
            }
        }
    }
    uint32_t nw = 0, nc = 0;
#pragma unroll
    for (int i = 0; i < WORDS; ++i) {
        nw += __builtin_popcount(wm[i]);
        nc += __builtin_popcount(cm[i]);
    }
    uint32_t       counted;
    const uint32_t base = block_scan(nw | nc << 16, s.scan, counted);
    if (tid == 0) {
        store_l2(&g.done[row + j],
                 uint32x4{counted & 0xffffu, min(counted >> 16, uint32_t{CAP}), 0u, epoch});
    }
    uint32_t  bc = base >> 16;
    uint32x4 *cl = g.candidates[row + j];
#pragma unroll
    for (int i = 0; i < WORDS; ++i) {
        for (uint32_t mk = cm[i]; mk; mk &= mk - 1) {
            const int k = 32 * i + __builtin_ctz(mk);
            if (bc < CAP) {
                const uint32_t kv =
                    reinterpret_cast<const uint32_t *>(keys)[4 * (k / 4 * Config::BLOCK_SIZE + tid) + k % 4];
                // in a layer kernel its slot, so block 0 reads no page table
                const int v = from + at(k);
                const int e = IN_LAYER ? pages[v / Config::INDEX_PAGE - p0] * Config::INDEX_PAGE +
                                             v % Config::INDEX_PAGE
                                       : v;
                store_l2(cl + bc, uint32x4{kv, static_cast<uint32_t>(e), 0u, epoch});
            }
            ++bc;
        }
    }

    // every block's counts: where its winners and its candidates start
    if (tid < THREADS_PER_WARP) {
        uint32_t w = 0, c = 0;
        if (tid < ROW_BLOCKS) {
            const auto done = raw_buffer(&g.done[row], ROW_BLOCKS * sizeof(uint32x4));
            uint32x4   d;
            do {
                asm volatile("" ::: "memory");
                d = buffer_load_l2(done, 16 * tid);
            } while (d[3] != epoch);
            w = d[0];
            c = d[1];
        }
        const uint32_t ow = wave_scan(w), oc = wave_scan(c);
        if (tid < ROW_BLOCKS) {
            s.off_w[tid + 1] = ow;
            s.off_c[tid + 1] = oc;
        }
        if (tid == 0) {
            s.off_w[0] = 0;
            s.off_c[0] = 0;
        }
    }
    block_sync_lds();
    // block 0 (past its winners): the candidates into LDS, every load issued before the first is used, again until all
    // show the epoch. Entry i of the row's list is entry i - off[b] of block b's
    const auto owner = [](const uint32_t *off, uint32_t i) {
        int b = 0;
#pragma unroll
        for (int step = ROW_BLOCKS / 2; step >= 1; step /= 2) {
            b = off[b + step] <= i ? b + step : b;
        }
        return b;
    };
    const uint32_t wins = s.off_w[ROW_BLOCKS];
    // all bits fixed: the candidates are equal, the first `need` of them win
    const uint32_t cands = bits == 32 ? min(s.off_c[ROW_BLOCKS], need) : s.off_c[ROW_BLOCKS];
    const auto list = raw_buffer(g.candidates[row], ROW_BLOCKS * CAP * sizeof(uint32x4));
    // entries k < used of each thread (mostly one: a row's candidates are mostly under 256)
    uint32_t at_w = s.off_w[j] + (base & 0xffffu);
#pragma unroll
    for (int i = 0; i < WORDS; ++i) {
        for (uint32_t mk = wm[i]; mk; mk &= mk - 1) {
            const int v = from + at(32 * i + __builtin_ctz(mk));
            if constexpr (IN_LAYER) {
                const int slot = pages[v / Config::INDEX_PAGE - p0] * Config::INDEX_PAGE + v % Config::INDEX_PAGE;
                store_sc1(reinterpret_cast<uint32_t *>(out + at_w), static_cast<uint32_t>(slot));
                store_sc1(&g.picks[m * TOPK + at_w], uint2{static_cast<uint32_t>(slot), epoch});
                ++at_w;
            } else {
                put(at_w++, v);
            }
        }
    }
    if (j != 0) {
        return;
    }
    const int used = static_cast<int>((cands + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE);
    int       c_at[PER_THREAD];
    uint32x4  c[PER_THREAD] = {};
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        if (k < used) {
            const uint32_t i = min(tid + k * Config::BLOCK_SIZE, cands - 1);
            const int      b = owner(s.off_c, i);
            c_at[k]          = 16 * (b * CAP + static_cast<int>(i - s.off_c[b]));
            c[k]             = buffer_load_l2(list, c_at[k]);
        }
    }
    bool ready = true;
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        ready &= k >= used || c[k][3] == epoch;
    }
    while (!ready) {
        asm volatile("" ::: "memory");
#pragma unroll
        for (int k = 0; k < PER_THREAD; ++k) {
            if (k < used) {
                c[k] = buffer_load_l2(list, c_at[k]);
            }
        }
        ready = true;
#pragma unroll
        for (int k = 0; k < PER_THREAD; ++k) {
            ready &= k >= used || c[k][3] == epoch;
        }
    }
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        const uint32_t i = tid + k * Config::BLOCK_SIZE;
        if (i < cands) {
            s.cand[i] = uint64_t{c[k][0]} << 32 | c[k][1];
        }
    }
    block_sync_lds();

    // the rest from the candidates: more rounds over their lower bits, in LDS
    uint32_t lneed = need, lprefix = prefix;
    int      lbits = bits;
    if (cands > need) {
        while (lbits < 32) {
            const int shift = 24 - lbits;
            s.hist[tid]     = 0;
            block_sync_lds();
#pragma unroll
            for (int k = 0; k < PER_THREAD; ++k) {
                const uint32_t i = tid + k * Config::BLOCK_SIZE;
                if (i < cands) {
                    count_in(s.hist, static_cast<uint32_t>(s.cand[i] >> 32), shift, lprefix << 8,
                             BINS + threadIdx.x % THREADS_PER_WARP);
                }
            }
            block_sync_lds();
            find_digit(s, [&](int b) { return s.hist[b]; }, lneed);
            block_sync_lds();
            lneed -= s.beyond;
            lprefix = lprefix << 8 | s.digit;
            lbits += 8;
            if (s.in_bin == lneed) {
                break; // the whole bin wins
            }
        }
    }
    // candidates above lprefix win; of those equal to it the first lneed in (thread, entry) order:
    // thread t takes entries t + 256 k, so neighbours read neighbouring LDS words
    const int llow = 32 - lbits;
    uint32_t  cw = 0, ct = 0;
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        const uint32_t i = tid + k * Config::BLOCK_SIZE;
        if (i < cands) {
            const uint32_t top = static_cast<uint32_t>(s.cand[i] >> 32) >> llow;
            cw += top > lprefix;
            ct += top == lprefix;
        }
    }
    uint32_t       both;
    const uint32_t start = block_scan(cw | ct << 16, s.scan, both);
    uint32_t       pw = wins + (start & 0xffffu), pt = start >> 16;
    const uint32_t ties = wins + (both & 0xffffu);
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        const uint32_t i = tid + k * Config::BLOCK_SIZE;
        if (i < cands) {
            const uint64_t e   = s.cand[i];
            const uint32_t top = static_cast<uint32_t>(e >> 32) >> llow;
            if (top > lprefix) {
                put_entry(pw++, static_cast<int>(e));
            } else if (top == lprefix) {
                if (pt < lneed) {
                    put_entry(ties + pt, static_cast<int>(e));
                }
                ++pt;
            }
        }
    }
    if constexpr (IN_LAYER) {
        // every block of the row is past round 0 (its done is in): the row's counts zeroed for the next call
        store_sc1(&g.r0_hist[m][tid], 0u);
        if (tid == 0) {
            store_sc1(&g.r0_arrived[m][0], 0u);
        }
    }
}

} // namespace infera_flash::glm5::topk

// MLA (mla.hip): its params; mla_q's and mla_o's product; the sparse path's device code for M <= 4
// tokens, used by mla_core, attn_qkv's MLA variant and the indexer layer's kernel.
#pragma once

#include <cstddef>
#include <type_traits>

#include "common/math.h"
#include "common/sync.h"
#include "glm5/all_reduce.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// MLA's q and k from q_b's output and the normed kv for M <= 4 tokens, through the KV write:
// q_latent = q_nope W_UK, RoPE (interleaved) on q_pe and k_pe as HF, and the tokens' fp8 KV rows.
struct MlaQParams {
    const bfloat16 *q;        // [M, MLA_HEADS * (QK_NOPE_DIM + QK_ROPE_DIM)] q_b's output
    const bfloat16 *k_latent; // [M, KV_LORA_RANK]
    const bfloat16 *k_pe;     // [M, QK_ROPE_DIM], rows k_pe_stride apart
    int             k_pe_stride;
    const int64_t  *position; // [M]
    const bfloat16 *cos;      // [positions, QK_ROPE_DIM / 2]
    const bfloat16 *sin;
    // [MLA_HEADS, KV_LORA_RANK, QK_NOPE_DIM] fp8, W_UK transposed, with one dequant scale [1]
    const uint8_t  *w_k;
    const float    *w_k_scale;
    uint8_t        *kv; // this layer's KV cache, fp8 [positions, KV_LORA_RANK + QK_ROPE_DIM]
    // [M, MLA_HEADS, KV_LORA_RANK + QK_ROPE_DIM]: q_latent then the turned q_pe, tokens
    // q_out_stride_m and heads q_out_stride_h apart
    bfloat16       *q_out;
    int             q_out_stride_m;
    int             q_out_stride_h;
};

void mla_q_launch(const MlaQParams &params, int num_tokens, hipStream_t stream);

// MLA's output for M <= 4 tokens: the attention's latent times W_UV per head, o_proj's input.
struct MlaOParams {
    // [M, MLA_HEADS, KV_LORA_RANK], tokens stride_m and heads stride_h apart
    const bfloat16 *o_latent;
    int             stride_m;
    int             stride_h;
    // [MLA_HEADS, V_HEAD_DIM, KV_LORA_RANK] fp8, with one dequant scale [1]
    const uint8_t  *w_v;
    const float    *w_v_scale;
    bfloat16       *out; // [M, MLA_HEADS * V_HEAD_DIM]
};

void mla_o_launch(const MlaOParams &params, int num_tokens, hipStream_t stream);

// MLA on the sparse path for M <= 4 tokens, q_b's output through W_UV: mla_q, the attention over
// each token's top-k rows of the KV cache, then mla_o.
struct MlaCoreParams {
    const bfloat16 *q;        // [M, MLA_HEADS * (QK_NOPE_DIM + QK_ROPE_DIM)] q_b's output
    const bfloat16 *k_latent; // [M, KV_LORA_RANK]
    const bfloat16 *k_pe;     // [M, QK_ROPE_DIM], rows k_pe_stride apart
    int             k_pe_stride;
    const int64_t  *position; // [M]
    const bfloat16 *cos;      // [positions, QK_ROPE_DIM / 2]
    const bfloat16 *sin;
    const uint8_t  *w_k; // [MLA_HEADS, KV_LORA_RANK, QK_NOPE_DIM] fp8, W_UK transposed, scale [1]
    const float    *w_k_scale;
    uint8_t        *kv;      // this layer's KV cache, fp8 [slots, KV_LORA_RANK + QK_ROPE_DIM]
    const int64_t  *slot;    // [M] each token's row of kv
    const int      *indices; // [M, INDEX_TOPK] the rows each token attends, -1 for none
    float           qk_scale; // sm_scale log2(e)
    const uint8_t  *w_v;      // [MLA_HEADS, V_HEAD_DIM, KV_LORA_RANK] fp8, one scale [1]
    const float    *w_v_scale;
    // attn_qkv's MLA variant only, for q and w_k: W_UK folded into q_b's q_nope rows,
    // [MLA_HEADS * KV_LORA_RANK, Q_LORA_RANK] fp8 preshuffled, with its 128 x 128 block scales
    const uint8_t  *w_lat;
    const float    *w_lat_scale;
    // o_proj's weight (row_linear_ar's, [HIDDEN_SIZE, MLA_HEADS * V_HEAD_DIM] fp8 preshuffled), read
    // ahead into the L2 of the XCDs whose o_proj blocks use it (prefetch_o_proj), or null
    const uint8_t  *prefetch;
    void           *workspace; // WORKSPACE_SIZE bytes, one per process
    void           *scratch;   // mla_core_scratch_bytes()
    bfloat16       *out;       // [M, MLA_HEADS * V_HEAD_DIM]
    // in a layer kernel: out again in 16 B packets, 4 values and the epoch, which o_proj polls
    // (zeroed once, kept between calls)
    uint32x4       *out_tagged;
};

size_t mla_core_scratch_bytes();
void   mla_core_launch(const MlaCoreParams &params, int num_tokens, hipStream_t stream);

} // namespace infera_flash::glm5

// IN_KERNEL: q_b's output, k_latent and k_pe were written earlier in the same kernel on other XCDs,
// so they are read with sc1 (the caller waits for them first).
namespace infera_flash::glm5::mla {

// mla_core: MLA on the sparse path for M <= 4 tokens in one kernel, from q_b's output to o_proj's
// input. Two kinds of block:
// - blocks 0 .. 32M - 1 attend: token b / 32's top-k rows 64 (b % 32) .. + 63, a tile of 16 a wave.
//   They read their rows at the start, turn the token's q_pe and build the rows of this call's
//   tokens themselves (the cache may not hold them yet), then wait for q_latent; each publishes its
//   partial softmax sums.
// - blocks 128 .. 255 (j = b - 128) first compute q_latent = q_nope W_UK, groups 2j and 2j + 1
//   (16 rows of a head each, waves 0 and 1), and publish it; block 128 then writes the tokens' KV
//   rows. Later each combines head j / 16 of one token over its partial sums and multiplies 16 MP
//   of the head's rows of W_UV (read at the start), MP = M rounded up to a power of 2.
constexpr int HEADS       = Config::MLA_HEADS;
constexpr int LATENT      = Config::KV_LORA_RANK;
constexpr int NOPE        = Config::QK_NOPE_DIM;
constexpr int ROPE        = Config::QK_ROPE_DIM;
constexpr int Q_HEAD      = NOPE + ROPE; // a head of q_b's output
constexpr int ROW         = LATENT + ROPE; // a head of q, a row of the KV cache
constexpr int V_HEAD      = Config::V_HEAD_DIM;
constexpr int TOPK        = Config::INDEX_TOPK;
constexpr int M_MAX       = Config::MAX_NUM_TOKENS;
constexpr int TILE        = 16;
constexpr int CHUNK       = WAVES * TILE;
constexpr int ATTN_BLOCKS = TOPK / CHUNK; // per token
constexpr int AD_FIRST    = Config::NUM_BLOCKS / 2;
constexpr int XCDS        = Config::NUM_XCDS;
// mla_ix_block: XCDs 0 .. HALF_XCDS - 1 combine, the others project q_latent and attend
constexpr int HALF_XCDS   = XCDS / 2;
constexpr int Q_GROUPS    = LATENT / 16; // per head
constexpr int SEG         = ROW / 4;
constexpr int STEPS       = SEG / 8;
constexpr int DIM_TILES   = LATENT / 16;
constexpr int V_STRIDE    = LATENT + 24; // bf16; rows 12 banks apart, so writes and transposed reads
                                         // both hit distinct banks
constexpr int ROW_CHUNKS  = ROW / 16;
constexpr int O_GROUPS    = V_HEAD / 16; // projecting blocks per head
// a slot's packet 1, posted once the block's partial sums are out (packet 0: q_latent)
constexpr int PARTIAL_SUMS_PACKET = 1;
static_assert(HEADS * Q_GROUPS == 2 * (Config::NUM_BLOCKS - AD_FIRST) &&
              LATENT == THREADS_PER_WARP * 8 && ROPE == THREADS_PER_WARP);
static_assert(SEG % 16 == 0 && M_MAX * ATTN_BLOCKS <= AD_FIRST &&
              HEADS * O_GROUPS == Config::NUM_BLOCKS - AD_FIRST);
static_assert(ATTN_BLOCKS % WAVES == 0 && LATENT == 2 * Config::BLOCK_SIZE &&
              M_MAX * LATENT / 8 == Config::BLOCK_SIZE && HEADS * ROPE / 2 == Config::BLOCK_SIZE);
// mla_ix_block: a token's chunks on one XCD's blocks
static_assert(ATTN_BLOCKS * XCDS == Config::NUM_BLOCKS);

using bfloat16x4 = bfloat16 __attribute__((ext_vector_type(4)));

// an attending block's partial sums: per head the max score and the sum of exp2(score - max) (a 16 B
// slot), and the unnormalized output in bf16, head-major
struct MlaCorePartial {
    floatx4  stats[HEADS];
    bfloat16 out[HEADS][LATENT];
};

struct MlaCoreScratch {
    bfloat16       q[M_MAX][HEADS][LATENT]; // q_latent
    MlaCorePartial partial[M_MAX][ATTN_BLOCKS];
};

struct MlaCoreSmem {
    bfloat16 q[HEADS][ROW];     // the token's q
    uint8_t  fresh[M_MAX][ROW]; // this call's tokens' rows, fp8
    union {
        bfloat16 v[WAVES][TILE][V_STRIDE];      // a tile's latent, bf16
        struct {                                 // the projecting step
            float    scale[ATTN_BLOCKS];         // each partial's weight
            float    osum[WAVES][LATENT];        // the waves' sums over their partials
            bfloat16 o[LATENT];                  // the head's o_latent
            float    rows[WAVES][16];            // each wave's sums for its tile
        };
    };
    float p[WAVES][HEADS][TILE]; // a tile's probabilities, against the block's max
    float max[WAVES][HEADS];     // each tile's max score
    float sum[WAVES][HEADS];     // each tile's sum of p
};

// x within fp8's finite values, as sglang's cache write saturates (a NaN stays one); the
// conversion makes a NaN of anything past them
__device__ inline float fp8_finite(float x) {
    return x > 448.0f ? 448.0f : x < -448.0f ? -448.0f : x;
}

// 8 fp8 values of a row for the cache from 8 bf16, saturated, rounded to nearest even
__device__ inline uint2 to_fp8x8(const bfloat16 (&v)[8]) {
    uint32_t out[2];
#pragma unroll
    for (int i = 0; i < 2; ++i) {
        const uint32_t lo = __builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(v[4 * i]),
                                                            fp8_finite(v[4 * i + 1]), 0, false);
        out[i]            = __builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(v[4 * i + 2]),
                                                            fp8_finite(v[4 * i + 3]), lo, true);
    }
    return uint2{out[0], out[1]};
}

// the 2 bf16 at element `at` of base (`bytes` long) as floats; the 8 from `at` into out
template <bool IN_KERNEL>
__device__ inline void load_pair(const bfloat16 *base, int bytes, int at, float &x0, float &x1) {
    uint32_t v;
    if constexpr (IN_KERNEL) {
        v = buffer_load_sc1<uint32_t>(raw_buffer(base, bytes), 2 * at);
    } else {
        v = *reinterpret_cast<const uint32_t *>(base + at);
    }
    bfloat16 b[2];
    __builtin_memcpy(b, &v, 4);
    x0 = b[0];
    x1 = b[1];
}
template <bool IN_KERNEL, typename T>
__device__ inline void load8(const bfloat16 *base, int bytes, int at, T &out) {
    static_assert(sizeof(T) == 16);
    uint32x4 v;
    if constexpr (IN_KERNEL) {
        v = buffer_load_sc1(raw_buffer(base, bytes), 2 * at);
    } else {
        v = *reinterpret_cast<const uint32x4 *>(base + at);
    }
    __builtin_memcpy(&out, &v, 16);
}

// A 16-row group of a per-head product, w [HEADS, N, K] fp8 times each token's K bf16 values of the
// head, on one wave: rows 16 group .. + 15 of head h. Lane (g, c) loads row 16 group + c over K
// K_SEG g .. + K_SEG - 1, and the same K of x from element at (token c's values of head h;
// IN_KERNEL: with sc1, x being bytes long); lane (g, c) gets rows 4g .. 4g + 3 for token c.
template <int K, int N, bool IN_KERNEL = false, bool BF16 = false>
__device__ __forceinline__ floatx4 head_product(const uint8_t *w, const bfloat16 *x, int at, int h,
                                                int group, int bytes = 0) {
    constexpr int K_SEG   = K / 4;
    constexpr int K_STEPS = K_SEG / 8;
    // 16 B of w: two steps' values in fp8, one step's in bf16
    constexpr int W_LOADS = BF16 ? K_STEPS : K_SEG / 16;
    static_assert(K_SEG % 16 == 0 && K_STEPS % 2 == 0);
    const int      lane  = threadIdx.x % THREADS_PER_WARP;
    const int      g     = lane / 16;
    const int      c     = lane % 16;
    const uint8_t *w_row =
        w + ((static_cast<size_t>(h) * N + 16 * group + c) * K + K_SEG * g) * (BF16 ? 2 : 1);
    uint32x4       wv[W_LOADS];
    bfloat16x8     xv[K_STEPS];
#pragma unroll
    for (int i = 0; i < W_LOADS; ++i) {
        wv[i] = reinterpret_cast<const uint32x4 *>(w_row)[i];
    }
#pragma unroll
    for (int i = 0; i < K_STEPS; ++i) {
        load8<IN_KERNEL>(x, bytes, at + K_SEG * g + 8 * i, xv[i]);
    }
    floatx4 acc = {};
#pragma unroll
    for (int i = 0; i < K_STEPS; ++i) {
        bfloat16x8 a;
        if constexpr (BF16) {
            a = __builtin_bit_cast(bfloat16x8, wv[i]);
        } else {
            const uint32x4 wi = wv[i / 2];
            a = i % 2 ? fp8x8_to_bf16(wi[2], wi[3]) : fp8x8_to_bf16(wi[0], wi[1]);
        }
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(a, xv[i], acc, 0, 0, 0);
    }
    return acc;
}

// constants of the o absorption: head h_d of token m_d, its rows R part_d .. + R - 1 (R = 16 MP),
// RT tiles of 16; wave w takes tile w / WPT over K 128 RT (w % WPT) .. + 128 RT - 1, lane l of it
// K 16 (4 i + l / 16) .. + 15 past that in its chunk i of W_UV's row (REGS chunks of 16 B)
template <int NUM_TOKENS>
struct Project {
    static constexpr int MP    = NUM_TOKENS == 3 ? 4 : NUM_TOKENS;
    static constexpr int PARTS = 16 / MP;
    static constexpr int R     = V_HEAD / PARTS;
    static constexpr int RT    = R / 16;
    static constexpr int WPT   = WAVES / RT;
    static constexpr int REGS  = 2 * RT;
    static_assert(RT * WPT == WAVES && LATENT == 128 * WAVES);
};

constexpr int Q_BYTES = M_MAX * HEADS * Q_HEAD * 2;

template <int NUM_TOKENS, typename Params>
__device__ inline int k_pe_bytes(const Params &p) {
    return ((NUM_TOKENS - 1) * p.k_pe_stride + ROPE) * 2;
}

// a pair's RoPE: (x0, x1) of position pos, pair i
template <typename Params>
__device__ inline void turn(const Params &p, float &x0, float &x1, int64_t pos, int i) {
    rope_pair(x0, x1, p.cos[pos * (ROPE / 2) + i], p.sin[pos * (ROPE / 2) + i]);
}

// an attending block's rows: lane (g, c)'s row of its wave's tile (row c) and its bytes SEG g ..
struct AttendRows {
    int      idx;
    uint32x4 raw[SEG / 16];
};

// The block attending chunk `chunk` of token m's top-k rows: its wave's tile, each lane its part
// as q . k takes it; an empty slot reads row 0. Only issues the loads. With pick, entry `at` of
// the top-k is pick(at).
template <typename Pick = std::nullptr_t>
__device__ __forceinline__ void attend_rows(const MlaCoreParams &p, int m, int chunk, AttendRows &r,
                                            Pick pick = nullptr) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    const int wave = threadIdx.x / THREADS_PER_WARP;
    const int at   = m * TOPK + chunk * CHUNK + wave * TILE + lane % 16;
    if constexpr (!std::is_same_v<Pick, std::nullptr_t>) {
        r.idx = pick(at);
    } else {
        r.idx = p.indices[at];
    }
    const auto *src = reinterpret_cast<const uint32x4 *>(
        p.kv + static_cast<size_t>(max(r.idx, 0)) * ROW + SEG * (lane / 16));
#pragma unroll
    for (int i = 0; i < SEG / 16; ++i) {
        r.raw[i] = src[i];
    }
}

// The token's q_pe, turned, into s.q: thread t takes pair t % 32 of head t / 32
template <bool IN_KERNEL>
__device__ __forceinline__ void turn_q_pe(const MlaCoreParams &p, MlaCoreSmem &s, int m) {
    const int     h   = threadIdx.x / (ROPE / 2);
    const int     i   = threadIdx.x % (ROPE / 2);
    const int64_t pos = p.position[m];
    float         x0, x1;
    load_pair<IN_KERNEL>(p.q, Q_BYTES, (m * HEADS + h) * Q_HEAD + NOPE + 2 * i, x0, x1);
    turn(p, x0, x1, pos, i);
    s.q[h][LATENT + 2 * i]     = static_cast<bfloat16>(x0);
    s.q[h][LATENT + 2 * i + 1] = static_cast<bfloat16>(x1);
}

// This call's tokens' rows into s.fresh as the cache takes them (the cache may not hold them yet):
// wave m token m's latent, 8 bf16 a lane from latent(m, lane, out), then k_pe a pair a thread
template <int NUM_TOKENS, bool IN_KERNEL, typename Latent>
__device__ __forceinline__ void fresh_rows(const MlaCoreParams &p, MlaCoreSmem &s, Latent latent) {
    const int tid  = threadIdx.x;
    const int m    = tid / THREADS_PER_WARP;
    const int lane = tid % THREADS_PER_WARP;
    if (m < NUM_TOKENS) {
        bfloat16 lat[8];
        latent(m, lane, lat);
        *reinterpret_cast<uint2 *>(&s.fresh[m][8 * lane]) = to_fp8x8(lat);
    }
    if (tid < NUM_TOKENS * (ROPE / 2)) {
        const int mm = tid / (ROPE / 2), i = tid % (ROPE / 2);
        float x0, x1;
        load_pair<IN_KERNEL>(p.k_pe, k_pe_bytes<NUM_TOKENS>(p), mm * p.k_pe_stride + 2 * i, x0, x1);
        turn(p, x0, x1, p.position[mm], i);
        *reinterpret_cast<uint16_t *>(&s.fresh[mm][LATENT + 2 * i]) =
            static_cast<uint16_t>(__builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(x0), fp8_finite(x1), 0, false));
    }
}

// token m's q_latent into s.q, written by other XCDs: sc1 loads
__device__ __forceinline__ void stage_q_latent(MlaCoreSmem &s, MlaCoreScratch &x, int m) {
    const int     tid      = threadIdx.x;
    const auto    qb       = raw_buffer(&x.q[m][0][0], HEADS * LATENT * sizeof(bfloat16));
    constexpr int Q_CHUNKS = HEADS * LATENT / 8;
    uint32x4      q_in[Q_CHUNKS / Config::BLOCK_SIZE];
#pragma unroll
    for (int i = 0; i < Q_CHUNKS / Config::BLOCK_SIZE; ++i) {
        q_in[i] = buffer_load_sc1(qb, 16 * (tid + i * Config::BLOCK_SIZE));
    }
#pragma unroll
    for (int i = 0; i < Q_CHUNKS / Config::BLOCK_SIZE; ++i) {
        const int at = tid + i * Config::BLOCK_SIZE; // head at / 64, dims 8 (at % 64) ..
        *reinterpret_cast<uint32x4 *>(&s.q[at / (LATENT / 8)][8 * (at % (LATENT / 8))]) = q_in[i];
    }
}

// The rest of the block attending chunk `chunk` of token m, its q_pe turned, fresh rows built and
// q_latent out (the caller waited, so a block sync since; Q_STAGED: q_latent already in s.q):
// attend, and store the block's partial sums (the caller publishes them).
template <int NUM_TOKENS, bool Q_STAGED = false>
__device__ __forceinline__ void attend(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x,
                                       int m, int chunk, const AttendRows &r) {
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int g    = lane / 16;
    const int c    = lane % 16;
    if constexpr (!Q_STAGED) {
        stage_q_latent(s, x, m);
    }
    // the B operands of q . k, rows of this call's tokens from what the block built
    uint32x4 kv[SEG / 16];
    {
        int own = -1; // the call's token whose row this is, if any
#pragma unroll
        for (int t = 0; t < NUM_TOKENS; ++t) {
            own = r.idx == static_cast<int>(p.slot[t]) ? t : own;
        }
        const bool     fresh = own >= 0;
        const uint8_t *built = s.fresh[max(own, 0)] + SEG * g;
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            kv[i] = fresh ? *reinterpret_cast<const uint32x4 *>(built + 16 * i) : r.raw[i];
        }
    }
    block_sync_lds();
    floatx4 dot = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        // A: q's head c % 8, dims SEG g + 8 i .. + 7 (C's rows past the heads repeat them, unused)
        const auto qa = *reinterpret_cast<const bfloat16x8 *>(&s.q[c % HEADS][SEG * g + 8 * i]);
        const uint32x4 w  = kv[i / 2];
        const auto     kb = i % 2 ? fp8x8_to_bf16(w[2], w[3]) : fp8x8_to_bf16(w[0], w[1]);
        dot = __builtin_amdgcn_mfma_f32_16x16x32_bf16(qa, kb, dot, 0, 0, 0);
    }
    // the latent of row c (this lane's part of it) into LDS as bf16 for p . v
#pragma unroll
    for (int i = 0; i < SEG / 16; ++i) {
        if (SEG * g + 16 * i < LATENT) {
            const uint32x4 w   = kv[i];
            auto          *dst = reinterpret_cast<bfloat16x8 *>(&s.v[wave][c][SEG * g + 16 * i]);
            dst[0]             = fp8x8_to_bf16(w[0], w[1]);
            dst[1]             = fp8x8_to_bf16(w[2], w[3]);
        }
    }
    // C: lane (g, c) holds head 4g + e's score of the tile's row c. The block's max per head first
    // (one LDS round): with every wave's p against it, p . v below splits the dims instead of the
    // rows, so each wave ends with whole sums and no partials need merging through LDS
    const bool valid = r.idx >= 0;
    float      score[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        score[e]        = valid ? dot[e] * p.qk_scale : -__builtin_inff();
        const float top = WarpReduce<MaxOp, float, 16>(score[e]);
        if (g < 2 && c == 0) {
            s.max[wave][4 * g + e] = top;
        }
    }
    block_sync_lds();
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        const int   h     = (4 * g + e) % HEADS; // lanes g >= 2 hold copies, dropped below
        const float best  = fmaxf(fmaxf(s.max[0][h], s.max[1][h]), fmaxf(s.max[2][h], s.max[3][h]));
        const float prob  = valid ? exp2f(score[e] - best) : 0.0f;
        const float total = WarpReduce<SumOp, float, 16>(prob);
        if (g < 2) {
            s.p[wave][4 * g + e][c] = prob;
            if (c == 0) {
                s.sum[wave][4 * g + e] = total;
            }
        }
    }
    block_sync_lds();
    // (p . v)^T = v^T p^T over all 4 tiles' rows, this wave's 128 dims: A = tile t's rows 4g + j,
    // dims 128 wave + 16 d + 4q .. read transposed so lane (g, i) gets that dim of rows 4g .. 4g + 3;
    // B = p of head c (zero past the real heads) over tile t's rows
    constexpr int OWN_TILES = DIM_TILES / WAVES;
    bfloat16x4    pa[WAVES] = {};
    if (c < HEADS) {
#pragma unroll
        for (int t = 0; t < WAVES; ++t) {
            const floatx4 pr = *reinterpret_cast<const floatx4 *>(&s.p[t][c][4 * g]);
            pa[t] = bfloat16x4{static_cast<bfloat16>(pr[0]), static_cast<bfloat16>(pr[1]),
                               static_cast<bfloat16>(pr[2]), static_cast<bfloat16>(pr[3])};
        }
    }
    floatx4 acc[OWN_TILES] = {};
#pragma unroll
    for (int t = 0; t < WAVES; ++t) {
        const bfloat16 *vt = &s.v[t][4 * g + c / 4][c % 4 * 4] + LATENT / WAVES * wave;
#pragma unroll
        for (int d = 0; d < OWN_TILES; ++d) {
            // an LDS pointer: generic to address space 3 takes a C-style cast
            const bfloat16x4 vb = __builtin_amdgcn_ds_read_tr16_b64_v4bf16(
                (__attribute__((address_space(3))) bfloat16x4 *)(vt + 16 * d));
            acc[d] = __builtin_amdgcn_mfma_f32_16x16x16bf16_1k(vb, pa[t], acc[d], 0, 0, 0);
        }
    }
    // C lane (g, c) holds head c's dims 128 wave + 16 d + 4g .. + 3 of the block's partial
    MlaCorePartial &mine = x.partial[m][chunk];
    if (c < HEADS) {
#pragma unroll
        for (int d = 0; d < OWN_TILES; ++d) {
            const bfloat16x4 o = {static_cast<bfloat16>(acc[d][0]), static_cast<bfloat16>(acc[d][1]),
                                  static_cast<bfloat16>(acc[d][2]), static_cast<bfloat16>(acc[d][3])};
            store_sc1(reinterpret_cast<uint2 *>(&mine.out[c][LATENT / WAVES * wave + 16 * d + 4 * g]),
                      __builtin_bit_cast(uint2, o));
        }
    }
    if (tid < HEADS) {
        const float best = fmaxf(fmaxf(s.max[0][tid], s.max[1][tid]), fmaxf(s.max[2][tid], s.max[3][tid]));
        const float sum  = s.sum[0][tid] + s.sum[1][tid] + s.sum[2][tid] + s.sum[3][tid];
        store_sc1(reinterpret_cast<uint32x4 *>(&mine.stats[tid]),
                  __builtin_bit_cast(uint32x4, floatx4{best, sum, 0.0f, 0.0f}));
    }
}

template <int NUM_TOKENS, bool Q_STAGED = false>
__device__ __forceinline__ void attend_c(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x,
                                       int m, int chunk, const AttendRows &r) {
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int g    = lane / 16;
    const int c    = lane % 16;
    if constexpr (!Q_STAGED) {
        stage_q_latent(s, x, m);
    }
    // the B operands of q . k, rows of this call's tokens from what the block built
    uint32x4 kv[SEG / 16];
    {
        int own = -1; // the call's token whose row this is, if any
#pragma unroll
        for (int t = 0; t < NUM_TOKENS; ++t) {
            own = r.idx == static_cast<int>(p.slot[t]) ? t : own;
        }
        const bool     fresh = own >= 0;
        const uint8_t *built = s.fresh[max(own, 0)] + SEG * g;
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            kv[i] = fresh ? *reinterpret_cast<const uint32x4 *>(built + 16 * i) : r.raw[i];
        }
    }
    block_sync_lds();
    floatx4 dot = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        // A: q's head c % 8, dims SEG g + 8 i .. + 7 (C's rows past the heads repeat them, unused)
        const auto qa = *reinterpret_cast<const bfloat16x8 *>(&s.q[c % HEADS][SEG * g + 8 * i]);
        const uint32x4 w  = kv[i / 2];
        const auto     kb = i % 2 ? fp8x8_to_bf16(w[2], w[3]) : fp8x8_to_bf16(w[0], w[1]);
        dot = __builtin_amdgcn_mfma_f32_16x16x32_bf16(qa, kb, dot, 0, 0, 0);
    }
    // the latent of row c (this lane's part of it) into LDS as bf16 for p . v
#pragma unroll
    for (int i = 0; i < SEG / 16; ++i) {
        if (SEG * g + 16 * i < LATENT) {
            const uint32x4 w   = kv[i];
            auto          *dst = reinterpret_cast<bfloat16x8 *>(&s.v[wave][c][SEG * g + 16 * i]);
            dst[0]             = fp8x8_to_bf16(w[0], w[1]);
            dst[1]             = fp8x8_to_bf16(w[2], w[3]);
        }
    }
    // C: lane (g, c) holds head 4g + e's score of the tile's row c. The block's max per head first
    // (one LDS round): with every wave's p against it, p . v below splits the dims instead of the
    // rows, so each wave ends with whole sums and no partials need merging through LDS
    // the four heads' reductions side by side, each lane's 4 maxima and sums as one LDS access, exp2f and the p
    // stores without a branch (c2m12 r6): lanes g >= 2 hold copies of lanes g - 2's (q's tile repeats its heads),
    // which store the same values at the same places
    const bool valid = r.idx >= 0;
    float      score[4], top[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        score[e] = valid ? dot[e] * p.qk_scale : -__builtin_inff();
    }
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        top[e] = WarpReduce<MaxOp, float, 16>(score[e]);
    }
    if (c == 0) {
        *reinterpret_cast<floatx4 *>(&s.max[wave][4 * (g % 2)]) = floatx4{top[0], top[1], top[2], top[3]};
    }
    block_sync_lds();
    floatx4 tops[WAVES];
#pragma unroll
    for (int w = 0; w < WAVES; ++w) {
        tops[w] = *reinterpret_cast<const floatx4 *>(&s.max[w][4 * (g % 2)]);
    }
    float part[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        const float best = fmaxf(fmaxf(tops[0][e], tops[1][e]), fmaxf(tops[2][e], tops[3][e]));
        // exp2f(-inf) is +0, an invalid row's probability; a valid row's best is finite
        part[e]                       = exp2f(valid ? score[e] - best : -__builtin_inff());
        s.p[wave][4 * (g % 2) + e][c] = part[e];
    }
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        part[e] = WarpReduce<SumOp, float, 16>(part[e]);
    }
    if (c == 0) {
        *reinterpret_cast<floatx4 *>(&s.sum[wave][4 * (g % 2)]) = floatx4{part[0], part[1], part[2], part[3]};
    }
    block_sync_lds();
    // (p . v)^T = v^T p^T over all 4 tiles' rows, this wave's 128 dims: A = tile t's rows 4g + j,
    // dims 128 wave + 16 d + 4q .. read transposed so lane (g, i) gets that dim of rows 4g .. 4g + 3;
    // B = p of head c (zero past the real heads) over tile t's rows
    constexpr int OWN_TILES = DIM_TILES / WAVES;
    bfloat16x4    pa[WAVES] = {};
    if (c < HEADS) {
#pragma unroll
        for (int t = 0; t < WAVES; ++t) {
            const floatx4 pr = *reinterpret_cast<const floatx4 *>(&s.p[t][c][4 * g]);
            pa[t] = bfloat16x4{static_cast<bfloat16>(pr[0]), static_cast<bfloat16>(pr[1]),
                               static_cast<bfloat16>(pr[2]), static_cast<bfloat16>(pr[3])};
        }
    }
    floatx4 acc[OWN_TILES] = {};
#pragma unroll
    for (int t = 0; t < WAVES; ++t) {
        const bfloat16 *vt = &s.v[t][4 * g + c / 4][c % 4 * 4] + LATENT / WAVES * wave;
#pragma unroll
        for (int d = 0; d < OWN_TILES; ++d) {
            // an LDS pointer: generic to address space 3 takes a C-style cast
            const bfloat16x4 vb = __builtin_amdgcn_ds_read_tr16_b64_v4bf16(
                (__attribute__((address_space(3))) bfloat16x4 *)(vt + 16 * d));
            acc[d] = __builtin_amdgcn_mfma_f32_16x16x16bf16_1k(vb, pa[t], acc[d], 0, 0, 0);
        }
    }
    MlaCorePartial &mine = x.partial[m][chunk];
    // C lane (g, c) holds head c's dims 128 wave + 16 d + 4g .. + 3 of the block's partial. sc1 stores are written
    // through to memory, where lines written in parts cost far more than whole ones, so the wave's rows go out through
    // LDS (in s.q: q . k, its last reader, is done), 16 lanes x 16 B a head's 256 B (c2m12 r7)
    constexpr int O_STRIDE = LATENT / WAVES + 16; // a head's dims of the wave, rows 8 banks apart
    static_assert(WAVES * HEADS * O_STRIDE * sizeof(bfloat16) <= sizeof(MlaCoreSmem::q));
    bfloat16 *const rows = &s.q[0][0] + HEADS * O_STRIDE * wave;
    if (c < HEADS) {
        bfloat16 *const row = rows + c * O_STRIDE + 4 * g;
#pragma unroll
        for (int d = 0; d < OWN_TILES; ++d) {
            *reinterpret_cast<bfloat16x4 *>(row + 16 * d) =
                bfloat16x4{static_cast<bfloat16>(acc[d][0]), static_cast<bfloat16>(acc[d][1]),
                           static_cast<bfloat16>(acc[d][2]), static_cast<bfloat16>(acc[d][3])};
        }
    }
    // the lanes read each other's writes: LDS keeps a wave's accesses in order, the fence keeps the compiler from
    // moving them; every read before the first store (each asm store is a compiler barrier)
    __builtin_amdgcn_fence(__ATOMIC_ACQ_REL, "wavefront");
    uint32x4 out_rows[2];
#pragma unroll
    for (int k = 0; k < 2; ++k) {
        out_rows[k] = *reinterpret_cast<const uint32x4 *>(rows + (4 * k + g) * O_STRIDE + 8 * c);
    }
#pragma unroll
    for (int k = 0; k < 2; ++k) {
        store_sc1(reinterpret_cast<uint32x4 *>(&mine.out[4 * k + g][LATENT / WAVES * wave + 8 * c]), out_rows[k]);
    }
    if (tid < HEADS) {
        const float best = fmaxf(fmaxf(s.max[0][tid], s.max[1][tid]), fmaxf(s.max[2][tid], s.max[3][tid]));
        const float sum  = s.sum[0][tid] + s.sum[1][tid] + s.sum[2][tid] + s.sum[3][tid];
        store_sc1(reinterpret_cast<uint32x4 *>(&mine.stats[tid]),
                  __builtin_bit_cast(uint32x4, floatx4{best, sum, 0.0f, 0.0f}));
    }
}

// Projecting block AD_FIRST + j, waves 0 and 1: q_latent = q_nope W_UK, group 2j + wave (16 rows
// of head group / 32), into x.q with sc1
template <int NUM_TOKENS, bool IN_KERNEL, bool BF16 = false>
__device__ __forceinline__ void project_q(const MlaCoreParams &p, MlaCoreScratch &x, int j) {
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int g    = lane / 16;
    const int c    = lane % 16;
    if (wave < 2) {
        const int group = 2 * j + wave;
        const int h     = group / Q_GROUPS;
        const int rows  = group % Q_GROUPS;
        // W_UK^T times token c's q_nope of head h (columns past M repeat token M - 1)
        const floatx4 acc = head_product<NOPE, LATENT, IN_KERNEL, BF16>(
            p.w_k, p.q, (min(c, NUM_TOKENS - 1) * HEADS + h) * Q_HEAD, h, rows, Q_BYTES);
        // C: lane (g, c) holds rows 4g .. 4g + 3 of the group for token c
        if (c < NUM_TOKENS) {
            const float scale = BF16 ? 1.0f : *p.w_k_scale;
            bfloat16    out[4];
#pragma unroll
            for (int r = 0; r < 4; ++r) {
                out[r] = static_cast<bfloat16>(acc[r] * scale);
            }
            store_sc1(reinterpret_cast<uint2 *>(&x.q[c][h][16 * rows + 4 * g]),
                      *reinterpret_cast<const uint2 *>(out));
        }
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
    }
}

// project_q in two steps, so that W_UK's loads go out before the wait for q_b's groups: its group's rows of W_UK
// (waves 0 and 1: head_product's w, only issued), then q_nope's loads and the MFMAs as head_product's
template <bool BF16> constexpr int WK_LOADS = BF16 ? NOPE / 4 / 8 : NOPE / 4 / 16;

template <bool BF16>
__device__ __forceinline__ void project_q_weights(const MlaCoreParams &p, int j, uint32x4 (&wv)[WK_LOADS<BF16>]) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    const int wave = threadIdx.x / THREADS_PER_WARP;
    if (wave < 2) {
        const int      group = 2 * j + wave;
        const int      h     = group / Q_GROUPS;
        const int      rows  = group % Q_GROUPS;
        const uint8_t *w_row = p.w_k + ((static_cast<size_t>(h) * LATENT + 16 * rows + lane % 16) * NOPE +
                                        NOPE / 4 * (lane / 16)) * (BF16 ? 2 : 1);
#pragma unroll
        for (int i = 0; i < WK_LOADS<BF16>; ++i) {
            wv[i] = reinterpret_cast<const uint32x4 *>(w_row)[i];
        }
    }
}

template <int NUM_TOKENS, bool IN_KERNEL, bool BF16 = false>
__device__ __forceinline__ void project_q_w(const MlaCoreParams &p, MlaCoreScratch &x, int j,
                                            const uint32x4 (&wv)[WK_LOADS<BF16>]) {
    constexpr int K_SEG   = NOPE / 4;
    constexpr int K_STEPS = K_SEG / 8;
    const int     tid     = threadIdx.x;
    const int     lane    = tid % THREADS_PER_WARP;
    const int     wave    = tid / THREADS_PER_WARP;
    const int     g       = lane / 16;
    const int     c       = lane % 16;
    if (wave < 2) {
        const int group = 2 * j + wave;
        const int h     = group / Q_GROUPS;
        const int rows  = group % Q_GROUPS;
        // W_UK^T times token c's q_nope of head h (columns past M repeat token M - 1), as head_product
        const int  at = (min(c, NUM_TOKENS - 1) * HEADS + h) * Q_HEAD;
        bfloat16x8 xv[K_STEPS];
#pragma unroll
        for (int i = 0; i < K_STEPS; ++i) {
            load8<IN_KERNEL>(p.q, Q_BYTES, at + K_SEG * g + 8 * i, xv[i]);
        }
        floatx4 acc = {};
#pragma unroll
        for (int i = 0; i < K_STEPS; ++i) {
            bfloat16x8 a;
            if constexpr (BF16) {
                a = __builtin_bit_cast(bfloat16x8, wv[i]);
            } else {
                const uint32x4 wi = wv[i / 2];
                a = i % 2 ? fp8x8_to_bf16(wi[2], wi[3]) : fp8x8_to_bf16(wi[0], wi[1]);
            }
            acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(a, xv[i], acc, 0, 0, 0);
        }
        // C: lane (g, c) holds rows 4g .. 4g + 3 of the group for token c
        if (c < NUM_TOKENS) {
            const float scale = BF16 ? 1.0f : *p.w_k_scale;
            bfloat16    out[4];
#pragma unroll
            for (int r = 0; r < 4; ++r) {
                out[r] = static_cast<bfloat16>(acc[r] * scale);
            }
            store_sc1(reinterpret_cast<uint2 *>(&x.q[c][h][16 * rows + 4 * g]), *reinterpret_cast<const uint2 *>(out));
        }
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
    }
}

// Projecting block AD_FIRST + j: its rows of W_UV for the o absorption (head j / 16), chunks as
// Project lays them out, only issued
template <int NUM_TOKENS, bool BF16 = false>
__device__ __forceinline__ void project_wv(const MlaCoreParams &p, int j,
                                           uint32x4 (&w_v)[Project<NUM_TOKENS>::REGS * (BF16 ? 2 : 1)]) {
    using P          = Project<NUM_TOKENS>;
    const int lane   = threadIdx.x % THREADS_PER_WARP;
    const int wave   = threadIdx.x / THREADS_PER_WARP;
    const int h_d    = j / 16;
    const int part_d = j % P::PARTS;
    constexpr int  BYTES = BF16 ? 2 : 1; // a value's
    const uint8_t *row =
        p.w_v +
        ((static_cast<size_t>(h_d) * V_HEAD + P::R * part_d + 16 * (wave / P::WPT) + lane % 16) *
             LATENT +
         128 * P::RT * (wave % P::WPT) + 16 * (lane / 16)) *
            BYTES;
#pragma unroll
    for (int i = 0; i < P::REGS * BYTES; ++i) { // bf16: a chunk's 16 values in two loads
        w_v[i] = *reinterpret_cast<const uint32x4 *>(row + 64 * BYTES * (i / BYTES) + 16 * (i % BYTES));
    }
}

// The KV rows of this call's tokens into the cache (one wave; nobody in the kernel waits for them):
// the latent 8 values a lane, then k_pe a pair a lane, as fp8 (scale 1)
template <int NUM_TOKENS, bool IN_KERNEL, typename Params>
__device__ __forceinline__ void write_kv(const Params &p) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        uint8_t *row = p.kv + static_cast<size_t>(p.slot[m]) * ROW;
        bfloat16 lat[8];
        load8<IN_KERNEL>(p.k_latent, NUM_TOKENS * LATENT * 2, m * LATENT + 8 * lane, lat);
        *reinterpret_cast<uint2 *>(row + 8 * lane) = to_fp8x8(lat);
    }
#pragma unroll
    for (int m = lane / (ROPE / 2); m < NUM_TOKENS; m += 2) {
        const int i = lane % (ROPE / 2);
        float     x0, x1;
        load_pair<IN_KERNEL>(p.k_pe, k_pe_bytes<NUM_TOKENS>(p), m * p.k_pe_stride + 2 * i, x0, x1);
        turn(p, x0, x1, p.position[m], i);
        uint8_t *row = p.kv + static_cast<size_t>(p.slot[m]) * ROW + LATENT;
        reinterpret_cast<uint16_t *>(row)[i] =
            static_cast<uint16_t>(__builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(x0), fp8_finite(x1), 0, false));
    }
}

// The KV rows of this call's tokens into the cache from s.fresh (nobody in the kernel waits for them)
template <int NUM_TOKENS>
__device__ __forceinline__ void write_fresh(const MlaCoreParams &p, const MlaCoreSmem &s) {
    const int tid = threadIdx.x;
    if (tid < NUM_TOKENS * ROW_CHUNKS) {
        const int m = tid / ROW_CHUNKS, k = tid % ROW_CHUNKS;
        *reinterpret_cast<uint32x4 *>(p.kv + static_cast<size_t>(p.slot[m]) * ROW + 16 * k) =
            *reinterpret_cast<const uint32x4 *>(&s.fresh[m][16 * k]);
    }
}

// row_linear_ar's block k's o_proj weight rows (its split_group groups, waves 0 and 2), each
// thread's loads only issued, all into sink (asm: kept though unused)
__device__ __forceinline__ void load_o_proj(const uint8_t *w, int k, uint32x4 &sink) {
    constexpr int GROUP = 16 * HEADS * V_HEAD; // bytes
#pragma unroll
    for (int h = 0; h < 2; ++h) {
        const uint8_t *src =
            w + static_cast<size_t>(split_group(k, 2 * h)) * GROUP + 16 * threadIdx.x;
#pragma unroll
        for (int i = 0; i < GROUP / (16 * Config::BLOCK_SIZE); ++i) {
            asm volatile("global_load_dwordx4 %0, %1, off"
                         : "+v"(sink)
                         : "v"(src + 16 * Config::BLOCK_SIZE * i)
                         : "memory");
        }
    }
}

// Projecting block AD_FIRST + j, idle until the partial sums are out: the rows of row_linear_ar's
// blocks k and k + XCDS on its XCD, read once and dropped, so they wait in its L2
__device__ __forceinline__ void prefetch_o_proj(const uint8_t *w, int j) {
    if (w == nullptr) {
        return;
    }
    const int k    = (AD_FIRST + j) % XCDS + 2 * XCDS * (j / XCDS);
    uint32x4  sink = {};
    load_o_proj(w, k, sink);
    load_o_proj(w, k + XCDS, sink);
    asm volatile("s_waitcnt vmcnt(0)" ::"v"(sink) : "memory");
}

// The indexer layers' o_proj block blockIdx.x's own rows, read once and dropped by the block while
// idle, so they wait in its XCD's L2
__device__ __forceinline__ void prefetch_own_o_proj(const uint8_t *w) {
    uint32x4 sink = {};
    load_o_proj(w, blockIdx.x, sink);
    asm volatile("s_waitcnt vmcnt(0)" ::"v"(sink) : "memory");
}

// Projecting block AD_FIRST + j, once the partial sums are out (packet partial_packet of the
// attending blocks): token m_d's head h_d combined, times its rows of W_UV, into p.out (SC1: in sc1
// stores, for other XCDs in the same kernel, and with p.out_tagged again as packets for o_proj to
// poll). XCD_ROLES: token m's attending blocks are 8 t + 4 + m (mla_ix_block's), not 32 m + t.
template <int NUM_TOKENS, bool SC1 = false, bool XCD_ROLES = false, bool BF16 = false>
__device__ __forceinline__ void combine(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x,
                                        int j,
                                        const uint32x4 (&w_v)[Project<NUM_TOKENS>::REGS * (BF16 ? 2 : 1)],
                                        const uint32x4 *slots, uint32_t epoch, int partial_packet) {
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    // token m_d's partial sums for head h_d (past M, M = 3: token M - 1's, dropped): their stats
    // (thread t < 32: partial t), each partial's weight exp2(max - top) / the sum over the token's;
    // wave w takes partials 8w .. 8w + 7, lane l dims 8l .. 8l + 7
    using P = Project<NUM_TOKENS>;
    // W_UV's rows in bf16 (exactly), while the partial sums are still on their way
    bfloat16x8 wb[P::REGS][2];
#pragma unroll
    for (int i = 0; i < P::REGS; ++i) {
        if constexpr (BF16) {
            wb[i][0] = __builtin_bit_cast(bfloat16x8, w_v[2 * i]);
            wb[i][1] = __builtin_bit_cast(bfloat16x8, w_v[2 * i + 1]);
        } else {
            wb[i][0] = fp8x8_to_bf16(w_v[i][0], w_v[i][1]);
            wb[i][1] = fp8x8_to_bf16(w_v[i][2], w_v[i][3]);
        }
    }
    constexpr int PER_WAVE = ATTN_BLOCKS / WAVES;
    const int     h_d      = j / 16;
    const int     m_d      = j / P::PARTS % P::MP;
    const int     part_d   = j % P::PARTS;
    const int     m_c      = min(m_d, NUM_TOKENS - 1);
    if constexpr (XCD_ROLES) { // its token's only
        wait_for(
            slots, partial_packet, ATTN_BLOCKS, [&](int t) { return XCDS * t + HALF_XCDS + m_c; },
            epoch);
    } else {
        wait_for(slots, partial_packet, m_c * ATTN_BLOCKS, ATTN_BLOCKS, epoch);
    }
    const auto    buf      = raw_buffer(&x.partial[m_c][0], ATTN_BLOCKS * sizeof(MlaCorePartial));
    float         st_max = -__builtin_inff(), st_sum = 0.0f;
    if (tid < ATTN_BLOCKS) {
        const floatx4 st = __builtin_bit_cast(
            floatx4, buffer_load_sc1(buf, tid * sizeof(MlaCorePartial) +
                                              offsetof(MlaCorePartial, stats) + sizeof(floatx4) * h_d));
        st_max = st[0];
        st_sum = st[1];
    }
    uint32x4 outs[PER_WAVE];
#pragma unroll
    for (int i = 0; i < PER_WAVE; ++i) {
        outs[i] = buffer_load_sc1(buf, (PER_WAVE * wave + i) * sizeof(MlaCorePartial) +
                                           offsetof(MlaCorePartial, out) +
                                           (h_d * LATENT + 8 * lane) * sizeof(bfloat16));
    }
    float top = st_max;
#pragma unroll
    for (int o = 1; o < 32; o <<= 1) {
        top = fmaxf(top, __shfl_xor(top, o, 32));
    }
    const float weight = st_max == -__builtin_inff() ? 0.0f : exp2f(st_max - top);
    float       total  = weight * st_sum;
#pragma unroll
    for (int o = 1; o < 32; o <<= 1) {
        total += __shfl_xor(total, o, 32);
    }
    if (tid < ATTN_BLOCKS) {
        s.scale[tid] = total > 0.0f ? weight / total : 0.0f;
    }
    block_sync_lds();
    {
        float o[8] = {};
#pragma unroll
        for (int i = 0; i < PER_WAVE; ++i) {
            const float w = s.scale[PER_WAVE * wave + i];
            bfloat16    v[8];
            __builtin_memcpy(v, &outs[i], 16);
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                o[e] += w * static_cast<float>(v[e]);
            }
        }
        *reinterpret_cast<floatx4 *>(&s.osum[wave][8 * lane])     = floatx4{o[0], o[1], o[2], o[3]};
        *reinterpret_cast<floatx4 *>(&s.osum[wave][8 * lane + 4]) = floatx4{o[4], o[5], o[6], o[7]};
    }
    block_sync_lds();
    {
        floatx2 o = {};
#pragma unroll
        for (int w = 0; w < WAVES; ++w) {
            o += *reinterpret_cast<const floatx2 *>(&s.osum[w][2 * tid]);
        }
        s.o[2 * tid]     = static_cast<bfloat16>(o[0]);
        s.o[2 * tid + 1] = static_cast<bfloat16>(o[1]);
    }
    block_sync_lds();
    // o_latent W_UV on the matrix cores: B every column o_latent at the lane's K, so column 0 is the
    // product; then each row summed over its tile's waves
    floatx4         acc = {};
    const bfloat16 *o   = s.o + 128 * P::RT * (wave % P::WPT) + 16 * (lane / 16);
#pragma unroll
    for (int i = 0; i < P::REGS; ++i) {
#pragma unroll
        for (int h = 0; h < 2; ++h) {
            const bfloat16x8 b = *reinterpret_cast<const bfloat16x8 *>(o + 64 * i + 8 * h);
            acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(wb[i][h], b, acc, 0, 0, 0);
        }
    }
    // C: lane (g, 0) holds rows 4g .. 4g + 3 of the tile
    if (lane % 16 == 0) {
        *reinterpret_cast<floatx4 *>(&s.rows[wave][lane / 4]) = acc;
    }
    block_sync_lds();
    const int at  = m_d * HEADS * V_HEAD + h_d * V_HEAD + P::R * part_d + tid;
    bfloat16  val = 0.0f;
    if (tid < P::R) {
        float sum = 0.0f;
#pragma unroll
        for (int v = 0; v < P::WPT; ++v) {
            sum += s.rows[tid / 16 * P::WPT + v][tid % 16];
        }
        val = static_cast<bfloat16>(BF16 ? sum : sum * *p.w_v_scale);
    }
    if (tid < P::R && m_d < NUM_TOKENS) {
        if constexpr (SC1) {
            store_sc1(p.out + at, val);
        } else {
            p.out[at] = val;
        }
    }
    if constexpr (SC1) {
        // lane 4i packs lanes 4i .. 4i + 3 (P::R is a multiple of 4, all in wave 0)
        const uint32_t v0 = __builtin_bit_cast(uint16_t, val);
        const uint32_t v1 = __shfl_down(v0, 1), v2 = __shfl_down(v0, 2), v3 = __shfl_down(v0, 3);
        if (tid < P::R && m_d < NUM_TOKENS && tid % 4 == 0) {
            store_sc1(p.out_tagged + at / 4, uint32x4{v0 | v1 << 16, v2 | v3 << 16, 0u, epoch});
        }
    }
}

// mla_core's work on this block, at this call's epoch (slots: its workspace's)
template <int NUM_TOKENS>
__device__ __forceinline__ void mla_core_block(const MlaCoreParams &p, uint8_t *smem,
                                               uint32x4 *slots, uint32_t epoch) {
    MlaCoreSmem    &s       = *reinterpret_cast<MlaCoreSmem *>(smem);
    MlaCoreScratch &x       = *static_cast<MlaCoreScratch *>(p.scratch);
    const int       tid     = threadIdx.x;
    const int       block   = blockIdx.x;
    uint32x4       *my_slot = slots + block * PACKETS_PER_SLOT;
    // every block stores packets 0 (q_latent out) and 1 (partial sums out) each call
    const auto post = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
            store_sc1(my_slot + PARTIAL_SUMS_PACKET, uint32x4{0u, 0u, 0u, epoch});
        }
    };
    if (block < NUM_TOKENS * ATTN_BLOCKS) {
        AttendRows r;
        attend_rows(p, block / ATTN_BLOCKS, block % ATTN_BLOCKS, r);
        turn_q_pe<false>(p, s, block / ATTN_BLOCKS);
        fresh_rows<NUM_TOKENS, false>(p, s, [&](int m, int lane, bfloat16(&lat)[8]) {
            load8<false>(p.k_latent, NUM_TOKENS * LATENT * 2, m * LATENT + 8 * lane, lat);
        });
        wait_for(slots, 0, AD_FIRST, Config::NUM_BLOCKS - AD_FIRST, epoch); // q_latent
        attend<NUM_TOKENS>(p, s, x, block / ATTN_BLOCKS, block % ATTN_BLOCKS, r);
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
        post();
        return;
    }
    if (block < AD_FIRST) {
        post(); // idle: keep the slot's calls in step
        return;
    }
    const int j = block - AD_FIRST;
    project_q<NUM_TOKENS, false>(p, x, j);
    uint32x4 w_v[Project<NUM_TOKENS>::REGS];
    project_wv<NUM_TOKENS>(p, j, w_v);
    post();
    if (j == 0 && tid / THREADS_PER_WARP == 2) {
        write_kv<NUM_TOKENS, false>(p);
    }
    prefetch_o_proj(p.prefetch, j);
    combine<NUM_TOKENS>(p, s, x, j, w_v, slots, epoch, PARTIAL_SUMS_PACKET);
}

// The indexer layer's MLA (layer.hip), its roles around the top-k on XCDs 0 .. M - 1. XCDs 4-7
// (b % 8 >= 4): q_latent's group pair j = 4 (b / 8) + b % 8 - 4 once wait_q() returns (q, k_latent
// and k_pe, written earlier on other XCDs, then read with sc1); then token m = b % 8 - 4 < M's
// chunk b / 8: q staged while the top-k runs, each row as soon as pick(at) returns its entry of the
// top-k. XCDs 0-3, free
// once their top-k is done: combine j = 4 (b / 8) + b % 8, o out in sc1 stores and as packets
// o_proj polls. Every block prefetches its own o_proj rows while it waits. Packet 0 every call
// (next_epoch reads it; XCDs 4-7: q_latent out), packet 1 only from the attending blocks (their
// partial sums, for combine).
template <int NUM_TOKENS, typename Pick, typename WaitQ>
__device__ __forceinline__ void mla_ix_block(const MlaCoreParams &p, uint8_t *smem,
                                             uint32x4 *slots, uint32_t epoch, Pick pick,
                                             WaitQ wait_q) {
    MlaCoreSmem    &s       = *reinterpret_cast<MlaCoreSmem *>(smem);
    MlaCoreScratch &x       = *static_cast<MlaCoreScratch *>(p.scratch);
    const int       tid     = threadIdx.x;
    const int       block   = blockIdx.x;
    const int       xcd     = block % XCDS;
    uint32x4       *my_slot = slots + block * PACKETS_PER_SLOT;
    // packet 0 once the block syncs, without publish's wait for the stores in flight
    const auto      post    = [&] {
        __syncthreads();
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
        }
    };
    if (xcd < HALF_XCDS) {
        post(); // the slot's epoch in step: nobody waits for it
        const int j = HALF_XCDS * (block / XCDS) + xcd;
        uint32x4  w_v[Project<NUM_TOKENS>::REGS];
        project_wv<NUM_TOKENS>(p, j, w_v);
        prefetch_own_o_proj(p.prefetch);
        combine<NUM_TOKENS, true, true>(p, s, x, j, w_v, slots, epoch, PARTIAL_SUMS_PACKET);
        return;
    }
    const int j = HALF_XCDS * (block / XCDS) + xcd - HALF_XCDS;
    wait_q();
    project_q<NUM_TOKENS, true>(p, x, j);
    post();
    if (j == 0 && tid / THREADS_PER_WARP == 2) {
        write_kv<NUM_TOKENS, true>(p);
    }
    const int m = xcd - HALF_XCDS;
    if (m >= NUM_TOKENS) {
        prefetch_own_o_proj(p.prefetch);
        return;
    }
    // every block's q_latent out; this token's q into LDS before the top-k is done
    wait_for(
        slots, 0, Config::NUM_BLOCKS / 2,
        [](int t) { return XCDS * (t / HALF_XCDS) + HALF_XCDS + t % HALF_XCDS; }, epoch);
    stage_q_latent(s, x, m);
    turn_q_pe<true>(p, s, m);
    fresh_rows<NUM_TOKENS, true>(p, s, [&](int mm, int lane, bfloat16(&lat)[8]) {
        load8<true>(p.k_latent, NUM_TOKENS * LATENT * 2, mm * LATENT + 8 * lane, lat);
    });
    prefetch_own_o_proj(p.prefetch);
    block_sync_lds(); // the rows and q staged above
    AttendRows r;
    attend_rows(p, m, block / XCDS, r, pick);
    attend<NUM_TOKENS, true>(p, s, x, m, block / XCDS, r);
    publish(my_slot + PARTIAL_SUMS_PACKET, epoch);
}

} // namespace infera_flash::glm5::mla

// mlp.hip: the dense layers' MLP up to down (mlp_gate_up), and the row-parallel linears ending in
// the all-reduce, o_proj and the MLP's down (row_linear_ar).
#pragma once

#include <algorithm>

#include "common/gemm.h"
#include "common/math.h"
#include "common/sync.h"
#include "glm5/all_reduce.h"
#include "glm5/config.h"

namespace infera_flash::glm5 {

// A row-parallel linear's x [M, K] times its weight shard [HIDDEN_SIZE, K], then the all-reduce:
// o_proj (K = O_PROJ_K) and the dense layers' MLP down (K = DENSE_ROWS).
struct RowLinearParams {
    const bfloat16 *x; // [M, K]
    // in a layer kernel, or null: x as 16 B packets, 4 values and the writers' epoch (o from the
    // combining blocks, MlaCoreParams::out_tagged), polled instead of wait()
    const uint32x4 *x_tagged;
    // preshuffled like gate_up's: fp8 with scales [HIDDEN_SIZE / 128, K / 128], or (mxfp4) e2m1
    // pairs with e8m0 [HIDDEN_SIZE, K / 32] in aiter shuffle_scale's layout, x quantized as Quark
    bool            mxfp4;
    const uint8_t  *weight;
    const void     *weight_scale;
    AllReduceParams ar;
};

void row_linear_ar_launch(const RowLinearParams &params, int num_tokens, int k, hipStream_t stream);

// row_linear_ar: the row split of moe's down (all_reduce.h), waves 0 and 2 taking the first half of
// K and waves 1 and 3 the second, all of a wave's weights loaded at once. Each block quantizes all
// of x itself.
constexpr int ROW_LINEAR_MAX_K = std::max(Config::O_PROJ_K, Config::DENSE_ROWS);
struct RowLinearSmem {
    uint8_t  x[Config::MAX_NUM_TOKENS * ROW_LINEAR_MAX_K]; // fp8 [M][K] or MXFP4 [M][K / 2]
    float    x_scale[Config::MAX_NUM_TOKENS * ROW_LINEAR_MAX_K / 128]; // or e8m0 [M][K / 32]
    RowsSmem rows;
};

// row_linear_ar's work on this block, last_call its all-reduce's last call number. IN_LAYER, in a
// layer kernel: x was written earlier in the same kernel on other XCDs, so wait() first and read it
// through sc1 loads (with x_tagged: its packets, each until it shows x_epoch); the all-reduce's
// output rows go out in sc1 stores, then publish().
template <int K, int NUM_TOKENS, bool IN_LAYER = false, bool MXFP4 = false,
          typename Wait = void (*)(), typename Publish = void (*)()>
__device__ __forceinline__ void row_linear_ar_block(const RowLinearParams &p, uint8_t *smem,
                                                    uint32_t last_call, Wait wait = [] {},
                                                    Publish publish = [] {}, uint32_t x_epoch = 0) {
    constexpr int K_BLOCKS      = K / 128;
    constexpr int WAVE_K_BLOCKS = K_BLOCKS / 2;
    constexpr int X_GROUPS      = NUM_TOKENS * K_BLOCKS;
    constexpr int X_ITERS       = (X_GROUPS * 16 + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
    static_assert(K % 256 == 0 && K <= ROW_LINEAR_MAX_K);

    RowLinearSmem &s = *reinterpret_cast<RowLinearSmem *>(smem);

    const int tid   = threadIdx.x;
    const int lane  = tid % THREADS_PER_WARP;
    const int wave  = __builtin_amdgcn_readfirstlane(tid / THREADS_PER_WARP);
    const int group = split_group(wave);
    const int kb0   = wave % 2 * WAVE_K_BLOCKS;

    const float residual = all_reduce_residual<NUM_TOKENS>(p.ar);
    // everything but the weights first, as loads complete in issue order
    const bool tagged = IN_LAYER && p.x_tagged != nullptr;
    if (IN_LAYER && !tagged) {
        wait();
    }
    // lane j: the scale of this wave's K block j (MXFP4: as load_group_mxfp4's, of its row)
    const int row      = split_row(wave, lane);
    float     w_scales = 0.0f;
    int       w_e8m0[WAVE_K_BLOCKS / 2];
    if constexpr (MXFP4) {
#pragma unroll
        for (int i = 0; i < WAVE_K_BLOCKS / 2; ++i) {
            w_e8m0[i] = *reinterpret_cast<const int *>(
                static_cast<const uint8_t *>(p.weight_scale) +
                e8m0_dword<K / 32>(group * 16 + row, 4 * (kb0 + 2 * i) + lane / 16));
        }
    } else {
        w_scales = static_cast<const float *>(
            p.weight_scale)[group / 8 * K_BLOCKS + kb0 + lane % WAVE_K_BLOCKS];
    }
    // 16 lanes per 1x128 group; past the last group, the last again
    const auto x_group = [&](int it) {
        return min((tid + it * Config::BLOCK_SIZE) / 16, X_GROUPS - 1);
    };
    bfloat16   x_regs[X_ITERS][8];
    const auto x_buffer = raw_buffer(p.x, NUM_TOKENS * K * sizeof(bfloat16));
    if (tagged) {
        // each 8 values from two packets, the ones not yet out loaded again
        const auto xt = raw_buffer(p.x_tagged, NUM_TOKENS * K / 4 * sizeof(uint32x4));
        uint32x4   a[X_ITERS], b[X_ITERS];
        bool       in[X_ITERS] = {};
        bool       all;
        do {
            asm volatile("" ::: "memory");
#pragma unroll
            for (int it = 0; it < X_ITERS; ++it) {
                if (!in[it]) {
                    const int at = (x_group(it) * 128 + tid % 16 * 8) / 4;
                    a[it]        = buffer_load_sc1(xt, at * sizeof(uint32x4));
                    b[it]        = buffer_load_sc1(xt, (at + 1) * sizeof(uint32x4));
                }
            }
            all = true;
#pragma unroll
            for (int it = 0; it < X_ITERS; ++it) {
                in[it] = a[it][3] == x_epoch && b[it][3] == x_epoch;
                all &= in[it];
            }
        } while (!all);
#pragma unroll
        for (int it = 0; it < X_ITERS; ++it) {
            const uint32x4 val = {a[it][0], a[it][1], b[it][0], b[it][1]};
            __builtin_memcpy(x_regs[it], &val, 16);
        }
    } else {
#pragma unroll
        for (int it = 0; it < X_ITERS; ++it) {
            const int at = x_group(it) * 128 + tid % 16 * 8;
            if constexpr (IN_LAYER) {
                const uint32x4 val = buffer_load_sc1(x_buffer, at * sizeof(bfloat16));
                __builtin_memcpy(x_regs[it], &val, 16);
            } else {
                load_data<bfloat16, 8>(p.x + at, x_regs[it]);
            }
        }
    }
    asm volatile("" ::: "memory"); // the weights' loads go out behind x's
    Fragment<MXFP4> w[WAVE_K_BLOCKS];
    if constexpr (MXFP4) {
        const uint8_t *src = p.weight + static_cast<size_t>(group) * 8 * K +
                             kb0 * K_BLOCK_BYTES_OF<true> + lane / 16 * 256 + row * 16;
#pragma unroll
        for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
            w[j] = *reinterpret_cast<const int32x4 *>(src + j * K_BLOCK_BYTES_OF<true>);
        }
    } else {
        const uint8_t *src = p.weight + static_cast<size_t>(group) * 16 * K + kb0 * K_BLOCK_BYTES +
                             lane / 16 * 256 + split_row(wave, lane) * 16;
#pragma unroll
        for (int j = 0; j < WAVE_K_BLOCKS; ++j) {
            w[j] = load_fragment(src + j * K_BLOCK_BYTES, src + j * K_BLOCK_BYTES + 1024);
        }
    }
    pin(last_call);
    if constexpr (MXFP4) {
#pragma unroll
        for (int i = 0; i < WAVE_K_BLOCKS / 2; ++i) {
            pin(w_e8m0[i]);
        }
    } else {
        pin(w_scales);
    }
#pragma unroll
    for (int it = 0; it < X_ITERS; ++it) {
        pin(*reinterpret_cast<uint32x4 *>(x_regs[it]));
    }
    const uint32_t call = last_call + 1u;

    auto *x_e8m0 = reinterpret_cast<uint8_t *>(s.x_scale);
    if constexpr (MXFP4) {
        int e8m0[X_ITERS];
#pragma unroll
        for (int it = 0; it < X_ITERS; ++it) {
            e8m0[it] = quant_mxfp4(x_regs[it], s.x + x_group(it) * 64 + tid % 16 * 4);
        }
        if (tid % 4 == 0) {
#pragma unroll
            for (int it = 0; it < X_ITERS; ++it) {
                x_e8m0[x_group(it) * 4 + tid % 16 / 4] = e8m0[it];
            }
        }
    } else {
        float x_scale[X_ITERS];
#pragma unroll
        for (int it = 0; it < X_ITERS; ++it) {
            x_scale[it] = quant_fp8(x_regs[it], s.x + x_group(it) * 128 + tid % 16 * 8);
        }
        if (tid % 16 == 0) {
#pragma unroll
            for (int it = 0; it < X_ITERS; ++it) {
                s.x_scale[x_group(it)] = x_scale[it];
            }
        }
    }
    block_sync_lds();

    // columns past M repeat token M - 1 and are dropped
    const int token = min(lane % 16, NUM_TOKENS - 1);
    floatx4   acc   = {};
    if constexpr (MXFP4) {
        acc = mxfp4_blocks<K, WAVE_K_BLOCKS>(w, w_e8m0, group % 2 * 8, s.x, x_e8m0, token, kb0);
    } else {
        acc = fp8_blocks<K, WAVE_K_BLOCKS>(w, w_scales, s.x, s.x_scale, token, kb0);
    }
    all_reduce_rows<NUM_TOKENS, IN_LAYER>(p.ar, s.rows, acc, call, residual);
    if constexpr (IN_LAYER) {
        publish();
    }
}


// The dense layers' MLP up to down for M <= 4 tokens, as HF computes it: post_attention_layernorm,
// then silu(gate(y)) * up(y).
struct MlpGateUpParams {
    const bfloat16 *x;     // [M, HIDDEN_SIZE] the stream
    const bfloat16 *gamma; // [HIDDEN_SIZE] post_attention_layernorm
    float           epsilon;
    // [DENSE_ROWS, HIDDEN_SIZE], this rank's rows of gate_proj and up_proj, preshuffled like
    // gate_up's: fp8 with scales [DENSE_ROWS / 128, NUM_GROUPS], or (mxfp4) e2m1 pairs with e8m0
    // [DENSE_ROWS, HIDDEN_SIZE / 32] in aiter shuffle_scale's layout, x quantized as Quark
    bool            mxfp4;
    const uint8_t  *gate_weight;
    const void     *gate_scale;
    const uint8_t  *up_weight;
    const void     *up_scale;
    void           *workspace; // WORKSPACE_SIZE bytes, one per process
    bfloat16       *gate;      // [M, DENSE_ROWS] scratch
    bfloat16       *act;       // [M, DENSE_ROWS] silu(gate) * up, down's input
};

void mlp_gate_up_launch(const MlpGateUpParams &params, int num_tokens, hipStream_t stream);

// mlp_gate_up: blocks 0-95 each compute a 16-row group of gate and publish it; blocks 96-191 the
// same group of up, which once its gate is out becomes silu(gate) * up. Each does
// post_attention_layernorm and x's quant itself; blocks 192-255 only keep the epochs in step.
namespace mlp {
constexpr int ROWS      = Config::DENSE_ROWS;
constexpr int GROUPS    = ROWS / 16;
constexpr int WAVE_K    = Config::NUM_GROUPS / WAVES;
// in a layer kernel: this up block's act is out
constexpr int ACT_PACKET = 1;

struct MlpGateUpSmem {
    uint8_t   x[Config::MAX_NUM_TOKENS * Config::HIDDEN_SIZE]; // y in fp8 [M][HIDDEN_SIZE] or MXFP4
    float     x_scale[Config::MAX_NUM_TOKENS * Config::NUM_GROUPS]; // or e8m0 [M][HIDDEN_SIZE / 32]
    GroupSmem<Config::MAX_NUM_TOKENS> group;
    float     reduce[WAVES * Config::MAX_NUM_TOKENS];
};

// mlp_gate_up's work on this block at this call's epoch (slots: its workspace's). IN_LAYER, in a
// layer kernel: x is the stream, written earlier in the same kernel on other XCDs, read with sc1
// once wait_x() returns (the weights loaded first); act goes out in sc1 stores, then each up block
// publishes ACT_PACKET.
template <int NUM_TOKENS, bool MXFP4, bool IN_LAYER = false, typename WaitX = void (*)()>
__device__ __forceinline__ void mlp_gate_up_block(const MlpGateUpParams &p, uint8_t *smem,
                                                  uint32x4 *slots, uint32_t epoch,
                                                  WaitX wait_x = [] {}) {
    MlpGateUpSmem &s = *reinterpret_cast<MlpGateUpSmem *>(smem);

    const int  tid     = threadIdx.x;
    const int  block   = blockIdx.x;
    uint32x4  *my_slot = slots + block * PACKETS_PER_SLOT;
    // every block every call, so the epochs stay in step
    const auto keep_in_step = [&] {
        if (tid == 0) {
            store_sc1(my_slot, uint32x4{0u, 0u, 0u, epoch});
        }
    };

    // x and gamma before any weights: loads complete in issue order. IN_LAYER: the weights first,
    // while the stream is still being written; the stream only once it is out
    const auto offset = [&](int m, int i) {
        return m * Config::HIDDEN_SIZE + (i * Config::BLOCK_SIZE + tid) * 8;
    };
    bfloat16   x[NUM_TOKENS][ROW_LOADS][8];
    bfloat16   gamma[ROW_LOADS][8];
    const bool up    = block >= GROUPS;
    const int  group = block - (up ? GROUPS : 0);
    Fragment<MXFP4> w[WAVE_K];
    float      w_scales;
    int        w_e8m0[WAVE_K / 2];
    const auto load_weights = [&] {
        const uint8_t *weight = up ? p.up_weight : p.gate_weight;
        const void    *scale  = up ? p.up_scale : p.gate_scale;
        if constexpr (MXFP4) {
            load_group_mxfp4<Config::HIDDEN_SIZE>(weight, static_cast<const uint8_t *>(scale),
                                                  group, w, w_e8m0);
        } else {
            load_group<Config::HIDDEN_SIZE>(weight, static_cast<const float *>(scale), group, w,
                                            w_scales);
        }
    };
    if (block >= 2 * GROUPS) {
        keep_in_step(); // no group: only the epochs in step
        return;
    }
    if constexpr (IN_LAYER) {
        load_weights();
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(p.gamma + (i * Config::BLOCK_SIZE + tid) * 8, gamma[i]);
        }
        wait_x();
        const auto x_buf = raw_buffer(p.x, NUM_TOKENS * Config::HIDDEN_SIZE * sizeof(bfloat16));
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                const uint32x4 val = buffer_load_sc1(x_buf, offset(m, i) * sizeof(bfloat16));
                __builtin_memcpy(x[m][i], &val, 16);
            }
        }
    } else {
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < ROW_LOADS; ++i) {
                load_data<bfloat16, 8>(p.x + offset(m, i), x[m][i]);
            }
        }
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
            load_data<bfloat16, 8>(p.gamma + (i * Config::BLOCK_SIZE + tid) * 8, gamma[i]);
        }
        asm volatile("" ::: "memory"); // the weights' loads go out behind x's
        load_weights();
        // nothing uses the values above before the weights' loads are out
#pragma unroll
        for (int i = 0; i < ROW_LOADS; ++i) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
                pin(*reinterpret_cast<uint32x4 *>(x[m][i]));
            }
            pin(*reinterpret_cast<uint32x4 *>(gamma[i]));
        }
        if constexpr (MXFP4) {
#pragma unroll
            for (int j = 0; j < WAVE_K / 2; ++j) {
                pin(w_e8m0[j]);
            }
        } else {
            pin(w_scales);
        }
    }
    // post_attention_layernorm as HF, then x's quant: fp8 as HF, or MXFP4 as Quark
    rms_norm<NUM_TOKENS, ROW_LOADS, true>(x, gamma, p.epsilon, s.reduce);
    quant_rows<NUM_TOKENS, ROW_LOADS, MXFP4>(x, s.x, s.x_scale);
    block_sync_lds();
    // up's group goes to act for now and stays in LDS (s.group.out)
    bfloat16 *out = (up ? p.act : p.gate) + 16 * group;
    if constexpr (MXFP4) {
        group_out_mxfp4<Config::HIDDEN_SIZE, NUM_TOKENS, true>(
            w, w_e8m0, group, s.x, reinterpret_cast<const uint8_t *>(s.x_scale), s.group, out,
            ROWS);
    } else {
        group_out<Config::HIDDEN_SIZE, NUM_TOKENS, true>(w, w_scales, s.x, s.x_scale, s.group, out,
                                                         ROWS);
    }
    publish(my_slot, epoch);
    if (!up) {
        return;
    }
    // once gate's group is out: silu(gate) * up, both rounded as HF
    wait_for(slots, 0, group, 1, epoch);
    if (tid < 2 * NUM_TOKENS) {
        const int      at   = tid / 2 * ROWS + 16 * group + tid % 2 * 8;
        const auto     buf  = raw_buffer(p.gate, NUM_TOKENS * ROWS * sizeof(bfloat16));
        const uint32x4 val  = buffer_load_sc1(buf, at * sizeof(bfloat16));
        bfloat16       gate[8];
        bfloat16       act[8];
        __builtin_memcpy(gate, &val, 16);
#pragma unroll
        for (int k = 0; k < 8; ++k) {
            act[k] = silu_mul(gate[k], s.group.out[8 * tid + k]);
        }
        if constexpr (IN_LAYER) {
            store_sc1(reinterpret_cast<uint32x4 *>(p.act + at), __builtin_bit_cast(uint32x4, act));
        } else {
            store_data<bfloat16, 8>(p.act + at, act);
        }
    }
    if constexpr (IN_LAYER) {
        publish(my_slot + ACT_PACKET, epoch);
    }
}

} // namespace mlp

} // namespace infera_flash::glm5

// The all-reduce over the TP ranks that ends moe's down and row_linear_ar, written for GLM-5's 6144
// rows = 256 blocks x 24: Infera-Flash's glm5/all_reduce.h for up to 16 tokens a call, a block's
// AR_ROWS x M outputs and its packets taken by its threads in turn.
#pragma once

#include "common/device.h"
#include "glm5_m16/config.h"

namespace infera_flash::glm5_m16 {

// a packet to another rank's receive buffer: system scope like store_nt, but without nt (the peer's last-level cache
// keeps the line for its poll)
__device__ inline void store_peer(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc0 sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}


// Block k of every rank swaps its share of the [M, HIDDEN_SIZE] output with block k of the others.
struct AllReduceParams {
    bfloat16       *out;        // [M, HIDDEN_SIZE]
    bool            accumulate; // out = bf16(bf16(sum) + prior), HF's residual add
    const bfloat16 *prior;      // [M, HIDDEN_SIZE] the residual
    // every rank's AR_BUFFER_SIZE receive buffer, IPC-mapped; per-block call counters. World 1
    // means no all-reduce.
    void *recv[Config::MAX_RANKS];
    int  *calls;
    int   rank;
    int   world;
};

// This block's last call number, as a vector load (a scalar one holds back the loads after it) that
// reads 0 past the end (world 1).
__device__ inline uint32_t last_call(const AllReduceParams &p) {
    return __builtin_amdgcn_raw_buffer_load_b32(
        raw_buffer(p.calls, p.world > 1 ? Config::NUM_BLOCKS * sizeof(int) : 0),
        blockIdx.x * sizeof(int), 0, 0);
}

// The row split of moe's down and row_linear_ar: block k owns output rows 24k .. 24k + 23. Blocks
// 2j and 2j + 1 share 16-row groups 3j .. 3j + 2, the even one taking group 3j and rows 0-7 of
// 3j + 1, the odd one rows 8-15 of 3j + 1 and group 3j + 2. Waves 0 and 1 take the full group,
// waves 2 and 3 the half group, each pair splitting K; in the half group lanes 8-15 repeat the rows
// of lanes 0-7 and their C rows are dropped.
static_assert(Config::AR_ROWS == 24); // the split: one 16-row group and half of another
__device__ inline int split_group(int block, int wave) {
    return block / 2 * 3 + (wave < 2 ? 2 * (block & 1) : 1);
}
__device__ inline int split_group(int wave) { return split_group(blockIdx.x, wave); }
// the row of its 16-row group this lane loads
__device__ inline int split_row(int wave, int lane) {
    return wave < 2 ? lane % 16 : lane % 8 + 8 * (blockIdx.x & 1);
}

// a block's AR_ROWS x M outputs per thread: thread t takes outputs t, t + BLOCK_SIZE, ...
template <int NUM_TOKENS>
constexpr int AR_ITEMS = (Config::AR_ROWS * NUM_TOKENS + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;

// The residuals this thread adds in all_reduce_rows (0 without accumulate). Load them well before
// the exchange: the exchange's poll waits for every load issued before it.
template <int NUM_TOKENS>
__device__ inline void all_reduce_residual(const AllReduceParams &p,
                                           float (&prior)[AR_ITEMS<NUM_TOKENS>]) {
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = threadIdx.x + k * Config::BLOCK_SIZE;
        prior[k]    = p.accumulate && t < Config::AR_ROWS * NUM_TOKENS
                          ? static_cast<float>(p.prior[t / Config::AR_ROWS * Config::HIDDEN_SIZE +
                                                       Config::AR_ROWS * blockIdx.x + t % Config::AR_ROWS])
                          : 0.0f;
    }
}

// packet i of block `block`'s share from rank src in the receive buffer, for call's parity
__device__ __forceinline__ uint32_t ar_slot(uint32_t call, int src, int block, int i) {
    return ((call % 2 * Config::MAX_RANKS + src) * Config::NUM_BLOCKS + block) *
               Config::AR_PACKETS +
           i;
}

// all_reduce_rows' LDS
struct RowsSmem {
    floatx4  tiles[Config::BLOCK_SIZE]; // each wave's 16x16 result
    // every rank's [M][AR_ROWS] share
    bfloat16 rows[Config::MAX_RANKS][Config::AR_ROWS * Config::MAX_NUM_TOKENS];
};

// The end of down and row_linear_ar: block k's output rows from its 4 waves' 16x16 tiles, split as
// above, summed over the TP ranks, plus prior (all_reduce_residual) when accumulating. SC1: the rows
// go out in sc1 stores, for other XCDs in the same kernel.
template <int NUM_TOKENS, bool SC1 = false>
__device__ __forceinline__ void all_reduce_rows(const AllReduceParams &p, RowsSmem &s, floatx4 acc,
                                                uint32_t call,
                                                const float (&prior)[AR_ITEMS<NUM_TOKENS>]) {
    constexpr int ROWS    = Config::AR_ROWS;
    constexpr int OUTPUTS = ROWS * NUM_TOKENS;
    const int     tid     = threadIdx.x;
    const int     block   = blockIdx.x;
    const int     odd     = block & 1;
    s.tiles[tid]          = acc;
    block_sync_lds(); // loads the block no longer needs may still be in flight
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = tid + k * Config::BLOCK_SIZE;
        if (t < OUTPUTS) {
            const int m = t / ROWS;
            const int q = t % ROWS; // our output row 24k + q
            // even CUs: the full group's 16 rows, then the half group's 8; odd CUs the other way round
            const bool     full = odd ? q >= 8 : q < 16;
            const int      c    = full ? q - 8 * odd : q - 16 + 16 * odd;
            const floatx4 *tile = s.tiles + (full ? 0 : 2) * THREADS_PER_WARP + 16 * (c / 4) + m;
            s.rows[p.rank][t] =
                static_cast<bfloat16>(tile[0][c % 4] + tile[THREADS_PER_WARP][c % 4]);
        }
    }
    block_sync_lds();

    // M <= 4 (MoE runs them on this kernel too) keeps 6 outputs and the call number a packet: there the
    // exchange waits on latency, not bytes, and the zeroing costs more than the fewer packets save.
    if constexpr (NUM_TOKENS <= 4) {
        // all-reduce: block k swaps its rows with block k of every other rank, a packet 6 outputs and
        // the call number in one 16 B store, which lands whole, so a packet showing this call is
        // complete. Every packet goes out before any is awaited. Two buffers by call parity: no rank
        // gets two calls ahead
        if (p.world > 1) {
            constexpr int PACKETS = OUTPUTS / 6;
            static_assert(PACKETS * 6 == OUTPUTS && PACKETS <= Config::AR_PACKETS);
            const int sends = (p.world - 1) * PACKETS;
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int       other = (p.rank + 1 + t / PACKETS) % p.world;
                const int       i     = t % PACKETS;
                const uint32_t *mine  = reinterpret_cast<const uint32_t *>(s.rows[p.rank]) + 3 * i;
                store_peer(static_cast<uint32x4 *>(p.recv[other]) + ar_slot(call, p.rank, block, i),
                         uint32x4{mine[0], mine[1], mine[2], call});
            }
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int       other = (p.rank + 1 + t / PACKETS) % p.world;
                const int       i     = t % PACKETS;
                const uint32x4 *src =
                    static_cast<const uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, i);
                uint32x4 packet;
                do {
                    packet = load_nt(src);
                } while (packet.w != call);
                uint32_t *rows = reinterpret_cast<uint32_t *>(s.rows[other]) + 3 * i;
                rows[0]        = packet.x;
                rows[1]        = packet.y;
                rows[2]        = packet.z;
            }
            block_sync_lds();
            if (tid == 0) {
                p.calls[block] = call;
            }
        }
    } else {
        // all-reduce: block k swaps its rows with block k of every other rank, a packet 8 outputs in one
        // 16 B store, which lands whole. No tag: a slot holds 0 until its packet lands and its receiver
        // zeroes it again after reading, and a packet's first output never has the bits of +0 (sent as
        // -0, which adds the same: the sum starts at +0). Two buffers by call parity: no rank gets two
        // calls ahead, and a slot is written again (two calls on) only after its zeroing, which ends with
        // the call that reads it. Slots DENSE_SLOT0 on: past the ones M <= 4 uses (its packets are never
        // zeroed). Every packet goes out before any is awaited.
        if (p.world > 1) {
            constexpr int PACKETS     = OUTPUTS / 8;
            constexpr int DENSE_SLOT0 = Config::AR_PACKETS - Config::AR_ROWS * Config::MAX_NUM_TOKENS / 8;
            static_assert(PACKETS * 8 == OUTPUTS && DENSE_SLOT0 >= Config::AR_ROWS * 4 / 6 &&
                          DENSE_SLOT0 + PACKETS <= Config::AR_PACKETS);
            const int sends = (p.world - 1) * PACKETS;
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int other = (p.rank + 1 + t / PACKETS) % p.world;
                const int i     = t % PACKETS;
                uint32x4  mine  = reinterpret_cast<const uint32x4 *>(s.rows[p.rank])[i];
                mine.x |= (mine.x & 0xffffu) == 0 ? 0x8000u : 0u;
                store_peer(static_cast<uint32x4 *>(p.recv[other]) + ar_slot(call, p.rank, block, DENSE_SLOT0 + i), mine);
            }
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int other = (p.rank + 1 + t / PACKETS) % p.world;
                const int i     = t % PACKETS;
                const uint32x4 *src =
                    static_cast<const uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, DENSE_SLOT0 + i);
                uint32x4  packet;
                do {
                    packet = load_nt(src);
                } while (packet.x == 0);
                reinterpret_cast<uint32x4 *>(s.rows[other])[i] = packet;
            }
            // zeroed once all of this thread's packets are in: a zeroing store ahead of a poll would hold
            // it back (a wave's memory accesses complete in order)
            for (int t = tid; t < sends; t += Config::BLOCK_SIZE) {
                const int other = (p.rank + 1 + t / PACKETS) % p.world;
                store_nt(static_cast<uint32x4 *>(p.recv[p.rank]) + ar_slot(call, other, block, DENSE_SLOT0 + t % PACKETS),
                         uint32x4{0, 0, 0, 0});
            }
            block_sync_lds();
            if (tid == 0) {
                p.calls[block] = call;
            }
        }
    }
    // in rank order, so every rank gets the same bits
#pragma unroll
    for (int k = 0; k < AR_ITEMS<NUM_TOKENS>; ++k) {
        const int t = tid + k * Config::BLOCK_SIZE;
        if (t < OUTPUTS) {
            float sum = 0.0f;
            for (int r = 0; r < p.world; ++r) {
                sum += static_cast<float>(s.rows[r][t]);
            }
            const bfloat16 val =
                p.accumulate
                    ? static_cast<bfloat16>(static_cast<float>(static_cast<bfloat16>(sum)) + prior[k])
                    : static_cast<bfloat16>(sum);
            bfloat16 *at = p.out + t / ROWS * Config::HIDDEN_SIZE + ROWS * block + t % ROWS;
            if constexpr (SC1) {
                store_sc1(at, val);
            } else {
                *at = val;
            }
        }
    }
}

} // namespace infera_flash::glm5_m16

// The start of a decoder layer's attention for up to 16 tokens a call, in a layer kernel: what attn_qkv
// (aklr_m16/attention_bf16.h) and the MLA after it (aklr_m16/attention_layer.h) share of Infera-Flash's
// glm5/attention.h, its roles' sizes. Not its indexer variant: an indexer kernel adds glm5_m16/indexer.h to these.
#pragma once

#include "common/gemm.h"
#include "common/math.h"
#include "common/sync.h"
#include "glm5_m16/config.h"
#include "glm5_m16/mla.h"

namespace infera_flash::glm5_m16 {

// blocks 0-163 each compute a 16-row group of qkv_a (q_a 0-127, kv 128-159, k_pe 160-163) and publish it; blocks
// 128-255 then each compute a 16-row group of q_b from all of q_a (glm5/attention.h's attn_qkv)
constexpr int Q_LORA     = Config::Q_LORA_RANK;
constexpr int KV_LORA    = Config::KV_LORA_RANK;
constexpr int QKV_ROWS   = Config::QKV_A_ROWS;
constexpr int QKV_GROUPS = QKV_ROWS / 16;
constexpr int QA_GROUPS  = Q_LORA / 16;
constexpr int KV_GROUPS  = KV_LORA / 16;
// q_b group j runs on block Q_B_BLOCK0 + j
constexpr int Q_B_BLOCK0 = Config::NUM_BLOCKS - Config::Q_B_ROWS / 16;
constexpr int XCDS       = Config::NUM_XCDS;
// MLA's attending blocks, 0 .. ATTENDING - 1, all before the q_b blocks (they wait for q_b)
template <int NUM_TOKENS> constexpr int ATTENDING = mla::ATTENDING<NUM_TOKENS>;
// each thread holds one 16 B chunk of a q_a row
static_assert(Q_LORA == Config::BLOCK_SIZE * 8);
static_assert(mla::AD_FIRST == Q_B_BLOCK0 && ATTENDING<Config::MAX_NUM_TOKENS> <= Q_B_BLOCK0 &&
              QA_GROUPS + KV_GROUPS + mla::ROPE / 16 == QKV_GROUPS && QKV_GROUPS <= Config::NUM_BLOCKS);

} // namespace infera_flash::glm5_m16

// GLM-5.3 on 8 GPUs (TP8): the sizes every GLM-5 kernel is written for, per card where noted.
#pragma once

#include "common/hw.h"

namespace infera_flash::glm5_m16 {

struct Config : Hw {
    static constexpr int   HIDDEN_SIZE           = 6144;
    static constexpr int   QUANT_GROUP_SIZE      = 128; // one fp8 scale per 1x128 of activations
    static constexpr int   NUM_GROUPS            = HIDDEN_SIZE / QUANT_GROUP_SIZE;
    static constexpr int   NUM_EXPERTS           = 256;
    static constexpr int   INTERMEDIATE_SIZE     = 256; // per card: 2048 / TP8
    static constexpr int   TOP_K                 = 8;
    static constexpr float ROUTED_SCALING_FACTOR = 2.5f;
    static constexpr int   MAX_NUM_TOKENS        = 16; // rows a decode call takes: 4 MTP k=3 verifies
    // attention per card: q_a_proj's rows, kv_a_proj_with_mqa's (the kv latent, then the rope
    // part of k), qkv_a's (both), q_b_proj's; o_proj's K
    static constexpr int   Q_LORA_RANK           = 2048;
    static constexpr int   KV_LORA_RANK          = 512;
    static constexpr int   QK_ROPE_DIM           = 64;
    static constexpr int   QK_NOPE_DIM           = 192;
    static constexpr int   MLA_HEADS             = 8; // per card
    static constexpr int   V_HEAD_DIM            = 256;
    static constexpr int   QKV_A_ROWS            = Q_LORA_RANK + KV_LORA_RANK + QK_ROPE_DIM;
    static constexpr int   Q_B_ROWS              = MLA_HEADS * (QK_NOPE_DIM + QK_ROPE_DIM);
    static constexpr int   O_PROJ_K              = MLA_HEADS * V_HEAD_DIM;
    // the dense layers' MLP per card: gate_proj's rows, up_proj's (12288 / TP8)
    static constexpr int   DENSE_ROWS            = 1536;
    // the MTP layer's eh_proj rows per card (6144 / TP8)
    static constexpr int   MTP_ROWS              = HIDDEN_SIZE / 8;
    // the DSA indexer (replicated): heads, head dim, tokens per ki page
    static constexpr int   INDEX_HEADS           = 32;
    static constexpr int   INDEX_DIM             = 128;
    static constexpr int   INDEX_PAGE            = 64;
    static constexpr int   INDEX_TOPK            = 2048;
    // ExpertTable slots: the shared expert, then the most distinct experts M tokens can pick
    static constexpr int   MAX_SLOTS             = MAX_NUM_TOKENS * TOP_K + 1;
    // the shared expert's id: its weights come after the routed ones
    static constexpr int   SHARED_EXPERT         = NUM_EXPERTS;
    // the all-reduce (AllReduceParams): block k sums output rows AR_ROWS k .., a 16 B packet
    // carrying 6 of its AR_ROWS x M; receive buffer [call parity][source rank][block][packet]
    static constexpr int MAX_RANKS      = 8;
    static constexpr int AR_ROWS        = HIDDEN_SIZE / NUM_BLOCKS;
    static constexpr int AR_PACKETS     = AR_ROWS * MAX_NUM_TOKENS / 6;
    static constexpr int AR_BUFFER_SIZE = 2 * MAX_RANKS * NUM_BLOCKS * AR_PACKETS * 16;
};

// each thread's 16 B chunks of a HIDDEN_SIZE row, a block's threads covering it
constexpr int ROW_LOADS = Config::HIDDEN_SIZE / (Config::BLOCK_SIZE * 8);
static_assert(ROW_LOADS * Config::BLOCK_SIZE * 8 == Config::HIDDEN_SIZE);

} // namespace infera_flash::glm5_m16

// index_topk (Infera-Flash's glm5/indexer.h, as AKLR edits it: the picks as KV slots through the page table) for up
// to 16 rows a call, in an indexer layer's kernel: the same radix select, its rounds, exchange and picks, each row on
// BPR blocks of one XCD, which trade through its L2. The first 8 rows run on XCDs 0 .. TOPK_XCDS - 1, so the other
// XCDs start the attention meanwhile, and the rest on those once they are done with q_latent (or on XCDs
// 0 .. TOPK_XCDS - 1 after a row of at most TOPK): 16 blocks a row, two rows an XCD at once, up to SHORT_LEN scores a
// row; past that 32 blocks a row, up to MAX_LEN. glm5::topk's LDS and helpers as they are; its state for 16 rows of 32
// blocks.
#pragma once

#include "common/sync.h"
#include "glm5/indexer.h"
#include "glm5_m16/config.h"

namespace infera_flash::glm5_m16::topk {

using glm5::IndexTopkParams;
using glm5::topk::BINS;
using glm5::topk::block_scan;
using glm5::topk::CAP;
using glm5::topk::count;
using glm5::topk::count_in;
using glm5::topk::count_first;
using glm5::topk::find_digit;
using glm5::topk::IndexTopkSmem;
using glm5::topk::KPT_CLASSES;
using glm5::topk::kpt_of;
using glm5::topk::MAX_KPT;
using glm5::topk::PACKETS;
using glm5::topk::PER_THREAD;
using glm5::topk::ROUNDS;
using glm5::topk::wave_scan;
using glm5::topk::COPIES;
using glm5::topk::COPY_STRIDE;
using glm5::topk::COPIES_AT;
using glm5::topk::KEYS_AT;
using glm5::topk::GROUP_STEP;
using glm5::topk::lds_add;

constexpr int TOPK       = Config::INDEX_TOPK;
// a block's slice's page-table entries in LDS past the keys: a slice is at most MAX_KPT * BLOCK_SIZE scores
constexpr int PT_AT    = KEYS_AT + MAX_KPT * Config::BLOCK_SIZE * 4;
constexpr int PT_LOADS = (MAX_KPT * Config::BLOCK_SIZE / Config::INDEX_PAGE + 2 + Config::BLOCK_SIZE - 1) /
                         Config::BLOCK_SIZE;
static_assert(PT_AT + PT_LOADS * Config::BLOCK_SIZE * 4 <= Config::SMEM_SIZE);
constexpr int M_MAX      = Config::MAX_NUM_TOKENS;
constexpr int XCDS       = Config::NUM_XCDS;
constexpr int TOPK_XCDS  = XCDS / 2;
constexpr int XCD_BLOCKS = Config::NUM_BLOCKS / XCDS;
constexpr int MAX_BPR    = XCD_BLOCKS;
constexpr int SHORT_BPR  = XCD_BLOCKS / 2;
constexpr int SHORT_LEN  = SHORT_BPR * Config::BLOCK_SIZE * MAX_KPT;
constexpr int MAX_LEN    = MAX_BPR * Config::BLOCK_SIZE * MAX_KPT;
// rows a pass: TOPK_XCDS XCDs, XCD_BLOCKS / BPR rows each
template <int BPR> constexpr int PASS_ROWS = TOPK_XCDS * (XCD_BLOCKS / BPR);
static_assert(glm5::topk::ROW_BLOCKS == MAX_BPR && glm5::topk::TOPK == TOPK && TOPK % MAX_BPR == 0 &&
              SHORT_BPR % WAVES == 0 && SHORT_BPR <= THREADS_PER_WARP && sizeof(IndexTopkSmem) <= Config::SMEM_SIZE);

// glm5::topk's, for M_MAX rows of MAX_BPR blocks: row m's block j at m MAX_BPR + j, whatever its BPR
struct IndexTopkState {
    uint32x4 packets[ROUNDS][M_MAX * MAX_BPR][PACKETS];
    uint32x4 done[M_MAX * MAX_BPR];
    uint32x4 candidates[M_MAX * MAX_BPR][CAP];
    uint2    picks[M_MAX * TOPK];
    // the scores' round-0 counts of each row (its keys by their top 8 bits), added up in device-scope atomics by the
    // blocks scoring its segment, and how many of those blocks have added theirs ([m][0], a line a row); the row's
    // block 0 zeroes both once every block of the row is past round 0
    uint32_t r0_hist[M_MAX][BINS];
    uint32_t r0_arrived[M_MAX][32];
};

// Entry `at` of the top-k (m * TOPK + i), on another XCD, once it shows this call's epoch
__device__ __forceinline__ int tagged_pick(const IndexTopkState &g, int at, uint32_t epoch) {
    const auto buf = raw_buffer(g.picks, sizeof(g.picks));
    uint2      e;
    do {
        asm volatile("" ::: "memory");
        e = buffer_load_sc1<uint2>(buf, 8 * at);
    } while (e.y != epoch);
    return static_cast<int>(e.x);
}

// The KPT class (keys a thread, 16 << c) that holds a row of len scores on BPR blocks
template <int BPR> __device__ __forceinline__ int kpt_class_of(int len) {
    const int per = (len + BPR * Config::BLOCK_SIZE - 1) / (BPR * Config::BLOCK_SIZE);
    int       c   = 0;
    while (c < KPT_CLASSES - 1 && kpt_of(c) < per) {
        ++c;
    }
    return c;
}

// glm5::topk::index_topk_row in a layer kernel for block j < BPR of row m, at this call's epoch: the scores were
// written earlier in the kernel on other XCDs, so they are read with sc1 once wait_scores(from, n) returns for the
// block's slice (positions from .. from + n - 1), and the picks go out as KV slots in sc1 stores and again tagged
// with the epoch (IndexTopkState::picks) for the attending blocks.
template <int BPR, int KPT, typename WaitScores>
__device__ __forceinline__ void index_topk_row(const IndexTopkParams &p, uint8_t *smem, uint32_t epoch, int m, int j,
                                               int r0_expected, WaitScores wait_scores) {
    constexpr int ROW_PACKETS = BPR * PACKETS;
    constexpr int WAVE_ROWS   = BPR / WAVES; // the row's blocks a wave adds up
    static_assert(BPR % WAVES == 0 && BPR <= MAX_BPR && TOPK % BPR == 0 && KPT <= MAX_KPT);
    IndexTopkSmem  &s   = *reinterpret_cast<IndexTopkSmem *>(smem);
    IndexTopkState &g   = *static_cast<IndexTopkState *>(p.state);
    const int       tid = threadIdx.x;
    const int       len = p.lens[m];
    int            *out = p.out + m * TOPK;
    const auto      slot_of = [&](int v) {
        return v < 0 ? v : p.page_table[m * p.page_table_stride + v / p.page_size] * p.page_size + v % p.page_size;
    };
    const auto put_slot = [&](int i, int slot) {
        store_sc1(reinterpret_cast<uint32_t *>(out + i), static_cast<uint32_t>(slot));
        store_sc1(&g.picks[m * TOPK + i], uint2{static_cast<uint32_t>(slot), epoch});
    };
    const auto put = [&](int i, int v) { put_slot(i, slot_of(v)); };
    if (len <= TOPK) {
        if (tid < TOPK / BPR) {
            const int i = j * (TOPK / BPR) + tid;
            put(i, i < len ? i : -1);
        }
        return;
    }

    // the slice into registers: key slot k is element 4 (tid + 256 (k / 4)) + k % 4
    const int per  = ((len + BPR - 1) / BPR + 3) & ~3;
    const int from = min(j * per, len);
    const int n    = min(per, len - from);
    // the slice's page-table entries (an input) loaded while the scores are waited for, then into LDS: the winners'
    // slots from there, not each a page-table read after the last winner's store
    constexpr int PAGE = Config::INDEX_PAGE;
    const int     p0   = from / PAGE;
    const int     np   = n > 0 ? (from + n - 1) / PAGE - p0 + 1 : 0;
    int           pt_v[PT_LOADS];
#pragma unroll
    for (int i = 0; i < PT_LOADS; ++i) {
        const int e = tid + i * Config::BLOCK_SIZE;
        pt_v[i]     = e < np ? p.page_table[m * p.page_table_stride + p0 + e] : 0;
    }
    wait_scores(from, n);
    int *const pages = reinterpret_cast<int *>(smem + PT_AT);
#pragma unroll
    for (int i = 0; i < PT_LOADS; ++i) {
        const int e = tid + i * Config::BLOCK_SIZE;
        if (e < np) {
            pages[e] = pt_v[i];
        }
    }
    const auto    slice = raw_buffer(p.logits + static_cast<size_t>(m) * p.stride + from, 4 * n);
    const auto    at    = [&](int k) { return 4 * (tid + Config::BLOCK_SIZE * (k / 4)) + k % 4; };
    constexpr int SC1   = 16; // the cache-policy operand's sc1 bit
    uint32x4      raw[KPT / 4];
#pragma unroll
    for (int q = 0; q < KPT / 4; ++q) {
        raw[q] = __builtin_bit_cast(uint32x4, __builtin_amdgcn_raw_buffer_load_b128(slice, 4 * at(4 * q), 0, SC1));
    }
    // every load out before the first is used: else the compiler waits for each in turn
#pragma unroll
    for (int q = 0; q < KPT / 4; ++q) {
        pin(raw[q]);
    }
    // PORT of m4opt ix round 4: the keys into LDS, the groups below `groups`
    uint32x4 *const keys   = reinterpret_cast<uint32x4 *>(smem + KEYS_AT);
    const int       groups = ((n + 4 * Config::BLOCK_SIZE - 1) / (4 * Config::BLOCK_SIZE) + GROUP_STEP - 1) &
                       ~(GROUP_STEP - 1);
    // the scores are their keys already (glm5::ix::score_key); only the groups past `full` hold slots past the slice
    const int       full   = n / (4 * Config::BLOCK_SIZE);
#pragma unroll
    for (int q = 0; q < KPT / 4; ++q) {
        if (q < groups) {
            uint32x4 k4;
            if (q < full) {
                k4 = raw[q];
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) {
                    k4[e] = at(4 * q + e) < n ? raw[q][e] : 0u;
                }
            }
            keys[q * Config::BLOCK_SIZE + tid] = k4;
        }
    }
    const uint32_t empty = static_cast<uint32_t>(4 * Config::BLOCK_SIZE * groups - n);
    const auto each_key = [&](auto fn) {
        for (int q = 0; q < groups; q += GROUP_STEP) {
            uint32x4 k4[GROUP_STEP];
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
                k4[i] = keys[(q + i) * Config::BLOCK_SIZE + tid];
            }
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
#pragma unroll
                for (int e = 0; e < 4; ++e) {
                    fn(k4[i][e]);
                }
            }
        }
    };

    const int row  = m * MAX_BPR; // the row's blocks in the state
    uint32_t  need = TOPK, prefix = 0;
    int       bits = 0;
    for (int r = 0; r < ROUNDS; ++r) {
        const int shift = 24 - 8 * r;
        if (r == 0) {
            // round 0 from the scores' counts, once every block scoring the row's segment has added its own
            const auto arrived = raw_buffer(&g.r0_arrived[m][0], sizeof(uint32_t));
            const auto counts  = raw_buffer(&g.r0_hist[m][0], BINS * sizeof(uint32_t));
            uint32_t   in;
            do {
                asm volatile("" ::: "memory");
                in = buffer_load_sc1<uint32_t>(arrived, 0);
            } while (static_cast<int>(in) < r0_expected);
            s.hist[tid] = buffer_load_sc1<uint32_t>(counts, 4 * tid);
            block_sync_lds();
            find_digit(s, [&](int b) { return s.hist[b]; }, need);
            block_sync_lds();
            need -= s.beyond;
            prefix = s.digit;
            bits   = 8;
            if (s.in_bin <= CAP) {
                break;
            }
            continue;
        }
        s.hist[tid] = 0;
        block_sync_lds();
        const uint32_t base = prefix << 8, out = BINS + threadIdx.x % THREADS_PER_WARP;
        each_key([&](uint32_t key) { count_in(s.hist, key, shift, base, out); });
        block_sync_lds();
        if (prefix == 0 && tid == 0) {
            s.hist[0] -= empty;
        }
        if (tid < PACKETS) {
            uint32x4 pk;
#pragma unroll
            for (int c = 0; c < 3; ++c) {
                const int      b  = 6 * tid + 2 * c;
                const uint32_t lo = b < BINS ? s.hist[b] : 0u;
                const uint32_t hi = b + 1 < BINS ? s.hist[b + 1] : 0u;
                pk[c]             = lo | hi << 16;
            }
            pk[3] = epoch;
            store_l2(&g.packets[r][row + j][tid], pk);
        }
        // the row's blocks' counts, added up: wave w's lane l < PACKETS adds up packet l of blocks
        // WAVE_ROWS w .. + WAVE_ROWS - 1
        const int wave = tid / THREADS_PER_WARP, lane = tid % THREADS_PER_WARP;
        if (lane < PACKETS) {
            const auto buf = raw_buffer(&g.packets[r][row][0], ROW_PACKETS * sizeof(uint32x4));
            uint32x4   v[WAVE_ROWS];
            bool       ready;
            do {
                // reload every time: without it the loads are hoisted and the loop assumed to end
                asm volatile("" ::: "memory");
#pragma unroll
                for (int i = 0; i < WAVE_ROWS; ++i) {
                    v[i] = buffer_load_l2(buf, 16 * ((WAVE_ROWS * wave + i) * PACKETS + lane));
                }
                ready = true;
#pragma unroll
                for (int i = 0; i < WAVE_ROWS; ++i) {
                    ready &= v[i][3] == epoch;
                }
            } while (!ready);
#pragma unroll
            for (int e = 0; e < 6; ++e) {
                uint32_t c = 0;
#pragma unroll
                for (int i = 0; i < WAVE_ROWS; ++i) {
                    c += v[i][e / 2] >> 16 * (e % 2) & 0xffffu;
                }
                if (6 * lane + e < BINS) {
                    s.part[wave][6 * lane + e] = c;
                }
            }
        }
        block_sync_lds();
        find_digit(
            s, [&](int b) { return s.part[0][b] + s.part[1][b] + s.part[2][b] + s.part[3][b]; }, need);
        block_sync_lds();
        need -= s.beyond;
        prefix = prefix << 8 | s.digit;
        bits   = 8 * (r + 1);
        if (s.in_bin <= CAP) {
            break;
        }
    }

    // this block's winners (fixed bits above prefix) go straight out, its candidates (equal to it) to its list for
    // block 0: at most CAP, enough for block 0 when all bits are fixed. Both as bit masks, so the stores below loop
    // over the few set bits, not over every key
    constexpr int WORDS = (KPT + 31) / 32;
    // the keys with the prefix: lo .. hi; above hi win, from lo (past the empty slots' 0) up to hi tie
    const uint32_t lo = prefix << (32 - bits), hi = lo | static_cast<uint32_t>((uint64_t{1} << (32 - bits)) - 1);
    const uint32_t lo1 = max(lo, 1u);
    uint32_t       wm[WORDS] = {}, cm[WORDS] = {}; // bit k % 32 of word k / 32: key k wins / ties
#pragma unroll
    for (int q = 0; q < KPT / 4; q += GROUP_STEP) {
        if (q < groups) {
            uint32x4 k4[GROUP_STEP];
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
                k4[i] = keys[(q + i) * Config::BLOCK_SIZE + tid];
            }
#pragma unroll
            for (int i = 0; i < GROUP_STEP; ++i) {
#pragma unroll
                for (int e = 0; e < 4; ++e) {
                    const int      k   = 4 * (q + i) + e;
                    const uint32_t key = k4[i][e];
                    wm[k / 32] |= static_cast<uint32_t>(key > hi) << k % 32;
                    cm[k / 32] |= static_cast<uint32_t>(key >= lo1) << k % 32; // wins too, cleared below
                }
            }
        }
    }
    uint32_t nw = 0, nc = 0;
#pragma unroll
    for (int i = 0; i < WORDS; ++i) {
        cm[i] &= ~wm[i];
        nw += __builtin_popcount(wm[i]);
        nc += __builtin_popcount(cm[i]);
    }
    uint32_t       counted;
    const uint32_t base = block_scan(nw | nc << 16, s.scan, counted);
    if (tid == 0) {
        store_l2(&g.done[row + j], uint32x4{counted & 0xffffu, min(counted >> 16, uint32_t{CAP}), 0u, epoch});
    }
    uint32_t  bc = base >> 16;
    uint32x4 *cl = g.candidates[row + j];
#pragma unroll
    for (int i = 0; i < WORDS; ++i) {
        for (uint32_t mk = cm[i]; mk; mk &= mk - 1) {
            const int k = 32 * i + __builtin_ctz(mk);
            if (bc < CAP) {
                const uint32_t kv =
                    reinterpret_cast<const uint32_t *>(keys)[4 * (k / 4 * Config::BLOCK_SIZE + tid) + k % 4];
                // its slot, so block 0 reads no page table
                const int v = from + at(k);
                store_l2(cl + bc, uint32x4{kv, static_cast<uint32_t>(pages[v / PAGE - p0] * PAGE + v % PAGE), 0u,
                                           epoch});
            }
            ++bc;
        }
    }

    // every block's counts: where its winners and its candidates start
    if (tid < THREADS_PER_WARP) {
        uint32_t w = 0, c = 0;
        if (tid < BPR) {
            const auto done = raw_buffer(&g.done[row], BPR * sizeof(uint32x4));
            uint32x4   d;
            do {
                asm volatile("" ::: "memory");
                d = buffer_load_l2(done, 16 * tid);
            } while (d[3] != epoch);
            w = d[0];
            c = d[1];
        }
        const uint32_t ow = wave_scan(w), oc = wave_scan(c);
        if (tid < BPR) {
            s.off_w[tid + 1] = ow;
            s.off_c[tid + 1] = oc;
        }
        if (tid == 0) {
            s.off_w[0] = 0;
            s.off_c[0] = 0;
        }
    }
    block_sync_lds();
    // block 0 (past its winners): the candidates into LDS, every load issued before the first is used, again until all
    // show the epoch. Entry i of the row's list is entry i - off[b] of block b's
    const auto owner = [](const uint32_t *off, uint32_t i) {
        int b = 0;
#pragma unroll
        for (int step = BPR / 2; step >= 1; step /= 2) {
            b = off[b + step] <= i ? b + step : b;
        }
        return b;
    };
    const uint32_t wins = s.off_w[BPR];
    // all bits fixed: the candidates are equal, the first `need` of them win
    const uint32_t cands = bits == 32 ? min(s.off_c[BPR], need) : s.off_c[BPR];
    const auto     list  = raw_buffer(g.candidates[row], BPR * CAP * sizeof(uint32x4));
    // entries k < used of each thread (mostly one: a row's candidates are mostly under 256)
    uint32_t at_w = s.off_w[j] + (base & 0xffffu);
#pragma unroll
    for (int i = 0; i < WORDS; ++i) {
        for (uint32_t mk = wm[i]; mk; mk &= mk - 1) {
            const int v = from + at(32 * i + __builtin_ctz(mk));
            put_slot(at_w++, pages[v / PAGE - p0] * PAGE + v % PAGE);
        }
    }
    if (j != 0) {
        return;
    }
    const int used = static_cast<int>((cands + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE);
    int       c_at[PER_THREAD];
    uint32x4  c[PER_THREAD] = {};
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        if (k < used) {
            const uint32_t i = min(tid + k * Config::BLOCK_SIZE, cands - 1);
            const int      b = owner(s.off_c, i);
            c_at[k]          = 16 * (b * CAP + static_cast<int>(i - s.off_c[b]));
            c[k]             = buffer_load_l2(list, c_at[k]);
        }
    }
    bool ready = true;
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        ready &= k >= used || c[k][3] == epoch;
    }
    while (!ready) {
        asm volatile("" ::: "memory");
#pragma unroll
        for (int k = 0; k < PER_THREAD; ++k) {
            if (k < used) {
                c[k] = buffer_load_l2(list, c_at[k]);
            }
        }
        ready = true;
#pragma unroll
        for (int k = 0; k < PER_THREAD; ++k) {
            ready &= k >= used || c[k][3] == epoch;
        }
    }
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        const uint32_t i = tid + k * Config::BLOCK_SIZE;
        if (i < cands) {
            s.cand[i] = uint64_t{c[k][0]} << 32 | c[k][1];
        }
    }
    block_sync_lds();

    // the rest from the candidates: more rounds over their lower bits, in LDS
    uint32_t lneed = need, lprefix = prefix;
    int      lbits = bits;
    if (cands > need) {
        while (lbits < 32) {
            const int shift = 24 - lbits;
            s.hist[tid]     = 0;
            block_sync_lds();
#pragma unroll
            for (int k = 0; k < PER_THREAD; ++k) {
                const uint32_t i = tid + k * Config::BLOCK_SIZE;
                if (i < cands) {
                    count_in(s.hist, static_cast<uint32_t>(s.cand[i] >> 32), shift, lprefix << 8,
                             BINS + threadIdx.x % THREADS_PER_WARP);
                }
            }
            block_sync_lds();
            find_digit(s, [&](int b) { return s.hist[b]; }, lneed);
            block_sync_lds();
            lneed -= s.beyond;
            lprefix = lprefix << 8 | s.digit;
            lbits += 8;
            if (s.in_bin == lneed) {
                break; // the whole bin wins
            }
        }
    }
    // candidates above lprefix win; of those equal to it the first lneed in (thread, entry) order: thread t takes
    // entries t + 256 k, so neighbours read neighbouring LDS words
    const int llow = 32 - lbits;
    uint32_t  cw = 0, ct = 0;
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        const uint32_t i = tid + k * Config::BLOCK_SIZE;
        if (i < cands) {
            const uint32_t top = static_cast<uint32_t>(s.cand[i] >> 32) >> llow;
            cw += top > lprefix;
            ct += top == lprefix;
        }
    }
    uint32_t       both;
    const uint32_t start = block_scan(cw | ct << 16, s.scan, both);
    uint32_t       pw = wins + (start & 0xffffu), pt = start >> 16;
    const uint32_t ties = wins + (both & 0xffffu);
    // the entry each of the thread's candidates takes (-1: none); then every page-table read before the first store
    // (each store's asm would keep the next read after it, a read's whole latency a pick)
    int dst[PER_THREAD], pos[PER_THREAD];
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        const uint32_t i = tid + k * Config::BLOCK_SIZE;
        dst[k]           = -1;
        pos[k]           = 0;
        if (i < cands) {
            const uint64_t e   = s.cand[i];
            const uint32_t top = static_cast<uint32_t>(e >> 32) >> llow;
            pos[k]             = static_cast<int>(e);
            if (top > lprefix) {
                dst[k] = static_cast<int>(pw++);
            } else if (top == lprefix) {
                if (pt < lneed) {
                    dst[k] = static_cast<int>(ties + pt);
                }
                ++pt;
            }
        }
    }
    // the list's entries are slots
#pragma unroll
    for (int k = 0; k < PER_THREAD; ++k) {
        if (dst[k] >= 0) {
            put_slot(dst[k], pos[k]);
        }
    }
    // every block of the row is past round 0 (its done is in): the row's counts zeroed for the next call
    store_sc1(&g.r0_hist[m][tid], 0u);
    if (tid == 0) {
        store_sc1(&g.r0_arrived[m][0], 0u);
    }
}

} // namespace infera_flash::glm5_m16::topk

// MLA on the sparse path for up to 16 tokens a call, in a layer kernel (aklr_m16/attention_layer.h): Infera-Flash's
// glm5/mla.h, its device code as AKLR edits it (rows at sglang's KV slots, fp8 rows saturated as sglang's cache write
// stores them), laid out so the tokens are the columns of the same MFMA tiles and every weight is read once for all of
// them.
#pragma once

#include <cstddef>
#include <type_traits>

#include "common/math.h"
#include "common/sync.h"
#include "glm5_m16/config.h"

namespace infera_flash::glm5_m16 {

// MLA on the sparse path for up to 16 tokens in a layer kernel, q_b's output through W_UV: q_latent = q_nope W_UK,
// RoPE (interleaved) on q_pe and k_pe as HF, the tokens' fp8 KV rows, the attention over each token's top-k rows of
// the KV cache, then o = o_latent W_UV per head, o_proj's input.
struct MlaCoreParams {
    const bfloat16 *q;        // [M, MLA_HEADS * (QK_NOPE_DIM + QK_ROPE_DIM)] q_b's output
    const bfloat16 *k_pe;     // [M, QK_ROPE_DIM], rows k_pe_stride apart
    int             k_pe_stride;
    const int64_t  *position; // [M]
    const bfloat16 *cos;      // [positions, QK_ROPE_DIM / 2]
    const bfloat16 *sin;
    // [MLA_HEADS, KV_LORA_RANK, QK_NOPE_DIM], W_UK transposed: fp8 with one dequant scale [1], or bf16
    const uint8_t  *w_k;
    const float    *w_k_scale;
    uint8_t        *kv;       // this layer's KV cache, fp8 [slots, KV_LORA_RANK + QK_ROPE_DIM]
    const int64_t  *slot;     // [M] each token's row of kv
    const int      *indices;  // [M, INDEX_TOPK] the rows each token attends, -1 for none
    float           qk_scale; // sm_scale log2(e)
    // [MLA_HEADS, V_HEAD_DIM, KV_LORA_RANK]: fp8 with one dequant scale [1], or bf16
    const uint8_t  *w_v;
    const float    *w_v_scale;
    void           *workspace; // WORKSPACE_SIZE bytes of sync slots, zeroed once and kept
    void           *scratch;   // sizeof(mla::MlaCoreScratch) bytes
    // 16 B packets of 4 values and the writers' epoch (zeroed once, kept between calls): o_latent [M, MLA_HEADS,
    // KV_LORA_RANK], which the W_UV blocks poll, and o [M, MLA_HEADS * V_HEAD_DIM], which o_proj polls
    uint32x4       *latent_tagged;
    uint32x4       *out_tagged;
};

} // namespace infera_flash::glm5_m16

// IN_KERNEL: q_b's output and k_pe were written earlier in the same kernel on other XCDs, so they are read with sc1
// (the caller waits for them first).
namespace infera_flash::glm5_m16::mla {

// Two kinds of block, as glm5/mla.h's mla_core:
// - blocks 0 .. ATTENDING - 1 attend: token b / TOKEN_BLOCKS's top-k rows 64 S (b % TOKEN_BLOCKS) .. + 64 S - 1 in S =
//   ATTN_STEPS steps of 64 (a tile of 16 a wave each), so 16 tokens' blocks fit before AD_FIRST. They read their rows
//   at the start, turn the token's q_pe and build the rows of this call's tokens themselves (the cache may not hold
//   them yet), then wait for q_latent. The block's max over all its rows comes first, so its S steps make one partial
//   sum, which it publishes.
// - blocks AD_FIRST .. 255 (j = b - AD_FIRST) first compute q_latent = q_nope W_UK, groups 2j and 2j + 1 (16 rows of a
//   head each, waves 0 and 1, the tokens the columns), and publish it. Once their token's partial sums are out, the
//   first UNITS each combine UNIT_DIMS dims of a head of a token into o_latent (combine_unit); then every one
//   multiplies 16-row group j % O_GROUPS of head j / O_GROUPS's W_UV (read at the start) by that head's o_latent of
//   every token (wuv_unit). o_latent and o go out as packets the next readers poll.
constexpr int HEADS      = Config::MLA_HEADS;
constexpr int LATENT     = Config::KV_LORA_RANK;
constexpr int NOPE       = Config::QK_NOPE_DIM;
constexpr int ROPE       = Config::QK_ROPE_DIM;
constexpr int Q_HEAD     = NOPE + ROPE;   // a head of q_b's output
constexpr int ROW        = LATENT + ROPE; // a head of q, a row of the KV cache
constexpr int V_HEAD     = Config::V_HEAD_DIM;
constexpr int TOPK       = Config::INDEX_TOPK;
constexpr int M_MAX      = Config::MAX_NUM_TOKENS;
constexpr int TILE       = 16;
constexpr int CHUNK      = WAVES * TILE; // an attending block's rows a step
constexpr int CHUNKS     = TOPK / CHUNK; // per token
constexpr int AD_FIRST   = Config::NUM_BLOCKS / 2;
constexpr int PROJECTING = Config::NUM_BLOCKS - AD_FIRST;
constexpr int Q_GROUPS   = LATENT / 16; // per head
constexpr int SEG        = ROW / 4;
constexpr int STEPS      = SEG / 8;
constexpr int DIM_TILES  = LATENT / 16;
constexpr int V_STRIDE   = LATENT + 24; // bf16; rows 12 banks apart, so writes and transposed reads
                                        // both hit distinct banks
constexpr int ROW_CHUNKS = ROW / 16;
constexpr int O_GROUPS   = V_HEAD / 16; // W_UV blocks per head
// a slot's packet 1, posted once the block's partial sums are out (packet 0: q_latent)
constexpr int PARTIAL_SUMS_PACKET = 1;
// an attending block's steps, a token's attending blocks, all of them
template <int NUM_TOKENS> constexpr int ATTN_STEPS   = NUM_TOKENS <= 4 ? 1 : NUM_TOKENS <= 8 ? 2 : 4;
template <int NUM_TOKENS> constexpr int TOKEN_BLOCKS = CHUNKS / ATTN_STEPS<NUM_TOKENS>;
template <int NUM_TOKENS> constexpr int ATTENDING    = NUM_TOKENS * TOKEN_BLOCKS<NUM_TOKENS>;
// aklr_m16/attention_layer.h's steps a block: ATTN_STEPS's, but 3 at 12 tokens, their 384 chunks on all AD_FIRST blocks.
// Where a token's CHUNKS are no whole number of blocks' (SPANS), the tokens' top-k rows are one list, block b attending
// its chunks S b .. S b + S - 1 (attend_rows of token 0, c = b): a block may hold the end of one token's rows and the
// start of the next one's (it straddles them: attend_spanned's hi_from), and a token's partial sums come from up to
// SPAN_BLOCKS blocks (combine_unit_spanned)
template <int NUM_TOKENS> constexpr int LAYER_STEPS     = NUM_TOKENS == 12 ? 3 : ATTN_STEPS<NUM_TOKENS>;
template <int NUM_TOKENS> constexpr int LAYER_ATTENDING = NUM_TOKENS * CHUNKS / LAYER_STEPS<NUM_TOKENS>;
template <int S> constexpr bool         SPANS           = CHUNKS % S != 0;
template <int S> constexpr int          SPAN_BLOCKS     = (CHUNKS + 2 * (S - 1)) / S;
static_assert(LAYER_ATTENDING<12> == AD_FIRST && 12 * CHUNKS % LAYER_STEPS<12> == 0);
// combine_unit: SPLIT units a head of a token, each UNIT_DIMS of its o_latent
template <int NUM_TOKENS> constexpr int SPLIT     = 4 / ATTN_STEPS<NUM_TOKENS>;
template <int NUM_TOKENS> constexpr int UNIT_DIMS = LATENT / SPLIT<NUM_TOKENS>;
template <int NUM_TOKENS> constexpr int UNITS     = NUM_TOKENS * HEADS * SPLIT<NUM_TOKENS>;
static_assert(HEADS * Q_GROUPS == 2 * PROJECTING && LATENT == THREADS_PER_WARP * 8 && ROPE == THREADS_PER_WARP);
static_assert(SEG % 16 == 0 && ATTENDING<M_MAX> <= AD_FIRST && UNITS<M_MAX> <= PROJECTING &&
              HEADS * O_GROUPS == PROJECTING && M_MAX <= 16);
static_assert(LATENT == 2 * Config::BLOCK_SIZE && HEADS * ROPE / 2 == Config::BLOCK_SIZE &&
              LATENT == 128 * WAVES);

using bfloat16x4 = bfloat16 __attribute__((ext_vector_type(4)));

// an attending block's partial sums: per head the max score and the sum of exp2(score - max) (a 16 B slot), and the
// unnormalized output in bf16, head-major
struct MlaCorePartial {
    floatx4  stats[HEADS];
    bfloat16 out[HEADS][LATENT];
};

struct MlaCoreScratch {
    bfloat16       q[M_MAX][HEADS][LATENT]; // q_latent
    MlaCorePartial partial[AD_FIRST];       // attending block b's
    MlaCorePartial partial_hi[M_MAX];       // spanned: token m's from the block straddling into it
};

// steps' latents in LDS at once (past that in rounds), and o_latent's rows in wuv_unit, 4 banks apart
constexpr int V_BUFS    = 2;
constexpr int WUV8_TILES = 8; // combine_wuv's 16-row groups of W_UV
constexpr int OL_STRIDE = LATENT + 8;

struct MlaCoreSmem {
    bfloat16 q[HEADS][ROW];     // the token's q
    uint8_t  fresh[M_MAX][ROW]; // this call's tokens' rows, fp8
    union {
        bfloat16 v[V_BUFS][WAVES][TILE][V_STRIDE]; // steps' tiles' latents, bf16
        struct {                                   // combine_unit
            float scale[CHUNKS];                   // each partial's weight
            float osum[WAVES][LATENT];             // the waves' sums over their partials
        };
        struct {                                   // combine_wuv
            float    g_scale[CHUNKS];
            float    g_osum[WAVES][LATENT];
            bfloat16 g_ol[LATENT];
            floatx4  g_tiles[WUV8_TILES][Config::BLOCK_SIZE];
        };
        struct {                                   // wuv_unit
            bfloat16 ol[16][OL_STRIDE];            // a head's o_latent, a row a token
            floatx4  tiles[Config::BLOCK_SIZE];    // each wave's 16x16 partial sum
        };
    };
    // the steps' tiles' probabilities against the block's max, in bf16 as p . v takes them
    bfloat16 p[ATTN_STEPS<M_MAX>][WAVES][HEADS][TILE];
    float    max[WAVES][HEADS]; // each wave's max score over its tiles
    float    sum[WAVES][HEADS]; // each wave's sum of p
    // attend_spanned's max and sum, a straddling block's next token's heads past HEADS
    float    max_span[WAVES][2 * HEADS];
    float    sum_span[WAVES][2 * HEADS];
};
static_assert(sizeof(MlaCoreSmem) <= Config::SMEM_SIZE);

// x within fp8's finite values, as sglang's cache write saturates (a NaN stays one); the
// conversion makes a NaN of anything past them
__device__ inline float fp8_finite(float x) {
    return x > 448.0f ? 448.0f : x < -448.0f ? -448.0f : x;
}

// 8 fp8 values of a row for the cache from 8 bf16, saturated, rounded to nearest even
__device__ inline uint2 to_fp8x8(const bfloat16 (&v)[8]) {
    uint32_t out[2];
#pragma unroll
    for (int i = 0; i < 2; ++i) {
        const uint32_t lo = __builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(v[4 * i]),
                                                            fp8_finite(v[4 * i + 1]), 0, false);
        out[i]            = __builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(v[4 * i + 2]),
                                                            fp8_finite(v[4 * i + 3]), lo, true);
    }
    return uint2{out[0], out[1]};
}

// the 2 bf16 at element `at` of base (`bytes` long) as floats; the 8 from `at` into out
template <bool IN_KERNEL>
__device__ inline void load_pair(const bfloat16 *base, int bytes, int at, float &x0, float &x1) {
    uint32_t v;
    if constexpr (IN_KERNEL) {
        v = buffer_load_sc1<uint32_t>(raw_buffer(base, bytes), 2 * at);
    } else {
        v = *reinterpret_cast<const uint32_t *>(base + at);
    }
    bfloat16 b[2];
    __builtin_memcpy(b, &v, 4);
    x0 = b[0];
    x1 = b[1];
}
template <bool IN_KERNEL, typename T>
__device__ inline void load8(const bfloat16 *base, int bytes, int at, T &out) {
    static_assert(sizeof(T) == 16);
    uint32x4 v;
    if constexpr (IN_KERNEL) {
        v = buffer_load_sc1(raw_buffer(base, bytes), 2 * at);
    } else {
        v = *reinterpret_cast<const uint32x4 *>(base + at);
    }
    __builtin_memcpy(&out, &v, 16);
}

// A 16-row group of a per-head product, w [HEADS, N, K] fp8 (BF16: bf16) times each token's K bf16 values of the
// head, on one wave: rows 16 group .. + 15 of head h. Lane (g, c) loads row 16 group + c over K K_SEG g .. + K_SEG - 1,
// and the same K of x from element at (token c's values of head h; IN_KERNEL: with sc1, x being bytes long); lane
// (g, c) gets rows 4g .. 4g + 3 for token c.
template <int K, int N, bool IN_KERNEL = false, bool BF16 = false>
__device__ __forceinline__ floatx4 head_product(const uint8_t *w, const bfloat16 *x, int at, int h,
                                                int group, int bytes = 0) {
    constexpr int K_SEG   = K / 4;
    constexpr int K_STEPS = K_SEG / 8;
    // 16 B of w: two steps' values in fp8, one step's in bf16
    constexpr int W_LOADS = BF16 ? K_STEPS : K_SEG / 16;
    static_assert(K_SEG % 16 == 0 && K_STEPS % 2 == 0);
    const int      lane  = threadIdx.x % THREADS_PER_WARP;
    const int      g     = lane / 16;
    const int      c     = lane % 16;
    const uint8_t *w_row =
        w + ((static_cast<size_t>(h) * N + 16 * group + c) * K + K_SEG * g) * (BF16 ? 2 : 1);
    uint32x4       wv[W_LOADS];
    bfloat16x8     xv[K_STEPS];
#pragma unroll
    for (int i = 0; i < W_LOADS; ++i) {
        wv[i] = reinterpret_cast<const uint32x4 *>(w_row)[i];
    }
#pragma unroll
    for (int i = 0; i < K_STEPS; ++i) {
        load8<IN_KERNEL>(x, bytes, at + K_SEG * g + 8 * i, xv[i]);
    }
    floatx4 acc = {};
#pragma unroll
    for (int i = 0; i < K_STEPS; ++i) {
        bfloat16x8 a;
        if constexpr (BF16) {
            a = __builtin_bit_cast(bfloat16x8, wv[i]);
        } else {
            const uint32x4 wi = wv[i / 2];
            a = i % 2 ? fp8x8_to_bf16(wi[2], wi[3]) : fp8x8_to_bf16(wi[0], wi[1]);
        }
        acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(a, xv[i], acc, 0, 0, 0);
    }
    return acc;
}

constexpr int Q_BYTES = M_MAX * HEADS * Q_HEAD * 2;

template <int NUM_TOKENS, typename Params>
__device__ inline int k_pe_bytes(const Params &p) {
    return ((NUM_TOKENS - 1) * p.k_pe_stride + ROPE) * 2;
}

// a pair's RoPE: (x0, x1) of position pos, pair i
template <typename Params>
__device__ inline void turn(const Params &p, float &x0, float &x1, int64_t pos, int i) {
    rope_pair(x0, x1, p.cos[pos * (ROPE / 2) + i], p.sin[pos * (ROPE / 2) + i]);
}

// an attending block's rows, each step's: lane (g, c)'s row of its wave's tile (row c) and its bytes SEG g ..
template <int S> struct AttendRows {
    int      idx[S];
    uint32x4 raw[S][SEG / 16];
};

// The block attending steps S c .. S c + S - 1 (chunks of 64) of token m's top-k rows: in each its wave's tile, each
// lane its part as q . k takes it; an empty slot reads row 0. Only issues the loads (every step's entries first). With
// pick, entry `at` of the top-k is pick(at), each step's rows loaded once its entries are in.
template <int S, typename Pick = std::nullptr_t>
__device__ __forceinline__ void attend_rows(const MlaCoreParams &p, int m, int c, AttendRows<S> &r,
                                            Pick pick = nullptr) {
    const int  lane = threadIdx.x % THREADS_PER_WARP;
    const int  wave = threadIdx.x / THREADS_PER_WARP;
    const auto rows = [&](int st) {
        const auto *src = reinterpret_cast<const uint32x4 *>(
            p.kv + static_cast<size_t>(max(r.idx[st], 0)) * ROW + SEG * (lane / 16));
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            r.raw[st][i] = src[i];
        }
    };
#pragma unroll
    for (int st = 0; st < S; ++st) {
        const int at = m * TOPK + (S * c + st) * CHUNK + wave * TILE + lane % 16;
        if constexpr (!std::is_same_v<Pick, std::nullptr_t>) {
            r.idx[st] = pick(at);
            rows(st);
        } else {
            r.idx[st] = p.indices[at];
        }
    }
    if constexpr (std::is_same_v<Pick, std::nullptr_t>) {
#pragma unroll
        for (int st = 0; st < S; ++st) {
            rows(st);
        }
    }
}

// The token's q_pe, turned, into s.q: thread t takes pair t % 32 of head t / 32
template <bool IN_KERNEL>
__device__ __forceinline__ void turn_q_pe(const MlaCoreParams &p, MlaCoreSmem &s, int m) {
    const int     h   = threadIdx.x / (ROPE / 2);
    const int     i   = threadIdx.x % (ROPE / 2);
    const int64_t pos = p.position[m];
    float         x0, x1;
    load_pair<IN_KERNEL>(p.q, Q_BYTES, (m * HEADS + h) * Q_HEAD + NOPE + 2 * i, x0, x1);
    turn(p, x0, x1, pos, i);
    s.q[h][LATENT + 2 * i]     = static_cast<bfloat16>(x0);
    s.q[h][LATENT + 2 * i + 1] = static_cast<bfloat16>(x1);
}

// This call's tokens' rows into s.fresh as the cache takes them (the cache may not hold them yet): wave w tokens w,
// w + 4, ..'s latent, 8 bf16 a lane from latent(m, lane, out), then k_pe a pair a thread
template <int NUM_TOKENS, bool IN_KERNEL, typename Latent>
__device__ __forceinline__ void fresh_rows(const MlaCoreParams &p, MlaCoreSmem &s, Latent latent) {
    const int tid  = threadIdx.x;
    const int wave = tid / THREADS_PER_WARP;
    const int lane = tid % THREADS_PER_WARP;
#pragma unroll
    for (int k = 0; k < (NUM_TOKENS + WAVES - 1) / WAVES; ++k) {
        const int m = wave + WAVES * k;
        if (m < NUM_TOKENS) {
            bfloat16 lat[8];
            latent(m, lane, lat);
            *reinterpret_cast<uint2 *>(&s.fresh[m][8 * lane]) = to_fp8x8(lat);
        }
    }
    constexpr int PAIRS = NUM_TOKENS * (ROPE / 2);
#pragma unroll
    for (int k = 0; k < (PAIRS + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE; ++k) {
        const int t = tid + Config::BLOCK_SIZE * k;
        if (t < PAIRS) {
            const int mm = t / (ROPE / 2), i = t % (ROPE / 2);
            float     x0, x1;
            load_pair<IN_KERNEL>(p.k_pe, k_pe_bytes<NUM_TOKENS>(p), mm * p.k_pe_stride + 2 * i, x0, x1);
            turn(p, x0, x1, p.position[mm], i);
            *reinterpret_cast<uint16_t *>(&s.fresh[mm][LATENT + 2 * i]) = static_cast<uint16_t>(
                __builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(x0), fp8_finite(x1), 0, false));
        }
    }
}

// token m's q_latent into s.q, written by other XCDs: sc1 loads
__device__ __forceinline__ void stage_q_latent(MlaCoreSmem &s, MlaCoreScratch &x, int m) {
    const int     tid      = threadIdx.x;
    const auto    qb       = raw_buffer(&x.q[m][0][0], HEADS * LATENT * sizeof(bfloat16));
    constexpr int Q_CHUNKS = HEADS * LATENT / 8;
    uint32x4      q_in[Q_CHUNKS / Config::BLOCK_SIZE];
#pragma unroll
    for (int i = 0; i < Q_CHUNKS / Config::BLOCK_SIZE; ++i) {
        q_in[i] = buffer_load_sc1(qb, 16 * (tid + i * Config::BLOCK_SIZE));
    }
#pragma unroll
    for (int i = 0; i < Q_CHUNKS / Config::BLOCK_SIZE; ++i) {
        const int at = tid + i * Config::BLOCK_SIZE; // head at / 64, dims 8 (at % 64) ..
        *reinterpret_cast<uint32x4 *>(&s.q[at / (LATENT / 8)][8 * (at % (LATENT / 8))]) = q_in[i];
    }
}

// A straddling block's next token's q, where its fresh rows were: attend_spanned's caller merges them first
// (merge_fresh), and block 0, which writes them to the cache last, never straddles
using HeadRows = bfloat16[HEADS][ROW];
__device__ __forceinline__ HeadRows &q_hi(MlaCoreSmem &s) {
    static_assert(sizeof(MlaCoreSmem::fresh) == sizeof(HeadRows));
    return *reinterpret_cast<HeadRows *>(s.fresh);
}

// fresh_build's tokens a wave (fresh_rows' k) and k_pe pairs a thread
template <int NUM_TOKENS> constexpr int FRESH_TOKENS = (NUM_TOKENS + WAVES - 1) / WAVES;
template <int NUM_TOKENS>
constexpr int FRESH_PAIRS = (NUM_TOKENS * (ROPE / 2) + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;

// What a block of attend_spanned's reads that no block of the kernel writes, for fresh_build and merge_fresh: the
// rope tables at its k_pe pairs' positions (fresh_rows' pairs) and at tokens m's and m1's (its q_pe pairs, turn_q_pe's
// threads), and the tokens' slots. fresh_tables issues the loads before attend_rows, so they land under its gather.
template <int NUM_TOKENS> struct FreshTables {
    bfloat16 k_cos[FRESH_PAIRS<NUM_TOKENS>], k_sin[FRESH_PAIRS<NUM_TOKENS>];
    bfloat16 q_cos[2], q_sin[2];
    int      slot[NUM_TOKENS];
};

template <int NUM_TOKENS>
__device__ __forceinline__ void fresh_tables(const MlaCoreParams &p, int m, int m1, FreshTables<NUM_TOKENS> &f) {
    const int     tid    = threadIdx.x;
    const int     i      = tid % (ROPE / 2);
    const int64_t pos[2] = {p.position[m], p.position[m1]};
#pragma unroll
    for (int k = 0; k < 2; ++k) {
        f.q_cos[k] = p.cos[pos[k] * (ROPE / 2) + i];
        f.q_sin[k] = p.sin[pos[k] * (ROPE / 2) + i];
    }
#pragma unroll
    for (int k = 0; k < FRESH_PAIRS<NUM_TOKENS>; ++k) {
        // pairs past the tokens' (not built) take the last token's position
        const int64_t pos_k = p.position[min((tid + Config::BLOCK_SIZE * k) / (ROPE / 2), NUM_TOKENS - 1)];
        f.k_cos[k]          = p.cos[pos_k * (ROPE / 2) + i];
        f.k_sin[k]          = p.sin[pos_k * (ROPE / 2) + i];
    }
#pragma unroll
    for (int t = 0; t < NUM_TOKENS; ++t) {
        f.slot[t] = static_cast<int>(p.slot[t]);
    }
}

// fresh_rows, then turn_q_pe of tokens m and m1, as one: every load first (one round trip, the rope tables in f),
// once kv's, k_pe's and q_b's groups are out. A wave's tokens' latent rows are load(t, lane)'s 16 B, then
// norm(raw, out) as fresh_rows' latent; token m's q_pe goes to s.q, token m1's to q1 (attend_spanned's q_hi(s) is
// s.fresh's bytes: the caller stores it there once merge_fresh is done with them, store_q_hi_pe).
template <int NUM_TOKENS, typename Load, typename Norm>
__device__ __forceinline__ void fresh_build(const MlaCoreParams &p, MlaCoreSmem &s, int m, int m1,
                                            const FreshTables<NUM_TOKENS> &f, Load load, Norm norm,
                                            float (&q1)[2]) {
    constexpr int TOKENS = FRESH_TOKENS<NUM_TOKENS>;
    constexpr int PAIRS  = NUM_TOKENS * (ROPE / 2);
    const int     tid    = threadIdx.x;
    const int     wave   = tid / THREADS_PER_WARP;
    const int     lane   = tid % THREADS_PER_WARP;
    const int     h      = tid / (ROPE / 2);
    const int     i      = tid % (ROPE / 2);
    // the loads unconditional (a branch would wait for its load inside), past the tokens the last one's again
    uint32x4 raw[TOKENS];
#pragma unroll
    for (int k = 0; k < TOKENS; ++k) {
        raw[k] = load(min(wave + WAVES * k, NUM_TOKENS - 1), lane);
    }
    float kx[FRESH_PAIRS<NUM_TOKENS>][2];
#pragma unroll
    for (int k = 0; k < FRESH_PAIRS<NUM_TOKENS>; ++k) {
        const int t = min(tid + Config::BLOCK_SIZE * k, PAIRS - 1);
        load_pair<true>(p.k_pe, k_pe_bytes<NUM_TOKENS>(p), t / (ROPE / 2) * p.k_pe_stride + 2 * i, kx[k][0],
                        kx[k][1]);
    }
    float qx[2][2];
    load_pair<true>(p.q, Q_BYTES, (m * HEADS + h) * Q_HEAD + NOPE + 2 * i, qx[0][0], qx[0][1]);
    load_pair<true>(p.q, Q_BYTES, (m1 * HEADS + h) * Q_HEAD + NOPE + 2 * i, qx[1][0], qx[1][1]);
#pragma unroll
    for (int k = 0; k < TOKENS; ++k) {
        if (NUM_TOKENS % WAVES == 0 || wave + WAVES * k < NUM_TOKENS) {
            bfloat16 lat[8];
            norm(raw[k], lat);
            *reinterpret_cast<uint2 *>(&s.fresh[wave + WAVES * k][8 * lane]) = to_fp8x8(lat);
        }
    }
    // every thread stores its pairs, so no branch takes their loads in: those past the tokens' go to rows NUM_TOKENS ..
    // of s.fresh, which nothing reads
    static_assert(FRESH_PAIRS<NUM_TOKENS> * Config::BLOCK_SIZE / (ROPE / 2) <= M_MAX);
#pragma unroll
    for (int k = 0; k < FRESH_PAIRS<NUM_TOKENS>; ++k) {
        const int t = tid + Config::BLOCK_SIZE * k;
        rope_pair(kx[k][0], kx[k][1], f.k_cos[k], f.k_sin[k]);
        *reinterpret_cast<uint16_t *>(&s.fresh[t / (ROPE / 2)][LATENT + 2 * i]) = static_cast<uint16_t>(
            __builtin_amdgcn_cvt_pk_fp8_f32(fp8_finite(kx[k][0]), fp8_finite(kx[k][1]), 0, false));
    }
#pragma unroll
    for (int k = 0; k < 2; ++k) {
        rope_pair(qx[k][0], qx[k][1], f.q_cos[k], f.q_sin[k]);
    }
    s.q[h][LATENT + 2 * i]     = static_cast<bfloat16>(qx[0][0]);
    s.q[h][LATENT + 2 * i + 1] = static_cast<bfloat16>(qx[0][1]);
    q1[0]                      = qx[1][0];
    q1[1]                      = qx[1][1];
}

// fresh_build's q1 into q_hi(s), once every wave is done with s.fresh
__device__ __forceinline__ void store_q_hi_pe(MlaCoreSmem &s, const float (&q1)[2]) {
    const int h                    = threadIdx.x / (ROPE / 2);
    const int i                    = threadIdx.x % (ROPE / 2);
    q_hi(s)[h][LATENT + 2 * i]     = static_cast<bfloat16>(q1[0]);
    q_hi(s)[h][LATENT + 2 * i + 1] = static_cast<bfloat16>(q1[1]);
}

// stage_q_latent of token m and, where hi, of token m + 1 into q_hi(s) (a straddling block's), the loads of both first
__device__ __forceinline__ void stage_q_latents(MlaCoreSmem &s, MlaCoreScratch &x, int m, bool hi) {
    const int     tid      = threadIdx.x;
    constexpr int Q_CHUNKS = HEADS * LATENT / 8;
    constexpr int LOADS    = Q_CHUNKS / Config::BLOCK_SIZE;
    const auto    qb       = raw_buffer(&x.q[m][0][0], 2 * HEADS * LATENT * sizeof(bfloat16));
    uint32x4      q_in[2][LOADS];
#pragma unroll
    for (int k = 0; k < 2; ++k) {
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            q_in[k][i] = buffer_load_sc1(qb, (k && hi ? HEADS * LATENT * sizeof(bfloat16) : 0) +
                                                 16 * (tid + i * Config::BLOCK_SIZE));
        }
    }
#pragma unroll
    for (int i = 0; i < LOADS; ++i) {
        const int at = tid + i * Config::BLOCK_SIZE; // head at / 64, dims 8 (at % 64) ..
        *reinterpret_cast<uint32x4 *>(&s.q[at / (LATENT / 8)][8 * (at % (LATENT / 8))]) = q_in[0][i];
        if (hi) {
            *reinterpret_cast<uint32x4 *>(&q_hi(s)[at / (LATENT / 8)][8 * (at % (LATENT / 8))]) = q_in[1][i];
        }
    }
}

// attend's B operands of q . k in place: the rows of this call's tokens from what the block built (the cache may not
// hold them yet), their slots in f
template <int NUM_TOKENS, int S>
__device__ __forceinline__ void merge_fresh(const FreshTables<NUM_TOKENS> &f, const MlaCoreSmem &s,
                                            AttendRows<S> &r) {
    const int g = threadIdx.x % THREADS_PER_WARP / 16;
#pragma unroll
    for (int st = 0; st < S; ++st) {
        int own = -1; // the call's token whose row this is, if any
#pragma unroll
        for (int t = 0; t < NUM_TOKENS; ++t) {
            own = r.idx[st] == f.slot[t] ? t : own;
        }
        const bool     fresh = own >= 0;
        const uint8_t *built = s.fresh[max(own, 0)] + SEG * g;
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            const uint32x4 b = *reinterpret_cast<const uint32x4 *>(built + 16 * i);
            r.raw[st][i]     = fresh ? b : r.raw[st][i];
        }
    }
}

// The rest of an attending block of token m, its q_pe turned, fresh rows built and q_latent out (the caller waited,
// so a block sync since; Q_STAGED: q_latent already in s.q): attend over its S steps' rows and store the block's
// partial sums in mine (the caller publishes them).
template <int NUM_TOKENS, int S, bool Q_STAGED = false>
__device__ __forceinline__ void attend(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x, int m,
                                       MlaCorePartial &mine, AttendRows<S> &r) {
    // the steps' latents go to LDS V_BUFS at a time, in rounds
    constexpr int ROUNDS    = S > V_BUFS ? S / V_BUFS : 1;
    constexpr int PER_ROUND = S / ROUNDS;
    constexpr int OWN_TILES = DIM_TILES / WAVES;
    static_assert(PER_ROUND * ROUNDS == S && PER_ROUND <= V_BUFS && S <= ATTN_STEPS<M_MAX>);
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int g    = lane / 16;
    const int c    = lane % 16;
    if constexpr (!Q_STAGED) {
        stage_q_latent(s, x, m);
    }
    // the B operands of q . k, rows of this call's tokens from what the block built, in place
#pragma unroll
    for (int st = 0; st < S; ++st) {
        int own = -1; // the call's token whose row this is, if any
#pragma unroll
        for (int t = 0; t < NUM_TOKENS; ++t) {
            own = r.idx[st] == static_cast<int>(p.slot[t]) ? t : own;
        }
        const bool     fresh = own >= 0;
        const uint8_t *built = s.fresh[max(own, 0)] + SEG * g;
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            const uint32x4 b = *reinterpret_cast<const uint32x4 *>(built + 16 * i);
            r.raw[st][i]     = fresh ? b : r.raw[st][i];
        }
    }
    block_sync_lds();
    floatx4 dot[S] = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        // A: q's head c % 8, dims SEG g + 8 i .. + 7 (C's rows past the heads repeat them, unused)
        const auto qa = *reinterpret_cast<const bfloat16x8 *>(&s.q[c % HEADS][SEG * g + 8 * i]);
#pragma unroll
        for (int st = 0; st < S; ++st) {
            const uint32x4 w  = r.raw[st][i / 2];
            const auto     kb = i % 2 ? fp8x8_to_bf16(w[2], w[3]) : fp8x8_to_bf16(w[0], w[1]);
            dot[st]           = __builtin_amdgcn_mfma_f32_16x16x32_bf16(qa, kb, dot[st], 0, 0, 0);
        }
    }
    // step st's latent of row c (this lane's part of it) into LDS as bf16 for p . v
    const auto stage_v = [&](int st) {
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            if (SEG * g + 16 * i < LATENT) {
                const uint32x4 w   = r.raw[st][i];
                auto          *dst = reinterpret_cast<bfloat16x8 *>(&s.v[st % V_BUFS][wave][c][SEG * g + 16 * i]);
                dst[0]             = fp8x8_to_bf16(w[0], w[1]);
                dst[1]             = fp8x8_to_bf16(w[2], w[3]);
            }
        }
    };
#pragma unroll
    for (int st = 0; st < PER_ROUND; ++st) {
        stage_v(st);
    }
    // C: lane (g, c) holds head 4g + e's score of row c of each step's tile. The block's max per head over all its
    // rows first (one LDS round): with every wave's p against it, p . v below splits the dims instead of the rows, so
    // each wave ends with whole sums over all the steps and no partials need merging through LDS
    float score[S][4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        float top = -__builtin_inff();
#pragma unroll
        for (int st = 0; st < S; ++st) {
            score[st][e] = r.idx[st] >= 0 ? dot[st][e] * p.qk_scale : -__builtin_inff();
            top          = fmaxf(top, score[st][e]);
        }
        top = WarpReduce<MaxOp, float, 16>(top);
        if (g < 2 && c == 0) {
            s.max[wave][4 * g + e] = top;
        }
    }
    block_sync_lds();
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        const int   h    = (4 * g + e) % HEADS; // lanes g >= 2 hold copies, dropped below
        const float best = fmaxf(fmaxf(s.max[0][h], s.max[1][h]), fmaxf(s.max[2][h], s.max[3][h]));
        float       part = 0.0f;
#pragma unroll
        for (int st = 0; st < S; ++st) {
            const float prob = r.idx[st] >= 0 ? exp2f(score[st][e] - best) : 0.0f;
            part += prob;
            if (g < 2) {
                s.p[st][wave][4 * g + e][c] = static_cast<bfloat16>(prob);
            }
        }
        const float total = WarpReduce<SumOp, float, 16>(part);
        if (g < 2 && c == 0) {
            s.sum[wave][4 * g + e] = total;
        }
    }
    block_sync_lds();
    // (p . v)^T = v^T p^T over every step's 4 tiles' rows, this wave's 128 dims: A = tile t's rows 4g + j, dims
    // 128 wave + 16 d + 4q .. read transposed so lane (g, i) gets that dim of rows 4g .. 4g + 3; B = p of head c
    // (zero past the real heads) over tile t's rows
    floatx4 acc[OWN_TILES] = {};
#pragma unroll
    for (int k = 0; k < ROUNDS; ++k) {
        if (k > 0) {
            block_sync_lds(); // every wave done with the last round's latents
#pragma unroll
            for (int st = PER_ROUND * k; st < PER_ROUND * (k + 1); ++st) {
                stage_v(st);
            }
            block_sync_lds();
        }
#pragma unroll
        for (int st = PER_ROUND * k; st < PER_ROUND * (k + 1); ++st) {
            bfloat16x4 pa[WAVES] = {};
            if (c < HEADS) {
#pragma unroll
                for (int t = 0; t < WAVES; ++t) {
                    pa[t] = *reinterpret_cast<const bfloat16x4 *>(&s.p[st][t][c][4 * g]);
                }
            }
#pragma unroll
            for (int t = 0; t < WAVES; ++t) {
                const bfloat16 *vt = &s.v[st % V_BUFS][t][4 * g + c / 4][c % 4 * 4] + LATENT / WAVES * wave;
#pragma unroll
                for (int d = 0; d < OWN_TILES; ++d) {
                    // an LDS pointer: generic to address space 3 takes a C-style cast
                    const bfloat16x4 vb = __builtin_amdgcn_ds_read_tr16_b64_v4bf16(
                        (__attribute__((address_space(3))) bfloat16x4 *)(vt + 16 * d));
                    acc[d] = __builtin_amdgcn_mfma_f32_16x16x16bf16_1k(vb, pa[t], acc[d], 0, 0, 0);
                }
            }
        }
    }
    // C lane (g, c) holds head c's dims 128 wave + 16 d + 4g .. + 3 of the block's partial
    if (c < HEADS) {
#pragma unroll
        for (int d = 0; d < OWN_TILES; ++d) {
            const bfloat16x4 o = {static_cast<bfloat16>(acc[d][0]), static_cast<bfloat16>(acc[d][1]),
                                  static_cast<bfloat16>(acc[d][2]), static_cast<bfloat16>(acc[d][3])};
            store_sc1(reinterpret_cast<uint2 *>(&mine.out[c][LATENT / WAVES * wave + 16 * d + 4 * g]),
                      __builtin_bit_cast(uint2, o));
        }
    }
    if (tid < HEADS) {
        const float best = fmaxf(fmaxf(s.max[0][tid], s.max[1][tid]), fmaxf(s.max[2][tid], s.max[3][tid]));
        const float sum  = s.sum[0][tid] + s.sum[1][tid] + s.sum[2][tid] + s.sum[3][tid];
        store_sc1(reinterpret_cast<uint32x4 *>(&mine.stats[tid]),
                  __builtin_bit_cast(uint32x4, floatx4{best, sum, 0.0f, 0.0f}));
    }
}

template <int NUM_TOKENS, int S, bool Q_STAGED = false>
__device__ __forceinline__ void attend_c(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x, int m,
                                       MlaCorePartial &mine, AttendRows<S> &r) {
    // the steps' latents go to LDS V_BUFS at a time, in rounds
    constexpr int ROUNDS    = S > V_BUFS ? S / V_BUFS : 1;
    constexpr int PER_ROUND = S / ROUNDS;
    constexpr int OWN_TILES = DIM_TILES / WAVES;
    static_assert(PER_ROUND * ROUNDS == S && PER_ROUND <= V_BUFS && S <= ATTN_STEPS<M_MAX>);
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int g    = lane / 16;
    const int c    = lane % 16;
    if constexpr (!Q_STAGED) {
        stage_q_latent(s, x, m);
    }
    // the B operands of q . k, rows of this call's tokens from what the block built, in place
#pragma unroll
    for (int st = 0; st < S; ++st) {
        int own = -1; // the call's token whose row this is, if any
#pragma unroll
        for (int t = 0; t < NUM_TOKENS; ++t) {
            own = r.idx[st] == static_cast<int>(p.slot[t]) ? t : own;
        }
        const bool     fresh = own >= 0;
        const uint8_t *built = s.fresh[max(own, 0)] + SEG * g;
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            const uint32x4 b = *reinterpret_cast<const uint32x4 *>(built + 16 * i);
            r.raw[st][i]     = fresh ? b : r.raw[st][i];
        }
    }
    block_sync_lds();
    floatx4 dot[S] = {};
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        // A: q's head c % 8, dims SEG g + 8 i .. + 7 (C's rows past the heads repeat them, unused)
        const auto qa = *reinterpret_cast<const bfloat16x8 *>(&s.q[c % HEADS][SEG * g + 8 * i]);
#pragma unroll
        for (int st = 0; st < S; ++st) {
            const uint32x4 w  = r.raw[st][i / 2];
            const auto     kb = i % 2 ? fp8x8_to_bf16(w[2], w[3]) : fp8x8_to_bf16(w[0], w[1]);
            dot[st]           = __builtin_amdgcn_mfma_f32_16x16x32_bf16(qa, kb, dot[st], 0, 0, 0);
        }
    }
    // step st's latent of row c (this lane's part of it) into LDS as bf16 for p . v
    const auto stage_v = [&](int st) {
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            if (SEG * g + 16 * i < LATENT) {
                const uint32x4 w   = r.raw[st][i];
                auto          *dst = reinterpret_cast<bfloat16x8 *>(&s.v[st % V_BUFS][wave][c][SEG * g + 16 * i]);
                dst[0]             = fp8x8_to_bf16(w[0], w[1]);
                dst[1]             = fp8x8_to_bf16(w[2], w[3]);
            }
        }
    };
#pragma unroll
    for (int st = 0; st < PER_ROUND; ++st) {
        stage_v(st);
    }
    // C: lane (g, c) holds head 4g + e's score of row c of each step's tile. The block's max per head over all its
    // rows first (one LDS round): with every wave's p against it, p . v below splits the dims instead of the rows, so
    // each wave ends with whole sums over all the steps and no partials need merging through LDS
    // the four heads' reductions side by side, each lane's 4 maxima and sums as one LDS access, exp2f and the p
    // stores without a branch (c2m12 r6): lanes g >= 2 hold copies of lanes g - 2's (q's tile repeats its heads),
    // which store the same values at the same places
    float score[S][4], top[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        top[e] = -__builtin_inff();
#pragma unroll
        for (int st = 0; st < S; ++st) {
            score[st][e] = r.idx[st] >= 0 ? dot[st][e] * p.qk_scale : -__builtin_inff();
            top[e]       = fmaxf(top[e], score[st][e]);
        }
    }
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        top[e] = WarpReduce<MaxOp, float, 16>(top[e]);
    }
    if (c == 0) {
        *reinterpret_cast<floatx4 *>(&s.max[wave][4 * (g % 2)]) = floatx4{top[0], top[1], top[2], top[3]};
    }
    block_sync_lds();
    floatx4 tops[WAVES];
#pragma unroll
    for (int w = 0; w < WAVES; ++w) {
        tops[w] = *reinterpret_cast<const floatx4 *>(&s.max[w][4 * (g % 2)]);
    }
    float part[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        const float best = fmaxf(fmaxf(tops[0][e], tops[1][e]), fmaxf(tops[2][e], tops[3][e]));
        part[e]          = 0.0f;
#pragma unroll
        for (int st = 0; st < S; ++st) {
            // exp2f(-inf) is +0, an invalid row's probability; a valid row's best is finite
            const float prob = exp2f(r.idx[st] >= 0 ? score[st][e] - best : -__builtin_inff());
            part[e] += prob;
            s.p[st][wave][4 * (g % 2) + e][c] = static_cast<bfloat16>(prob);
        }
    }
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        part[e] = WarpReduce<SumOp, float, 16>(part[e]);
    }
    if (c == 0) {
        *reinterpret_cast<floatx4 *>(&s.sum[wave][4 * (g % 2)]) = floatx4{part[0], part[1], part[2], part[3]};
    }
    block_sync_lds();
    // (p . v)^T = v^T p^T over every step's 4 tiles' rows, this wave's 128 dims: A = tile t's rows 4g + j, dims
    // 128 wave + 16 d + 4q .. read transposed so lane (g, i) gets that dim of rows 4g .. 4g + 3; B = p of head c
    // (zero past the real heads) over tile t's rows
    floatx4 acc[OWN_TILES] = {};
#pragma unroll
    for (int k = 0; k < ROUNDS; ++k) {
        if (k > 0) {
            block_sync_lds(); // every wave done with the last round's latents
#pragma unroll
            for (int st = PER_ROUND * k; st < PER_ROUND * (k + 1); ++st) {
                stage_v(st);
            }
            block_sync_lds();
        }
#pragma unroll
        for (int st = PER_ROUND * k; st < PER_ROUND * (k + 1); ++st) {
            bfloat16x4 pa[WAVES] = {};
            if (c < HEADS) {
#pragma unroll
                for (int t = 0; t < WAVES; ++t) {
                    pa[t] = *reinterpret_cast<const bfloat16x4 *>(&s.p[st][t][c][4 * g]);
                }
            }
#pragma unroll
            for (int t = 0; t < WAVES; ++t) {
                const bfloat16 *vt = &s.v[st % V_BUFS][t][4 * g + c / 4][c % 4 * 4] + LATENT / WAVES * wave;
#pragma unroll
                for (int d = 0; d < OWN_TILES; ++d) {
                    // an LDS pointer: generic to address space 3 takes a C-style cast
                    const bfloat16x4 vb = __builtin_amdgcn_ds_read_tr16_b64_v4bf16(
                        (__attribute__((address_space(3))) bfloat16x4 *)(vt + 16 * d));
                    acc[d] = __builtin_amdgcn_mfma_f32_16x16x16bf16_1k(vb, pa[t], acc[d], 0, 0, 0);
                }
            }
        }
    }
    // C lane (g, c) holds head c's dims 128 wave + 16 d + 4g .. + 3 of the block's partial. sc1 stores are written
    // through to memory, where lines written in parts cost far more than whole ones, so the wave's rows go out through
    // LDS (in s.q: q . k, its last reader, is done), 16 lanes x 16 B a head's 256 B (c2m12 r7)
    constexpr int O_STRIDE = LATENT / WAVES + 16; // a head's dims of the wave, rows 8 banks apart
    static_assert(WAVES * HEADS * O_STRIDE * sizeof(bfloat16) <= sizeof(MlaCoreSmem::q));
    bfloat16 *const rows = &s.q[0][0] + HEADS * O_STRIDE * wave;
    if (c < HEADS) {
        bfloat16 *const row = rows + c * O_STRIDE + 4 * g;
#pragma unroll
        for (int d = 0; d < OWN_TILES; ++d) {
            *reinterpret_cast<bfloat16x4 *>(row + 16 * d) =
                bfloat16x4{static_cast<bfloat16>(acc[d][0]), static_cast<bfloat16>(acc[d][1]),
                           static_cast<bfloat16>(acc[d][2]), static_cast<bfloat16>(acc[d][3])};
        }
    }
    // the lanes read each other's writes: LDS keeps a wave's accesses in order, the fence keeps the compiler from
    // moving them; every read before the first store (each asm store is a compiler barrier)
    __builtin_amdgcn_fence(__ATOMIC_ACQ_REL, "wavefront");
    uint32x4 out_rows[2];
#pragma unroll
    for (int k = 0; k < 2; ++k) {
        out_rows[k] = *reinterpret_cast<const uint32x4 *>(rows + (4 * k + g) * O_STRIDE + 8 * c);
    }
#pragma unroll
    for (int k = 0; k < 2; ++k) {
        store_sc1(reinterpret_cast<uint32x4 *>(&mine.out[4 * k + g][LATENT / WAVES * wave + 8 * c]), out_rows[k]);
    }
    if (tid < HEADS) {
        const float best = fmaxf(fmaxf(s.max[0][tid], s.max[1][tid]), fmaxf(s.max[2][tid], s.max[3][tid]));
        const float sum  = s.sum[0][tid] + s.sum[1][tid] + s.sum[2][tid] + s.sum[3][tid];
        store_sc1(reinterpret_cast<uint32x4 *>(&mine.stats[tid]),
                  __builtin_bit_cast(uint32x4, floatx4{best, sum, 0.0f, 0.0f}));
    }
}

// attend for a block of the tokens' rows as one list (SPANS<S>), its fresh rows already merged (merge_fresh): token
// m's steps and, from hi_from on where hi_from < S (it straddles), token m + 1's. That token's q goes to q_hi(s) (its
// q_pe turned there by the caller, store_q_hi_pe), q . k's A rows and p . v's B columns 8 .. 15 (copies or zeros in
// attend) take it, and its partial sums go to mine_hi.
template <int NUM_TOKENS, int S>
__device__ __forceinline__ void attend_spanned(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x, int m,
                                               MlaCorePartial &mine, MlaCorePartial &mine_hi, AttendRows<S> &r,
                                               int hi_from) {
    // the steps' latents go to LDS V_BUFS at a time, in rounds (the last one may take fewer)
    constexpr int ROUNDS    = (S + V_BUFS - 1) / V_BUFS;
    constexpr int PER_ROUND = (S + ROUNDS - 1) / ROUNDS;
    constexpr int OWN_TILES = DIM_TILES / WAVES;
    static_assert(SPANS<S> && PER_ROUND <= V_BUFS && S < ATTN_STEPS<M_MAX>);
    const int  tid  = threadIdx.x;
    const int  lane = tid % THREADS_PER_WARP;
    const int  wave = tid / THREADS_PER_WARP;
    const int  g    = lane / 16;
    const int  c    = lane % 16;
    const bool hi   = hi_from < S;
    // step st's rows are token m + 1's
    const auto next = [&](int st) { return st >= hi_from; };
    stage_q_latents(s, x, m, hi);
    block_sync_lds();
    floatx4 dot[S] = {};
    // A: q's head c % 8 (C's rows past the heads repeat them, unused; straddling: token m + 1's heads)
    const bfloat16 *q_row = hi && c >= HEADS ? q_hi(s)[c - HEADS] : s.q[c % HEADS];
#pragma unroll
    for (int i = 0; i < STEPS; ++i) {
        // A's dims SEG g + 8 i .. + 7
        const auto qa = *reinterpret_cast<const bfloat16x8 *>(q_row + SEG * g + 8 * i);
#pragma unroll
        for (int st = 0; st < S; ++st) {
            const uint32x4 w  = r.raw[st][i / 2];
            const auto     kb = i % 2 ? fp8x8_to_bf16(w[2], w[3]) : fp8x8_to_bf16(w[0], w[1]);
            dot[st]           = __builtin_amdgcn_mfma_f32_16x16x32_bf16(qa, kb, dot[st], 0, 0, 0);
        }
    }
    // step st's latent of row c (this lane's part of it) into LDS as bf16 for p . v
    const auto stage_v = [&](int st) {
#pragma unroll
        for (int i = 0; i < SEG / 16; ++i) {
            if (SEG * g + 16 * i < LATENT) {
                const uint32x4 w   = r.raw[st][i];
                auto          *dst = reinterpret_cast<bfloat16x8 *>(&s.v[st % V_BUFS][wave][c][SEG * g + 16 * i]);
                dst[0]             = fp8x8_to_bf16(w[0], w[1]);
                dst[1]             = fp8x8_to_bf16(w[2], w[3]);
            }
        }
    };
#pragma unroll
    for (int st = 0; st < PER_ROUND; ++st) {
        stage_v(st);
    }
    // C: lane (g, c) holds head 4g + e's score of row c of each step's tile: lanes g < 2 token m's heads, which count
    // only on its steps, lanes g >= 2 token m + 1's, on its steps. The block's max per head first, as attend's. The
    // four heads' reductions run side by side, each lane's 4 maxima and sums move as one LDS access, and neither
    // exp2f nor the p stores sit in a branch
    float score[S][4];
    float top[4];
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        top[e] = -__builtin_inff();
#pragma unroll
        for (int st = 0; st < S; ++st) {
            const bool valid = r.idx[st] >= 0 && (g >= 2) == next(st);
            score[st][e]     = valid ? dot[st][e] * p.qk_scale : -__builtin_inff();
            top[e]           = fmaxf(top[e], score[st][e]);
        }
    }
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        top[e] = WarpReduce<MaxOp, float, 16>(top[e]);
    }
    if (c == 0) {
        *reinterpret_cast<floatx4 *>(&s.max_span[wave][4 * g]) = floatx4{top[0], top[1], top[2], top[3]};
    }
    block_sync_lds();
    floatx4 tops[WAVES];
#pragma unroll
    for (int w = 0; w < WAVES; ++w) {
        tops[w] = *reinterpret_cast<const floatx4 *>(&s.max_span[w][4 * g]);
    }
    float part[4] = {};
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        const float best = fmaxf(fmaxf(tops[0][e], tops[1][e]), fmaxf(tops[2][e], tops[3][e]));
#pragma unroll
        for (int st = 0; st < S; ++st) {
            const bool valid = r.idx[st] >= 0 && (g >= 2) == next(st);
            // exp2f(-inf) is +0, the invalid rows' probability; a valid row's best is finite
            const float prob = exp2f(valid ? score[st][e] - best : -__builtin_inff());
            part[e] += prob;
            // the other token's lanes store to step slot S, which p . v never reads
            s.p[(g >= 2) == next(st) ? st : S][wave][(4 * g + e) % HEADS][c] = static_cast<bfloat16>(prob);
        }
    }
#pragma unroll
    for (int e = 0; e < 4; ++e) {
        part[e] = WarpReduce<SumOp, float, 16>(part[e]);
    }
    if (c == 0) {
        *reinterpret_cast<floatx4 *>(&s.sum_span[wave][4 * g]) = floatx4{part[0], part[1], part[2], part[3]};
    }
    block_sync_lds();
    // (p . v)^T as attend's; B columns 8 .. 15 token m + 1's heads, each half zero on the other token's steps
    floatx4 acc[OWN_TILES] = {};
#pragma unroll
    for (int k = 0; k < ROUNDS; ++k) {
        if (k > 0) {
            block_sync_lds(); // every wave done with the last round's latents
#pragma unroll
            for (int st = PER_ROUND * k; st < S && st < PER_ROUND * (k + 1); ++st) {
                stage_v(st);
            }
            block_sync_lds();
        }
#pragma unroll
        for (int st = PER_ROUND * k; st < S && st < PER_ROUND * (k + 1); ++st) {
            bfloat16x4 pa[WAVES] = {};
            if ((c >= HEADS) == next(st)) {
#pragma unroll
                for (int t = 0; t < WAVES; ++t) {
                    pa[t] = *reinterpret_cast<const bfloat16x4 *>(&s.p[st][t][c % HEADS][4 * g]);
                }
            }
#pragma unroll
            for (int t = 0; t < WAVES; ++t) {
                const bfloat16 *vt = &s.v[st % V_BUFS][t][4 * g + c / 4][c % 4 * 4] + LATENT / WAVES * wave;
#pragma unroll
                for (int d = 0; d < OWN_TILES; ++d) {
                    // an LDS pointer: generic to address space 3 takes a C-style cast
                    const bfloat16x4 vb = __builtin_amdgcn_ds_read_tr16_b64_v4bf16(
                        (__attribute__((address_space(3))) bfloat16x4 *)(vt + 16 * d));
                    acc[d] = __builtin_amdgcn_mfma_f32_16x16x16bf16_1k(vb, pa[t], acc[d], 0, 0, 0);
                }
            }
        }
    }
    // C lane (g, c) holds head c's dims 128 wave + 16 d + 4g .. + 3 of the block's partial (straddling: c >= 8 head
    // c - 8's of token m + 1's). The sc1 stores are written through to memory, where lines written in parts cost far
    // more than whole ones, so the wave's rows go out through LDS: token m's heads in s.q, token m + 1's in s.fresh
    // (q . k, their last reader, is done; block 0, which reads s.fresh after this, never straddles)
    constexpr int O_STRIDE = LATENT / WAVES + 16; // a head's dims of the wave, rows 8 banks apart
    static_assert(WAVES * HEADS * O_STRIDE * sizeof(bfloat16) == sizeof(MlaCoreSmem::q) &&
                  sizeof(MlaCoreSmem::q) == sizeof(MlaCoreSmem::fresh));
    bfloat16 *const rows_lo = &s.q[0][0] + HEADS * O_STRIDE * wave;
    bfloat16 *const rows_hi = reinterpret_cast<bfloat16 *>(s.fresh) + HEADS * O_STRIDE * wave;
    if (c < HEADS || hi) {
        bfloat16 *const row = (c >= HEADS ? rows_hi : rows_lo) + c % HEADS * O_STRIDE + 4 * g;
#pragma unroll
        for (int d = 0; d < OWN_TILES; ++d) {
            *reinterpret_cast<bfloat16x4 *>(row + 16 * d) =
                bfloat16x4{static_cast<bfloat16>(acc[d][0]), static_cast<bfloat16>(acc[d][1]),
                           static_cast<bfloat16>(acc[d][2]), static_cast<bfloat16>(acc[d][3])};
        }
    }
    // the lanes read each other's writes: LDS keeps a wave's accesses in order, the fence keeps the compiler from
    // moving them
    __builtin_amdgcn_fence(__ATOMIC_ACQ_REL, "wavefront");
    // lane (g, c) stores dims 8c .. 8c + 7 of head 4 (k % 2) + g, so 16 lanes write a head's 256 B (k >= 2: token
    // m + 1's); every read first, as each store is a compiler barrier
    uint32x4 out_rows[4];
#pragma unroll
    for (int k = 0; k < 4; ++k) {
        const bfloat16 *row = (k < 2 ? rows_lo : rows_hi) + (4 * (k % 2) + g) * O_STRIDE;
        out_rows[k]         = *reinterpret_cast<const uint32x4 *>(row + 8 * c);
    }
#pragma unroll
    for (int k = 0; k < 4; ++k) {
        if (k < 2 || hi) {
            MlaCorePartial &out = k < 2 ? mine : mine_hi;
            store_sc1(reinterpret_cast<uint32x4 *>(&out.out[4 * (k % 2) + g][LATENT / WAVES * wave + 8 * c]),
                      out_rows[k]);
        }
    }
    if (tid < HEADS || (hi && tid < 2 * HEADS)) {
        const float best = fmaxf(fmaxf(s.max_span[0][tid], s.max_span[1][tid]),
                                 fmaxf(s.max_span[2][tid], s.max_span[3][tid]));
        const float     sum = s.sum_span[0][tid] + s.sum_span[1][tid] + s.sum_span[2][tid] + s.sum_span[3][tid];
        MlaCorePartial &out = tid >= HEADS ? mine_hi : mine;
        store_sc1(reinterpret_cast<uint32x4 *>(&out.stats[tid % HEADS]),
                  __builtin_bit_cast(uint32x4, floatx4{best, sum, 0.0f, 0.0f}));
    }
}

// Projecting block AD_FIRST + j, waves 0 and 1: q_latent = q_nope W_UK, group 2j + wave (16 rows of head group / 32,
// the tokens the columns), into x.q with sc1. BF16: W_UK bf16, without a scale.
template <int NUM_TOKENS, bool IN_KERNEL, bool BF16 = false>
__device__ __forceinline__ void project_q(const MlaCoreParams &p, MlaCoreScratch &x, int j) {
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int g    = lane / 16;
    const int c    = lane % 16;
    if (wave < 2) {
        const int group = 2 * j + wave;
        const int h     = group / Q_GROUPS;
        const int rows  = group % Q_GROUPS;
        // W_UK^T times token c's q_nope of head h (columns past M repeat token M - 1)
        const floatx4 acc = head_product<NOPE, LATENT, IN_KERNEL, BF16>(
            p.w_k, p.q, (min(c, NUM_TOKENS - 1) * HEADS + h) * Q_HEAD, h, rows, Q_BYTES);
        // C: lane (g, c) holds rows 4g .. 4g + 3 of the group for token c
        if (c < NUM_TOKENS) {
            const float scale = BF16 ? 1.0f : *p.w_k_scale;
            bfloat16    out[4];
#pragma unroll
            for (int r = 0; r < 4; ++r) {
                out[r] = static_cast<bfloat16>(acc[r] * scale);
            }
            store_sc1(reinterpret_cast<uint2 *>(&x.q[c][h][16 * rows + 4 * g]),
                      *reinterpret_cast<const uint2 *>(out));
        }
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
    }
}

// project_q in two steps, so that W_UK's loads go out before the wait for q_b's groups: its group's rows of W_UK
// (waves 0 and 1: head_product's w, only issued), then q_nope's loads and the MFMAs as head_product's
template <bool BF16> constexpr int WK_LOADS = BF16 ? NOPE / 4 / 8 : NOPE / 4 / 16;

template <bool BF16>
__device__ __forceinline__ void project_q_weights(const MlaCoreParams &p, int j, uint32x4 (&wv)[WK_LOADS<BF16>]) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    const int wave = threadIdx.x / THREADS_PER_WARP;
    if (wave < 2) {
        const int      group = 2 * j + wave;
        const int      h     = group / Q_GROUPS;
        const int      rows  = group % Q_GROUPS;
        const uint8_t *w_row = p.w_k + ((static_cast<size_t>(h) * LATENT + 16 * rows + lane % 16) * NOPE +
                                        NOPE / 4 * (lane / 16)) * (BF16 ? 2 : 1);
#pragma unroll
        for (int i = 0; i < WK_LOADS<BF16>; ++i) {
            wv[i] = reinterpret_cast<const uint32x4 *>(w_row)[i];
        }
    }
}

template <int NUM_TOKENS, bool IN_KERNEL, bool BF16 = false>
__device__ __forceinline__ void project_q_w(const MlaCoreParams &p, MlaCoreScratch &x, int j,
                                            const uint32x4 (&wv)[WK_LOADS<BF16>]) {
    constexpr int K_SEG   = NOPE / 4;
    constexpr int K_STEPS = K_SEG / 8;
    const int     tid     = threadIdx.x;
    const int     lane    = tid % THREADS_PER_WARP;
    const int     wave    = tid / THREADS_PER_WARP;
    const int     g       = lane / 16;
    const int     c       = lane % 16;
    if (wave < 2) {
        const int group = 2 * j + wave;
        const int h     = group / Q_GROUPS;
        const int rows  = group % Q_GROUPS;
        // W_UK^T times token c's q_nope of head h (columns past M repeat token M - 1), as head_product
        const int  at = (min(c, NUM_TOKENS - 1) * HEADS + h) * Q_HEAD;
        bfloat16x8 xv[K_STEPS];
#pragma unroll
        for (int i = 0; i < K_STEPS; ++i) {
            load8<IN_KERNEL>(p.q, Q_BYTES, at + K_SEG * g + 8 * i, xv[i]);
        }
        floatx4 acc = {};
#pragma unroll
        for (int i = 0; i < K_STEPS; ++i) {
            bfloat16x8 a;
            if constexpr (BF16) {
                a = __builtin_bit_cast(bfloat16x8, wv[i]);
            } else {
                const uint32x4 wi = wv[i / 2];
                a = i % 2 ? fp8x8_to_bf16(wi[2], wi[3]) : fp8x8_to_bf16(wi[0], wi[1]);
            }
            acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(a, xv[i], acc, 0, 0, 0);
        }
        // C: lane (g, c) holds rows 4g .. 4g + 3 of the group for token c
        if (c < NUM_TOKENS) {
            const float scale = BF16 ? 1.0f : *p.w_k_scale;
            bfloat16    out[4];
#pragma unroll
            for (int r = 0; r < 4; ++r) {
                out[r] = static_cast<bfloat16>(acc[r] * scale);
            }
            store_sc1(reinterpret_cast<uint2 *>(&x.q[c][h][16 * rows + 4 * g]), *reinterpret_cast<const uint2 *>(out));
        }
        // the stores above are asm, which the compiler does not count: wait for them explicitly
        asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
    }
}

// The KV rows of this call's tokens into the cache from s.fresh (nobody in the kernel waits for them)
template <int NUM_TOKENS>
__device__ __forceinline__ void write_fresh(const MlaCoreParams &p, const MlaCoreSmem &s) {
    constexpr int CHUNKS_ALL = NUM_TOKENS * ROW_CHUNKS;
#pragma unroll
    for (int k = 0; k < (CHUNKS_ALL + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE; ++k) {
        const int t = threadIdx.x + Config::BLOCK_SIZE * k;
        if (t < CHUNKS_ALL) {
            const int m = t / ROW_CHUNKS, i = t % ROW_CHUNKS;
            *reinterpret_cast<uint32x4 *>(p.kv + static_cast<size_t>(p.slot[m]) * ROW + 16 * i) =
                *reinterpret_cast<const uint32x4 *>(&s.fresh[m][16 * i]);
        }
    }
}

// Projecting block AD_FIRST + u, u < UNITS, once token m's partial sums are out (packet partial_packet of its
// attending blocks, TOKEN_BLOCKS from m TOKEN_BLOCKS): o_latent's dims d0 .. d0 + UNIT_DIMS - 1 of head h of token m
// (u = SPLIT (HEADS m + h) + d0 / UNIT_DIMS) from the partials, each weighted by exp2(max - top) / the sum over the
// token's; out in bf16 as packets of 4 values and the epoch (p.latent_tagged) for wuv_unit.
template <int NUM_TOKENS>
__device__ __forceinline__ void combine_unit(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x, int u,
                                             const uint32x4 *slots, uint32_t epoch, int partial_packet) {
    constexpr int B      = TOKEN_BLOCKS<NUM_TOKENS>;
    constexpr int D      = UNIT_DIMS<NUM_TOKENS>;
    constexpr int ROW_CH = D / 8; // 16 B chunks of a partial's dims
    constexpr int LOADS  = B * ROW_CH / Config::BLOCK_SIZE;
    static_assert(LOADS * Config::BLOCK_SIZE == B * ROW_CH && B <= THREADS_PER_WARP && B <= CHUNKS &&
                  THREADS_PER_WARP % ROW_CH == 0 && UNITS<NUM_TOKENS> <= PROJECTING);
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int m    = u / (HEADS * SPLIT<NUM_TOKENS>);
    const int h    = u / SPLIT<NUM_TOKENS> % HEADS;
    const int d0   = u % SPLIT<NUM_TOKENS> * D;
    wait_for(slots, partial_packet, m * B, B, epoch);
    // thread t < B: partial t's stats; load k: chunk q = t + BLOCK_SIZE k, partial q / ROW_CH's dims d0 + 8 (q %
    // ROW_CH) .. + 7 (the lanes ROW_CH apart holding the same dims)
    const auto buf    = raw_buffer(&x.partial[m * B], B * sizeof(MlaCorePartial));
    float      st_max = -__builtin_inff(), st_sum = 0.0f;
    if (tid < B) {
        const floatx4 st = __builtin_bit_cast(
            floatx4, buffer_load_sc1(buf, tid * sizeof(MlaCorePartial) + offsetof(MlaCorePartial, stats) +
                                              sizeof(floatx4) * h));
        st_max = st[0];
        st_sum = st[1];
    }
    uint32x4 outs[LOADS];
#pragma unroll
    for (int k = 0; k < LOADS; ++k) {
        const int q = tid + Config::BLOCK_SIZE * k;
        outs[k]     = buffer_load_sc1(buf, q / ROW_CH * sizeof(MlaCorePartial) + offsetof(MlaCorePartial, out) +
                                           (h * LATENT + d0 + 8 * (q % ROW_CH)) * sizeof(bfloat16));
    }
    // wave 0 holds the stats: each partial's weight against the top max
    const float top    = WarpReduce<MaxOp>(st_max);
    const float weight = st_max == -__builtin_inff() ? 0.0f : exp2f(st_max - top);
    const float total  = WarpReduce<SumOp>(weight * st_sum);
    if (tid < B) {
        s.scale[tid] = total > 0.0f ? weight / total : 0.0f;
    }
    block_sync_lds();
    float o[8] = {};
#pragma unroll
    for (int k = 0; k < LOADS; ++k) {
        const float w = s.scale[(tid + Config::BLOCK_SIZE * k) / ROW_CH];
        bfloat16    v[8];
        __builtin_memcpy(v, &outs[k], 16);
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            o[e] += w * static_cast<float>(v[e]);
        }
    }
#pragma unroll
    for (int off = ROW_CH; off < THREADS_PER_WARP; off <<= 1) {
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            o[e] += __shfl_xor(o[e], off);
        }
    }
    if (lane < ROW_CH) {
        *reinterpret_cast<floatx4 *>(&s.osum[wave][8 * lane])     = floatx4{o[0], o[1], o[2], o[3]};
        *reinterpret_cast<floatx4 *>(&s.osum[wave][8 * lane + 4]) = floatx4{o[4], o[5], o[6], o[7]};
    }
    block_sync_lds();
    // the waves' sums in wave order, then lane 4i packs dims 4i .. 4i + 3
#pragma unroll
    for (int k = 0; k < (D + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE; ++k) {
        const int d   = tid + Config::BLOCK_SIZE * k;
        float     sum = 0.0f;
        if (d < D) {
#pragma unroll
            for (int w = 0; w < WAVES; ++w) {
                sum += s.osum[w][d];
            }
        }
        const uint32_t v0 = __builtin_bit_cast(uint16_t, static_cast<bfloat16>(sum));
        const uint32_t v1 = __shfl_down(v0, 1), v2 = __shfl_down(v0, 2), v3 = __shfl_down(v0, 3);
        if (d < D && d % 4 == 0) {
            store_sc1(p.latent_tagged + ((m * HEADS + h) * LATENT + d0 + d) / 4,
                      uint32x4{v0 | v1 << 16, v2 | v3 << 16, 0u, epoch});
        }
    }
}

// combine_unit for attend_spanned's partials (SPANS<S>): token m's from the blocks its rows touch, first .. first +
// count - 1 (up to SPAN_BLOCKS), the first one's in partial_hi where it straddles into m
template <int NUM_TOKENS, int S>
__device__ __forceinline__ void combine_unit_spanned(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x,
                                                     int u, const uint32x4 *slots, uint32_t epoch,
                                                     int partial_packet) {
    constexpr int B      = SPAN_BLOCKS<S>; // partials a token's, at most
    constexpr int D      = UNIT_DIMS<NUM_TOKENS>;
    constexpr int ROW_CH = D / 8; // 16 B chunks of a partial's dims
    constexpr int LOADS  = B * ROW_CH / Config::BLOCK_SIZE;
    static_assert(SPANS<S> && LOADS * Config::BLOCK_SIZE == B * ROW_CH && B <= THREADS_PER_WARP && B <= CHUNKS &&
                  THREADS_PER_WARP % ROW_CH == 0 && UNITS<NUM_TOKENS> <= PROJECTING);
    const int  tid      = threadIdx.x;
    const int  lane     = tid % THREADS_PER_WARP;
    const int  wave     = tid / THREADS_PER_WARP;
    const int  m        = u / (HEADS * SPLIT<NUM_TOKENS>);
    const int  h        = u / SPLIT<NUM_TOKENS> % HEADS;
    const int  d0       = u % SPLIT<NUM_TOKENS> * D;
    const int  first    = CHUNKS * m / S;
    const int  count    = (CHUNKS * m + CHUNKS - 1) / S - first + 1;
    const bool hi_first = S * first < CHUNKS * m;
    wait_for(slots, partial_packet, first, count, epoch);
    // as combine_unit's, partial k past count the token's last again, weighted 0
    const auto buf = raw_buffer(&x, sizeof(MlaCoreScratch));
    const auto at  = [&](int k) -> int { // partial k's bytes in buf
        return k == 0 && hi_first
                   ? offsetof(MlaCoreScratch, partial_hi) + m * sizeof(MlaCorePartial)
                   : offsetof(MlaCoreScratch, partial) + (first + min(k, count - 1)) * sizeof(MlaCorePartial);
    };
    float st_max = -__builtin_inff(), st_sum = 0.0f;
    if (tid < count) {
        const floatx4 st = __builtin_bit_cast(
            floatx4, buffer_load_sc1(buf, at(tid) + offsetof(MlaCorePartial, stats) + sizeof(floatx4) * h));
        st_max = st[0];
        st_sum = st[1];
    }
    uint32x4 outs[LOADS];
#pragma unroll
    for (int k = 0; k < LOADS; ++k) {
        const int q = tid + Config::BLOCK_SIZE * k;
        outs[k]     = buffer_load_sc1(buf, at(q / ROW_CH) + offsetof(MlaCorePartial, out) +
                                           (h * LATENT + d0 + 8 * (q % ROW_CH)) * sizeof(bfloat16));
    }
    // wave 0 holds the stats: each partial's weight against the top max
    const float top    = WarpReduce<MaxOp>(st_max);
    const float weight = st_max == -__builtin_inff() ? 0.0f : exp2f(st_max - top);
    const float total  = WarpReduce<SumOp>(weight * st_sum);
    if (tid < B) {
        s.scale[tid] = total > 0.0f ? weight / total : 0.0f;
    }
    block_sync_lds();
    float o[8] = {};
#pragma unroll
    for (int k = 0; k < LOADS; ++k) {
        const float w = s.scale[(tid + Config::BLOCK_SIZE * k) / ROW_CH];
        bfloat16    v[8];
        __builtin_memcpy(v, &outs[k], 16);
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            o[e] += w * static_cast<float>(v[e]);
        }
    }
#pragma unroll
    for (int off = ROW_CH; off < THREADS_PER_WARP; off <<= 1) {
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            o[e] += __shfl_xor(o[e], off);
        }
    }
    if (lane < ROW_CH) {
        *reinterpret_cast<floatx4 *>(&s.osum[wave][8 * lane])     = floatx4{o[0], o[1], o[2], o[3]};
        *reinterpret_cast<floatx4 *>(&s.osum[wave][8 * lane + 4]) = floatx4{o[4], o[5], o[6], o[7]};
    }
    block_sync_lds();
    // the waves' sums in wave order, then lane 4i packs dims 4i .. 4i + 3
#pragma unroll
    for (int k = 0; k < (D + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE; ++k) {
        const int d   = tid + Config::BLOCK_SIZE * k;
        float     sum = 0.0f;
        if (d < D) {
#pragma unroll
            for (int w = 0; w < WAVES; ++w) {
                sum += s.osum[w][d];
            }
        }
        const uint32_t v0 = __builtin_bit_cast(uint16_t, static_cast<bfloat16>(sum));
        const uint32_t v1 = __shfl_down(v0, 1), v2 = __shfl_down(v0, 2), v3 = __shfl_down(v0, 3);
        if (d < D && d % 4 == 0) {
            store_sc1(p.latent_tagged + ((m * HEADS + h) * LATENT + d0 + d) / 4,
                      uint32x4{v0 | v1 << 16, v2 | v3 << 16, 0u, epoch});
        }
    }
}

// a lane's 16 B chunks of its row of W_UV in wuv_unit (fp8; bf16 in twice as many)
constexpr int WUV_REGS = 2;

// Projecting block AD_FIRST + j: its rows of W_UV for wuv_unit, 16-row group j % O_GROUPS of head j / O_GROUPS: lane
// (g, c) row c of the group, wave w K 128 w + 64 i + 16 g .. + 15 in chunk i; only issued. BF16: W_UV bf16.
template <bool BF16 = false>
__device__ __forceinline__ void wuv_weights(const MlaCoreParams &p, int j,
                                            uint32x4 (&w_v)[WUV_REGS * (BF16 ? 2 : 1)]) {
    const int      lane  = threadIdx.x % THREADS_PER_WARP;
    const int      wave  = threadIdx.x / THREADS_PER_WARP;
    constexpr int  BYTES = BF16 ? 2 : 1; // a value's
    const uint8_t *row =
        p.w_v + ((static_cast<size_t>(j / O_GROUPS) * V_HEAD + 16 * (j % O_GROUPS) + lane % 16) * LATENT +
                 LATENT / WAVES * wave + 16 * (lane / 16)) *
                    BYTES;
#pragma unroll
    for (int i = 0; i < WUV_REGS * BYTES; ++i) { // bf16: a chunk's 16 values in two loads
        w_v[i] = *reinterpret_cast<const uint32x4 *>(row + 64 * BYTES * (i / BYTES) + 16 * (i % BYTES));
    }
}

// Projecting block AD_FIRST + j once head h = j / O_GROUPS's o_latent is out (combine_unit's packets, each loaded
// until it shows epoch): rows 16 (j % O_GROUPS) .. + 15 of head h's o, W_UV's (w_v, as wuv_weights loads them) times
// every token's o_latent, the tokens the MFMA's columns; out as packets of 4 values and the epoch (p.out_tagged) for
// o_proj.
template <int NUM_TOKENS, bool BF16 = false>
__device__ __forceinline__ void wuv_unit(const MlaCoreParams &p, MlaCoreSmem &s, int j,
                                         const uint32x4 (&w_v)[WUV_REGS * (BF16 ? 2 : 1)], uint32_t epoch) {
    // the head's o_latent of every token in 16 B chunks, chunk q token q / 64's dims 8 (q % 64) ..
    constexpr int OL_CHUNKS = NUM_TOKENS * LATENT / 8;
    constexpr int OL_LOADS  = (OL_CHUNKS + Config::BLOCK_SIZE - 1) / Config::BLOCK_SIZE;
    const int     tid       = threadIdx.x;
    const int     lane      = tid % THREADS_PER_WARP;
    const int     wave      = tid / THREADS_PER_WARP;
    const int     h         = j / O_GROUPS;
    const int     group     = j % O_GROUPS;
    // W_UV's rows in bf16 (exactly), while o_latent is still on its way
    bfloat16x8 wb[WUV_REGS][2];
#pragma unroll
    for (int i = 0; i < WUV_REGS; ++i) {
        if constexpr (BF16) {
            wb[i][0] = __builtin_bit_cast(bfloat16x8, w_v[2 * i]);
            wb[i][1] = __builtin_bit_cast(bfloat16x8, w_v[2 * i + 1]);
        } else {
            wb[i][0] = fp8x8_to_bf16(w_v[i][0], w_v[i][1]);
            wb[i][1] = fp8x8_to_bf16(w_v[i][2], w_v[i][3]);
        }
    }
    // chunk q from packets 2 (q % 64) and + 1 of token q / 64's head h, the ones not yet out loaded again
    const auto lt = raw_buffer(p.latent_tagged, NUM_TOKENS * HEADS * LATENT / 4 * sizeof(uint32x4));
    const auto at = [&](int q) {
        return ((q / (LATENT / 8) * HEADS + h) * (LATENT / 4) + 2 * (q % (LATENT / 8))) * sizeof(uint32x4);
    };
    uint32x4 a[OL_LOADS] = {}, b[OL_LOADS] = {};
    bool     in[OL_LOADS];
#pragma unroll
    for (int i = 0; i < OL_LOADS; ++i) {
        in[i] = tid + Config::BLOCK_SIZE * i >= OL_CHUNKS;
    }
    bool all;
    do {
        asm volatile("" ::: "memory");
#pragma unroll
        for (int i = 0; i < OL_LOADS; ++i) {
            if (!in[i]) {
                const int q = tid + Config::BLOCK_SIZE * i;
                a[i]        = buffer_load_sc1(lt, at(q));
                b[i]        = buffer_load_sc1(lt, at(q) + sizeof(uint32x4));
            }
        }
        all = true;
#pragma unroll
        for (int i = 0; i < OL_LOADS; ++i) {
            in[i] = in[i] || (a[i][3] == epoch && b[i][3] == epoch);
            all &= in[i];
        }
    } while (!all);
#pragma unroll
    for (int i = 0; i < OL_LOADS; ++i) {
        const int q = tid + Config::BLOCK_SIZE * i;
        if (q < OL_CHUNKS) {
            *reinterpret_cast<uint32x4 *>(&s.ol[q / (LATENT / 8)][8 * (q % (LATENT / 8))]) =
                uint32x4{a[i][0], a[i][1], b[i][0], b[i][1]};
        }
    }
    block_sync_lds();
    // B: token c's o_latent at the lane's K (columns past M repeat token M - 1 and are dropped)
    const bfloat16 *o   = &s.ol[min(lane % 16, NUM_TOKENS - 1)][LATENT / WAVES * wave + 16 * (lane / 16)];
    floatx4         acc = {};
#pragma unroll
    for (int i = 0; i < WUV_REGS; ++i) {
#pragma unroll
        for (int hh = 0; hh < 2; ++hh) {
            const bfloat16x8 bv = *reinterpret_cast<const bfloat16x8 *>(o + 64 * i + 8 * hh);
            acc                 = __builtin_amdgcn_mfma_f32_16x16x32_bf16(wb[i][hh], bv, acc, 0, 0, 0);
        }
    }
    // C: lane (g, c) holds rows 4g .. 4g + 3 for token c. Thread (m, r) sums row r of token m over the waves in wave
    // order, at lane 16 (r / 4) + m of each wave's tile, element r % 4; lane 4i then packs rows 4i .. 4i + 3
    s.tiles[tid] = acc;
    block_sync_lds();
    const int m   = tid / 16;
    const int r   = tid % 16;
    float     sum = 0.0f;
    if (m < NUM_TOKENS) {
        const floatx4 *tile = s.tiles + 16 * (r / 4) + m;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][r % 4];
        }
    }
    const bfloat16 val = static_cast<bfloat16>(BF16 ? sum : sum * *p.w_v_scale);
    const uint32_t v0  = __builtin_bit_cast(uint16_t, val);
    const uint32_t v1 = __shfl_down(v0, 1), v2 = __shfl_down(v0, 2), v3 = __shfl_down(v0, 3);
    if (m < NUM_TOKENS && r % 4 == 0) {
        store_sc1(p.out_tagged + (m * Config::O_PROJ_K + h * V_HEAD + 16 * group + r) / 4,
                  uint32x4{v0 | v1 << 16, v2 | v3 << 16, 0u, epoch});
    }
}

// G (M = 6, 8, aklr_m16/attention_layer.h's units path): projecting block j < UNITS combines token m = j / 16's
// partial sums for head h = j / 2 % 8 into its whole o_latent (combine_unit's sums, both of its halves), then multiplies
// W_UV's rows 128 (j % 2) .. + 127 of head h (wuv_unit's products and wave sums for 8 of its 16-row groups), o out as
// the packets o_proj polls: no o_latent hop between combine_unit and wuv_unit. The 8 blocks reading the same rows of
// W_UV (one per token) share an XCD (j % 8), so its L2 serves the other 7.
constexpr int WUV8_REGS = WUV8_TILES * WUV_REGS;

template <bool BF16 = false>
__device__ __forceinline__ void wuv8_weights(const MlaCoreParams &p, int j, uint32x4 (&w_v)[WUV8_REGS * (BF16 ? 2 : 1)]) {
    constexpr int R = WUV_REGS * (BF16 ? 2 : 1);
    const int     h = j / SPLIT<8> % HEADS;
#pragma unroll
    for (int t = 0; t < WUV8_TILES; ++t) {
        uint32x4 wt[R];
        wuv_weights<BF16>(p, O_GROUPS * h + WUV8_TILES * (j % SPLIT<8>) + t, wt);
#pragma unroll
        for (int i = 0; i < R; ++i) {
            w_v[R * t + i] = wt[i];
        }
    }
}

template <int NUM_TOKENS, bool BF16 = false>
__device__ __forceinline__ void combine_wuv(const MlaCoreParams &p, MlaCoreSmem &s, MlaCoreScratch &x, int j,
                                            const uint32x4 (&w_v)[WUV8_REGS * (BF16 ? 2 : 1)], const uint32x4 *slots,
                                            uint32_t epoch, int partial_packet) {
    constexpr int B      = TOKEN_BLOCKS<NUM_TOKENS>;
    constexpr int D      = UNIT_DIMS<NUM_TOKENS>; // combine_unit's half of o_latent
    constexpr int ROW_CH = D / 8;
    constexpr int LOADS  = B * ROW_CH / Config::BLOCK_SIZE;
    static_assert(SPLIT<NUM_TOKENS> == 2 && 2 * D == LATENT && LOADS * Config::BLOCK_SIZE == B * ROW_CH &&
                  B <= THREADS_PER_WARP && THREADS_PER_WARP % ROW_CH == 0 && D <= Config::BLOCK_SIZE &&
                  WUV8_TILES * 16 * SPLIT<NUM_TOKENS> == V_HEAD && WUV8_TILES * 16 <= Config::BLOCK_SIZE);
    const int tid  = threadIdx.x;
    const int lane = tid % THREADS_PER_WARP;
    const int wave = tid / THREADS_PER_WARP;
    const int m    = j / (HEADS * SPLIT<NUM_TOKENS>);
    const int h    = j / SPLIT<NUM_TOKENS> % HEADS;
    const int half = j % SPLIT<NUM_TOKENS>; // of head h's o: rows 128 half ..
    // W_UV's rows in bf16 (exactly), as wuv_unit's
    bfloat16x8 wb[WUV8_TILES][WUV_REGS][2];
#pragma unroll
    for (int t = 0; t < WUV8_TILES; ++t) {
#pragma unroll
        for (int i = 0; i < WUV_REGS; ++i) {
            if constexpr (BF16) {
                wb[t][i][0] = __builtin_bit_cast(bfloat16x8, w_v[2 * (WUV_REGS * t + i)]);
                wb[t][i][1] = __builtin_bit_cast(bfloat16x8, w_v[2 * (WUV_REGS * t + i) + 1]);
            } else {
                const uint32x4 w = w_v[WUV_REGS * t + i];
                wb[t][i][0]      = fp8x8_to_bf16(w[0], w[1]);
                wb[t][i][1]      = fp8x8_to_bf16(w[2], w[3]);
            }
        }
    }
    wait_for(slots, partial_packet, m * B, B, epoch);
    // combine_unit's loads for both halves d2: chunk q = tid + BLOCK_SIZE k, partial q / ROW_CH's dims D d2 + 8 (q %
    // ROW_CH) ..
    const auto buf    = raw_buffer(&x.partial[m * B], B * sizeof(MlaCorePartial));
    float      st_max = -__builtin_inff(), st_sum = 0.0f;
    if (tid < B) {
        const floatx4 st = __builtin_bit_cast(
            floatx4, buffer_load_sc1(buf, tid * sizeof(MlaCorePartial) + offsetof(MlaCorePartial, stats) +
                                              sizeof(floatx4) * h));
        st_max = st[0];
        st_sum = st[1];
    }
    uint32x4 outs[2][LOADS];
#pragma unroll
    for (int d2 = 0; d2 < 2; ++d2) {
#pragma unroll
        for (int k = 0; k < LOADS; ++k) {
            const int q  = tid + Config::BLOCK_SIZE * k;
            outs[d2][k] = buffer_load_sc1(buf, q / ROW_CH * sizeof(MlaCorePartial) + offsetof(MlaCorePartial, out) +
                                                   (h * LATENT + D * d2 + 8 * (q % ROW_CH)) * sizeof(bfloat16));
        }
    }
    const float top    = WarpReduce<MaxOp>(st_max);
    const float weight = st_max == -__builtin_inff() ? 0.0f : exp2f(st_max - top);
    const float total  = WarpReduce<SumOp>(weight * st_sum);
    if (tid < B) {
        s.g_scale[tid] = total > 0.0f ? weight / total : 0.0f;
    }
    block_sync_lds();
#pragma unroll
    for (int d2 = 0; d2 < 2; ++d2) {
        float o[8] = {};
#pragma unroll
        for (int k = 0; k < LOADS; ++k) {
            const float w = s.g_scale[(tid + Config::BLOCK_SIZE * k) / ROW_CH];
            bfloat16    v[8];
            __builtin_memcpy(v, &outs[d2][k], 16);
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                o[e] += w * static_cast<float>(v[e]);
            }
        }
#pragma unroll
        for (int off = ROW_CH; off < THREADS_PER_WARP; off <<= 1) {
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                o[e] += __shfl_xor(o[e], off);
            }
        }
        if (lane < ROW_CH) {
            *reinterpret_cast<floatx4 *>(&s.g_osum[wave][D * d2 + 8 * lane])     = floatx4{o[0], o[1], o[2], o[3]};
            *reinterpret_cast<floatx4 *>(&s.g_osum[wave][D * d2 + 8 * lane + 4]) = floatx4{o[4], o[5], o[6], o[7]};
        }
    }
    block_sync_lds();
    // o_latent: the waves' sums in wave order, rounded to bf16 (combine_unit's values)
#pragma unroll
    for (int d2 = 0; d2 < 2; ++d2) {
        if (tid < D) {
            float sum = 0.0f;
#pragma unroll
            for (int w = 0; w < WAVES; ++w) {
                sum += s.g_osum[w][D * d2 + tid];
            }
            s.g_ol[D * d2 + tid] = static_cast<bfloat16>(sum);
        }
    }
    block_sync_lds();
    // wuv_unit's products for each group: wave w K 128 w .., every column o_latent (column 0 read below)
    const bfloat16 *o = s.g_ol + LATENT / WAVES * wave + 16 * (lane / 16);
    bfloat16x8      bv[WUV_REGS][2];
#pragma unroll
    for (int i = 0; i < WUV_REGS; ++i) {
#pragma unroll
        for (int hh = 0; hh < 2; ++hh) {
            bv[i][hh] = *reinterpret_cast<const bfloat16x8 *>(o + 64 * i + 8 * hh);
        }
    }
#pragma unroll
    for (int t = 0; t < WUV8_TILES; ++t) {
        floatx4 acc = {};
#pragma unroll
        for (int i = 0; i < WUV_REGS; ++i) {
#pragma unroll
            for (int hh = 0; hh < 2; ++hh) {
                acc = __builtin_amdgcn_mfma_f32_16x16x32_bf16(wb[t][i][hh], bv[i][hh], acc, 0, 0, 0);
            }
        }
        s.g_tiles[t][tid] = acc;
    }
    block_sync_lds();
    // thread (t, r) < 128: row r of group t summed over the waves in wave order, at lane 16 (r / 4) of each wave's tile
    // (column 0), element r % 4; lane 4i then packs rows 4i .. 4i + 3
    const int t   = tid / 16;
    const int r   = tid % 16;
    float     sum = 0.0f;
    if (t < WUV8_TILES) {
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += s.g_tiles[t][v * THREADS_PER_WARP + 16 * (r / 4)][r % 4];
        }
    }
    const bfloat16 val = static_cast<bfloat16>(BF16 ? sum : sum * *p.w_v_scale);
    const uint32_t v0  = __builtin_bit_cast(uint16_t, val);
    const uint32_t v1 = __shfl_down(v0, 1), v2 = __shfl_down(v0, 2), v3 = __shfl_down(v0, 3);
    if (t < WUV8_TILES && r % 4 == 0) {
        store_sc1(p.out_tagged + (m * Config::O_PROJ_K + h * V_HEAD + 16 * (WUV8_TILES * half + t) + r) / 4,
                  uint32x4{v0 | v1 << 16, v2 | v3 << 16, 0u, epoch});
    }
}

