using Params = AttentionIndexerParams<AttnQkvBf16Params, IndexerBf16Params>;

// The kernels' work in turn: attn_qkv_bf16, the indexer's products, its heads and k, the scores,
// the top-k on XCDs 0 .. M - 1, mla_core's (mla_after_topk, the combining blocks reading their
// o_proj rows into L2 while they wait), then o_proj on o's packets.
template <int NUM_TOKENS, bool W_BF16>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1))) void
attention_indexer_kernel(const Params p) {
    extern __shared__ __align__(16) uint8_t smem[];
    const int  block      = blockIdx.x;
    auto      *attn_slots = static_cast<uint32x4 *>(p.attn.workspace);
    auto      *ix_slots   = static_cast<uint32x4 *>(p.topk.workspace);
    auto      *mla_slots  = static_cast<uint32x4 *>(p.mla.workspace);
    const auto attn_epoch = attn_qkv_bf16_units<NUM_TOKENS>(p.attn, smem);
    ix_bf16::products<NUM_TOKENS>(p.attn, p.ix, smem, attn_epoch);
    if (block <= ix_bf16::KEY_BLOCK) {
        ix_bf16::finish_qk<NUM_TOKENS>(p.ix, attn_slots, attn_epoch);
    }
    // read here, not at the start: waiting for them there held back x's loads
    const uint32_t ix_epoch  = next_epoch(ix_slots + block * PACKETS_PER_SLOT);
    const uint32_t mla_epoch = next_epoch(mla_slots + block * PACKETS_PER_SLOT);
    const uint32_t r0_rows = ix_bf16::scores<NUM_TOKENS>(p.ix, smem, attn_slots, attn_epoch);
    r0_flush<NUM_TOKENS>(p.topk, smem, r0_rows);
    publish(ix_slots + block * PACKETS_PER_SLOT + SCORES_PACKET, ix_epoch);
    r0_arrive<NUM_TOKENS>(p.topk, r0_rows);
    if (block % topk::XCDS < NUM_TOKENS) {
        topk_block<NUM_TOKENS>(p.topk, smem, ix_slots, ix_epoch);
    }
    const uint32_t call =
        mla_after_topk<NUM_TOKENS, W_BF16>(p, smem, attn_slots, attn_epoch, ix_epoch, mla_slots,
                                           mla_epoch,
                                           [&] { row_linear_bf16_prefetch<Config::O_PROJ_K>(p.o_proj); });
    uint32x4 w_o[ROW_LINEAR_STEPS<Config::O_PROJ_K>];
    row_linear_bf16_weights<Config::O_PROJ_K>(p.o_proj, w_o);
    row_linear_bf16_rows<Config::O_PROJ_K, NUM_TOKENS>(p.o_proj, smem, call, w_o, mla_epoch);
}

void run(const at::Tensor &hidden_states, const at::Tensor &input_norm_weight, double input_norm_eps,
         const at::Tensor &qkv_a_weight, const std::optional<at::Tensor> &qkv_a_scale,
         const at::Tensor &q_a_norm_weight, const at::Tensor &kv_a_norm_weight, double eps,
         const at::Tensor &q_b_weight, const std::optional<at::Tensor> &q_b_scale,
         const at::Tensor &wq_b, const at::Tensor &wk, const at::Tensor &weights_proj,
         const at::Tensor &k_norm_weight, const at::Tensor &k_norm_bias, double k_norm_eps,
         const at::Tensor &index_cos_cache, const at::Tensor &index_sin_cache,
         const at::Tensor &positions, const at::Tensor &out_cache_loc, at::Tensor &index_k_cache,
         const at::Tensor &seq_lens, const at::Tensor &page_table, at::Tensor &kv_cache,
         double sm_scale, const at::Tensor &cos_cache, const at::Tensor &sin_cache,
         const at::Tensor &w_uk_t, const at::Tensor &w_uv, const std::optional<at::Tensor> &w_scale,
         const at::Tensor &o_proj_weight, const std::optional<at::Tensor> &o_proj_scale,
         at::Tensor &topk_indices, at::Tensor &output, at::Tensor &state, const at::Tensor &peers,
         int64_t rank) {
    check_run(hidden_states, state, IndexerState::BYTES, peers, rank);
    const int64_t num_tokens = hidden_states.size(0);
    TORCH_CHECK(qkv_a_weight.scalar_type() == at::kBFloat16 && !qkv_a_scale && !q_b_scale &&
                    o_proj_weight.scalar_type() == at::kBFloat16 && !o_proj_scale &&
                    w_uk_t.scalar_type() == at::kBFloat16 && w_uv.scalar_type() == at::kBFloat16 &&
                    !w_scale,
                "bf16 linears; W_UK and W_UV bf16, without a scale");
    TORCH_CHECK(index_k_cache.size(1) == ix::PAGE_BYTES && page_table.size(0) == num_tokens &&
                    topk_indices.size(1) == Config::INDEX_TOPK,
                "pages of ", Config::INDEX_PAGE, " keys, a page-table row and the top-",
                Config::INDEX_TOPK, " per token");
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(hidden_states.device());
    const auto options    = hidden_states.options();
    const auto bytes      = options.dtype(at::kByte);
    const int  table      = static_cast<int>(page_table.size(1));
    // every position a page-table row names, at most every one the top-k takes
    const int  logits_len = std::min(Config::INDEX_PAGE * table, MAX_LEN);
    at::Tensor qkv        = at::empty({num_tokens, Config::QKV_A_ROWS}, options);
    at::Tensor q          = at::empty({num_tokens, Config::Q_B_ROWS}, options);
    at::Tensor k_pe       = at::empty({num_tokens, Config::QK_ROPE_DIM}, options);
    at::Tensor ix_q       = at::empty({num_tokens, ix::Q_ROWS}, options);
    at::Tensor partial =
        at::empty({ix_bf16::UNITS, num_tokens, 16}, options.dtype(at::kFloat));
    at::Tensor q_fp8   = at::empty({num_tokens, ix::Q_ROWS}, bytes);
    at::Tensor weights = at::empty({num_tokens, ix::HEADS}, options.dtype(at::kFloat));
    at::Tensor logits  = at::empty({num_tokens, logits_len}, options.dtype(at::kFloat));
    at::Tensor scratch = at::empty({static_cast<int64_t>(sizeof(mla::MlaCoreScratch))}, bytes);
    at::Tensor o       = at::empty({num_tokens, Config::O_PROJ_K}, options);
    uint8_t   *st      = static_cast<uint8_t *>(state.data_ptr());
    Params     p{};
    AttnQkvBf16Params &a  = p.attn;
    a.x                   = static_cast<const bfloat16 *>(hidden_states.data_ptr());
    a.gamma               = static_cast<const bfloat16 *>(input_norm_weight.data_ptr());
    a.epsilon             = static_cast<float>(input_norm_eps);
    a.qkv_weight          = static_cast<const bfloat16 *>(qkv_a_weight.data_ptr());
    a.q_gamma             = static_cast<const bfloat16 *>(q_a_norm_weight.data_ptr());
    a.kv_gamma            = static_cast<const bfloat16 *>(kv_a_norm_weight.data_ptr());
    a.latent_epsilon      = static_cast<float>(eps);
    a.q_b_weight          = static_cast<const bfloat16 *>(q_b_weight.data_ptr());
    a.workspace           = st;
    a.qkv                 = static_cast<bfloat16 *>(qkv.data_ptr());
    a.q                   = static_cast<bfloat16 *>(q.data_ptr());
    a.k_pe                = static_cast<bfloat16 *>(k_pe.data_ptr());
    IndexerBf16Params &ix = p.ix;
    ix.position           = positions.data_ptr<int64_t>();
    ix.slot               = out_cache_loc.data_ptr<int64_t>();
    ix.wq_b               = static_cast<const bfloat16 *>(wq_b.data_ptr());
    ix.wk                 = static_cast<const bfloat16 *>(wk.data_ptr());
    ix.weights_proj       = static_cast<const bfloat16 *>(weights_proj.data_ptr());
    ix.k_gamma            = static_cast<const bfloat16 *>(k_norm_weight.data_ptr());
    ix.k_beta             = static_cast<const bfloat16 *>(k_norm_bias.data_ptr());
    ix.k_epsilon          = static_cast<float>(k_norm_eps);
    ix.cos                = static_cast<const bfloat16 *>(index_cos_cache.data_ptr());
    ix.sin                = static_cast<const bfloat16 *>(index_sin_cache.data_ptr());
    ix.ki                 = static_cast<uint8_t *>(index_k_cache.data_ptr());
    ix.lens               = seq_lens.data_ptr<int>();
    ix.page_table         = page_table.data_ptr<int>();
    ix.table_width        = table;
    ix.q                  = static_cast<bfloat16 *>(ix_q.data_ptr());
    ix.partial            = partial.data_ptr<float>();
    ix.q_fp8              = static_cast<uint8_t *>(q_fp8.data_ptr());
    ix.weights            = weights.data_ptr<float>();
    ix.logits             = logits.data_ptr<float>();
    ix.logits_stride      = logits_len;
    IndexTopkParams &tk   = p.topk;
    tk.logits             = ix.logits;
    tk.stride             = logits_len;
    tk.lens               = ix.lens;
    tk.workspace          = st + IndexerState::IX;
    tk.state              = st + IndexerState::TOPK;
    tk.out                = topk_indices.data_ptr<int>();
    tk.page_table         = ix.page_table;
    tk.page_table_stride  = table;
    tk.page_size          = Config::INDEX_PAGE;
    MlaCoreParams &m      = p.mla;
    m.q                   = a.q;
    m.k_pe                = a.k_pe;
    m.k_pe_stride         = Config::QK_ROPE_DIM;
    m.position            = ix.position;
    m.cos                 = static_cast<const bfloat16 *>(cos_cache.data_ptr());
    m.sin                 = static_cast<const bfloat16 *>(sin_cache.data_ptr());
    m.w_k                 = static_cast<const uint8_t *>(w_uk_t.data_ptr());
    m.w_k_scale           = nullptr;
    m.kv                  = static_cast<uint8_t *>(kv_cache.data_ptr());
    m.slot                = ix.slot;
    m.indices             = tk.out;
    m.qk_scale            = static_cast<float>(sm_scale * LOG2E);
    m.w_v                 = static_cast<const uint8_t *>(w_uv.data_ptr());
    m.w_v_scale           = m.w_k_scale;
    m.workspace           = st + IndexerState::MLA;
    m.scratch             = scratch.data_ptr();
    m.out                 = static_cast<bfloat16 *>(o.data_ptr());
    m.out_tagged          = reinterpret_cast<uint32x4 *>(st + IndexerState::TAGGED);
    RowLinearParams &op   = p.o_proj;
    op.x_tagged           = m.out_tagged;
    op.weight             = static_cast<const uint8_t *>(o_proj_weight.data_ptr());
    op.ar                 = all_reduce_params(output, a.x, peers, rank, st + IndexerState::CALLS);
    static void (*const kernels[Config::MAX_NUM_TOKENS])(Params) = {
        attention_indexer_kernel<1, true>, attention_indexer_kernel<2, true>,
        attention_indexer_kernel<3, true>, attention_indexer_kernel<4, true>};
    const auto kernel = kernels[num_tokens - 1];
    // all of a CU's LDS: one block per CU
    kernel<<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, Config::SMEM_SIZE,
             at::hip::getCurrentHIPStream()>>>(p);
    C10_HIP_CHECK(hipGetLastError());
}

