using Params = AttentionIndexerParams;

// glm5's kernel for more tokens: attn_qkv_bf16, the indexer's products, its heads and k, the scores of the rows'
// segments, the top-k on XCDs 0 .. 3 (its rows past 8 on XCDs 4 .. 7, in mla_after_topk), MLA's (mla_after_topk, each
// block loading its o_proj weights), then o_proj on o's packets. W_UK and W_UV bf16, without a scale. 0.5-0.9 MB of
// code an instance, whose speed depends on where it starts (~1 %): each starts on a 1 KB boundary, laid out in run()'s
// order (M = 16 first, M = 12 last).
template <int NUM_TOKENS>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1), aligned(1024))) void
attention_indexer_kernel(const Params p) {
    extern __shared__ __align__(16) uint8_t smem[];
    const int  block      = blockIdx.x;
    auto      *attn_slots = static_cast<uint32x4 *>(p.attn.workspace);
    auto      *ix_slots   = static_cast<uint32x4 *>(p.topk.workspace);
    auto      *mla_slots  = static_cast<uint32x4 *>(p.mla.workspace);
    const auto lens       = ix_bf16::row_lens<NUM_TOKENS>(p.ix);
    const auto attn_epoch = attn_qkv_bf16_any<NUM_TOKENS>(p.attn, smem); // units at QA_UNITS
    const bool scored     = ix_bf16::scored(lens);
    ix_bf16::products<NUM_TOKENS>(p.attn, p.ix, smem, attn_epoch, scored);
    if (block <= ix_bf16::KEY_BLOCK) {
        ix_bf16::finish_qk<NUM_TOKENS>(p.ix, attn_slots, attn_epoch, scored);
    }
    // read here, not at the start: waiting for them there held back x's loads
    const uint32_t ix_epoch  = next_epoch(ix_slots + block * PACKETS_PER_SLOT);
    const uint32_t mla_epoch = next_epoch(mla_slots + block * PACKETS_PER_SLOT);
    const auto     sg        = ix_bf16::segments<NUM_TOKENS>(p.ix);
    const uint32_t r0_rows   = ix_bf16::scores<NUM_TOKENS>(p.ix, sg, smem, attn_slots, attn_epoch);
    r0_flush(p.topk, smem, r0_rows);
    publish(ix_slots + block * PACKETS_PER_SLOT + SCORES_PACKET, ix_epoch);
    r0_arrive(p.topk, r0_rows);
    if (block % XCDS < topk::TOPK_XCDS) {
        topk_rows<NUM_TOKENS>(p.topk, smem, sg, ix_slots, ix_epoch);
    }
    uint32x4       w_o[ROW_LINEAR_STEPS<Config::O_PROJ_K>];
    const uint32_t call = mla_after_topk<NUM_TOKENS, true>(p, smem, sg, attn_slots, attn_epoch, ix_slots, ix_epoch,
                                                           mla_slots, mla_epoch, w_o);
    row_linear_bf16_rows<Config::O_PROJ_K, NUM_TOKENS>(p.o_proj, smem, call, w_o, mla_epoch);
}

// glm5's state first, then this kernel's; its receive buffers after glm5's in each rank's peer memory
constexpr int64_t STATE_BYTES = glm5::IndexerState::BYTES + IndexerState::BYTES;
static_assert(STATE_BYTES == 23620096, "the schema's state_bytes");
constexpr int64_t PEER_OFFSET = glm5::Config::AR_BUFFER_SIZE;

void run(const at::Tensor &hidden_states, const at::Tensor &input_norm_weight, double input_norm_eps,
         const at::Tensor &qkv_a_weight, const std::optional<at::Tensor> &qkv_a_scale,
         const at::Tensor &q_a_norm_weight, const at::Tensor &kv_a_norm_weight, double eps,
         const at::Tensor &q_b_weight, const std::optional<at::Tensor> &q_b_scale,
         const at::Tensor &wq_b, const at::Tensor &wk, const at::Tensor &weights_proj,
         const at::Tensor &k_norm_weight, const at::Tensor &k_norm_bias, double k_norm_eps,
         const at::Tensor &index_cos_cache, const at::Tensor &index_sin_cache,
         const at::Tensor &positions, const at::Tensor &out_cache_loc, at::Tensor &index_k_cache,
         const at::Tensor &seq_lens, const at::Tensor &page_table, at::Tensor &kv_cache,
         double sm_scale, const at::Tensor &cos_cache, const at::Tensor &sin_cache,
         const at::Tensor &w_uk_t, const at::Tensor &w_uv, const std::optional<at::Tensor> &w_scale,
         const at::Tensor &o_proj_weight, const std::optional<at::Tensor> &o_proj_scale,
