    m.k_pe                = a.k_pe;
    m.k_pe_stride         = Config::QK_ROPE_DIM;
    m.position            = ix.position;
    m.cos                 = static_cast<const bfloat16 *>(cos_cache.data_ptr());
    m.sin                 = static_cast<const bfloat16 *>(sin_cache.data_ptr());
    m.w_k                 = static_cast<const uint8_t *>(w_uk_t.data_ptr());
    m.w_k_scale           = nullptr;
    m.kv                  = static_cast<uint8_t *>(kv_cache.data_ptr());
    m.slot                = ix.slot;
    m.indices             = tk.out;
    m.qk_scale            = static_cast<float>(sm_scale * LOG2E);
    m.w_v                 = static_cast<const uint8_t *>(w_uv.data_ptr());
    m.w_v_scale           = m.w_k_scale;
    m.workspace           = st + IndexerState::MLA;
    m.scratch             = scratch.data_ptr();
    m.latent_tagged       = reinterpret_cast<uint32x4 *>(st + IndexerState::LATENT_TAGGED);
    m.out_tagged          = reinterpret_cast<uint32x4 *>(st + IndexerState::TAGGED);
    RowLinearBf16Params &op = p.o_proj;
    op.x_tagged             = m.out_tagged;
    op.weight               = static_cast<const bfloat16 *>(o_proj_weight.data_ptr());
    op.ar = all_reduce_params(output, a.x, peers, rank, st + IndexerState::CALLS, PEER_OFFSET);
    // the instances in the order their code is laid out: M = 16's start then depends on no other instance's size, and
    // M = 12's size on no other's start
    static void (*const kernels[])(Params) = {attention_indexer_kernel<16>, attention_indexer_kernel<8>,
                                              attention_indexer_kernel<6>, attention_indexer_kernel<12>};
    const auto kernel = kernels[num_tokens == 16 ? 0 : num_tokens == 8 ? 1 : num_tokens == 6 ? 2 : 3];
    // all of a CU's LDS: one block per CU
    kernel<<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, Config::SMEM_SIZE,
             at::hip::getCurrentHIPStream()>>>(p);
    C10_HIP_CHECK(hipGetLastError());
}

